  /**
   * Layout ATC tool clamps across the bar with approximate spacing
   * Sets tool clamp positions from Machine Zero (absolute coordinates)
   */
  public layoutATCClampsApprox(): void {
    const barLength = this._atcStructure.barLength;
    const numberOfTools = this._atcNumberOfTools;

    if (numberOfTools <= 0) return;

    // Get ATC bar center position from Machine Zero
    const atcCenterX = this._atcLocation.x;
    const atcCenterY = this._atcLocation.y;
    const atcCenterZ = this._atcLocation.z;

    // Calculate spacing to spread clamps evenly across bar length
    // Leave some margin at ends (10% of bar length on each side)
    const margin = barLength * 0.1;
    const usableLength = barLength - (2 * margin);
    const spacing = numberOfTools > 1 ? usableLength / (numberOfTools - 1) : 0;

    // Set tool clamp positions from Machine Zero
    this._atcToolClamps.forEach((clamp, index) => {
      // X position: ATC center + offset along bar (spread evenly with margin)
      // Assuming bar runs along X axis
      const barOffset = margin + (index * spacing) - (barLength / 2);
      clamp.offsetX = atcCenterX + barOffset;

      // Y position: ATC center Y (tools are at bar center in Y)
      clamp.offsetY = atcCenterY;

      // Z position: ATC center + bar height / 2 (top of bar)
      clamp.offsetZ = atcCenterZ + (this._atcStructure.barHeight / 2);
    });

    StateManager.propertyChanged(this, 'atcToolHolders');
  }

  /**
   * Calculate ATC bar location from existing tool holder positions
   * Sets bar and post dimensions to fit all tool holders with 6" margin on each end
   * Posts are positioned under each end of the bar
   */
  public calculateATCBarFromToolHolders(): void {
    if (this._atcToolClamps.length === 0) return;

    // Find min/max X and Y positions of all tool holders (in Machine Zero coordinates)
    let minX = Number.MAX_VALUE;
    let maxX = Number.MIN_VALUE;
    let minY = Number.MAX_VALUE;
    let maxY = Number.MIN_VALUE;
    let avgZ = 0;

    this._atcToolClamps.forEach((clamp) => {
      minX = Math.min(minX, clamp.offsetX);
      maxX = Math.max(maxX, clamp.offsetX);
      minY = Math.min(minY, clamp.offsetY);
      maxY = Math.max(maxY, clamp.offsetY);
      avgZ += clamp.offsetZ;
    });

    avgZ = avgZ / this._atcToolClamps.length;

    // Determine if tools are arranged along X or Y axis
    const xSpread = maxX - minX;
    const ySpread = maxY - minY;

    const margin = 6.0; // 6 inches margin on each end

    if (xSpread > ySpread) {
      // Tools arranged along X axis
      const barLength = xSpread + (2 * margin); // Delta + 12"
      const toolClampDepth = 2.0; // Standard tool clamp depth (matches ATC.tsx)

      // ATC location is in Machine Zero coordinates (same as tool holders)
      this._atcLocation.x = minX - margin; // Start at min X minus 6"
      this._atcLocation.y = (minY + maxY) / 2 + toolClampDepth / 2; // Move back half the tool holder depth
      this._atcLocation.z = avgZ; // Top of bar at tool holder height
      this._atcStructure.barLength = barLength;
    } else {
      // Tools arranged along Y axis
      const barLength = ySpread + (2 * margin); // Delta + 12"
      const toolClampDepth = 2.0; // Standard tool clamp depth (matches ATC.tsx)

      // ATC location is in Machine Zero coordinates (same as tool holders)
      this._atcLocation.x = (minX + maxX) / 2 + toolClampDepth / 2; // Move back half the tool holder depth
      this._atcLocation.y = minY - margin; // Start at min Y minus 6"
      this._atcLocation.z = avgZ; // Top of bar at tool holder height
      this._atcStructure.barLength = barLength;
    }

    StateManager.propertyChanged(this, 'atcLocation');
    StateManager.propertyChanged(this, 'atcStructure');
  }

  /**
   * Static method to trigger auto-calculation of ATC bar location
   * Called whenever tool holder positions change or relevant settings change
   */
  public static triggerATCBarAutoCalculation(): void {
    const instance = MachineData.Instance;
    if (instance._atcAutoCalculateBarLocation && instance._hasATC) {
      instance.calculateATCBarFromToolHolders();
    }
  }

  /**
   * Layout tool holders with user-specified spacing on the non-approach axis
   * @param spacing - The increment to apply between each tool holder
   */
  public layoutToolHoldersWithSpacing(spacing: number): void {
    if (this._atcToolClamps.length === 0) return;

    // Get the first tool holder's position as the base
    const firstClamp = this._atcToolClamps[0];
    const baseX = firstClamp.offsetX;
    const baseY = firstClamp.offsetY;

    // Apply spacing to non-approach axis
    this._atcToolClamps.forEach((clamp, index) => {
      if (this._atcApproachAxis === 'Y') {
        // Approach is Y, so modify X (non-approach axis)
        clamp.offsetX = baseX + (index * spacing);
      } else {
        // Approach is X, so modify Y (non-approach axis)
        clamp.offsetY = baseY + (index * spacing);
      }
    });

    StateManager.propertyChanged(this, 'atcToolHolders');
  }

