import {
  Box,
  Button,
  Paper,
  Step,
  StepButton,
  StepLabel,
  Stepper,
  Typography
} from '@mui/material';
import React, { useEffect } from 'react';
import { ConfigurationState } from '../../data/ConfigurationState';
import { Job } from '../../data/Job';
import { LayoutState, ViewType } from '../../data/LayoutState';
import { MillingWorkflowState } from '../../data/MillingWorkflowState';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { ConfirmRunStage } from './Milling/ConfirmRunStage';
import { GCodeStage } from './Milling/GCodeStage';
import { PreviewGCodeStage } from './Milling/PreviewGCodeStage';
import { RunStage } from './Milling/RunStage';
import { SetupJobStage } from './Milling/SetupJobStage';

export const Milling: React.FC = () => {
  const workflowState = MillingWorkflowState.Instance;

  // Register trigger function for navigation to reset workflow
  useEffect(() => {
    const triggerReset = () => {
      workflowState.reset();
    };

    (ConfigurationState.Instance as any)._millingTriggerRun = triggerReset;

    return () => {
      delete (ConfigurationState.Instance as any)._millingTriggerRun;
    };
  }, [workflowState]);

  const handleNext = () => {
    // Special handling for Select GCode stage (stage 0)
    if (workflowState.activeStage === 0) {
      // If in editor tab with content, create the preview job
      if (workflowState.isInEditorTab() && workflowState.hasEditorContent()) {
        const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, -5);
        const jobName = `custom_job_${timestamp}`;

        // Create preview job
        const job = new Job();
        job.gcode = workflowState.editorGCode;
        job.name = jobName;

        // Copy material/clamps from current or last job
        const baseJob = ConfigurationState.Instance.currentJob || ConfigurationState.Instance.lastJob;
        if (baseJob?.material) {
          job.material = baseJob.material.clone();
        }
        if (baseJob?.clamps) {
          job.clamps = baseJob.clamps.map((c: any) => c.clone());
        }

        ConfigurationState.Instance.proposedJob = job;
        workflowState.selectionMethod = 'editor';
      }

      // Check if proposedJob exists
      if (!ConfigurationState.Instance.proposedJob) {
        UserMessageQueue.Instance.addMessage('❌ Please select or create a G-code file');
        return;
      }
    }

    // Validate stage-specific requirements before allowing progression
    if (workflowState.activeStage === 3) { // Setup Job stage (index 3)
      if (!ConfigurationState.Instance.currentJob?.workZeroConfirmed) {
        UserMessageQueue.Instance.addMessage('❌ Please confirm work zero before proceeding');
        return;
      }
    }

    // Call the moving to next callback for the current step
    handleMovingToNext(workflowState.activeStage);

    // If at the last stage and clicking Finish, go back to home
    if (workflowState.activeStage === workflowState.stages.length - 1) {
      // Reset workflow and navigate to home
      workflowState.reset();
      LayoutState.Instance.selectedView = ViewType.Home;
      return;
    }

    // Use workflow state to manage navigation
    workflowState.goToNextStage();
  };

  const handleBack = () => {
    if (workflowState.canGoBack()) {
      // If going back from Preview (1) to Select (0), clear proposedJob and selection
      if (workflowState.activeStage === 1) {
        ConfigurationState.Instance.proposedJob = undefined;
        workflowState.clearSelection();
      }
      // If going back TO Preview (stage 1), restore currentJob as proposedJob
      else if (workflowState.activeStage === 2 && ConfigurationState.Instance.currentJob) {
        ConfigurationState.Instance.proposedJob = ConfigurationState.Instance.currentJob;
      }

      workflowState.goToPreviousStage();
    }
  };

  const handleStepClick = (step: number) => {
    if (workflowState.isStageClickable(step)) {
      // If navigating back from Preview to Select, clear selection
      if (workflowState.activeStage === 1 && step === 0) {
        ConfigurationState.Instance.proposedJob = undefined;
        workflowState.clearSelection();
      }
      // If navigating TO Preview (step 1) from later stages, restore currentJob as proposedJob
      else if (step === 1 && workflowState.activeStage > 1 && ConfigurationState.Instance.currentJob) {
        ConfigurationState.Instance.proposedJob = ConfigurationState.Instance.currentJob;
      }

      workflowState.goToStage(step);
    }
  };

  // Callback for stages to customize the next step behavior
  const handleMovingToNext = (step: number) => {

    // Handle specific step logic
    if (step === 1) { // Preview stage (second stage, index 1)
      if (ConfigurationState.Instance.proposedJob) {
        // Store current job as last job before replacing
        if (ConfigurationState.Instance.currentJob) {
          ConfigurationState.Instance.lastJob = ConfigurationState.Instance.currentJob;
        }

        // Set the proposed job as current (but keep proposedJob for potential back navigation)
        ConfigurationState.Instance.currentJob = ConfigurationState.Instance.proposedJob;
      }
    }
  };

  // Callback for stages to customize the next button text
  const getNextStepName = (step: number) => {
    if (step === workflowState.stages.length - 1) {
      return 'Finish';
    } else if (step === 1 && ConfigurationState.Instance.proposedJob) {
      return 'Use This File';
    } else {
      return 'Next';
    }
  };

  const renderStageContent = () => {
    const stageProps = {
      onMovingToNext: () => handleMovingToNext(workflowState.activeStage),
      getNextStepName: () => getNextStepName(workflowState.activeStage),
      onPreviewReady: workflowState.activeStage === 0 ? () => workflowState.goToNextStage() : undefined
    };

    switch (workflowState.activeStage) {
      case 0:
        return <GCodeStage {...stageProps} />;
      case 1:
        return <PreviewGCodeStage {...stageProps} />;
      case 2:
        return <ConfirmRunStage {...stageProps} />;
      case 3:
        return <SetupJobStage {...stageProps} />;
      case 4:
        return <RunStage {...stageProps} />;
      default:
        return <GCodeStage {...stageProps} />;
    }
  };

  return (
    <ObserveState
      key="milling-workflow"
      listenTo={workflowState}
      properties={['activeStage', 'completedStages']}
      control={() => {
        return (
          <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
            {/* Header with Stage Navigation */}
            <Paper sx={{ p: 3, mb: 2, borderRadius: 0, borderBottom: 1, borderColor: 'divider' }}>
              <Box sx={{ px: 3 }}>
                <Stepper activeStep={workflowState.activeStage} alternativeLabel>
                  {workflowState.stages.map((label, index) => (
                    <Step key={label} completed={workflowState.isStageCompleted(index)}>
                      <StepButton
                        onClick={() => handleStepClick(index)}
                        disabled={!workflowState.isStageClickable(index)}
                        sx={{
                          '& .MuiStepLabel-root': {
                            cursor: workflowState.isStageClickable(index) ? 'pointer' : 'default',
                          },
                          '& .MuiStepLabel-label': {
                            fontSize: '1rem',
                            fontWeight: workflowState.activeStage === index ? 'bold' : 'normal',
                          }
                        }}
                      >
                        <StepLabel>{label}</StepLabel>
                      </StepButton>
                    </Step>
                  ))}
                </Stepper>
              </Box>
            </Paper>

            {/* Stage Content */}
            <Box sx={{ flex: 1, overflow: 'auto' }}>
              <Box sx={{ px: 3, py: 3, height: '100%' }}>
                {renderStageContent()}
              </Box>
            </Box>

            {/* Navigation Buttons */}
            <Paper sx={{ p: 2, borderRadius: 0, borderTop: 1, borderColor: 'divider' }}>
              <Box sx={{ px: 3 }}>
                <ObserveState
                  key="milling-navigation"
                  listenTo={ConfigurationState.Instance}
                  properties={['proposedJob']}
                  control={() => {
                    return (
                      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <Button
                          variant="outlined"
                          onClick={handleBack}
                          disabled={!workflowState.canGoBack()}
                        >
                          Back
                        </Button>

                        <Typography variant="body2" color="text.secondary">
                          Step {workflowState.activeStage + 1} of {workflowState.stages.length}: {workflowState.currentStageName}
                        </Typography>

                        <Button
                          variant="contained"
                          onClick={handleNext}
                          disabled={workflowState.activeStage === workflowState.stages.length - 1 && workflowState.isStageCompleted(workflowState.activeStage)}
                        >
                          {getNextStepName(workflowState.activeStage)}
                        </Button>
                      </Box>
                    );
                  }}
                />
              </Box>
            </Paper>
          </Box>
        );
      }}
    />
  );
};
