import { Grid, Typography } from '@mui/material';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';

export function SpindleSection() {
    const machine = MachineData.Instance;

    return (
        <Grid container spacing={3}>
            {/* Spindle */}
            <Grid item xs={12}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                    Spindle
                </Typography>
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="spindle-diameter"
                    listenTo={machine}
                    properties={['spindleDiameter']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Spindle Diameter"
                            value={machine.spindleDiameter}
                            onChange={(value) => machine.spindleDiameter = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="spindle-length"
                    listenTo={machine}
                    properties={['spindleLength']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Spindle Length"
                            value={machine.spindleLength}
                            onChange={(value) => machine.spindleLength = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            {/* Tool Holder */}
            <Grid item xs={12}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom sx={{ mt: 2 }}>
                    Tool Holder
                </Typography>
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="tool-holder-diameter"
                    listenTo={machine}
                    properties={['toolHolderDiameter']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Tool Holder Diameter"
                            value={machine.toolHolderDiameter}
                            onChange={(value) => machine.toolHolderDiameter = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="tool-holder-length"
                    listenTo={machine}
                    properties={['toolHolderLength']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Tool Holder Length"
                            value={machine.toolHolderLength}
                            onChange={(value) => machine.toolHolderLength = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            {/* Z-Plate */}
            <Grid item xs={12}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom sx={{ mt: 2 }}>
                    Z-Plate
                </Typography>
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="z-plate-height"
                    listenTo={machine}
                    properties={['zPlateHeight']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Height"
                            value={machine.zPlateHeight}
                            onChange={(value) => machine.zPlateHeight = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="z-plate-side-extension"
                    listenTo={machine}
                    properties={['zPlateSideExtension']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Side Extension"
                            value={machine.zPlateSideExtension}
                            onChange={(value) => machine.zPlateSideExtension = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="z-plate-depth"
                    listenTo={machine}
                    properties={['zPlateDepth']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Depth"
                            value={machine.zPlateDepth}
                            onChange={(value) => machine.zPlateDepth = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="z-plate-vertical-offset"
                    listenTo={machine}
                    properties={['zPlateVerticalOffset']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Vertical Offset"
                            value={machine.zPlateVerticalOffset}
                            onChange={(value) => machine.zPlateVerticalOffset = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            {/* Z-Carriage */}
            <Grid item xs={12}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom sx={{ mt: 2 }}>
                    Z-Carriage Plate
                </Typography>
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="z-carriage-plate-height"
                    listenTo={machine}
                    properties={['zCarriagePlateHeight']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Height"
                            value={machine.zCarriagePlateHeight}
                            onChange={(value) => machine.zCarriagePlateHeight = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="z-carriage-plate-depth"
                    listenTo={machine}
                    properties={['zCarriagePlateDepth']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Depth"
                            value={machine.zCarriagePlateDepth}
                            onChange={(value) => machine.zCarriagePlateDepth = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="z-carriage-plate-vertical-offset"
                    listenTo={machine}
                    properties={['zCarriagePlateVerticalOffset']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Vertical Offset"
                            value={machine.zCarriagePlateVerticalOffset}
                            onChange={(value) => machine.zCarriagePlateVerticalOffset = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            {/* Z-Carriage Body */}
            <Grid item xs={12}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom sx={{ mt: 2 }}>
                    Z-Carriage Body
                </Typography>
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="z-carriage-vertical-offset"
                    listenTo={machine}
                    properties={['zCarriageVerticalOffset']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Vertical Offset"
                            value={machine.zCarriageVerticalOffset}
                            onChange={(value) => machine.zCarriageVerticalOffset = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="z-carriage-horizontal-offset"
                    listenTo={machine}
                    properties={['zCarriageHorizontalOffset']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Horizontal Offset"
                            value={machine.zCarriageHorizontalOffset}
                            onChange={(value) => machine.zCarriageHorizontalOffset = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>
            <Grid item xs={12} sm={6}>
                <ObserveState
                    key="z-carriage-width"
                    listenTo={machine}
                    properties={['zCarriageWidth']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Width"
                            value={machine.zCarriageWidth}
                            onChange={(value) => machine.zCarriageWidth = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>
        </Grid>
    );
}
