import {
    Box,
    Button,
    FormControlLabel,
    Grid,
    Paper,
    Switch,
    Typography
} from '@mui/material';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';

export function InputTooltipsSection() {
    const config = ConfigurationData.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
                <Paper sx={{ p: 3 }}>
                    <Typography variant="h6" gutterBottom>Tooltip Settings</Typography>

                    <ObserveState
                        key="input-tooltips-settings"
                        listenTo={config}
                        properties={['showNumberInputTooltips', 'numberInputTooltipCount']}
                        control={() => (
                            <>
                                <FormControlLabel
                                    control={
                                        <Switch
                                            checked={config.showNumberInputTooltips}
                                            onChange={(e) => config.showNumberInputTooltips = e.target.checked}
                                        />
                                    }
                                    label="Show Number Input Tooltips"
                                />

                                <Box sx={{ mt: 2 }}>
                                    <Typography variant="body2" color="text.secondary" gutterBottom>
                                        Remaining tooltip shows: {config.numberInputTooltipCount}
                                    </Typography>

                                    <Button
                                        variant="outlined"
                                        onClick={() => config.resetNumberInputTooltipCount()}
                                        sx={{ mt: 1 }}
                                    >
                                        Reset Tooltip Count
                                    </Button>

                                    <Typography variant="caption" display="block" sx={{ mt: 1, color: 'text.secondary' }}>
                                        Tooltips will stop showing after being displayed 10 times. Use this button to reset the counter.
                                    </Typography>
                                </Box>
                            </>
                        )}
                    />
                </Paper>
            </Grid>
        </Grid>
    );
}
