import React from 'react';
import { LogCategory, Logger } from '../utils/Logger';
import { NotificationList } from '../utils/NotificationList';
import { ConfigurationData } from './ConfigurationData';
import { ConfigurationDataColors } from './ConfigurationDataColors';

export interface UserMessage {
  id: string;
  message: string;
  timestamp: number;
}

/**
 * Manages user messages using the simple NotificationList system
 * Automatically prevents duplicates and handles timeouts
 */
export class UserMessageQueue {
  private static _instance: UserMessageQueue;
  private _activeMessages: Set<string> = new Set(); // Track active messages to prevent duplicates

  private constructor() { }

  /**
   * Add a new message to the queue
   * @param message The message text to display
   */
  public addMessage(message: string): void {
    Logger.Instance.logDebug(LogCategory.UserInterface, 'UserMessageQueue: Adding message', message);

    // Check if this message is already being displayed
    if (this._activeMessages.has(message)) {
      return;
    }

    // Mark as active
    this._activeMessages.add(message);

    // Get display time from configuration
    const displayTime = this.getMessageDisplayTime();

    // Create message ID
    const messageId = `user_msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    // Create the message component
    const messageComponent = this.createMessageComponent(message, messageId);

    // Add to notification list
    NotificationList.Instance.add(messageId, messageComponent, 1); // User messages have ordinal 1 (above actions)

    // Set up auto-removal
    setTimeout(() => {
      this.removeMessageInternal(messageId, message);
    }, displayTime);
  }

  /**
   * Add a persistent error message that must be manually dismissed
   * @param message The error message text to display
   */
  public addPersistentError(message: string): void {
    Logger.Instance.logDebug(LogCategory.UserInterface, 'UserMessageQueue: Adding persistent error', message);
    console.error('PERSISTENT ERROR:', message);

    // Check if this message is already being displayed
    if (this._activeMessages.has(message)) {
      return;
    }

    // Mark as active
    this._activeMessages.add(message);

    // Create message ID
    const messageId = `error_msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    // Create the error message component (red background, no auto-dismiss)
    const messageComponent = this.createErrorMessageComponent(message, messageId);

    // Add to notification list with high priority (ordinal 0 = highest)
    NotificationList.Instance.add(messageId, messageComponent, 0);
  }

  /**
   * Create a React component for the message that matches the old styling
   */
  private createMessageComponent(message: string, messageId: string): React.ReactNode {
    const config = ConfigurationData.Instance;
    const colors = ConfigurationDataColors.Instance;

    return React.createElement('div', {
      style: {
        backgroundColor: colors.modalBackdrop,
        color: colors.lightTextColor,
        padding: '12px 16px',
        borderRadius: '8px',
        minWidth: '250px',
        fontFamily: 'Arial, sans-serif',
        cursor: 'pointer',
        border: `1px solid ${colors.borderColor}`,
        boxShadow: `0 4px 12px ${colors.shadowColor}`,
        transition: 'opacity 0.2s ease-out'
      },
      onClick: () => this.removeMessageInternal(messageId, message),
      onMouseEnter: (e: any) => {
        e.currentTarget.style.opacity = '0.9';
      },
      onMouseLeave: (e: any) => {
        e.currentTarget.style.opacity = '1';
      }
    }, [
      React.createElement('div', {
        key: 'main-text',
        style: {
          fontSize: '14px',
          fontWeight: 'bold',
          marginBottom: '4px'
        }
      }, message),
      React.createElement('div', {
        key: 'dismiss-text',
        style: {
          fontSize: '11px',
          opacity: 0.8,
          fontStyle: 'italic'
        }
      }, 'Click to dismiss')
    ]);
  }

  /**
   * Create a React component for persistent error messages (red background)
   */
  private createErrorMessageComponent(message: string, messageId: string): React.ReactNode {
    return React.createElement('div', {
      style: {
        backgroundColor: ConfigurationDataColors.Instance.errorColor,
        color: ConfigurationDataColors.Instance.lightTextColor,
        padding: '16px 20px',
        borderRadius: '8px',
        minWidth: '300px',
        maxWidth: '500px',
        fontFamily: 'Arial, sans-serif',
        cursor: 'pointer',
        border: `2px solid ${ConfigurationDataColors.Instance.errorColor}`,
        boxShadow: `0 6px 16px ${ConfigurationDataColors.Instance.shadowColor}`,
        transition: 'opacity 0.2s ease-out'
      },
      onClick: () => this.removeMessageInternal(messageId, message),
      onMouseEnter: (e: any) => {
        e.currentTarget.style.opacity = '0.9';
      },
      onMouseLeave: (e: any) => {
        e.currentTarget.style.opacity = '1';
      }
    }, [
      React.createElement('div', {
        key: 'icon',
        style: {
          fontSize: '20px',
          marginBottom: '8px'
        }
      }, '⚠️ CRITICAL ERROR'),
      React.createElement('div', {
        key: 'main-text',
        style: {
          fontSize: '14px',
          fontWeight: 'bold',
          marginBottom: '8px',
          lineHeight: '1.4'
        }
      }, message),
      React.createElement('div', {
        key: 'dismiss-text',
        style: {
          fontSize: '12px',
          opacity: 0.9,
          fontStyle: 'italic',
          borderTop: `1px solid ${ConfigurationDataColors.Instance.lightTextColor}4D`,
          paddingTop: '8px',
          marginTop: '8px'
        }
      }, 'Click to dismiss • Check console for details')
    ]);
  }

  /**
   * Internal method to remove a message
   */
  private removeMessageInternal(messageId: string, message: string): void {
    NotificationList.Instance.remove(messageId);
    this._activeMessages.delete(message);
    Logger.Instance.logDebug(LogCategory.UserInterface, 'UserMessageQueue: Removed message', message);
  }

  /**
   * Remove a message by ID (for backwards compatibility)
   */
  public removeMessage(messageId: string): void {
    // For backwards compatibility, just remove from notification list
    // We can't easily track which message text this ID corresponds to
    NotificationList.Instance.remove(messageId);
  }

  /**
   * Clear all user messages
   */
  public clearAllMessages(): void {
    // Clear all user messages (those with ordinal 0)
    const notifications = NotificationList.Instance.notifications;
    notifications.forEach(notification => {
      if (notification.ordinal === 0) { // User messages have ordinal 0
        NotificationList.Instance.remove(notification.id);
      }
    });

    this._activeMessages.clear();
  }

  /**
   * Get all current user messages (for backwards compatibility)
   */
  public get messages(): UserMessage[] {
    const notifications = NotificationList.Instance.notifications;
    return notifications
      .filter(n => n.ordinal === 0) // User messages have ordinal 0
      .map(n => ({
        id: n.id,
        message: Array.from(this._activeMessages)[0] || 'Message', // Best effort
        timestamp: Date.now()
      }));
  }

  /**
   * Get the configured message display time from ConfigurationData
   */
  private getMessageDisplayTime(): number {
    // Import here to avoid circular dependency
    const { ConfigurationData } = require('./ConfigurationData');
    return ConfigurationData.Instance.messageDisplayTime;
  }

  /**
   * Get the singleton instance
   */
  public static get Instance(): UserMessageQueue {
    if (!UserMessageQueue._instance) {
      UserMessageQueue._instance = new UserMessageQueue();
    }
    return UserMessageQueue._instance;
  }
}
