import { Box, Typography } from '@mui/material';
import { CNCOffset } from '../../data/CNCOffset';
import { NumberInput } from './NumberInput';

interface OffsetEditorProps {
    offset: CNCOffset;
    label?: string;
    showLabel?: boolean;
    disabled?: boolean;
    precision?: number;
    xLabel?: string;
    yLabel?: string;
    zLabel?: string;
    onOffsetChange?: (offset: CNCOffset) => void;
}

/**
 * Reusable component for editing CNCOffset values
 * Displays three NumberInput fields for X, Y, and Z coordinates
 */
export function OffsetEditor({
    offset,
    label = 'Offset',
    showLabel = true,
    disabled = false,
    precision = 3,
    xLabel = 'X Offset',
    yLabel = 'Y Offset',
    zLabel = 'Z Offset',
    onOffsetChange
}: OffsetEditorProps) {
    const handleXChange = (value: number) => {
        offset.x = value;
    };

    const handleYChange = (value: number) => {
        offset.y = value;
    };

    const handleZChange = (value: number) => {
        offset.z = value;
    };

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
            {showLabel && (
                <Typography variant="subtitle2" sx={{ fontWeight: 'bold' }}>
                    {label}
                </Typography>
            )}
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
                <NumberInput
                    label={xLabel}
                    value={offset.x}
                    onChange={handleXChange}
                    disabled={disabled}
                    precision={precision}
                />
                <NumberInput
                    label={yLabel}
                    value={offset.y}
                    onChange={handleYChange}
                    disabled={disabled}
                    precision={precision}
                />
                <NumberInput
                    label={zLabel}
                    value={offset.z}
                    onChange={handleZChange}
                    disabled={disabled}
                    precision={precision}
                />
            </Box>
        </Box>
    );
}
