import { Close as CloseIcon } from '@mui/icons-material';
import { Button, Dialog, DialogActions, DialogContent, DialogTitle, IconButton, Typography } from '@mui/material';
import { useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../data/ConfigurationState';
import { MachineData } from '../../../data/Machine/MachineData';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import { LogCategory, Logger } from '../../../utils/Logger';

interface FixedTouchPlateTouchOffDialogProps {
    open: boolean;
    onClose: () => void;
}

export function FixedTouchPlateTouchOffDialog({ open, onClose }: FixedTouchPlateTouchOffDialogProps) {
    const colors = ConfigurationDataColors.Instance;
    const [isProcessing, setIsProcessing] = useState(false);

    const handleSetPosition = async () => {
        try {
            setIsProcessing(true);

            // Get current machine position
            const currentPosition = ConfigurationState.Instance.currentMachinePoint;

            // Update the fixed touch plate position in MachineData
            const machineData = MachineData.Instance;
            machineData.fixedTouchPlateX = currentPosition.x;
            machineData.fixedTouchPlateY = currentPosition.y;
            machineData.fixedTouchPlateZ = currentPosition.z;


            UserMessageQueue.Instance.addMessage(
                `✓ Touch plate position set: X=${currentPosition.x.toFixed(3)}, Y=${currentPosition.y.toFixed(3)}, Z=${currentPosition.z.toFixed(3)}`
            );

            onClose();
        } catch (error) {
            Logger.Instance.logError(LogCategory.UserInterface, 'Failed to set touch plate position:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to set touch plate position');
        } finally {
            setIsProcessing(false);
        }
    };

    return (
        <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
            <DialogTitle sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                backgroundColor: colors.primaryColor,
                color: colors.lightTextColor,
                py: 2,
                px: 3
            }}>
                Touch Off Spindle to Fixed Touch Plate
                <IconButton
                    onClick={onClose}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>
            <DialogContent>
                <Typography variant="body1" sx={{ mt: 3, mb: 2 }}>
                    <strong>Instructions:</strong>
                </Typography>
                <Typography variant="body2" sx={{ mb: 1 }}>
                    1. Manually jog the spindle until the tool tip touches the fixed touch plate surface
                </Typography>
                <Typography variant="body2" sx={{ mb: 1 }}>
                    2. Ensure the tool is precisely touching the plate in X, Y, and Z
                </Typography>
                <Typography variant="body2" sx={{ mb: 2 }}>
                    3. Click "Set Position" to save the current machine coordinates as the touch plate position
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ fontStyle: 'italic' }}>
                    Note: This will update the X, Y, Z coordinates of the fixed touch plate in machine zero coordinates.
                </Typography>
            </DialogContent>
            <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${colors.borderColor}` }}>
                <Button onClick={onClose} disabled={isProcessing}>
                    Cancel
                </Button>
                <Button
                    variant="contained"
                    onClick={handleSetPosition}
                    disabled={isProcessing}
                    sx={{
                        backgroundColor: colors.primaryColor,
                        '&:hover': {
                            backgroundColor: colors.primaryColor,
                            opacity: 0.9
                        }
                    }}
                >
                    Set Position
                </Button>
            </DialogActions>
        </Dialog>
    );
}
