// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-nocheck
import React, { useCallback, useRef } from 'react';
import { CNCOffset } from '../../../data/CNCOffset';
import { CNCPoint } from '../../../data/CNCPoint';
import { CoordinateType } from '../../../data/Common/CoordinateType';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ViewStyle } from '../../../data/Common/ViewStyle';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../data/ConfigurationState';
import { Job } from '../../../data/Job';
import { MachineData } from '../../../data/Machine/MachineData';
import { MachineStateData } from '../../../data/MachineStateData';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { Box } from './Box';

export interface ClampsProps {
  simulatorView: SimulatorView;
  machineState: MachineStateData;
  machineData: MachineData;
  job?: Job; // Optional job - can be null, only use what's passed in
  enableClampDragging?: boolean;
  orbitControlsRef?: React.RefObject<any>;
}

export const Clamps: React.FC<ClampsProps> = ({
  simulatorView,
  machineState,
  machineData,
  job,
  enableClampDragging = false,
  orbitControlsRef
}) => {
  // Get configuration state instance
  const configState = ConfigurationState.Instance;
  const config = ConfigurationData.Instance;
  const colors = ConfigurationDataColors.Instance;

  // Helper function to convert simulator position to clamp offsets
  const simulatorPositionToClampOffsets = useCallback((simulatorPos: [number, number, number], clampWidth: number, clampHeight: number) => {
    // Convert from simulator coordinates to machine coordinates
    const simulatorPoint = new CNCPoint(simulatorPos[0], simulatorPos[1], simulatorPos[2], CoordinateType.Simulator);
    const machinePoint = CoordinateUtil.toMachineZero(simulatorPoint);

    // Calculate material corner position using the same method as rendering
    const materialCornerPosition = CoordinateUtil.getMaterialCornerPosition(machineState);

    // Calculate clamp offsets using CNCPoint.subtractOffset
    const clampCenterOffset = new CNCOffset(clampWidth / 2, clampHeight / 2, 0);
    const offsetPoint = CNCPoint.subtractOffset(machinePoint, materialCornerPosition);
    const finalOffsetPoint = CNCPoint.subtractOffset(offsetPoint, clampCenterOffset);

    return { offsetX: finalOffsetPoint.x, offsetY: finalOffsetPoint.y };
  }, [machineState]);

  const handleClampClick = useCallback((clampId: string) => {
    // Only allow clamp selection if dragging is enabled (selection is implied with dragging)
    if (enableClampDragging) {
      configState.selectClamp(clampId);
    }
  }, [enableClampDragging, configState]);

  const handleClampDragEnd = useCallback(() => {
    // Note: Clamp position changes are applied directly to the job object passed in
    // No need to notify state manager since we don't track currentJob here
  }, []);

  // DraggableBox component for clamps that can be dragged
  const DraggableBox = ({ clamp, position, size, color, viewStyle, opacity, onDragEnd }: {
    clamp: any;
    position: [number, number, number];
    size: [number, number, number];
    color: string;
    viewStyle: any;
    opacity: number;
    onDragEnd: () => void;
  }) => {
    const meshRef = useRef<any>();
    const [isDragging, setIsDragging] = React.useState(false);
    const [isHovered, setIsHovered] = React.useState(false);
    const [hasShownMessage, setHasShownMessage] = React.useState(false);

    // Check if this clamp is selected and being dragged
    const isSelected = configState.selectedClampId === clamp.id;
    const isThisClampDragging = isDragging && isSelected;

    // Use proposed position if this specific clamp is being dragged, otherwise use calculated position
    const currentPosition = (isThisClampDragging && configState.proposedClampPosition)
      ? [configState.proposedClampPosition.x, configState.proposedClampPosition.y, configState.proposedClampPosition.z]
      : position;

    // Determine the visual color based on selection and hover state
    const getClampColor = () => {
      if (isSelected || isDragging) return colors.highlightColor;
      if (isHovered) return colors.highlightColor;
      return color;
    };

    const handlePointerOver = useCallback(() => {
      setIsHovered(true);

      // Show message when hover begins if clamp dragging is enabled, clamp is not already selected,
      // and we haven't already shown the message for this hover session
      if (enableClampDragging && !isSelected && !hasShownMessage) {
        UserMessageQueue.Instance.addMessage('Click and drag to move clamp');
        setHasShownMessage(true);
      }
    }, [isSelected, hasShownMessage]);

    const handlePointerOut = useCallback(() => {
      setIsHovered(false);
      // Reset the message flag when leaving the clamp so it can show again on next hover
      setHasShownMessage(false);
    }, []);

    const handlePointerDown = useCallback((event: any) => {
      event.stopPropagation();

      if (!enableClampDragging) {
        return;
      }

      // Select the clamp and start dragging immediately (like spindle behavior)
      handleClampClick(clamp.id);

      // Set initial proposed position to current position
      const initialPos = new CNCPoint(position[0], position[1], position[2], CoordinateType.Simulator);
      configState.proposedClampPosition = initialPos;

      // Start dragging immediately
      setIsDragging(true);

      // Disable orbit controls during dragging
      if (orbitControlsRef?.current) {
        orbitControlsRef.current.enabled = false;
      }
    }, [clamp.id, position]);

    const handlePointerUp = useCallback((event: any) => {
      if (isDragging) {
        event.stopPropagation();

        // Apply final drag position to the actual clamp object
        if (configState.proposedClampPosition && job) {
          const targetClamp = job.clamps.find(c => c.id === clamp.id);
          if (targetClamp) {
            // Use the helper function to ensure consistent calculation
            const proposedPos = configState.proposedClampPosition;
            const newOffsets = simulatorPositionToClampOffsets(
              [proposedPos.x, proposedPos.y, proposedPos.z],
              targetClamp.clampXWidth,
              targetClamp.clampYWidth
            );

            // Update clamp position
            targetClamp.clampOffsetX = newOffsets.offsetX;
            targetClamp.clampOffsetY = newOffsets.offsetY;
          }
        }

        // Clear proposed position when done dragging
        configState.proposedClampPosition = null;

        // Notify state manager of the final position when dragging ends
        onDragEnd();
      }

      setIsDragging(false);

      // Re-enable orbit controls
      if (orbitControlsRef?.current) {
        orbitControlsRef.current.enabled = true;
      }
    }, [isDragging, onDragEnd, clamp.id]);

    const handlePointerMove = useCallback((event: any) => {
      if (!isDragging || !enableClampDragging) return;

      event.stopPropagation();

      // Get the intersection point on the spoilboard plane (Z = constant)
      const intersects = event.intersections;
      if (intersects && intersects.length > 0) {
        const point = intersects[0].point;

        // Update proposed position for immediate visual feedback
        // Keep the same Z position (on spoilboard surface), only allow X/Y movement
        const currentZ = configState.proposedClampPosition ? configState.proposedClampPosition.z : position[2];
        const newProposedPos = new CNCPoint(point.x, point.y, currentZ, CoordinateType.Simulator);
        configState.proposedClampPosition = newProposedPos;
      }
    }, [isDragging, position]);

    const handleClick = useCallback((event: any) => {
      // Only handle click if we're not dragging
      if (!isDragging && !enableClampDragging) {
        event.stopPropagation();
        handleClampClick(clamp.id);
      }
    }, [clamp.id, isDragging]);

    return (
      <group position={currentPosition}>
        {/* Main clamp box */}
        <Box
          ref={meshRef}
          position={[0, 0, 0]}
          size={size}
          color={getClampColor()}
          viewStyle={viewStyle}
          opacity={opacity}
          onClick={handleClick}
          onPointerDown={handlePointerDown}
          onPointerUp={handlePointerUp}
          onPointerMove={handlePointerMove}
          onPointerOver={handlePointerOver}
          onPointerOut={handlePointerOut}
        />

        {/* Large invisible collision mesh for easier dragging when in drag mode */}
        {enableClampDragging && (
          <mesh
            onPointerDown={handlePointerDown}
            onPointerUp={handlePointerUp}
            onPointerMove={handlePointerMove}
            onPointerOver={handlePointerOver}
            onPointerOut={handlePointerOut}
            style={{ cursor: isDragging ? 'grabbing' : (enableClampDragging ? 'grab' : 'pointer') }}
          >
            <boxGeometry args={[size[0] * 3, size[1] * 3, size[2] * 3]} />
            <meshBasicMaterial
              transparent={true}
              opacity={0}
              depthWrite={false}
            />
          </mesh>
        )}
      </group>
    );
  };
  return (
    <ObserveMultiProperties
      listenTo={[
        { object: machineState, properties: ['currentWorkZero'] },
        { object: configState, properties: ['selectedClampId', 'proposedClampPosition'] },
        { object: simulatorView, properties: ['clamps'] },
        { object: ConfigurationDataColors.Instance, properties: ['clampTransparency', 'defaultClampColor'] }
      ]}
      control={() => {
        const colors = ConfigurationDataColors.Instance;

        // Only render if job exists with clamps
        if (!job ||
          !job.clamps ||
          job.clamps.length === 0) {
          return null;
        }

        // Also observe job clamps array and material offsets for immediate updates
        // Get spoilboard box for Z positioning
        const spoilboardBox = CoordinateUtil.getSpoilboardBox(machineState);

        // Calculate material corner position using centralized method
        const materialCornerPosition = CoordinateUtil.getMaterialCornerPosition(machineState);
        const materialCornerX = materialCornerPosition.x;
        const materialCornerY = materialCornerPosition.y;

        // Render each clamp individually
        return (
          <group>
            {job.clamps.map((clamp, index) => (
              <ObserveState
                key={clamp.id}
                listenTo={clamp}
                properties={['clampOffsetX', 'clampOffsetY', 'clampXWidth', 'clampYWidth', 'clampHeight', 'clampColor']}
                control={() => {
                  // Calculate clamp position: material corner + clamp offsets, Z on spoilboard surface
                  const clampX = materialCornerX + clamp.clampOffsetX + clamp.clampXWidth / 2;
                  const clampY = materialCornerY + clamp.clampOffsetY + clamp.clampYWidth / 2;
                  const clampZ = spoilboardBox.origin.z + spoilboardBox.height + clamp.clampHeight / 2; // On top of spoilboard

                  // Convert to simulator coordinates for rendering
                  const clampSimPos = CoordinateUtil.toSimulator(
                    new CNCPoint(clampX, clampY, clampZ, CoordinateType.MachineZero)
                  );

                  const isSelected = enableClampDragging && ConfigurationState.Instance.selectedClampId === clamp.id;
                  const displayColor = isSelected ? colors.errorColor : clamp.clampColor;

                  return (
                    <React.Fragment>
                      {enableClampDragging ? (
                        <DraggableBox
                          clamp={clamp}
                          position={[clampSimPos.x, clampSimPos.y, clampSimPos.z]}
                          size={[clamp.clampXWidth, clamp.clampYWidth, clamp.clampHeight]}
                          color={displayColor}
                          viewStyle={simulatorView.clamps}
                          opacity={simulatorView.clamps === ViewStyle.SemiTransparent ? colors.clampTransparency : 1}
                          onDragEnd={handleClampDragEnd}
                        />
                      ) : (
                        <Box
                          position={[clampSimPos.x, clampSimPos.y, clampSimPos.z]}
                          size={[clamp.clampXWidth, clamp.clampYWidth, clamp.clampHeight]}
                          color={displayColor}
                          viewStyle={simulatorView.clamps}
                          opacity={simulatorView.clamps === ViewStyle.SemiTransparent ? colors.clampTransparency : 1}
                          onClick={() => handleClampClick(clamp.id)}
                        />
                      )}
                    </React.Fragment>
                  );
                }}
              />
            ))}
          </group>
        );
      }}
    />
  );
};