import CloseIcon from '@mui/icons-material/Close';
import {
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    Paper,
    Typography
} from '@mui/material';
import { useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { IsChangedStatement } from '../statements/IsChangedStatement';

interface IsChangedStructureDialogProps {
    isChanged: IsChangedStatement;
    open: boolean;
    onClose: () => void;
}

/**
 * IsChangedStructureDialog - Configure which action branches to show/hide
 * Displays pseudo-code visualization with clickable [show]/[hide] links
 */
export function IsChangedStructureDialog(props: IsChangedStructureDialogProps) {
    const { isChanged, open, onClose } = props;
    const colors = ConfigurationDataColors.Instance;

    // Local state for editing (uncommitted changes)
    const [localHideRisingEdgeActions, setLocalHideRisingEdgeActions] = useState(isChanged.hideRisingEdgeActions);
    const [localHideFallingEdgeActions, setLocalHideFallingEdgeActions] = useState(isChanged.hideFallingEdgeActions);

    const handleApply = () => {
        isChanged.hideRisingEdgeActions = localHideRisingEdgeActions;
        isChanged.hideFallingEdgeActions = localHideFallingEdgeActions;
        StateManager.propertyChanged(isChanged, 'hideRisingEdgeActions');
        StateManager.propertyChanged(isChanged, 'hideFallingEdgeActions');
        onClose();
    };

    const handleCancel = () => {
        // Reset local state to current values
        setLocalHideRisingEdgeActions(isChanged.hideRisingEdgeActions);
        setLocalHideFallingEdgeActions(isChanged.hideFallingEdgeActions);
        onClose();
    };

    // Get condition expression for display
    const conditionLogic = isChanged.conditionGroup?.getPLCLogic([]);
    const conditionExpr = conditionLogic && conditionLogic.length > 0 ? conditionLogic[0] : '[condition]';

    // Style definitions matching LogicStructureDialog
    const enabledStyle = {
        color: colors.darkTextColor,
        fontWeight: 'bold',
        fontFamily: 'monospace',
        fontSize: '14px',
        padding: '4px 8px',
        backgroundColor: colors.primaryColor + '20',
        borderRadius: '4px',
        marginBottom: '4px',
        display: 'flex',
        alignItems: 'center',
        gap: 1
    };

    const disabledStyle = {
        color: colors.mutedTextColor,
        fontWeight: 'normal',
        fontFamily: 'monospace',
        fontSize: '14px',
        padding: '4px 8px',
        marginBottom: '4px',
        display: 'flex',
        alignItems: 'center',
        gap: 1
    };

    const strikethrough = {
        textDecoration: 'line-through'
    };

    const linkStyle = {
        color: colors.primaryColor,
        textDecoration: 'none !important',
        cursor: 'pointer',
        fontSize: '11px',
        fontFamily: 'sans-serif',
        fontWeight: 'bold',
        border: `1px solid ${colors.primaryColor}`,
        padding: '2px 6px',
        borderRadius: '3px',
        backgroundColor: colors.lightOverlay,
        '&:hover': {
            backgroundColor: colors.primaryColor,
            color: colors.lightTextColor
        }
    };

    return (
        <Dialog open={open} onClose={handleCancel} maxWidth="sm" fullWidth>
            <DialogTitle sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                backgroundColor: colors.primaryColor,
                color: colors.lightTextColor,
                py: 2,
                px: 3
            }}>
                Configure IsChanged Structure
                <IconButton
                    onClick={handleCancel}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>

            <DialogContent>
                <Box sx={{ mt: 3 }}>
                    <Typography variant="body1" sx={{ mb: 2, color: colors.darkTextColor }}>
                        Click links in the structure below to configure sections. Links appear only when relevant.
                    </Typography>

                    {/* Pseudo-code visualization */}
                    <Paper sx={{
                        p: 2,
                        backgroundColor: colors.lightBackgroundColor,
                        border: `1px solid ${colors.borderColor}`,
                        fontFamily: 'monospace'
                    }}>
                        <Box sx={enabledStyle}>
                            <span>when ({conditionExpr}) changes</span>
                        </Box>

                        {/* Rising Edge Branch - to set (true) */}
                        <Box sx={{ ...(!localHideRisingEdgeActions ? enabledStyle : disabledStyle), ml: 2 }}>
                            <span style={localHideRisingEdgeActions ? strikethrough : undefined}>
                                to set (true) [actions]
                            </span>
                            <Typography
                                component="span"
                                onClick={() => setLocalHideRisingEdgeActions(!localHideRisingEdgeActions)}
                                sx={linkStyle}
                            >
                                [{localHideRisingEdgeActions ? 'show' : 'hide'}]
                            </Typography>
                        </Box>

                        {/* Falling Edge Branch - to reset (false) */}
                        <Box sx={{ ...(!localHideFallingEdgeActions ? enabledStyle : disabledStyle), ml: 2 }}>
                            <span style={localHideFallingEdgeActions ? strikethrough : undefined}>
                                to reset (false) [actions]
                            </span>
                            <Typography
                                component="span"
                                onClick={() => setLocalHideFallingEdgeActions(!localHideFallingEdgeActions)}
                                sx={linkStyle}
                            >
                                [{localHideFallingEdgeActions ? 'show' : 'hide'}]
                            </Typography>
                        </Box>
                    </Paper>
                </Box>
            </DialogContent>

            <DialogActions sx={{
                p: 2,
                gap: 1,
                justifyContent: 'flex-end',
                borderTop: `1px solid ${colors.borderColor}`
            }}>
                <Button onClick={handleCancel} variant="outlined">
                    Cancel
                </Button>
                <Button onClick={handleApply} variant="contained">
                    Apply
                </Button>
            </DialogActions>
        </Dialog>
    );
}
