import { StateManager } from '../utils/statemanager/StateManager';

/**
 * Centralized state management for the milling workflow stages.
 * Tracks stage progression, editor content, selection method, and navigation state.
 */
export class MillingWorkflowState {
    private static _instance: MillingWorkflowState;

    private _activeStage: number = 0;
    private _completedStages: Set<number> = new Set();

    // Editor state
    private _editorGCode: string = '';

    // Selection method tracking
    private _selectionMethod: 'none' | 'file' | 'recent' | 'upload' | 'wizard' | 'editor' = 'none';
    private _selectedTab: 'files' | 'recent' | 'wizards' | 'editor' = 'files';

    // Stage definitions
    private _stages: string[] = ['Select GCode', 'Preview', 'Material & Clamps', 'Analysis', 'Run Job'];

    private constructor() { }

    public static get Instance(): MillingWorkflowState {
        if (!MillingWorkflowState._instance) {
            MillingWorkflowState._instance = new MillingWorkflowState();
        }
        return MillingWorkflowState._instance;
    }

    // Active stage management
    public get activeStage(): number {
        return this._activeStage;
    }

    public set activeStage(value: number) {
        if (value >= 0 && value < this._stages.length && value !== this._activeStage) {
            this._activeStage = value;
            StateManager.propertyChanged(this, 'activeStage');
        }
    }

    // Completed stages management
    public get completedStages(): Set<number> {
        return new Set(this._completedStages);
    }

    public markStageCompleted(stage: number): void {
        if (!this._completedStages.has(stage)) {
            this._completedStages.add(stage);
            StateManager.propertyChanged(this, 'completedStages');
        }
    }

    public clearStageCompletion(fromStage: number): void {
        const newCompleted = new Set(Array.from(this._completedStages).filter(s => s < fromStage));
        this._completedStages = newCompleted;
        StateManager.propertyChanged(this, 'completedStages');
    }

    public isStageCompleted(stage: number): boolean {
        return this._completedStages.has(stage);
    }

    // Editor G-code
    public get editorGCode(): string {
        return this._editorGCode;
    }

    public set editorGCode(value: string) {
        if (value !== this._editorGCode) {
            this._editorGCode = value;
            StateManager.propertyChanged(this, 'editorGCode');
        }
    }

    // Selection method
    public get selectionMethod(): 'none' | 'file' | 'recent' | 'upload' | 'wizard' | 'editor' {
        return this._selectionMethod;
    }

    public set selectionMethod(value: 'none' | 'file' | 'recent' | 'upload' | 'wizard' | 'editor') {
        if (value !== this._selectionMethod) {
            this._selectionMethod = value;
            StateManager.propertyChanged(this, 'selectionMethod');
        }
    }

    // Selected tab
    public get selectedTab(): 'files' | 'recent' | 'wizards' | 'editor' {
        return this._selectedTab;
    }

    public set selectedTab(value: 'files' | 'recent' | 'wizards' | 'editor') {
        if (value !== this._selectedTab) {
            this._selectedTab = value;
            StateManager.propertyChanged(this, 'selectedTab');
        }
    }

    // Stage definitions
    public get stages(): string[] {
        return [...this._stages];
    }

    public get currentStageName(): string {
        return this._stages[this._activeStage] || '';
    }

    // Navigation helpers
    public canGoBack(): boolean {
        return this._activeStage > 0;
    }

    public canGoForward(): boolean {
        return this._activeStage < this._stages.length - 1;
    }

    public isStageClickable(stage: number): boolean {
        // Can click on completed stages or the next available stage
        const maxCompleted = Math.max(...Array.from(this._completedStages), -1);
        return stage <= maxCompleted + 1;
    }

    // Navigation actions
    public goToNextStage(): void {
        if (this.canGoForward()) {
            this.markStageCompleted(this._activeStage);
            this.activeStage = this._activeStage + 1;
        }
    }

    public goToPreviousStage(): void {
        if (this.canGoBack()) {
            const newStage = this._activeStage - 1;
            this.clearStageCompletion(newStage);
            this.activeStage = newStage;
        }
    }

    public goToStage(stage: number): void {
        if (this.isStageClickable(stage)) {
            if (stage < this._activeStage) {
                this.clearStageCompletion(stage);
            }
            this.activeStage = stage;
        }
    }

    // Workflow state
    public hasEditorContent(): boolean {
        return this._editorGCode.trim().length > 0;
    }

    public isInEditorTab(): boolean {
        return this._selectedTab === 'editor';
    }

    public isReadyForPreview(): boolean {
        // Ready if we have editor content in editor tab or a selection method is set
        return (this.isInEditorTab() && this.hasEditorContent()) ||
            this._selectionMethod !== 'none';
    }

    // Reset workflow
    public reset(): void {
        this._activeStage = 0;
        this._completedStages.clear();
        this._editorGCode = '';
        this._selectionMethod = 'none';
        this._selectedTab = 'files';

        StateManager.propertyChanged(this, 'activeStage');
        StateManager.propertyChanged(this, 'completedStages');
        StateManager.propertyChanged(this, 'editorGCode');
        StateManager.propertyChanged(this, 'selectionMethod');
        StateManager.propertyChanged(this, 'selectedTab');
    }

    // Clear selection (when going back from preview to select)
    public clearSelection(): void {
        this._selectionMethod = 'none';
        StateManager.propertyChanged(this, 'selectionMethod');
    }
}
