  /**
   * Reset system default PLC program to defaults
   * Fetches from backend API if available, otherwise falls back to public file
   */
  public async resetPLCSystemDefaultOnly(): Promise<void> {
    // WORKAROUND: Breaking circular dependency - UserMessageQueue uses DataManager
    const { UserMessageQueue } = await import('./UserMessageQueue');
    const { BackendAvailabilityChecker } = await import('../utils/BackendAvailabilityChecker');
    const { PLCProgram } = await import('../centroid/plc/data/PLCProgram');
    const { PLCProgramType } = await import('../centroid/plc/data/PLCUtilities');
    const { StateManager } = await import('../utils/statemanager/StateManager');

    const backendAvailable = await BackendAvailabilityChecker.isBackendAvailable();
    const program = PLCProgram.Instance(PLCProgramType.SystemDefault);

    try {
      if (backendAvailable) {
        // Try to get from backend API
        try {
          const jsonText = await Machine.getInstance().setup.GetDefaultPLC();
          const json = JSON.parse(jsonText);
          program.fromJSON(json);

          // Save to file
          await this.store(DataFileConstants.PLC_SYSTEM_DEFAULT, program);

          // Trigger state update
          StateManager.propertyChanged(program, 'stages');

          UserMessageQueue.Instance.addMessage('✓ PLC System Default program reset from backend (use Install to apply changes)');
          return;
        } catch (apiError) {
          Logger.Instance.logError(LogCategory.DataManager, 'Failed to get default from backend API, falling back to public file:', apiError);
        }
      }

      // Fallback: Load from public file
      const response = await fetch('/systemdefault.json');
      if (!response.ok) {
        throw new Error('Failed to fetch systemdefault.json');
      }
      const json = await response.json();
      program.fromJSON(json);

      // Save to file
      await this.store(DataFileConstants.PLC_SYSTEM_DEFAULT, program);

      // Trigger state update
      StateManager.propertyChanged(program, 'stages');

      UserMessageQueue.Instance.addMessage('✓ PLC System Default program reset from public file (simulator mode)');
    } catch (error) {
      Logger.Instance.logError(LogCategory.DataManager, 'Failed to reset PLC System Default program:', error);
      UserMessageQueue.Instance.addMessage('❌ Failed to reset PLC System Default program');
      throw error;
    }
  }

  /**
   * Reset system PLC program to defaults
   * Fetches from backend API if available, otherwise falls back to public file
   */
  public async resetPLCSystemOnly(): Promise<void> {
    // WORKAROUND: Breaking circular dependency - UserMessageQueue uses DataManager
    const { UserMessageQueue } = await import('./UserMessageQueue');
    const { BackendAvailabilityChecker } = await import('../utils/BackendAvailabilityChecker');
    const { PLCProgram } = await import('../centroid/plc/data/PLCProgram');
    const { PLCProgramType } = await import('../centroid/plc/data/PLCUtilities');
    const { StateManager } = await import('../utils/statemanager/StateManager');

    const backendAvailable = await BackendAvailabilityChecker.isBackendAvailable();
    const program = PLCProgram.Instance(PLCProgramType.System);

    try {
      if (backendAvailable) {
        // Try to get from backend API (System uses same defaults as SystemDefault)
        try {
          const jsonText = await Machine.getInstance().setup.GetDefaultPLC();
          const json = JSON.parse(jsonText);
          program.fromJSON(json);

          // Save to file
          await this.store(DataFileConstants.PLC_SYSTEM, program);

          // Trigger state update
          StateManager.propertyChanged(program, 'stages');

          UserMessageQueue.Instance.addMessage('✓ PLC System program reset from backend (use Install to apply changes)');
          return;
        } catch (apiError) {
          Logger.Instance.logError(LogCategory.DataManager, 'Failed to get default from backend API, falling back to public file:', apiError);
        }
      }

      // Fallback: Load from public file (system.json or fallback to systemdefault.json)
      let json;
      try {
        const response = await fetch('/system.json');
        if (response.ok) {
          json = await response.json();
        } else {
          // Fallback to systemdefault.json if system.json doesn't exist
          const fallbackResponse = await fetch('/systemdefault.json');
          if (!fallbackResponse.ok) {
            throw new Error('Failed to fetch system.json or systemdefault.json');
          }
          json = await fallbackResponse.json();
        }
      } catch (fetchError) {
        throw new Error('Failed to fetch default PLC files');
      }

      program.fromJSON(json);

      // Save to file
      await this.store(DataFileConstants.PLC_SYSTEM, program);

      // Trigger state update
      StateManager.propertyChanged(program, 'stages');

      UserMessageQueue.Instance.addMessage('✓ PLC System program reset from public file (simulator mode)');
    } catch (error) {
      Logger.Instance.logError(LogCategory.DataManager, 'Failed to reset PLC System program:', error);
      UserMessageQueue.Instance.addMessage('❌ Failed to reset PLC System program');
      throw error;
    }
  }

