  /**
   * Save system default PLC program individually
   */
  public async savePLCSystemDefaultIndividual(): Promise<void> {
    try {
      const plcProgram = PLCProgram.Instance(PLCProgramType.SystemDefault);
      await this.store(DataFileConstants.PLC_SYSTEM_DEFAULT, plcProgram);
    } catch (error) {
      console.error('Failed to save System Default PLC:', error);
      const { UserMessageQueue } = require('./UserMessageQueue');
      UserMessageQueue.Instance.addPersistentError(
        `Failed to save System Default PLC: ${error.message || 'Unknown error'}. Your changes were NOT saved.`
      );
      throw error;
    }
  }

  /**
   * Save system PLC program individually
   */
  public async savePLCSystemIndividual(): Promise<void> {
    try {
      const plcProgram = PLCProgram.Instance(PLCProgramType.System) as PLCProgramSystem;
      // Increment update version on every save
      plcProgram.incrementUpdateVersion();
      await this.store(DataFileConstants.PLC_SYSTEM, plcProgram);
    } catch (error) {
      console.error('Failed to save System PLC:', error);
      const { UserMessageQueue } = require('./UserMessageQueue');
      UserMessageQueue.Instance.addPersistentError(
        `Failed to save System PLC: ${error.message || 'Unknown error'}. Your changes were NOT saved.`
      );
      throw error;
    }
  }


