import { Close as CloseIcon } from '@mui/icons-material';
import {
  Box,
  Button,
  Checkbox,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControlLabel,
  FormGroup,
  IconButton,
  Paper,
  Slider,
  Switch,
  Tab,
  Tabs,
  Typography
} from '@mui/material';
import React, { useState } from 'react';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { LogCategory, Logger, LogLevel } from '../../../utils/Logger';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { LogViewer } from '../../Common/LogViewer';

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`log-tabpanel-${index}`}
      aria-labelledby={`log-tab-${index}`}
      {...other}
    >
      {value === index && (
        <Box sx={{ height: '100%' }}>
          {children}
        </Box>
      )}
    </div>
  );
}

export function LogViewerTab() {
  const colors = ConfigurationDataColors.Instance;
  const [activeTab, setActiveTab] = useState(0);
  const [categoryDialogOpen, setCategoryDialogOpen] = useState(false);

  const handleTabChange = (event: React.SyntheticEvent, newValue: number) => {
    setActiveTab(newValue);
  };

  const LogConfigurationContent = () => {
    const config = ConfigurationData.Instance;

    const handleUpdateLoggerConfiguration = (config: ConfigurationData) => {
      const enabledLevels = new Set<LogLevel>();
      if (config.logInfoEnabled) enabledLevels.add(LogLevel.Info);
      if (config.logDebugEnabled) enabledLevels.add(LogLevel.Debug);
      if (config.logErrorEnabled) enabledLevels.add(LogLevel.Error);

      const enabledCategories = config.logEnabledCategories.length === 0
        ? new Set(Object.values(LogCategory))
        : new Set(config.logEnabledCategories);

      Logger.Instance.updateConfiguration({
        enabledLevels,
        enabledCategories,
        outputToConsole: config.logOutputToConsole,
        maxLogEntries: config.logMaxEntries
      });
    };

    const CategorySelectionDialog = () => {
      const allCategories = Object.values(LogCategory);
      const [selectedCategories, setSelectedCategories] = useState<string[]>(
        config.logEnabledCategories.length === 0 ? allCategories : config.logEnabledCategories
      );

      const handleSave = () => {
        config.logEnabledCategories = selectedCategories;
        handleUpdateLoggerConfiguration(config);
        setCategoryDialogOpen(false);
      };

      const handleSelectAll = () => {
        setSelectedCategories(selectedCategories.length === allCategories.length ? [] : allCategories);
      };

      return (
        <Dialog open={categoryDialogOpen} onClose={() => setCategoryDialogOpen(false)} maxWidth="sm" fullWidth>
          <DialogTitle sx={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            backgroundColor: colors.primaryColor,
            color: colors.lightTextColor,
            py: 2,
            px: 3
          }}>
            Configure Log Categories
            <IconButton
              onClick={() => setCategoryDialogOpen(false)}
              sx={{
                color: colors.lightTextColor,
                '&:hover': {
                  backgroundColor: colors.lightOverlay
                }
              }}
            >
              <CloseIcon />
            </IconButton>
          </DialogTitle>
          <DialogContent>
            <Box sx={{ mt: 3, mb: 2 }}>
              <Button variant="text" onClick={handleSelectAll}>
                {selectedCategories.length === allCategories.length ? 'Deselect All' : 'Select All'}
              </Button>
            </Box>
            <FormGroup>
              {allCategories.map((category) => (
                <FormControlLabel
                  key={category}
                  control={
                    <Checkbox
                      checked={selectedCategories.includes(category)}
                      onChange={(e) => {
                        if (e.target.checked) {
                          setSelectedCategories([...selectedCategories, category]);
                        } else {
                          setSelectedCategories(selectedCategories.filter(c => c !== category));
                        }
                      }}
                    />
                  }
                  label={category}
                />
              ))}
            </FormGroup>
          </DialogContent>
          <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${colors.borderColor}` }}>
            <Button onClick={() => setCategoryDialogOpen(false)}>Cancel</Button>
            <Button
              onClick={handleSave}
              variant="contained"
              sx={{
                backgroundColor: colors.primaryColor,
                '&:hover': {
                  backgroundColor: colors.primaryColor,
                  filter: 'brightness(0.9)'
                }
              }}
            >
              Save
            </Button>
          </DialogActions>
        </Dialog>
      );
    };

    return (
      <Box sx={{ p: 3, height: '100%', overflow: 'auto' }}>
        <Typography variant="h6" gutterBottom>
          Log Configuration
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
          Configure logging behavior and output preferences
        </Typography>

        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
          <Box>
            <Typography variant="subtitle1" gutterBottom>Log Levels</Typography>
            <FormControlLabel
              control={
                <Switch
                  checked={config.logInfoEnabled}
                  onChange={(e) => {
                    config.logInfoEnabled = e.target.checked;
                    handleUpdateLoggerConfiguration(config);
                  }}
                />
              }
              label="Info Messages"
            />
            <FormControlLabel
              control={
                <Switch
                  checked={config.logDebugEnabled}
                  onChange={(e) => {
                    config.logDebugEnabled = e.target.checked;
                    handleUpdateLoggerConfiguration(config);
                  }}
                />
              }
              label="Debug Messages"
            />
            <FormControlLabel
              control={
                <Switch
                  checked={config.logErrorEnabled}
                  onChange={(e) => {
                    config.logErrorEnabled = e.target.checked;
                    handleUpdateLoggerConfiguration(config);
                  }}
                />
              }
              label="Error Messages"
            />
          </Box>

          <Box>
            <Typography variant="subtitle1" gutterBottom>Output Options</Typography>
            <FormControlLabel
              control={
                <Switch
                  checked={config.logOutputToConsole}
                  onChange={(e) => {
                    config.logOutputToConsole = e.target.checked;
                    handleUpdateLoggerConfiguration(config);
                  }}
                />
              }
              label="Output to Browser Console"
            />
          </Box>

          <Box>
            <Typography variant="subtitle1" gutterBottom>Categories</Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
              {config.logEnabledCategories.length === 0
                ? 'All categories enabled'
                : `${config.logEnabledCategories.length} categories enabled`}
            </Typography>
            <Button variant="outlined" onClick={() => setCategoryDialogOpen(true)}>
              Configure Categories
            </Button>
          </Box>

          <Box>
            <Typography variant="subtitle1" gutterBottom>
              Max Log Entries: {config.logMaxEntries}
            </Typography>
            <Slider
              value={config.logMaxEntries}
              min={100}
              max={10000}
              step={100}
              onChange={(_, value) => {
                config.logMaxEntries = value as number;
                handleUpdateLoggerConfiguration(config);
              }}
              valueLabelDisplay="auto"
            />
          </Box>
        </Box>

        <CategorySelectionDialog />
      </Box>
    );
  };

  const LogConfigurationContentWithObserver = () => (
    <ObserveMultiProperties
      listenTo={[
        { object: ConfigurationData.Instance, properties: ['logOutputToConsole', 'logDebugEnabled', 'logInfoEnabled', 'logErrorEnabled', 'logMaxEntries', 'logEnabledCategories'] }
      ]}
      control={() => <LogConfigurationContent />}
    />
  );

  return (
    <Box sx={{ width: '100%', height: '100%', display: 'flex', flexDirection: 'column' }}>
      <Paper sx={{ borderBottom: 1, borderColor: 'divider' }}>
        <Tabs value={activeTab} onChange={handleTabChange} aria-label="log tabs">
          <Tab label="Log Viewer" />
          <Tab label="Configuration" />
        </Tabs>
      </Paper>

      <Box sx={{ flex: 1, overflow: 'hidden' }}>
        <TabPanel value={activeTab} index={0}>
          <LogViewer />
        </TabPanel>
        <TabPanel value={activeTab} index={1}>
          <LogConfigurationContentWithObserver />
        </TabPanel>
      </Box>
    </Box>
  );
}
