import {
    FormControlLabel,
    Grid,
    Paper,
    Switch,
    Typography,
} from '@mui/material';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';

export function FeaturesSection() {
    const config = ConfigurationData.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12}>
                <Paper sx={{ p: 3 }}>
                    <Typography variant="h6" gutterBottom>
                        Navigation Features
                    </Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                        Control which features are visible in the navigation menu. Features are hidden by default.
                    </Typography>

                    <Grid container spacing={2}>
                        <Grid item xs={12} sm={6} md={4}>
                            <ObserveState
                                key="show-learning-feature"
                                listenTo={config}
                                properties={['showLearningFeature']}
                                control={() => (
                                    <FormControlLabel
                                        control={
                                            <Switch
                                                checked={config.showLearningFeature}
                                                onChange={(e) => config.showLearningFeature = e.target.checked}
                                            />
                                        }
                                        label="Learning"
                                    />
                                )}
                            />
                        </Grid>

                        <Grid item xs={12} sm={6} md={4}>
                            <ObserveState
                                key="show-turning-feature"
                                listenTo={config}
                                properties={['showTurningFeature']}
                                control={() => (
                                    <FormControlLabel
                                        control={
                                            <Switch
                                                checked={config.showTurningFeature}
                                                onChange={(e) => config.showTurningFeature = e.target.checked}
                                            />
                                        }
                                        label="Turning"
                                    />
                                )}
                            />
                        </Grid>

                        <Grid item xs={12} sm={6} md={4}>
                            <ObserveState
                                key="show-laser-feature"
                                listenTo={config}
                                properties={['showLaserFeature']}
                                control={() => (
                                    <FormControlLabel
                                        control={
                                            <Switch
                                                checked={config.showLaserFeature}
                                                onChange={(e) => config.showLaserFeature = e.target.checked}
                                            />
                                        }
                                        label="Laser"
                                    />
                                )}
                            />
                        </Grid>
                    </Grid>
                </Paper>
            </Grid>
        </Grid>
    );
}
