import { MachineInterfaceManager } from './MachineInterfaceManager';

/**
 * Utility for checking if the backend CNC server is available
 */
export class BackendAvailabilityChecker {
    private static cachedResult: boolean | null = null;

    /**
     * Check if backend server is available using lightweight status endpoint
     * @returns Promise<boolean> - true if backend is available, false otherwise
     */
    public static async isBackendAvailable(): Promise<boolean> {
        // Return cached result if available
        if (this.cachedResult !== null) {
            return this.cachedResult;
        }

        try {
            // Get service configuration (defaults to localhost:5000)
            const config = MachineInterfaceManager.Instance.getServiceConfiguration();

            // Use lightweight status endpoint - less overhead than other API calls
            const { CNCServerApi } = await import('../services/src/apis/CNCServerApi');
            const serverApi = new CNCServerApi(config);

            // Try to get server status
            await serverApi.apiCNCServerStatusGet();

            // Success! Backend is available
            this.cachedResult = true;
            return true;
        } catch (error) {
            // Backend not available
            this.cachedResult = false;
            return false;
        }
    }

    /**
     * Reset cached availability check
     * Call this when connectivity might have changed
     */
    public static resetCache(): void {
        this.cachedResult = null;
    }

    /**
     * Get cached result without making a new check
     * @returns boolean | null - cached result or null if not yet checked
     */
    public static getCachedResult(): boolean | null {
        return this.cachedResult;
    }
}
