import { CheckCircle as CheckCircleIcon, Check as CheckIcon, Close as CloseIcon, Error as ErrorIcon, HourglassEmpty as LoadingIcon } from '@mui/icons-material';
import { Box, Button, Checkbox, CircularProgress, Dialog, DialogActions, DialogContent, DialogTitle, FormControlLabel, IconButton, List, ListItem, ListItemIcon, ListItemText, Radio, RadioGroup, Typography } from '@mui/material';
import { useCallback, useEffect, useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../data/ConfigurationState';
import { DataManager } from '../../../data/DataManager';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import { LogCategory, Logger } from '../../../utils/Logger';
import { MachineInstaller } from '../../../utils/MachineInstaller';
import { PLCProgram, PLCProgramSystem } from '../data/PLCProgram';
import { PLCProgramType } from '../data/PLCUtilities';

interface MachineInstallationDialogProps {
    open: boolean;
    onClose: () => void;
    onSuccess?: () => void;
}

interface ChecklistItem {
    label: string;
    status: 'pending' | 'running' | 'success' | 'error';
    message?: string;
}

type VersionBump = 'major' | 'minor';

/**
 * Dialog for installing PLC program and machine configuration
 * Shows progress checklist and version management
 */
export function MachineInstallationDialog({ open, onClose, onSuccess }: MachineInstallationDialogProps) {
    const colors = ConfigurationDataColors.Instance;
    const [checks, setChecks] = useState<ChecklistItem[]>([
        { label: 'Generate PLC code', status: 'pending' },
        { label: 'Check for changes', status: 'pending' },
        { label: 'Test compilation', status: 'pending' }
    ]);

    const [versionBump, setVersionBump] = useState<VersionBump>('minor');
    const [applyConfiguration, setApplyConfiguration] = useState(true);
    const [isPreCheckComplete, setIsPreCheckComplete] = useState(false);
    const [canInstall, setCanInstall] = useState(false);
    const [isInstalling, setIsInstalling] = useState(false);
    const [installedVersion, setInstalledVersion] = useState('0.0');
    const [currentVersion, setCurrentVersion] = useState('1.0');
    const [newVersion, setNewVersion] = useState('1.1');
    const [hasChanges, setHasChanges] = useState(false);
    const [plcCodeChanged, setPlcCodeChanged] = useState(false); // Track if PLC code actually changed
    const [plcWasInstalled, setPlcWasInstalled] = useState(false); // Track if PLC was installed (for reboot message)
    const [compilationResult, setCompilationResult] = useState<any>(null);
    const [installationStatus, setInstallationStatus] = useState<string>('');
    const [installationError, setInstallationError] = useState<string>('');

    // Reset state when dialog opens/closes
    useEffect(() => {
        if (open) {
            // Save PLC programs before installation
            const savePrograms = async () => {
                try {
                    await DataManager.Instance.savePLCSystemIndividual();
                    await DataManager.Instance.savePLCSystemDefaultIndividual();
                } catch (error) {
                    Logger.Instance.logError(LogCategory.System, 'Failed to save PLC programs:', error);
                }
            };
            savePrograms();

            // Reset all state when dialog opens
            setIsPreCheckComplete(false);
            setCanInstall(false);
            setHasChanges(false);
            setPlcCodeChanged(false);
            setPlcWasInstalled(false);
            setCompilationResult(null);
            setInstallationStatus('');
            setInstallationError('');
            setIsInstalling(false);
            setChecks([
                { label: 'Generate PLC code', status: 'pending' },
                { label: 'Check for changes', status: 'pending' },
                { label: 'Test compilation', status: 'pending' }
            ]);

            // Run pre-checks after state is reset
            // Use setTimeout to ensure state updates have been applied
            setTimeout(() => {
                runPreChecks();
            }, 0);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [open]);

    // Update version display when bump type changes
    useEffect(() => {
        const system = PLCProgram.Instance(PLCProgramType.System) as PLCProgramSystem;
        const current = system.getVersionString();
        setCurrentVersion(current);

        // Get installed version from server
        const installed = ConfigurationState.Instance.installedPLCVersion;
        setInstalledVersion(installed);

        const [major, minor] = current.split('.').map(Number);
        if (versionBump === 'major') {
            setNewVersion(`${major + 1}.0`);
        } else {
            setNewVersion(`${major}.${minor + 1}`);
        }
    }, [versionBump]);

    const updateCheckStatus = (index: number, status: ChecklistItem['status'], message?: string) => {
        setChecks(prev => prev.map((check, i) =>
            i === index ? { ...check, status, message } : check
        ));
    };

    const runPreChecks = useCallback(async () => {
        try {
            // Check 1: Generate PLC code
            updateCheckStatus(0, 'running');
            await new Promise(resolve => setTimeout(resolve, 300)); // Brief delay for UX
            const system = PLCProgram.Instance(PLCProgramType.System) as PLCProgramSystem;
            const plcCode = system.generateCompletePLCCode();
            const lines = plcCode.split('\n');
            updateCheckStatus(0, 'success', `Generated ${lines.length} lines`);
            setCurrentVersion(system.getVersionString());

            // Check 2: Check for changes vs installed
            updateCheckStatus(1, 'running');
            await new Promise(resolve => setTimeout(resolve, 300));

            try {
                const comparison = await MachineInstaller.comparePLCWithInstalled();

                if (!comparison.installedFileExists) {
                    updateCheckStatus(1, 'success', 'No installed PLC found - this will be first installation');
                    setHasChanges(true);
                    setPlcCodeChanged(true); // PLC will be installed for the first time
                    setCanInstall(true);
                } else if (comparison.isDifferent) {
                    updateCheckStatus(1, 'success', 'Changes detected - ready to install');
                    setHasChanges(true);
                    setPlcCodeChanged(true); // PLC code has changed and needs to be installed
                    setCanInstall(true);
                } else {
                    updateCheckStatus(1, 'success', 'No changes detected - already up to date');
                    setHasChanges(false);
                    setPlcCodeChanged(false); // PLC code hasn't changed
                    // Still allow installation if user wants to apply configuration
                    setCanInstall(true);
                }
            } catch (error) {
                Logger.Instance.logError(LogCategory.System, 'Failed to compare PLC:', error);
                updateCheckStatus(1, 'error', 'Could not compare with installed PLC');
                setHasChanges(true);
                setPlcCodeChanged(true); // Assume PLC changed if we can't verify
                setCanInstall(true); // Allow installation even if comparison fails
            }

            // Check 3: Test compilation
            updateCheckStatus(2, 'running');
            await new Promise(resolve => setTimeout(resolve, 300));

            try {
                const compilationResult = await MachineInstaller.testCompilePLC();

                // Log the full result for debugging
                console.log('PLC Compilation Result:', JSON.stringify(compilationResult, null, 2));

                setCompilationResult(compilationResult);

                if (compilationResult.success) {
                    const warnings = compilationResult.issues?.length || 0;
                    if (warnings > 0) {
                        updateCheckStatus(2, 'success', `Compiled successfully with ${warnings} warning(s)`);
                    } else {
                        updateCheckStatus(2, 'success', 'Compiled successfully with no errors');
                    }
                } else {
                    const errorCount = compilationResult.issues?.length || 0;
                    const outputLines = compilationResult.compilerOutput?.length || 0;

                    if (errorCount > 0) {
                        updateCheckStatus(2, 'error', `Compilation failed with ${errorCount} error(s) - see details below`);
                    } else if (outputLines > 0) {
                        updateCheckStatus(2, 'error', `Compilation failed - check compiler output below (${outputLines} lines)`);
                    } else {
                        updateCheckStatus(2, 'error', 'Compilation failed - no error details provided by server');
                    }
                    setCanInstall(false);
                }
            } catch (error) {
                Logger.Instance.logError(LogCategory.System, 'Failed to compile PLC:', error);
                updateCheckStatus(2, 'error', `Compilation test failed: ${error}`);
                setCanInstall(false);
            }

            setIsPreCheckComplete(true);
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Pre-check failed:', error);
            UserMessageQueue.Instance.addMessage('❌ Pre-check failed');
        }
    }, []); // Empty dependencies since updateCheckStatus and setters are stable

    const handleInstall = async () => {
        if (isInstalling) return;

        setIsInstalling(true);
        setInstallationStatus('Saving PLC programs...');
        setInstallationError('');

        try {
            // Save PLC programs first (like the Save button in PLCEditorApp)
            try {
                await DataManager.Instance.savePLCSystemIndividual();
                await DataManager.Instance.savePLCSystemDefaultIndividual();
            } catch (error) {
                Logger.Instance.logError(LogCategory.System, 'Failed to save PLC programs:', error);
                throw new Error(`Failed to save PLC programs: ${error instanceof Error ? error.message : String(error)}`);
            }

            // Update version
            setInstallationStatus('Updating version...');
            const system = PLCProgram.Instance(PLCProgramType.System) as PLCProgramSystem;
            if (versionBump === 'major') {
                system.incrementMajorVersion();
            } else {
                system.incrementMinorVersion();
            }

            // Update the displayed version after increment
            const updatedVersion = system.getVersionString();
            setNewVersion(updatedVersion);
            setCurrentVersion(updatedVersion);

            // Perform installation
            if (applyConfiguration) {
                setInstallationStatus('Installing PLC and configuration...');
                const result = await MachineInstaller.installCompleteMachine();

                if (result.success) {
                    // Only set plcWasInstalled if PLC code actually changed (requires reboot)
                    if (plcCodeChanged) {
                        setPlcWasInstalled(true);
                    }
                    const successMsg = `✓ Machine installed successfully (v${system.getVersionString()})`;
                    setInstallationStatus(successMsg);
                    setIsInstalling(false);

                    // Don't close dialog - let user read the message and close manually
                    // if (onSuccess) onSuccess();
                } else {
                    const errorMsg = `Installation failed: ${result.message || 'Unknown error'}`;
                    setInstallationError(errorMsg);
                    Logger.Instance.logError(LogCategory.System, '❌ ' + errorMsg);
                    UserMessageQueue.Instance.addMessage('❌ ' + errorMsg);
                    setIsInstalling(false);
                }
            } else {
                setInstallationStatus('Installing PLC...');
                const result = await MachineInstaller.installPLC();

                if (result.installationSuccess) {
                    // PLC-only installation always changes PLC code (requires reboot)
                    setPlcWasInstalled(true);
                    const successMsg = `✓ PLC installed successfully (v${system.getVersionString()})`;
                    setInstallationStatus(successMsg);
                    setIsInstalling(false);

                    // Don't close dialog - let user read the message and close manually
                    // if (onSuccess) onSuccess();
                } else {
                    const errorMsg = `PLC installation failed: ${result.message || 'Unknown error'}`;
                    setInstallationError(errorMsg);
                    Logger.Instance.logError(LogCategory.System, '❌ ' + errorMsg);
                    UserMessageQueue.Instance.addMessage('❌ ' + errorMsg);
                    setIsInstalling(false);
                }
            }
        } catch (error) {
            const errorMsg = `Installation exception: ${error instanceof Error ? error.message : String(error)}`;
            setInstallationError(errorMsg);
            Logger.Instance.logError(LogCategory.System, '❌ Installation failed:', error);
            UserMessageQueue.Instance.addMessage('❌ ' + errorMsg);
            setIsInstalling(false);
        }
    };

    const handleClose = () => {
        if (!isInstalling) {
            onClose();
        }
    };

    const getStatusIcon = (status: ChecklistItem['status']) => {
        switch (status) {
            case 'success':
                return <CheckIcon sx={{ color: colors.successColor }} />;
            case 'error':
                return <ErrorIcon sx={{ color: colors.errorColor }} />;
            case 'running':
                return <LoadingIcon sx={{ color: colors.primaryColor, animation: 'spin 1s linear infinite', '@keyframes spin': { '0%': { transform: 'rotate(0deg)' }, '100%': { transform: 'rotate(360deg)' } } }} />;
            default:
                return <Box sx={{ width: 24, height: 24 }} />;
        }
    };

    return (
        <Dialog
            open={open}
            onClose={handleClose}
            maxWidth="md"
            fullWidth
            PaperProps={{
                sx: {
                    minHeight: '500px'
                }
            }}
        >
            <DialogTitle
                sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    backgroundColor: colors.primaryColor,
                    color: colors.lightTextColor,
                    py: 2,
                    px: 3
                }}
            >
                <Typography variant="h6">Install PLC and Machine Configuration</Typography>
                <IconButton
                    onClick={handleClose}
                    disabled={isInstalling}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: `${colors.lightTextColor}1A`
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>

            <DialogContent sx={{ py: 3 }}>
                {/* Pre-check Progress */}
                <Box sx={{ mb: 3 }}>
                    <Typography variant="subtitle1" sx={{ mb: 2, fontWeight: 'bold' }}>
                        Pre-Installation Checks
                    </Typography>
                    <List dense>
                        {checks.map((check, index) => (
                            <ListItem key={index}>
                                <ListItemIcon>
                                    {getStatusIcon(check.status)}
                                </ListItemIcon>
                                <ListItemText
                                    primary={check.label}
                                    secondary={check.message}
                                    secondaryTypographyProps={{
                                        sx: {
                                            color: check.status === 'error' ? colors.errorColor : undefined
                                        }
                                    }}
                                />
                            </ListItem>
                        ))}
                    </List>
                </Box>

                {/* Compilation Errors/Warnings Display */}
                {isPreCheckComplete && compilationResult && !compilationResult.success && (compilationResult.issues?.length > 0 || compilationResult.compilerOutput?.length > 0) && (
                    <Box sx={{ mb: 3, p: 2, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, borderRadius: 1, border: `1px solid ${colors.errorColor}` }}>
                        <Typography variant="subtitle1" sx={{ mb: 2, fontWeight: 'bold', color: colors.errorColor }}>
                            Compilation Errors
                        </Typography>

                        {compilationResult.issues && compilationResult.issues.length > 0 && (
                            <Box sx={{ mb: 2 }}>
                                <Typography variant="body2" sx={{ fontWeight: 'bold', mb: 1 }}>Issues:</Typography>
                                <Box sx={{ maxHeight: '200px', overflow: 'auto', backgroundColor: colors.lightTextColor, p: 1.5, borderRadius: 1, fontFamily: 'monospace', fontSize: '0.85rem' }}>
                                    {compilationResult.issues.map((issue: string, index: number) => (
                                        <Box key={index} sx={{ mb: 0.5, color: colors.errorColor }}>
                                            {issue}
                                        </Box>
                                    ))}
                                </Box>
                            </Box>
                        )}

                        {compilationResult.compilerOutput && compilationResult.compilerOutput.length > 0 && (
                            <Box>
                                <Typography variant="body2" sx={{ fontWeight: 'bold', mb: 1 }}>Compiler Output:</Typography>
                                <Box sx={{ maxHeight: '200px', overflow: 'auto', backgroundColor: colors.lightTextColor, p: 1.5, borderRadius: 1, fontFamily: 'monospace', fontSize: '0.75rem', whiteSpace: 'pre-wrap' }}>
                                    {compilationResult.compilerOutput.map((line: string, index: number) => (
                                        <Box key={index}>{line}</Box>
                                    ))}
                                </Box>
                            </Box>
                        )}
                    </Box>
                )}

                {/* Version Selection */}
                {isPreCheckComplete && hasChanges && (
                    <Box sx={{ mb: 3, p: 2, backgroundColor: colors.lightBackgroundColor, borderRadius: 1 }}>
                        <Typography variant="subtitle1" sx={{ mb: 2, fontWeight: 'bold' }}>
                            Version Management
                        </Typography>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2, flexWrap: 'wrap' }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                <Typography variant="body2">Installed:</Typography>
                                <Typography variant="h6" sx={{ color: colors.mutedTextColor }}>
                                    {installedVersion}
                                </Typography>
                            </Box>
                            <Typography variant="body2">→</Typography>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                <Typography variant="body2">Current (Editor):</Typography>
                                <Typography variant="h6" sx={{ color: colors.primaryColor }}>
                                    {currentVersion}
                                </Typography>
                            </Box>
                            <Typography variant="body2">→</Typography>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                <Typography variant="body2">After Install:</Typography>
                                <Typography variant="h6" sx={{ color: colors.secondaryColor }}>
                                    {newVersion}
                                </Typography>
                            </Box>
                        </Box>
                        <RadioGroup
                            value={versionBump}
                            onChange={(e) => setVersionBump(e.target.value as VersionBump)}
                        >
                            <FormControlLabel
                                value="minor"
                                control={<Radio />}
                                label="Minor Version Update (bug fixes, small changes)"
                            />
                            <FormControlLabel
                                value="major"
                                control={<Radio />}
                                label="Major Version Update (breaking changes, new features)"
                            />
                        </RadioGroup>
                    </Box>
                )}

                {/* No changes message */}
                {isPreCheckComplete && !hasChanges && (
                    <Box sx={{ p: 2, backgroundColor: colors.lightBackgroundColor, borderRadius: 1, display: 'flex', alignItems: 'center', gap: 1.5 }}>
                        <CheckCircleIcon sx={{ color: colors.successColor, fontSize: 24 }} />
                        <Typography variant="body1" sx={{ color: colors.mutedTextColor }}>
                            PLC is up to date - you can still install machine configuration if needed
                        </Typography>
                    </Box>
                )}

                {/* Configuration Option */}
                {isPreCheckComplete && canInstall && (
                    <Box sx={{ p: 2, backgroundColor: colors.lightBackgroundColor, borderRadius: 1 }}>
                        <FormControlLabel
                            control={
                                <Checkbox
                                    checked={applyConfiguration}
                                    onChange={(e) => setApplyConfiguration(e.target.checked)}
                                />
                            }
                            label={
                                <Box>
                                    <Typography variant="body1">Apply Machine Configuration</Typography>
                                    <Typography variant="caption" sx={{ color: colors.mutedTextColor }}>
                                        Update machine settings (axes, spindle, probe, ATC, etc.) along with PLC
                                    </Typography>
                                </Box>
                            }
                        />
                    </Box>
                )}

                {/* Installation Status */}
                {isInstalling && installationStatus && (
                    <Box sx={{ mt: 3, p: 2, backgroundColor: colors.primaryColor, borderRadius: 1, display: 'flex', alignItems: 'center', gap: 2 }}>
                        <CircularProgress size={24} sx={{ color: colors.lightTextColor }} />
                        <Typography variant="body1" sx={{ color: colors.lightTextColor, fontWeight: 'bold' }}>
                            {installationStatus}
                        </Typography>
                    </Box>
                )}

                {/* Installation Success with Optional Reboot Message */}
                {!isInstalling && installationStatus && (
                    <Box sx={{ mt: 3 }}>
                        <Box sx={{ p: 2, backgroundColor: colors.successColor, borderRadius: 1, mb: plcWasInstalled ? 2 : 0 }}>
                            <Typography variant="body1" sx={{ color: colors.lightTextColor, fontWeight: 'bold' }}>
                                {installationStatus}
                            </Typography>
                        </Box>
                        {/* Only show reboot message if PLC code changed */}
                        {plcWasInstalled && (
                            <Box sx={{ p: 2, backgroundColor: colors.warningColor, borderRadius: 1 }}>
                                <Typography variant="h6" sx={{ color: colors.lightTextColor, fontWeight: 'bold', mb: 1 }}>
                                    ⚠️ Reboot Required
                                </Typography>
                                <Typography variant="body1" sx={{ color: colors.lightTextColor }}>
                                    Please reboot the Acorn board and restart CNC12 to apply PLC changes.
                                </Typography>
                            </Box>
                        )}
                    </Box>
                )}

                {/* Installation Error */}
                {installationError && (
                    <Box sx={{ mt: 3, p: 2, backgroundColor: colors.errorColor, borderRadius: 1 }}>
                        <Typography variant="body1" sx={{ color: colors.lightTextColor, fontWeight: 'bold' }}>
                            ❌ {installationError}
                        </Typography>
                    </Box>
                )}
            </DialogContent>

            <DialogActions sx={{ px: 3, py: 2, borderTop: `1px solid ${colors.borderColor}`, justifyContent: 'flex-end' }}>
                {!installationStatus ? (
                    <>
                        <Button
                            onClick={handleClose}
                            disabled={isInstalling}
                            variant="outlined"
                        >
                            Cancel
                        </Button>
                        <Button
                            onClick={handleInstall}
                            disabled={!isPreCheckComplete || !canInstall || isInstalling}
                            variant="contained"
                            sx={{
                                backgroundColor: colors.primaryColor,
                                '&:hover': {
                                    backgroundColor: colors.secondaryColor
                                }
                            }}
                        >
                            {isInstalling ? 'Installing...' : 'Install'}
                        </Button>
                    </>
                ) : (
                    <Button
                        onClick={handleClose}
                        variant="contained"
                        sx={{
                            backgroundColor: colors.primaryColor,
                            '&:hover': {
                                backgroundColor: colors.secondaryColor
                            }
                        }}
                    >
                        Close
                    </Button>
                )}
            </DialogActions>
        </Dialog>
    );
}
