import { PLCOutputName } from '../../../../data/PLCIONames';
import { PLCOutput } from './PLCOutput';

/**
 * Default PLC output definitions with predefined data
 * Used to initialize output configurations
 */
export class DefaultPLCOutputs {
    /**
     * Get default output configurations
     */
    public static getDefaults(): PLCOutput[] {
        const outputs: PLCOutput[] = [];

        // Safety & Emergency Output (4 functions)
        const noFaultOut = new PLCOutput();
        noFaultOut.centroidName = PLCOutputName.NoFaultOut;
        noFaultOut.name = 'No Fault Output';
        noFaultOut.category = 'Safety';
        noFaultOut.activeText = 'System OK';
        noFaultOut.inactiveText = 'System Fault';
        outputs.push(noFaultOut);


        const driveResetOut = new PLCOutput();
        driveResetOut.centroidName = PLCOutputName.DriveResetOut;
        driveResetOut.name = 'Drive Reset Output';
        driveResetOut.category = 'Safety';
        driveResetOut.activeText = 'Active';
        driveResetOut.inactiveText = 'Inactive';
        outputs.push(driveResetOut);


        // Spindle Control (7 functions)
        const spinFWD = new PLCOutput();
        spinFWD.centroidName = PLCOutputName.SpinFWD;
        spinFWD.name = 'Spindle Forward';
        spinFWD.category = 'Spindle';
        spinFWD.activeText = 'On';
        spinFWD.inactiveText = 'Stopped';
        outputs.push(spinFWD);

        const spinREV = new PLCOutput();
        spinREV.centroidName = PLCOutputName.SpinREV;
        spinREV.name = 'Spindle Reverse';
        spinREV.category = 'Spindle';
        spinREV.activeText = 'On';
        spinREV.inactiveText = 'Stopped';
        outputs.push(spinREV);

        const spindleBrakeRelease = new PLCOutput();
        spindleBrakeRelease.centroidName = PLCOutputName.SpindleBrakeRelease;
        spindleBrakeRelease.name = 'Spindle Brake Release';
        spindleBrakeRelease.category = 'Spindle';
        spindleBrakeRelease.activeText = 'Released';
        spindleBrakeRelease.inactiveText = 'Engaged';
        outputs.push(spindleBrakeRelease);



        // Tool Management & ATC (3 functions)
        const unclampTool = new PLCOutput();
        unclampTool.centroidName = PLCOutputName.UnclampTool;
        unclampTool.name = 'Unclamp Tool';
        unclampTool.category = 'Tool Management';
        unclampTool.activeText = 'Unclamped';
        unclampTool.inactiveText = 'Clamped';
        outputs.push(unclampTool);

        const drawBarUpO = new PLCOutput();
        drawBarUpO.centroidName = PLCOutputName.DrawBarUp_O;
        drawBarUpO.name = 'Draw Bar Up';
        drawBarUpO.category = 'Tool Management';
        drawBarUpO.activeText = 'Up';
        drawBarUpO.inactiveText = 'Down';
        outputs.push(drawBarUpO);

        const atcAirBlowActivate = new PLCOutput();
        atcAirBlowActivate.centroidName = PLCOutputName.ATCAirBlowActivate;
        atcAirBlowActivate.name = 'ATC Air Blow';
        atcAirBlowActivate.category = 'Tool Management';
        atcAirBlowActivate.activeText = 'On';
        atcAirBlowActivate.inactiveText = 'Off';
        outputs.push(atcAirBlowActivate);

        // Coolant & Auxiliary (6 functions)
        const flood = new PLCOutput();
        flood.centroidName = PLCOutputName.Flood;
        flood.name = 'Flood Coolant';
        flood.category = 'Coolant & Auxiliary';
        flood.activeText = 'On (M8)';
        flood.inactiveText = 'Off (M9)';
        outputs.push(flood);

        const mist = new PLCOutput();
        mist.centroidName = PLCOutputName.Mist;
        mist.name = 'Mist Coolant';
        mist.category = 'Coolant & Auxiliary';
        mist.activeText = 'On (M7)';
        mist.inactiveText = 'Off (M9)';
        outputs.push(mist);

        const lubePump = new PLCOutput();
        lubePump.centroidName = PLCOutputName.LubePump;
        lubePump.name = 'Lubrication Pump';
        lubePump.category = 'Coolant & Auxiliary';
        lubePump.activeText = 'On';
        lubePump.inactiveText = 'Off';
        outputs.push(lubePump);

        const routerVacuumHoldDown = new PLCOutput();
        routerVacuumHoldDown.centroidName = PLCOutputName.RouterVacuumHoldDown;
        routerVacuumHoldDown.name = 'Router Vacuum Hold Down';
        routerVacuumHoldDown.category = 'Coolant & Auxiliary';
        routerVacuumHoldDown.activeText = 'On';
        routerVacuumHoldDown.inactiveText = 'Off';
        outputs.push(routerVacuumHoldDown);

        const dustCollectionOn = new PLCOutput();
        dustCollectionOn.centroidName = PLCOutputName.DustCollectionOn;
        dustCollectionOn.name = 'Dust Collection On';
        dustCollectionOn.category = 'Coolant & Auxiliary';
        dustCollectionOn.activeText = 'On';
        dustCollectionOn.inactiveText = 'Off';
        outputs.push(dustCollectionOn);


        // Router/Mill Specific (5 functions)
        const dustFootActivate = new PLCOutput();
        dustFootActivate.centroidName = PLCOutputName.DustFootActivate;
        dustFootActivate.name = 'Dust Foot Activate';
        dustFootActivate.category = 'Router/Mill';
        dustFootActivate.activeText = 'Up';
        dustFootActivate.inactiveText = 'Down';

        outputs.push(dustFootActivate);

        const laserAlignActivate = new PLCOutput();
        laserAlignActivate.centroidName = PLCOutputName.LaserAlignActivate;
        laserAlignActivate.name = 'Laser Alignment';
        laserAlignActivate.category = 'Router/Mill';
        laserAlignActivate.activeText = 'On';
        laserAlignActivate.inactiveText = 'Off';
        outputs.push(laserAlignActivate);

        const airBlowNozzle = new PLCOutput();
        airBlowNozzle.centroidName = PLCOutputName.AirBlowNozzle;
        airBlowNozzle.name = 'Air Blow Nozzle';
        airBlowNozzle.category = 'Router/Mill';
        airBlowNozzle.activeText = 'On';
        airBlowNozzle.inactiveText = 'Off';
        outputs.push(airBlowNozzle);

        const laserPointer = new PLCOutput();
        laserPointer.centroidName = PLCOutputName.LaserPointer;
        laserPointer.name = 'Laser Pointer';
        laserPointer.category = 'Router/Mill';
        laserPointer.activeText = 'On';
        laserPointer.inactiveText = 'Off';
        outputs.push(laserPointer);

        const positioningPins = new PLCOutput();
        positioningPins.centroidName = PLCOutputName.PositioningPins;
        positioningPins.name = 'Positioning Pins';
        positioningPins.category = 'Router/Mill';
        positioningPins.activeText = 'Up';
        positioningPins.inactiveText = 'Down';
        outputs.push(positioningPins);


        // Laser Functions (8 functions)
        const laserEnable = new PLCOutput();
        laserEnable.centroidName = PLCOutputName.LaserEnable;
        laserEnable.name = 'Laser Enable';
        laserEnable.category = 'Laser';
        laserEnable.activeText = 'Enabled';
        laserEnable.inactiveText = 'Disabled';
        outputs.push(laserEnable);

        const laserReset = new PLCOutput();
        laserReset.centroidName = PLCOutputName.LaserReset;
        laserReset.name = 'Laser Reset';
        laserReset.category = 'Laser';
        laserReset.activeText = 'Active';
        laserReset.inactiveText = 'Inactive';
        outputs.push(laserReset);

        const alignmentLaserEnableO = new PLCOutput();
        alignmentLaserEnableO.centroidName = PLCOutputName.AlignmentLaserEnable_O;
        alignmentLaserEnableO.name = 'Alignment Laser Enable';
        alignmentLaserEnableO.category = 'Laser';
        alignmentLaserEnableO.activeText = 'On';
        alignmentLaserEnableO.inactiveText = 'Off';
        outputs.push(alignmentLaserEnableO);

        const laserStandbyO = new PLCOutput();
        laserStandbyO.centroidName = PLCOutputName.LaserStandby_O;
        laserStandbyO.name = 'Laser Standby';
        laserStandbyO.category = 'Laser';
        laserStandbyO.activeText = 'Standby';
        laserStandbyO.inactiveText = 'Active';
        outputs.push(laserStandbyO);

        const fiberLaserResetO = new PLCOutput();
        fiberLaserResetO.centroidName = PLCOutputName.FiberLaserReset_O;
        fiberLaserResetO.name = 'Fiber Laser Reset';
        fiberLaserResetO.category = 'Laser';
        fiberLaserResetO.activeText = 'Active';
        fiberLaserResetO.inactiveText = 'Inactive';
        outputs.push(fiberLaserResetO);

        const laserDeployO = new PLCOutput();
        laserDeployO.centroidName = PLCOutputName.LaserDeploy_O;
        laserDeployO.name = 'Laser Deploy';
        laserDeployO.category = 'Laser';
        laserDeployO.activeText = 'Deployed';
        laserDeployO.inactiveText = 'Retracted';
        outputs.push(laserDeployO);

        // PWM and Special Outputs (1 function)
        const pwmSelect = new PLCOutput();
        pwmSelect.centroidName = PLCOutputName.PWMSelect;
        pwmSelect.name = 'PWM Select';
        pwmSelect.category = 'Special';
        pwmSelect.activeText = 'Enabled';
        pwmSelect.inactiveText = 'Disabled';
        outputs.push(pwmSelect);

        return outputs;
    }

    /**
     * Get default output by centroid name
     */
    public static getDefaultByCentroidName(centroidName: string): PLCOutput | undefined {
        return this.getDefaults().find(output => output.centroidName === centroidName);
    }

}
