import { Box, Button, Dialog, DialogActions, DialogContent, DialogProps, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';

export interface DraggableDialogProps extends Omit<DialogProps, 'title'> {
    title: string;
    onClose: () => void;
    actions?: React.ReactNode;
    children: React.ReactNode;
}

/**
 * Draggable dialog with styled header bar
 * Similar to FloatingWindow but as a Dialog component
 */
export function DraggableDialog({
    title,
    onClose,
    actions,
    children,
    ...dialogProps
}: DraggableDialogProps) {
    const colors = ConfigurationDataColors.Instance;

    return (
        <Dialog
            {...dialogProps}
            onClose={onClose}
            PaperComponent={(props) => (
                <Box
                    {...props}
                    sx={{
                        ...props.sx,
                        cursor: 'default',
                        backgroundColor: colors.lightBackgroundColor
                    }}
                    onMouseDown={(e: React.MouseEvent) => {
                        // Allow dragging from the header area only
                        const target = e.target as HTMLElement;

                        // Don't interfere with any mouse events inside dialog content or actions
                        if (target.closest('.MuiDialogContent-root') || target.closest('.MuiDialogActions-root')) {
                            return;
                        }

                        // Don't interfere with buttons
                        if (target.closest('button')) {
                            return;
                        }

                        // Check if clicking on header area
                        if (!target.closest('.draggable-header')) {
                            return;
                        }

                        const startX = e.clientX;
                        const startY = e.clientY;
                        const element = e.currentTarget as HTMLElement;
                        const rect = element.getBoundingClientRect();
                        const offsetX = startX - rect.left;
                        const offsetY = startY - rect.top;

                        const handleMouseMove = (moveEvent: MouseEvent) => {
                            if (!element) return; // Safety check
                            const newLeft = moveEvent.clientX - offsetX;
                            const newTop = moveEvent.clientY - offsetY;
                            element.style.left = `${newLeft}px`;
                            element.style.top = `${newTop}px`;
                            element.style.right = 'auto';
                            element.style.bottom = 'auto';
                        };

                        const handleMouseUp = () => {
                            document.removeEventListener('mousemove', handleMouseMove);
                            document.removeEventListener('mouseup', handleMouseUp);
                        };

                        document.addEventListener('mousemove', handleMouseMove);
                        document.addEventListener('mouseup', handleMouseUp);
                    }}
                />
            )}
        >
            <Box
                className="draggable-header"
                sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    p: 1.5,
                    backgroundColor: colors.primaryColor,
                    color: colors.lightTextColor,
                    cursor: 'grab',
                    userSelect: 'none',
                    '&:active': {
                        cursor: 'grabbing'
                    }
                }}
            >
                <Typography variant="h6" sx={{ fontSize: '1rem', fontWeight: 'bold' }}>
                    {title}
                </Typography>
                <Button
                    onClick={onClose}
                    sx={{
                        color: colors.lightTextColor,
                        minWidth: 'auto',
                        p: 0.5,
                        '&:hover': {
                            backgroundColor: `${colors.lightTextColor}1A`
                        }
                    }}
                >
                    ✕
                </Button>
            </Box>
            <DialogContent>
                {children}
            </DialogContent>
            {actions && (
                <DialogActions sx={{ justifyContent: 'flex-end', p: 2, gap: 1 }}>
                    {actions}
                </DialogActions>
            )}
        </Dialog>
    );
}
