import CloseIcon from '@mui/icons-material/Close';
import ExpandLessIcon from '@mui/icons-material/ExpandLess';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import LocationOnIcon from '@mui/icons-material/LocationOn';
import SearchIcon from '@mui/icons-material/Search';
import {
    Box,
    Button,
    Chip,
    Collapse,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    List,
    ListItem,
    ListItemButton,
    ListItemText,
    TextField,
    Typography,
} from '@mui/material';
import React, { useEffect, useMemo, useState } from 'react';
import { Declaration } from '../../centroid/plc/data/Declaration';
import { IPLCSource, PLCUtilities } from '../../centroid/plc/data/PLCUtilities';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';

interface VariableSearchDialogProps {
    open: boolean;
    onClose: () => void;
    program: IPLCSource;
    onNavigateTo: (stageName: string, blockName: string) => void;
}

interface VariableInfo {
    declaration: Declaration;
    usages: Array<{
        stageName: string;
        blockName: string;
        isWritten: boolean;
    }>;
}

export function VariableSearchDialog({
    open,
    onClose,
    program,
    onNavigateTo,
}: VariableSearchDialogProps) {
    const colors = ConfigurationDataColors.Instance;
    const [searchTerm, setSearchTerm] = useState('');
    const [expandedVars, setExpandedVars] = useState<Set<string>>(new Set());

    // Reset state when dialog opens
    useEffect(() => {
        if (open) {
            setSearchTerm('');
            setExpandedVars(new Set());
        }
    }, [open]);

    // Get all declarations from the program
    const allVariables = useMemo<VariableInfo[]>(() => {
        if (!program) return [];

        // Use centralized method to get all declarations
        const declarations = PLCUtilities.getAllDeclarations(program);

        // Get usage information for each declaration and filter out unused ones
        return declarations
            .map(declaration => ({
                declaration,
                usages: PLCUtilities.getDeclarationUsages(program, declaration.name),
            }))
            .filter(varInfo => varInfo.usages.length > 0); // Only show declarations that are used
    }, [program]);

    // Filter variables based on search term
    const filteredVariables = useMemo(() => {
        if (!searchTerm.trim()) return allVariables;

        const lower = searchTerm.toLowerCase();
        return allVariables.filter(varInfo =>
            varInfo.declaration.name.toLowerCase().includes(lower) ||
            varInfo.declaration.description?.toLowerCase().includes(lower) ||
            varInfo.declaration.dataType.toLowerCase().includes(lower)
        );
    }, [allVariables, searchTerm]);

    const handleToggleExpand = (varName: string) => {
        const newExpanded = new Set(expandedVars);
        if (newExpanded.has(varName)) {
            newExpanded.delete(varName);
        } else {
            newExpanded.add(varName);
        }
        setExpandedVars(newExpanded);
    };

    const handleNavigate = (stageName: string, blockName: string) => {
        onNavigateTo(stageName, blockName);
        onClose();
    };

    return (
        <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
            <DialogTitle
                sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    backgroundColor: colors.primaryColor,
                    color: colors.lightTextColor,
                    py: 2,
                    px: 3,
                }}
            >
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <SearchIcon />
                    <Typography variant="h6">Variable Search</Typography>
                </Box>
                <IconButton
                    onClick={onClose}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay,
                        },
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>

            <DialogContent>
                <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', gap: 2 }}>
                    {/* Search Input */}
                    <TextField
                        fullWidth
                        variant="outlined"
                        placeholder="Search by variable name, type, or description..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        InputProps={{
                            startAdornment: <SearchIcon sx={{ mr: 1, color: 'text.secondary' }} />,
                        }}
                        autoFocus
                    />

                    {/* Results Count */}
                    <Typography variant="body2" color="text.secondary">
                        {filteredVariables.length} variable{filteredVariables.length !== 1 ? 's' : ''} found
                        {allVariables.length !== filteredVariables.length && ` (filtered from ${allVariables.length} total)`}
                    </Typography>

                    {/* Variable List */}
                    <List
                        sx={{
                            maxHeight: '500px',
                            overflow: 'auto',
                            border: `1px solid ${colors.borderColor}`,
                            borderRadius: 1,
                        }}
                    >
                        {filteredVariables.length === 0 ? (
                            <ListItem>
                                <ListItemText
                                    primary="No variables found"
                                    secondary="Try a different search term"
                                    sx={{ textAlign: 'center', color: 'text.secondary' }}
                                />
                            </ListItem>
                        ) : (
                            filteredVariables.map((varInfo) => {
                                const isExpanded = expandedVars.has(varInfo.declaration.name);
                                const writes = varInfo.usages.filter(u => u.isWritten).length;
                                const reads = varInfo.usages.filter(u => !u.isWritten).length;

                                return (
                                    <React.Fragment key={varInfo.declaration.name}>
                                        <ListItem
                                            disablePadding
                                            sx={{
                                                borderBottom: `1px solid ${colors.borderColor}`,
                                            }}
                                        >
                                            <ListItemButton
                                                onClick={() => handleToggleExpand(varInfo.declaration.name)}
                                            >
                                                <Box sx={{ display: 'flex', alignItems: 'center', width: '100%', gap: 2 }}>
                                                    {/* Expand Icon */}
                                                    <Box sx={{ minWidth: 24 }}>
                                                        {varInfo.usages.length > 0 && (
                                                            isExpanded ? <ExpandLessIcon /> : <ExpandMoreIcon />
                                                        )}
                                                    </Box>

                                                    {/* Variable Info */}
                                                    <Box sx={{ flex: 1 }}>
                                                        <Typography variant="body1" sx={{ fontWeight: 'bold' }}>
                                                            {varInfo.declaration.name}
                                                        </Typography>
                                                        <Box sx={{ display: 'flex', gap: 1, mt: 0.5, alignItems: 'center', flexWrap: 'wrap' }}>
                                                            <Chip
                                                                label={varInfo.declaration.dataType}
                                                                size="small"
                                                                sx={{ fontSize: '0.7rem' }}
                                                            />
                                                            {varInfo.declaration.description && (
                                                                <Typography variant="caption" color="text.secondary">
                                                                    {varInfo.declaration.description}
                                                                </Typography>
                                                            )}
                                                        </Box>
                                                    </Box>

                                                    {/* Usage Stats */}
                                                    <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
                                                        {reads > 0 && (
                                                            <Chip
                                                                label={`Read: ${reads}`}
                                                                size="small"
                                                                color="success"
                                                                sx={{ fontSize: '0.7rem' }}
                                                            />
                                                        )}
                                                        {writes > 0 && (
                                                            <Chip
                                                                label={`Write: ${writes}`}
                                                                size="small"
                                                                color="primary"
                                                                sx={{ fontSize: '0.7rem' }}
                                                            />
                                                        )}
                                                    </Box>
                                                </Box>
                                            </ListItemButton>
                                        </ListItem>

                                        {/* Usage Details (Collapsible) */}
                                        <Collapse in={isExpanded} timeout="auto" unmountOnExit>
                                            <Box sx={{ bgcolor: 'background.default', p: 2 }}>
                                                <List dense>
                                                    {varInfo.usages.map((usage, idx) => (
                                                        <ListItem
                                                            key={idx}
                                                            disablePadding
                                                            sx={{ mb: 0.5 }}
                                                        >
                                                            <Button
                                                                fullWidth
                                                                variant="outlined"
                                                                size="small"
                                                                startIcon={<LocationOnIcon />}
                                                                onClick={() => handleNavigate(usage.stageName, usage.blockName)}
                                                                sx={{
                                                                    justifyContent: 'flex-start',
                                                                    textAlign: 'left',
                                                                    borderColor: usage.isWritten
                                                                        ? colors.primaryColor
                                                                        : colors.borderColor,
                                                                }}
                                                            >
                                                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, width: '100%' }}>
                                                                    <Typography variant="body2">
                                                                        {usage.stageName} › {usage.blockName}
                                                                    </Typography>
                                                                    <Box sx={{ flex: 1 }} />
                                                                    <Chip
                                                                        label={usage.isWritten ? 'Write' : 'Read'}
                                                                        size="small"
                                                                        color={usage.isWritten ? 'primary' : 'success'}
                                                                        sx={{ fontSize: '0.65rem', height: 20 }}
                                                                    />
                                                                </Box>
                                                            </Button>
                                                        </ListItem>
                                                    ))}
                                                </List>
                                            </Box>
                                        </Collapse>
                                    </React.Fragment>
                                );
                            })
                        )}
                    </List>
                </Box>
            </DialogContent>

            <DialogActions
                sx={{
                    p: 2,
                    gap: 1,
                    justifyContent: 'flex-end',
                    borderTop: `1px solid ${colors.borderColor}`,
                }}
            >
                <Button onClick={onClose} variant="outlined">
                    Close
                </Button>
            </DialogActions>
        </Dialog>
    );
}
