import React from 'react';
import { CNCPoint } from '../../../data/CNCPoint';
import { CoordinateType } from '../../../data/Common/CoordinateType';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../data/ConfigurationState';
import { MachineStateData } from '../../../data/MachineStateData';
import { ActionBus } from '../../../utils/actions/ActionBus';
import { MoveAction, MoveType } from '../../../utils/actions/MoveAction';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';

export interface WorkHomeIndicatorProps {
  simulatorView: SimulatorView;
  machineState: MachineStateData;
}

export const WorkHomeIndicator: React.FC<WorkHomeIndicatorProps> = ({
  simulatorView,
  machineState
}) => {
  // State for tracking sphere hover
  const [isHovered, setIsHovered] = React.useState<boolean>(false);

  return (
    <ObserveMultiProperties
      key="work-home-indicator"
      listenTo={[
        { object: machineState, properties: ['currentWorkZero'] }
      ]}
      control={() => {
        const colors = ConfigurationDataColors.Instance;

        // Work zero (0,0,0) - absolute position on workpiece, independent of tool
        const workZeroPoint = new CNCPoint(0, 0, 0, CoordinateType.WorkZero);
        const simulatorWorkZero = CoordinateUtil.toSimulator(workZeroPoint);

        // Handler to move machine to work zero location
        const handleTargetClick = () => {
          // Work zero origin in WorkZero coordinates
          const workZeroOrigin = new CNCPoint(0, 0, 0, CoordinateType.WorkZero);
          // Convert to WorkZeroWithOffsets (accounts for tool offsets)
          const targetInWorkZero = CoordinateUtil.toWorkZeroWithOffsets(workZeroOrigin);
          // Keep current Z position unchanged - get current Z in WorkZeroWithOffsets
          const currentPosInWorkZero = CoordinateUtil.toWorkZeroWithOffsets(ConfigurationState.Instance.currentMachinePoint);
          // Create and execute move action - move tool tip to work zero X,Y position
          const moveAction = new MoveAction(CoordinateType.WorkZeroWithOffsets, targetInWorkZero.x, targetInWorkZero.y, currentPosInWorkZero.z, undefined, MoveType.Coordinates);
          ActionBus.Instance.addAction(moveAction);
        };

        return (
          <group position={[simulatorWorkZero.x, simulatorWorkZero.y, simulatorWorkZero.z]}>
            {/* X axis - Red (positive direction only) */}
            <mesh position={[2.5, 0, 0]} rotation={[0, 0, Math.PI / 2]}>
              <cylinderGeometry args={[0.1, 0.1, 5, 8]} />
              <meshStandardMaterial color={colors.errorColor} />
            </mesh>

            {/* Y axis - Green (positive direction only) */}
            <mesh position={[0, 2.5, 0]}>
              <cylinderGeometry args={[0.1, 0.1, 5, 8]} />
              <meshStandardMaterial color={colors.successColor} />
            </mesh>

            {/* Z axis - Blue (positive direction only) */}
            <mesh position={[0, 0, 2.5]} rotation={[Math.PI / 2, 0, 0]}>
              <cylinderGeometry args={[0.1, 0.1, 5, 8]} />
              <meshStandardMaterial color={colors.infoColor} />
            </mesh>

            {/* Origin sphere - Interactive target sphere */}
            <mesh
              onClick={handleTargetClick}
              onPointerOver={() => setIsHovered(true)}
              onPointerOut={() => setIsHovered(false)}
              castShadow
              receiveShadow
            >
              <sphereGeometry args={[ConfigurationData.Instance.targetSphereSize, 16, 16]} />
              <meshStandardMaterial
                color={ConfigurationDataColors.toThreeJsColor(isHovered ? colors.highlightColor : colors.lightTextColor)}
                transparent={true}
                opacity={isHovered ? 1.0 : 0.0}
              />
            </mesh>
          </group>
        );
      }}
    />
  );
};
