import { Grid } from '@mui/material';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';

export function TouchPadSection() {
    const machine = MachineData.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
                <ObserveState
                    key="touch-pad-holder-width"
                    listenTo={machine}
                    properties={['touchPadHolderWidth']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Touch Pad Holder Width"
                            value={machine.touchPadHolderWidth}
                            onChange={(value) => machine.touchPadHolderWidth = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />

                <ObserveState
                    key="touch-pad-holder-depth"
                    listenTo={machine}
                    properties={['touchPadHolderDepth']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Touch Pad Holder Depth"
                            value={machine.touchPadHolderDepth}
                            onChange={(value) => machine.touchPadHolderDepth = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="touch-pad-diameter"
                    listenTo={machine}
                    properties={['touchPadDiameter']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Touch Pad Diameter"
                            value={machine.touchPadDiameter}
                            onChange={(value) => machine.touchPadDiameter = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>
        </Grid>
    );
}
