import { StateManager } from '../../utils/statemanager/StateManager';
import { MachineData } from '../Machine/MachineData';
import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Checklist item for Fixed Tool Measurement Point Position
 * Conditional validation - only validates when fixed tool measurement is enabled
 * Auto-validates that X,Y position is not at or very near 0,0
 */
export class FixedToolMeasurementPositionChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Fixed Tool Measurement Position',
            'Configure X, Y position for fixed tool measurement point (must not be at 0,0)'
        );

        // Listen to MachineData changes that affect this checklist item
        const machine = MachineData.Instance;
        StateManager.addObserver(machine, () => {
            StateManager.propertyChanged(this, 'manuallyConfirmed');
        }, ['fixedToolMeasurementPointEnabled', 'fixedToolMeasurementPointX', 'fixedToolMeasurementPointY']);
    }

    public shouldInclude(): boolean {
        return MachineData.Instance.fixedToolMeasurementPointEnabled;
    }

    public needsManualConfirmation(): boolean {
        return false; // Auto-validation only
    }

    public completionCheck(): boolean {
        const machine = MachineData.Instance;

        // If fixed tool measurement is not enabled, this item is N/A (considered complete)
        if (!machine.fixedToolMeasurementPointEnabled) {
            return true;
        }

        // If enabled, validate that X,Y position is not at or very near 0,0
        const x = machine.fixedToolMeasurementPointX;
        const y = machine.fixedToolMeasurementPointY;

        // Check if both coordinates are significantly different from 0 (tolerance of 0.001)
        const tolerance = 0.001;
        const isNearZero = Math.abs(x) < tolerance && Math.abs(y) < tolerance;

        return !isNearZero;
    }

    public clone(): FixedToolMeasurementPositionChecklistItem {
        const cloned = new FixedToolMeasurementPositionChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
