import { Close as CloseIcon, Error as ErrorIcon, CheckCircle as SuccessIcon } from '@mui/icons-material';
import { Box, Dialog, DialogContent, DialogTitle, IconButton, Paper, Tab, Tabs, Tooltip, Typography } from '@mui/material';
import { useMemo, useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { PLCCompilationResult } from '../../../services/src/models/PLCCompilationResult';

interface PLCCompilationResultsWithSourceDialogProps {
    open: boolean;
    onClose: () => void;
    result: PLCCompilationResult | null;
    timestamp?: Date;
    sourceCode: string;
    messageFile: string;
}

interface ParsedError {
    line: number;
    column: number;
    message: string;
    fullText: string;
}

/**
 * Dialog for displaying PLC compilation results with source code
 * Highlights error lines in red and shows error messages on hover
 */
export function PLCCompilationResultsWithSourceDialog({
    open,
    onClose,
    result,
    timestamp,
    sourceCode,
    messageFile
}: PLCCompilationResultsWithSourceDialogProps) {
    const colors = ConfigurationDataColors.Instance;
    const [activeTab, setActiveTab] = useState(0);

    const isSuccess = result?.success ?? true;

    // Parse error messages to extract line numbers and messages
    const parsedErrors = useMemo(() => {
        const errors: ParsedError[] = [];
        if (result?.issues) {
            result.issues.forEach(issue => {
                // Parse format: "Error Line 49 Col 18: Undefined label unknown"
                const match = issue.match(/Error Line (\d+) Col (\d+): (.+)/);
                if (match) {
                    errors.push({
                        line: parseInt(match[1]),
                        column: parseInt(match[2]),
                        message: match[3],
                        fullText: issue
                    });
                }
            });
        }
        return errors;
    }, [result?.issues]);

    // Create a map of line numbers to errors
    const errorsByLine = useMemo(() => {
        const map = new Map<number, ParsedError[]>();
        parsedErrors.forEach(error => {
            if (!map.has(error.line)) {
                map.set(error.line, []);
            }
            map.get(error.line)!.push(error);
        });
        return map;
    }, [parsedErrors]);

    // Split source code into lines
    const sourceLines = useMemo(() => sourceCode.split('\n'), [sourceCode]);

    const hasCompilerOutput = result?.compilerOutput && result.compilerOutput.length > 0;
    const hasIssues = result?.issues && result.issues.length > 0;
    const hasAnyOutput = hasCompilerOutput || hasIssues;

    // Combine both compilerOutput and issues for display in raw log
    let logText = '';
    if (hasCompilerOutput && result?.compilerOutput) {
        logText = result.compilerOutput.join('\n');
    }
    if (hasIssues && result?.issues) {
        if (logText) logText += '\n\n';
        logText += result.issues.join('\n');
    }

    if (!result) {
        return null;
    }

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth="lg"
            fullWidth
            PaperProps={{
                sx: {
                    height: '90vh',
                }
            }}
        >
            <DialogTitle
                sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    backgroundColor: colors.primaryColor,
                    color: colors.lightTextColor,
                    py: 2,
                    px: 3
                }}
            >
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                    {isSuccess ? (
                        <SuccessIcon fontSize="large" />
                    ) : (
                        <ErrorIcon fontSize="large" />
                    )}
                    <Typography variant="h6">
                        PLC Compilation {isSuccess ? 'Successful' : 'Failed'}
                    </Typography>
                </Box>
                <IconButton
                    onClick={onClose}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>
            <DialogContent sx={{ p: 0, display: 'flex', flexDirection: 'column', height: '100%' }}>
                {parsedErrors.length > 0 && (
                    <Box sx={{ p: 3, pb: 2, borderBottom: `1px solid ${colors.borderColor}` }}>
                        <Typography variant="body2" color="error">
                            {parsedErrors.length} error(s) found - hover over red lines for details
                        </Typography>
                    </Box>
                )}

                {/* Tabs for Source Code and Message File */}
                <Box sx={{ borderBottom: 1, borderColor: 'divider', px: 3, pt: 2 }}>
                    <Tabs
                        value={activeTab}
                        onChange={(_, newValue) => setActiveTab(newValue)}
                        sx={{
                            '& .MuiTab-root': {
                                color: colors.darkTextColor
                            },
                            '& .Mui-selected': {
                                color: colors.primaryColor
                            },
                            '& .MuiTabs-indicator': {
                                backgroundColor: colors.primaryColor
                            }
                        }}
                    >
                        <Tab label="Source Code" />
                        <Tab label="Message File" />
                    </Tabs>
                </Box>

                {/* Two column layout: Source code/Message and Raw log */}
                <Box sx={{ display: 'flex', gap: 2, p: 3, flex: 1, minHeight: 0 }}>
                    {/* Source Code or Message File with highlighted errors */}
                    <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', minWidth: 0 }}>
                        {activeTab === 0 ? (
                            // Source Code Tab
                            <>
                                <Typography variant="body1" sx={{ mb: 1, fontWeight: 'bold' }}>
                                    Source Code:
                                </Typography>
                                <Paper
                                    sx={{
                                        flex: 1,
                                        overflow: 'auto',
                                        backgroundColor: ConfigurationDataColors.Instance.darkBackgroundColor,
                                        p: 0,
                                        border: `1px solid ${colors.borderColor}`
                                    }}
                                >
                                    <Box sx={{ fontFamily: 'Consolas, Monaco, "Courier New", monospace', fontSize: '12px' }}>
                                        {sourceLines.map((line, index) => {
                                            const lineNumber = index + 1;
                                            const lineErrors = errorsByLine.get(lineNumber);
                                            const hasError = lineErrors && lineErrors.length > 0;
                                            const errorTooltip = lineErrors?.map(e => e.message).join('\n') || '';

                                            return (
                                                <Tooltip
                                                    key={lineNumber}
                                                    title={hasError ? errorTooltip : ''}
                                                    placement="right"
                                                    arrow
                                                >
                                                    <Box
                                                        sx={{
                                                            display: 'flex',
                                                            backgroundColor: hasError ? ConfigurationDataColors.Instance.darkBackgroundColor : `${colors.lightTextColor}00`,
                                                            borderLeft: hasError ? `3px solid ${ConfigurationDataColors.Instance.errorColor}` : 'none',
                                                            '&:hover': {
                                                                backgroundColor: hasError ? ConfigurationDataColors.Instance.darkBackgroundColor : `${colors.lightTextColor}0D`
                                                            },
                                                            cursor: hasError ? 'help' : 'default'
                                                        }}
                                                    >
                                                        <Box
                                                            sx={{
                                                                minWidth: '50px',
                                                                px: 2,
                                                                py: 0.5,
                                                                textAlign: 'right',
                                                                color: hasError ? ConfigurationDataColors.Instance.errorColor : ConfigurationDataColors.Instance.lightTextColor,
                                                                backgroundColor: hasError ? ConfigurationDataColors.Instance.darkBackgroundColor : ConfigurationDataColors.Instance.darkBackgroundColor,
                                                                borderRight: `1px solid ${ConfigurationDataColors.Instance.borderColor}`,
                                                                userSelect: 'none',
                                                                fontWeight: hasError ? 'bold' : 'normal'
                                                            }}
                                                        >
                                                            {lineNumber}
                                                        </Box>
                                                        <Box
                                                            sx={{
                                                                flex: 1,
                                                                px: 2,
                                                                py: 0.5,
                                                                color: hasError ? ConfigurationDataColors.Instance.errorColor : ConfigurationDataColors.Instance.lightTextColor,
                                                                whiteSpace: 'pre',
                                                                fontWeight: hasError ? 'bold' : 'normal'
                                                            }}
                                                        >
                                                            {line || ' '}
                                                        </Box>
                                                    </Box>
                                                </Tooltip>
                                            );
                                        })}
                                    </Box>
                                </Paper>
                            </>
                        ) : (
                            // Message File Tab
                            <>
                                <Typography variant="body1" sx={{ mb: 1, fontWeight: 'bold' }}>
                                    Message File:
                                </Typography>
                                <Paper
                                    sx={{
                                        flex: 1,
                                        overflow: 'auto',
                                        backgroundColor: ConfigurationDataColors.Instance.darkBackgroundColor,
                                        p: 0,
                                        border: `1px solid ${colors.borderColor}`
                                    }}
                                >
                                    <Box sx={{ fontFamily: 'Consolas, Monaco, "Courier New", monospace', fontSize: '12px' }}>
                                        {messageFile.split('\n').map((line, index) => {
                                            const lineNumber = index + 1;
                                            return (
                                                <Box
                                                    key={lineNumber}
                                                    sx={{
                                                        display: 'flex',
                                                        '&:hover': {
                                                            backgroundColor: `${colors.lightTextColor}0D`
                                                        }
                                                    }}
                                                >
                                                    <Box
                                                        sx={{
                                                            minWidth: '50px',
                                                            px: 2,
                                                            py: 0.5,
                                                            textAlign: 'right',
                                                            color: ConfigurationDataColors.Instance.lightTextColor,
                                                            backgroundColor: ConfigurationDataColors.Instance.darkBackgroundColor,
                                                            borderRight: `1px solid ${ConfigurationDataColors.Instance.borderColor}`,
                                                            userSelect: 'none'
                                                        }}
                                                    >
                                                        {lineNumber}
                                                    </Box>
                                                    <Box
                                                        sx={{
                                                            flex: 1,
                                                            px: 2,
                                                            py: 0.5,
                                                            color: ConfigurationDataColors.Instance.lightTextColor,
                                                            whiteSpace: 'pre'
                                                        }}
                                                    >
                                                        {line || ' '}
                                                    </Box>
                                                </Box>
                                            );
                                        })}
                                    </Box>
                                </Paper>
                            </>
                        )}
                    </Box>

                    {/* Raw compilation log */}
                    {hasAnyOutput && (
                        <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', minWidth: 0 }}>
                            <Typography variant="body1" sx={{ mb: 1, fontWeight: 'bold' }}>
                                {parsedErrors.length > 0 ? 'Compilation Errors:' : 'Compilation Log:'}
                            </Typography>
                            <Paper
                                sx={{
                                    flex: 1,
                                    overflow: 'auto',
                                    backgroundColor: ConfigurationDataColors.Instance.darkBackgroundColor,
                                    p: 2,
                                    border: `1px solid ${isSuccess ? colors.borderColor : ConfigurationDataColors.Instance.errorColor}`
                                }}
                            >
                                <pre
                                    style={{
                                        margin: 0,
                                        color: isSuccess ? ConfigurationDataColors.Instance.mutedTextColor : ConfigurationDataColors.Instance.errorColor,
                                        fontFamily: 'Consolas, Monaco, "Courier New", monospace',
                                        fontSize: '12px',
                                        lineHeight: 1.6,
                                        whiteSpace: 'pre-wrap',
                                        wordBreak: 'break-word'
                                    }}
                                >
                                    {logText}
                                </pre>
                            </Paper>
                        </Box>
                    )}
                </Box>
            </DialogContent>
        </Dialog>
    );
}
