import { Cancel as EmergencyStopIcon } from '@mui/icons-material';
import { Alert, Box, Button, CircularProgress, Typography } from '@mui/material';
import React from 'react';
import { Tool } from '../../../../data/Common/Tool';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { WizardStep } from '../../../Wizard/WizardStep';
import { ToolMeasurementMethod, ToolMeasurementWizard } from '../ToolMeasurementWizard';

/**
 * Step to trigger the measurement with touchplate
 */
export class TriggerMeasureStep extends WizardStep {
    private tool: Tool;
    private method: ToolMeasurementMethod;

    constructor(wizard: ToolMeasurementWizard, tool: Tool, previousStep: WizardStep | null, method: ToolMeasurementMethod) {
        super(wizard, previousStep);
        this.tool = tool;
        this.method = method;
    }

    getTitle(): string {
        return 'Measure Tool';
    }

    nextStep(): WizardStep | null {
        // Final step - wizard will close after measurement
        return null;
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return <TriggerMeasureStepComponent step={this} />;
    }
}

interface TriggerMeasureStepComponentProps {
    step: TriggerMeasureStep;
}

function TriggerMeasureStepComponent({ step }: TriggerMeasureStepComponentProps) {
    const wizard = step.wizard as ToolMeasurementWizard;
    const colors = ConfigurationDataColors.Instance;

    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const handleMeasure = async () => {
        // TODO: Trigger actual measurement
        await wizard.callback?.onComplete?.();
    };

    const handleEmergencyStop = async () => {
        // TODO: Trigger emergency stop
        // Emergency stop triggered
        await wizard.callback?.onCancel?.();
    };

    return (
        <Box sx={{ p: 3, display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>
            <Alert severity="warning" sx={{ mb: 2 }}>
                <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 1 }}>
                    ⚠️ MEASUREMENT IN PROGRESS
                </Typography>
                <Typography variant="body2">
                    The machine is automatically measuring the tool. Do not interfere with the process.
                </Typography>
            </Alert>

            <Box sx={{
                flex: 1,
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                gap: 3
            }}>
                <CircularProgress size={80} thickness={4} sx={{ color: colors.primaryColor }} />
                <Typography variant="h6" color="text.secondary">
                    Measuring tool with touchplate...
                </Typography>
            </Box>

            <Box sx={{ display: 'flex', justifyContent: 'center', mt: 3 }}>
                <Button
                    variant="contained"
                    color="error"
                    size="large"
                    startIcon={<EmergencyStopIcon sx={{ fontSize: '2rem !important' }} />}
                    onClick={handleEmergencyStop}
                    sx={{
                        fontWeight: 'bold',
                        fontSize: '1.25rem',
                        py: 2,
                        px: 6,
                        minHeight: 60
                    }}
                >
                    EMERGENCY STOP
                </Button>
            </Box>
        </Box>
    );
}
