import { Grid } from '@mui/material';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';
import { OffsetEditor } from '../../../Common/OffsetEditor';

export function LaserPointerSection() {
    const machine = MachineData.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
                <ObserveState
                    key="laser-pointer-offset"
                    listenTo={machine}
                    properties={['laserPointerOffset']}
                    control={() => (
                        <OffsetEditor
                            offset={machine.laserPointerOffset}
                            label="Offset from Spindle"
                            showLabel={true}
                            precision={3}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="laser-pointer-diameter"
                    listenTo={machine}
                    properties={['laserPointerDiameter']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Diameter"
                            value={machine.laserPointerDiameter}
                            onChange={(value) => machine.laserPointerDiameter = value}
                            margin="normal"
                            precision={3}
                            helperText="Diameter of cylindrical laser pointer"
                        />
                    )}
                />

                <ObserveState
                    key="laser-pointer-height"
                    listenTo={machine}
                    properties={['laserPointerHeight']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Height"
                            value={machine.laserPointerHeight}
                            onChange={(value) => machine.laserPointerHeight = value}
                            margin="normal"
                            precision={3}
                            helperText="Height of laser pointer"
                        />
                    )}
                />
            </Grid>
        </Grid>
    );
}
