import { IStorable } from '../common/IStorable';
import { SaveableDataBase } from './Common/SaveableDataBase';
import { SimulatorView } from './Common/SimulatorView';
import { DataFileConstants } from './DataFileConstants';

/**
 * Singleton for managing persistent 3D viewer settings
 * Stores camera positions and view configurations separately from machine state
 */
export class ViewSettings extends SaveableDataBase implements IStorable {
    private static _instance: ViewSettings | null = null;

    private _savedViews: Map<string, SimulatorView> = new Map();

    private constructor() {
        super();
        this.init();
    }

    public static get Instance(): ViewSettings {
        if (!ViewSettings._instance) {
            ViewSettings._instance = new ViewSettings();
        }
        return ViewSettings._instance;
    }

    private async init(): Promise<void> {
        await this.load();
    }

    /**
     * Get the filename for view settings storage
     */
    protected get filename(): string {
        return DataFileConstants.VIEW_SETTINGS;
    }

    /**
     * Get a saved view by name
     */
    public getSavedView(viewName: string): SimulatorView | undefined {
        return this._savedViews.get(viewName);
    }

    /**
     * Save a view configuration
     */
    public saveView(viewName: string, view: SimulatorView): void {
        this._savedViews.set(viewName, view);
        this.manualSave();
    }

    /**
     * Check if a view exists
     */
    public hasView(viewName: string): boolean {
        return this._savedViews.has(viewName);
    }

    /**
     * Delete a saved view
     */
    public deleteView(viewName: string): void {
        this._savedViews.delete(viewName);
        this.manualSave();
    }

    /**
     * Get all saved view names
     */
    public listViewNames(): string[] {
        return Array.from(this._savedViews.keys());
    }

    /**
     * Clear all saved views
     */
    public async reset(): Promise<void> {
        this._savedViews.clear();
        await this.manualSave();
    }

    // Serialization
    public toJSON(): object {
        // Convert Map to array of [key, value] pairs for serialization
        const viewsArray = Array.from(this._savedViews.entries()).map(([name, view]) => ({
            name,
            view: view.toJSON()
        }));

        return {
            savedViews: viewsArray
        };
    }

    public fromJSON(data: any): void {
        if (data.savedViews && Array.isArray(data.savedViews)) {
            this._savedViews.clear();
            data.savedViews.forEach((item: any) => {
                if (item.name && item.view) {
                    const view = new SimulatorView();
                    view.fromJSON(item.view);
                    this._savedViews.set(item.name, view);
                }
            });
        }
    }
}
