  // G-code preview properties - delegates to ConfigurationState (runtime only, not persisted)
  /**
   * Show G-code preview dialog
   * Delegates to ConfigurationState (runtime state, not persisted)
   */
  public showGCodePreview(title: string, lines: string[], callback?: any, startImmediately: boolean = false): void {
    // WORKAROUND: Breaking circular dependency between ConfigurationData and ConfigurationState
    // ConfigurationData -> ConfigurationState -> ConfigurationData creates cycle
    const { ConfigurationState } = require('./ConfigurationState');
    ConfigurationState.Instance.showGCodePreview(title, lines, callback, startImmediately);
  }

  /**
   * Clear G-code preview and hide dialog
   * Delegates to ConfigurationState (runtime state, not persisted)
   */
  public clearGCodePreview(): void {
    // WORKAROUND: Breaking circular dependency between ConfigurationData and ConfigurationState
    const { ConfigurationState } = require('./ConfigurationState');
    ConfigurationState.Instance.clearGCodePreview();
  }

  /**
   * Reset only color-related properties to their default values
   */
  public resetColors(): void {
    try {
      // Create a new default instance to get default color values
      // WORKAROUND: Dynamic constructor call requires 'as any' to invoke with new keyword
      const defaultInstance = new (this.constructor as any)();
      const defaultData = defaultInstance.toJSON();
      const currentData = this.toJSON();

      // Find all properties that contain 'color' or 'Color' in their name
      const colorProperties = Object.keys(defaultData).filter(key =>
        key.toLowerCase().includes('color')
      );

      // Apply only the color properties from the default instance
      colorProperties.forEach(colorProp => {
        if (defaultData.hasOwnProperty(colorProp)) {
          // WORKAROUND: Dynamic property access requires 'as any' for indexed access
          (currentData as any)[colorProp] = defaultData[colorProp];
        }
      });

      // Load the updated data with only color properties changed
      this.fromJSON(currentData);

      // Trigger state manager update
      StateManager.propertyChanged(this, 'colorReset');
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to reset color properties:', error);
    }
  }

  /**
   * Get the singleton instance
   */
  public static get Instance(): ConfigurationData {
    if (!SingletonRegistry.ConfigurationData) {
      const instance = new ConfigurationData();
      // Setup auto-save after instance is fully created
      instance.setupAutoSave();
    }
    return SingletonRegistry.ConfigurationData!;
  }
