import {
  Box
} from '@mui/material';
import { createTheme, Theme } from '@mui/material/styles';
import { Component } from 'react';
import { LogViewer } from '../Common/LogViewer';

interface LogViewerDrawerState {
  // Add any drawer-specific state here if needed
}

interface LogViewerDrawerProps {
  onViewChange?: (view: string) => void;
}

class LogViewerDrawerComponent extends Component<LogViewerDrawerProps, LogViewerDrawerState> {
  private theme: Theme;

  constructor(props: LogViewerDrawerProps) {
    super(props);
    this.theme = createTheme();
    this.state = {};
  }

  render() {
    return (
      <Box
        sx={{
          height: '100%',
          display: 'flex',
          flexDirection: 'column',
          backgroundColor: this.theme.palette.background.default,
          overflow: 'hidden',
        }}
      >
        <LogViewer />
      </Box>
    );
  }
}

export const LogViewerDrawer = LogViewerDrawerComponent;
