/**
 * StageConfirmationDialog - Dialog for M00, M01, M02 confirmation
 * Shows a simple confirmation message and waits for user to press Continue
 */

import {
    Close as CloseIcon,
    PlayArrow as CycleStartIcon,
    Warning as WarningIcon
} from '@mui/icons-material';
import {
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    Typography
} from '@mui/material';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';

export interface StageConfirmationDialogProps {
    open: boolean;
    title: string;
    message: string;
    showWarning?: boolean;
    confirmButtonText?: string;
    cancelButtonText?: string;
    onConfirm: () => void;
    onCancel: () => void;
}

export function StageConfirmationDialog({
    open,
    title,
    message,
    showWarning = false,
    confirmButtonText = 'Continue',
    cancelButtonText = 'Cancel Job',
    onConfirm,
    onCancel
}: StageConfirmationDialogProps) {
    const colors = ConfigurationDataColors.Instance;

    return (
        <Dialog
            open={open}
            maxWidth="sm"
            fullWidth
            disableEscapeKeyDown
        >
            <DialogTitle sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                backgroundColor: colors.primaryColor,
                color: colors.lightTextColor,
                py: 2,
                px: 3
            }}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    {showWarning && <WarningIcon />}
                    {title}
                </Box>
                <IconButton
                    onClick={onCancel}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>

            <DialogContent sx={{ position: 'relative', minHeight: 120, pb: 6 }}>
                {(() => {
                    // Parse message to separate main content from jogging/instruction text
                    const lines = message.split('\n').filter(line => line.trim());
                    const mainMessage: string[] = [];
                    const secondaryInfo: string[] = [];

                    for (const line of lines) {
                        const trimmed = line.trim();
                        // Filter out instruction lines and jogging info
                        if (trimmed.toLowerCase().includes('jogging is enabled')) {
                            secondaryInfo.push(trimmed);
                        } else if (trimmed.toLowerCase().includes('press continue') ||
                            trimmed.toLowerCase().includes('press cycle start') ||
                            (trimmed.toLowerCase().includes('cancel') && trimmed.toLowerCase().includes('stop'))) {
                            // Skip instruction text - it's redundant with the buttons
                            continue;
                        } else if (trimmed) {
                            mainMessage.push(trimmed);
                        }
                    }

                    return (
                        <>
                            {/* Main message - large and prominent */}
                            <Typography
                                variant="h5"
                                sx={{
                                    mt: 3,
                                    mb: 4,
                                    fontWeight: 'bold',
                                    color: 'text.primary',
                                    textAlign: 'center'
                                }}
                            >
                                {mainMessage.join(' ')}
                            </Typography>

                            {/* Secondary info (jogging) - small at bottom left */}
                            {secondaryInfo.length > 0 && (
                                <Box sx={{
                                    position: 'absolute',
                                    bottom: 16,
                                    left: 16,
                                }}>
                                    <Typography
                                        variant="caption"
                                        sx={{
                                            color: 'text.secondary',
                                            fontStyle: 'italic'
                                        }}
                                    >
                                        {secondaryInfo.join(' ')}
                                    </Typography>
                                </Box>
                            )}
                        </>
                    );
                })()}
            </DialogContent>

            <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${colors.borderColor}` }}>
                <Button
                    variant="outlined"
                    color="error"
                    size="large"
                    onClick={onCancel}
                >
                    {cancelButtonText}
                </Button>
                <Button
                    variant="contained"
                    size="large"
                    startIcon={<CycleStartIcon />}
                    onClick={onConfirm}
                    sx={{
                        backgroundColor: colors.primaryColor,
                        '&:hover': {
                            backgroundColor: colors.primaryColor,
                            opacity: 0.9
                        }
                    }}
                >
                    {confirmButtonText}
                </Button>
            </DialogActions>
        </Dialog>
    );
}
