import {
    Cancel as CancelIcon,
    Close as CloseIcon,
    Home as HomeIcon
} from '@mui/icons-material';
import {
    Box,
    Button,
    Checkbox,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    FormControl,
    FormControlLabel,
    IconButton,
    InputLabel,
    MenuItem,
    Select,
    Typography
} from '@mui/material';
import React from 'react';
import { SetupChecklistLibrary } from '../data/Checklist/SetupChecklistLibrary';
import { ToolLibrary } from '../data/Common/ToolLibrary';
import { ConfigurationDataColors } from '../data/ConfigurationDataColors';
import { ConfigurationState } from '../data/ConfigurationState';
import { MachineData } from '../data/Machine/MachineData';
import { MachineStateData } from '../data/MachineStateData';
import { UserMessageQueue } from '../data/UserMessageQueue';
import { TouchOffTarget } from '../machine/ICNCSystem';
import { IMachineCallback } from '../machine/IMachineCallback';
import { Machine } from '../machine/Machine';
import { LogCategory, Logger } from '../utils/Logger';
import { ObserveState } from '../utils/statemanager/ObserveState';
import { WizardManager } from './Wizard/WizardManager';
import { WarmUpSpindleWizard } from './wizards/spindle/WarmUpSpindleWizard';
import { SurfaceSpoilboardWizard } from './wizards/surfacing/SurfaceSpoilboardWizard';

/**
 * Setup operation - a function that accepts a callback for completion notification
 */
type SetupOperation = (callback: IMachineCallback) => void;

/**
 * HomePromptDialog appears when machine is not homed on startup
 * Prompts user to home the machine before operations
 * Includes optional spindle warmup and spoilboard touch-off
 */
export function HomePromptDialog() {
    const [warmupSpindle, setWarmupSpindle] = React.useState(false);
    const [currentToolNumber, setCurrentToolNumber] = React.useState<number | null>(null);
    const [setSpoilboardZ, setSetSpoilboardZ] = React.useState(false);
    const [surfaceSpoilboard, setSurfaceSpoilboard] = React.useState(false);
    const [measureTools, setMeasureTools] = React.useState(false);

    // Initialize currentToolNumber from machine state on first render
    React.useEffect(() => {
        setCurrentToolNumber(MachineStateData.Instance.currentToolNumber);
    }, []);

    const handleHome = () => {
        // Update machine state with selected current tool
        if (currentToolNumber !== null) {
            const machineState = MachineStateData.Instance;
            machineState.currentToolNumber = currentToolNumber;
            machineState.manualSave();
        }

        const machine = Machine.getInstance();

        // Home the machine using callback pattern
        machine.system.HomeMachine({
            onComplete: async () => {

                // Chain operations sequentially using callbacks only
                const operationsToRun: SetupOperation[] = [];

                // 1. Spindle warmup wizard
                if (warmupSpindle) {
                    operationsToRun.push((callback) => {
                        const wizard = new WarmUpSpindleWizard();
                        wizard.callback = callback;
                        WizardManager.Instance.start(wizard);
                    });
                }

                // 2. Measure current tool (if doing spoilboard operations)
                if (setSpoilboardZ || surfaceSpoilboard) {
                    operationsToRun.push((callback) => {
                        machine.system.measureCurrentTool(callback);
                    });
                }

                // 3. Set spoilboard Z (touch-off)
                if (setSpoilboardZ) {
                    operationsToRun.push((callback) => {
                        machine.system.touchOffMaterial(TouchOffTarget.SpoilBoard, callback);
                    });
                }

                // 4. Surface spoilboard wizard
                if (surfaceSpoilboard) {
                    operationsToRun.push((callback) => {
                        const wizard = new SurfaceSpoilboardWizard();
                        wizard.callback = callback;
                        WizardManager.Instance.start(wizard);
                    });
                }

                // 5. Measure all tools
                if (measureTools) {
                    operationsToRun.push((callback) => {
                        const { MeasureAllToolsWizard } = require('./wizards/measurealltools/MeasureAllToolsWizard');
                        MeasureAllToolsWizard.show(callback);
                    });
                }

                // Start the operation chain - each operation triggers the next via callback
                if (operationsToRun.length > 0) {
                    const startOperationChain = (index: number) => {
                        if (index >= operationsToRun.length) {
                            return;
                        }

                        const operation = operationsToRun[index];

                        // Create callback that chains to next operation
                        const chainCallback: IMachineCallback = {
                            onComplete: async () => {
                                startOperationChain(index + 1);
                            },
                            onCancel: async () => {
                            },
                            onError: async (error: Error | string) => {
                                Logger.Instance.logError(LogCategory.System, `Operation ${index + 1} error - stopping chain:`, error);
                            }
                        };

                        operation(chainCallback);
                    };

                    startOperationChain(0);
                }
            },
            onError: async (error: Error | string) => {
                Logger.Instance.logError(LogCategory.System, 'Failed to home machine from startup prompt:', error);
                UserMessageQueue.Instance.addMessage('❌ Failed to home machine');
            }
        });
    };

    const handleDismiss = () => {
        // User chose not to home - just close the dialog
        // Set skipHoming to prevent dialog from showing again this session
        ConfigurationState.Instance.skipHoming = true;
    };

    return (
        <ObserveState
            key="home-prompt-dialog-observer"
            listenTo={ConfigurationState.Instance}
            properties={['isHomed', 'skipHoming']}
            control={() => {
                const configState = ConfigurationState.Instance;
                const colors = ConfigurationDataColors.Instance;
                const toolLibrary = ToolLibrary.Instance;
                const machineData = MachineData.Instance;
                const checklistLibrary = SetupChecklistLibrary.Instance;

                // Only show dialog when machine is not homed AND user hasn't skipped
                const open = !configState.isHomed && !configState.skipHoming;

                // Get incomplete checklist items
                const incompleteItems = checklistLibrary.incompleteItems;

                return (
                    <Dialog
                        open={open}
                        maxWidth="md"
                        fullWidth
                        disableEscapeKeyDown
                    >
                        <DialogTitle sx={{
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'space-between',
                            backgroundColor: colors.primaryColor,
                            color: colors.lightTextColor,
                            py: 2,
                            px: 3
                        }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                <HomeIcon />
                                Machine Setup Required
                            </Box>
                            <IconButton
                                onClick={handleDismiss}
                                sx={{
                                    color: colors.lightTextColor,
                                    '&:hover': {
                                        backgroundColor: colors.lightOverlay
                                    }
                                }}
                            >
                                <CloseIcon />
                            </IconButton>
                        </DialogTitle>

                        <DialogContent>
                            <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', gap: 3 }}>
                                <Typography variant="h6">
                                    Machine has not been homed
                                </Typography>

                                <Typography variant="body1">
                                    The machine needs to be homed before you can perform operations.
                                    Homing establishes the machine's zero reference point for all axes.
                                </Typography>

                                {incompleteItems.length > 0 && (
                                    <Box
                                        sx={{
                                            backgroundColor: colors.lightBackgroundColor,
                                            borderLeft: `4px solid ${colors.errorColor}`,
                                            borderRadius: 1,
                                            padding: 2
                                        }}
                                    >
                                        <Typography variant="subtitle2" sx={{ fontWeight: 'bold', marginBottom: 1 }}>
                                            ⚠ Incomplete Setup Items ({incompleteItems.length}):
                                        </Typography>
                                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                                            {incompleteItems.slice(0, 5).map((item, index) => (
                                                <Typography key={index} variant="body2">
                                                    • {item.name}
                                                </Typography>
                                            ))}
                                            {incompleteItems.length > 5 && (
                                                <Typography variant="body2" sx={{ fontStyle: 'italic', mt: 0.5 }}>
                                                    ... and {incompleteItems.length - 5} more items
                                                </Typography>
                                            )}
                                        </Box>
                                    </Box>
                                )}

                                <FormControl fullWidth>
                                    <InputLabel>Current Tool in Spindle</InputLabel>
                                    <Select
                                        value={currentToolNumber ?? ''}
                                        onChange={(e) => setCurrentToolNumber(e.target.value === '' ? null : Number(e.target.value))}
                                        label="Current Tool in Spindle"
                                    >
                                        <MenuItem value="">No Tool</MenuItem>
                                        {toolLibrary.tools
                                            .filter(tool => tool.toolNumber !== null)
                                            .sort((a, b) => (a.toolNumber ?? 0) - (b.toolNumber ?? 0))
                                            .map((tool) => (
                                                <MenuItem key={tool.toolNumber} value={tool.toolNumber!}>
                                                    T{tool.toolNumber} - {tool.displayName}
                                                </MenuItem>
                                            ))}
                                    </Select>
                                </FormControl>

                                <Box
                                    sx={{
                                        backgroundColor: colors.lightBackgroundColor,
                                        borderRadius: 1,
                                        padding: 2,
                                        border: `1px solid ${colors.borderColor}`
                                    }}
                                >
                                    <Typography variant="subtitle2" sx={{ fontWeight: 'bold', marginBottom: 1.5 }}>
                                        Additional Setup Options:
                                    </Typography>
                                    <FormControlLabel
                                        control={
                                            <Checkbox
                                                checked={warmupSpindle}
                                                onChange={(e) => setWarmupSpindle(e.target.checked)}
                                                sx={{
                                                    color: colors.primaryColor,
                                                    '&.Mui-checked': {
                                                        color: colors.primaryColor
                                                    }
                                                }}
                                            />
                                        }
                                        label="Warm up spindle"
                                    />
                                    <FormControlLabel
                                        control={
                                            <Checkbox
                                                checked={setSpoilboardZ}
                                                onChange={(e) => setSetSpoilboardZ(e.target.checked)}
                                                sx={{
                                                    color: colors.primaryColor,
                                                    '&.Mui-checked': {
                                                        color: colors.primaryColor
                                                    }
                                                }}
                                            />
                                        }
                                        label="Set spoilboard Z"
                                    />
                                    <FormControlLabel
                                        control={
                                            <Checkbox
                                                checked={surfaceSpoilboard}
                                                onChange={(e) => setSurfaceSpoilboard(e.target.checked)}
                                                sx={{
                                                    color: colors.primaryColor,
                                                    '&.Mui-checked': {
                                                        color: colors.primaryColor
                                                    }
                                                }}
                                            />
                                        }
                                        label="Surface spoilboard"
                                    />
                                    {machineData.hasATC && (
                                        <FormControlLabel
                                            control={
                                                <Checkbox
                                                    checked={measureTools}
                                                    onChange={(e) => setMeasureTools(e.target.checked)}
                                                    sx={{
                                                        color: colors.primaryColor,
                                                        '&.Mui-checked': {
                                                            color: colors.primaryColor
                                                        }
                                                    }}
                                                />
                                            }
                                            label="Measure all tools"
                                        />
                                    )}
                                </Box>

                                <Box
                                    sx={{
                                        backgroundColor: colors.lightBackgroundColor,
                                        borderLeft: `4px solid ${colors.warningColor}`,
                                        borderRadius: 1,
                                        padding: 2
                                    }}
                                >
                                    <Typography variant="body2" sx={{ fontWeight: 'bold', marginBottom: 1 }}>
                                        ⚠ Important Safety Notes:
                                    </Typography>
                                    <Typography variant="body2" component="div">
                                        • Ensure the work area is clear
                                        <br />
                                        • Machine will move to home position on all axes
                                        <br />
                                        • Be ready to press emergency stop if needed
                                    </Typography>
                                </Box>
                            </Box>
                        </DialogContent>

                        <DialogActions sx={{
                            p: 2,
                            gap: 1,
                            justifyContent: 'flex-end',
                            borderTop: `1px solid ${colors.borderColor}`
                        }}>
                            <Button
                                onClick={handleDismiss}
                                variant="outlined"
                                startIcon={<CancelIcon />}
                            >
                                Skip for Now
                            </Button>
                            <Button
                                onClick={handleHome}
                                variant="contained"
                                startIcon={<HomeIcon />}
                                sx={{
                                    backgroundColor: colors.primaryColor,
                                    '&:hover': {
                                        backgroundColor: colors.primaryColor,
                                        filter: 'brightness(0.9)'
                                    }
                                }}
                            >
                                {warmupSpindle || setSpoilboardZ || surfaceSpoilboard || measureTools
                                    ? 'Home & Run Setup'
                                    : 'Home Machine Now'}
                            </Button>
                        </DialogActions>
                    </Dialog>
                );
            }}
        />
    );
}
