import { Box, Button, Typography } from '@mui/material';
import React, { useState } from 'react';
import { ToolLibrary } from '../../../../data/Common/ToolLibrary';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { NumberInput } from '../../../Common/NumberInput';
import { ToolSelectionDialog } from '../../../Common/ToolSelectionDialog';
import { WizardStep } from '../../../Wizard/WizardStep';
import { SurfaceSpoilboardWizard } from '../SurfaceSpoilboardWizard';
import { SurfacingStep } from './SurfacingStep';

export class SelectToolParametersStep extends WizardStep {
    constructor(wizard: SurfaceSpoilboardWizard, priorStep: WizardStep | null = null) {
        super(wizard, priorStep);
    }

    getTitle(): string {
        return 'Surface Spoilboard - Tool & Parameters';
    }

    nextStep(): WizardStep | null {
        return new SurfacingStep(this.wizard as SurfaceSpoilboardWizard, this);
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return (
            <ObserveState
                key="select-tool-parameters-step"
                listenTo={ConfigurationData.Instance}
                properties={[
                    'surfacingSpoilboardToolNumber',
                    'surfacingSpoilboardSpindleSpeed',
                    'surfacingSpoilboardFeedRate',
                    'surfacingSpoilboardStepover',
                    'surfacingSpoilboardAmountToRemove',
                    'surfacingSpoilboardOverlapEdge'
                ]}
                control={() => <SelectToolParametersStepComponent step={this} />}
            />
        );
    }
}

interface SelectToolParametersStepComponentProps {
    step: SelectToolParametersStep;
}

function SelectToolParametersStepComponent({ step }: SelectToolParametersStepComponentProps) {
    const config = ConfigurationData.Instance;
    const colors = ConfigurationDataColors.Instance;
    const wizard = step.wizard as SurfaceSpoilboardWizard;
    const toolLibrary = ToolLibrary.Instance;

    const [toolDialogOpen, setToolDialogOpen] = useState(false);

    const selectedTool = config.surfacingSpoilboardToolNumber ?
        toolLibrary.getToolByNumber(config.surfacingSpoilboardToolNumber) : null;

    const handleChangeTool = () => {
        setToolDialogOpen(true);
    };

    const handleCloseToolDialog = () => {
        setToolDialogOpen(false);
    };

    const handleToolSelected = (toolNumber: number) => {
        config.surfacingSpoilboardToolNumber = toolNumber;
        StateManager.propertyChanged(config, 'surfacingSpoilboardToolNumber');
    };

    const handleRun = () => {
        // Update wizard state from ConfigurationData
        wizard.state = {
            ...wizard.state,
            selectedToolNumber: config.surfacingSpoilboardToolNumber,
            spindleSpeed: config.surfacingSpoilboardSpindleSpeed,
            stepover: config.surfacingSpoilboardStepover,
            amountToRemove: config.surfacingSpoilboardAmountToRemove
        };
        StateManager.propertyChanged(wizard, 'state');
        wizard.advanceToNextStep();
    };

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>
            <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 2 }}>
                <Typography variant="body1" sx={{ color: colors.darkTextColor }}>
                    Configure the tool and parameters for surfacing the spoilboard.
                </Typography>

                <Box
                    sx={{
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                        gap: 2,
                        p: 2,
                        border: `1px solid ${colors.borderColor}`,
                        borderRadius: 1,
                        backgroundColor: colors.lightBackgroundColor,
                        cursor: 'pointer',
                        '&:hover': {
                            backgroundColor: colors.hoverColor,
                            borderColor: colors.primaryColor
                        }
                    }}
                    onClick={handleChangeTool}
                >
                    <Box>
                        <Typography variant="body2" sx={{ color: colors.mutedTextColor, fontSize: '0.875rem' }}>
                            Selected Tool
                        </Typography>
                        <Typography variant="body1" sx={{ fontWeight: 600, color: selectedTool ? colors.darkTextColor : colors.errorColor }}>
                            {selectedTool ? `Tool ${selectedTool.toolNumber} - ${selectedTool.toolName}` : 'No tool selected'}
                        </Typography>
                    </Box>
                    <Button
                        variant="outlined"
                        size="small"
                        onClick={(e) => {
                            e.stopPropagation();
                            handleChangeTool();
                        }}
                    >
                        Change Tool
                    </Button>
                </Box>

                <NumberInput
                    label="Spindle Speed (RPM)"
                    sx={{ width: 200 }}
                    value={config.surfacingSpoilboardSpindleSpeed}
                    onChange={(value) => {
                        config.surfacingSpoilboardSpindleSpeed = value;
                        StateManager.propertyChanged(config, 'surfacingSpoilboardSpindleSpeed');
                    }}
                    allowNegative={false}
                    allowFractions={false}
                    min={0}
                />

                <NumberInput
                    label="Feed Rate (IPM)"
                    sx={{ width: 200 }}
                    value={config.surfacingSpoilboardFeedRate}
                    onChange={(value) => {
                        config.surfacingSpoilboardFeedRate = value;
                        StateManager.propertyChanged(config, 'surfacingSpoilboardFeedRate');
                    }}
                    allowNegative={false}
                    allowFractions={false}
                    min={1}
                />

                <NumberInput
                    label="Stepover (inches)"
                    sx={{ width: 200 }}
                    value={config.surfacingSpoilboardStepover}
                    onChange={(value) => {
                        config.surfacingSpoilboardStepover = value;
                        StateManager.propertyChanged(config, 'surfacingSpoilboardStepover');
                    }}
                    allowNegative={false}
                    min={0.01}
                    max={2}
                    precision={2}
                />

                <NumberInput
                    label="Amount to Remove (inches)"
                    sx={{ width: 200 }}
                    value={config.surfacingSpoilboardAmountToRemove}
                    onChange={(value) => {
                        config.surfacingSpoilboardAmountToRemove = value;
                        StateManager.propertyChanged(config, 'surfacingSpoilboardAmountToRemove');
                    }}
                    allowNegative={false}
                    min={0.001}
                    max={0.5}
                    precision={3}
                />

                <NumberInput
                    label="Overlap Edge (inches)"
                    sx={{ width: 200 }}
                    value={config.surfacingSpoilboardOverlapEdge}
                    onChange={(value) => {
                        config.surfacingSpoilboardOverlapEdge = value;
                        StateManager.propertyChanged(config, 'surfacingSpoilboardOverlapEdge');
                    }}
                    allowNegative={false}
                    min={0}
                    max={2}
                    precision={2}
                />
            </Box>

            <Box sx={{ display: 'flex', justifyContent: 'space-between', gap: 2, pt: 2, borderTop: `1px solid ${colors.borderColor}` }}>
                <Button
                    variant="text"
                    onClick={() => wizard.goToPreviousStep()}
                >
                    Back
                </Button>
                <Box sx={{ display: 'flex', gap: 2 }}>
                    <Button
                        variant="outlined"
                        onClick={() => wizard.cancelWizard()}
                    >
                        Cancel
                    </Button>
                    <Button
                        variant="contained"
                        onClick={handleRun}
                        disabled={!config.surfacingSpoilboardToolNumber}
                    >
                        Run Surfacing
                    </Button>
                </Box>
            </Box>

            <ToolSelectionDialog
                open={toolDialogOpen}
                onClose={handleCloseToolDialog}
                onToolSelected={handleToolSelected}
            />
        </Box>
    );
}
