// Jog increment speed multipliers (X1, X10, X100)
export enum JogIncrementSpeed {
  X1 = 'X1',
  X10 = 'X10',
  X100 = 'X100'
}

/**
 * Request object for G-code preview dialog
 * Contains code, title, optional callback for completion, and auto-run flag
 */
export interface GCodePreviewRequest {
  title: string;
  code: string[];
  callback?: GCodeExecutionCallback;
  startImmediately?: boolean;  // If true, auto-run on dialog open (default: false)
  showPreviewSettings?: boolean; // If true, show option to disable preview in settings (default: false)
}

/**
 * Handler for cycle start button/action
 * Allows code to show a cycle start prompt and execute when user presses cycle start
 */
export interface CycleStartHandler {
  /** Title for the cycle start prompt */
  title: string;
  /** Message to display to the user */
  message: string;
  /** Async method to execute when cycle start is pressed */
  onCycleStart: () => Promise<void>;
  /** Optional callback when the prompt is cancelled/closed */
  onCancel?: () => void;
}

/**
 * Long-running system operation state
 * Used for operations like load tool, drop tool, measure tool, home machine, etc.
 */
export interface LongRunningOperation {
  /** Title shown in dialog (e.g., "Loading Tool", "Homing Machine") */
  title: string;
  /** Status message displayed to user */
  message: string;
  /** Optional callback for operation lifecycle events */
  callback?: IMachineCallback;
  /** Optional duration in milliseconds - for simulator countdown */
  duration?: number;
  /** Complete the operation - calls onComplete callback */
  complete: () => Promise<void>;
  /** Cancel the operation - calls onCancel callback */
  cancel: () => Promise<void>;
}

