  /**
   * Set installed PLC version from controller (synced from ServerStatus)
   */
  public set installedPLCVersion(value: string | { major: number; minor: number; update: number }) {
    let newVersion: { major: number; minor: number; update: number };

    if (typeof value === 'string') {
      // Parse string format "1.2.3"
      const parts = value.split('.').map(p => parseInt(p) || 0);
      newVersion = {
        major: parts[0] || 0,
        minor: parts[1] || 0,
        update: parts[2] || 0
      };
    } else {
      newVersion = value;
    }

    if (this._installedPLCVersion.major !== newVersion.major ||
      this._installedPLCVersion.minor !== newVersion.minor ||
      this._installedPLCVersion.update !== newVersion.update) {
      this._installedPLCVersion = newVersion;
      StateManager.propertyChanged(this, 'installedPLCVersion');
    }
  }

