  public get safeModeRemainingTime(): number {
    return this._safeModeRemainingTime;
  }

  public get isSafeModeActive(): boolean {
    return this._delayOff || this._collisionOff || this._softLimitsOff;
  }

  /**
   * Public method to restart the countdown with current timeout value
   * Used when timeout setting is changed while countdown is active
   */
  public restartSafeModeCountdown(): void {
    if (this.isSafeModeActive) {
      // Clear existing countdown if running
      if (this._safeModeTimeoutId !== null) {
        clearInterval(this._safeModeTimeoutId);
        this._safeModeTimeoutId = null;
      }

      // Start new countdown with current timeout setting
      this.startSafeModeCountdown();
    }
  }

  // Safe mode countdown management
  private startSafeModeCountdown(): void {
    // Get countdown duration from ConfigurationData
    const countdownDuration = ConfigurationData.Instance.safeModeTimeout;

    // If countdown is already running, restart it from the beginning
    if (this._safeModeTimeoutId !== null) {
      // Just reset the start time to restart the countdown
      this._safeModeStartTime = Date.now();
      this._safeModeRemainingTime = countdownDuration;
      StateManager.propertyChanged(this, 'safeModeRemainingTime');
      return;
    }

    // Start new countdown
    this._safeModeStartTime = Date.now();
    this._safeModeRemainingTime = countdownDuration;
    StateManager.propertyChanged(this, 'safeModeRemainingTime');

    // Update countdown every 100ms for smooth progress bar
    const updateInterval = setInterval(() => {
      if (this._safeModeStartTime === null) {
        clearInterval(updateInterval);
        return;
      }

      const elapsed = Date.now() - this._safeModeStartTime;
      this._safeModeRemainingTime = Math.max(0, countdownDuration - elapsed);

      // Use requestAnimationFrame to ensure safe DOM updates
      requestAnimationFrame(() => {
        StateManager.propertyChanged(this, 'safeModeRemainingTime');
      });

      // Check if countdown is complete
      if (this._safeModeRemainingTime <= 0) {
        clearInterval(updateInterval);
        this.resetAllSafeModes();
      }
    }, 100);

    this._safeModeTimeoutId = updateInterval as unknown as number;
  }

  private checkClearSafeModeCountdown(): void {
    // If all safe modes are turned off, clear the countdown
    if (!this._delayOff && !this._collisionOff && !this._softLimitsOff) {
      if (this._safeModeTimeoutId !== null) {
        clearTimeout(this._safeModeTimeoutId);
        clearInterval(this._safeModeTimeoutId);
        this._safeModeTimeoutId = null;
      }
      this._safeModeStartTime = null;
      this._safeModeRemainingTime = 0;
      StateManager.propertyChanged(this, 'safeModeRemainingTime');
    }
  }

  private resetAllSafeModes(): void {
    // Clear timeout first
    this._safeModeTimeoutId = null;
    this._safeModeStartTime = null;
    this._safeModeRemainingTime = 0;

    // Reset modes using a timeout to avoid unmounting slider during event handling
    setTimeout(() => {
      // Set the private fields directly to avoid triggering countdown restart
      const wasDelayOff = this._delayOff;
      const wasCollisionOff = this._collisionOff;
      const wasSoftLimitsOff = this._softLimitsOff;

      this._delayOff = false;
      this._collisionOff = false;
      this._softLimitsOff = false;

      // Only notify if values actually changed
      if (wasDelayOff) {
        StateManager.propertyChanged(this, 'delayOff');
      }
      if (wasCollisionOff) {
        StateManager.propertyChanged(this, 'collisionOff');
      }
      if (wasSoftLimitsOff) {
        StateManager.propertyChanged(this, 'softLimitsOff');
      }

      StateManager.propertyChanged(this, 'safeModeRemainingTime');
    }, 0);
  }

  // Utility methods for spindle selection behavior
  public selectSpindle(): void {
    // Don't allow spindle dragging if machine is not homed
    if (!this._isHomed) {
      return;
    }
    this.selectedObject = 'spindle';
    this.isSpindleDragging = true;
    this.isOrbitEnabled = false;
  }

  public deselectSpindle(): void {
    if (this.selectedObject === 'spindle') {
      this.selectedObject = null;
    }
    this.isSpindleDragging = false;
    this.isOrbitEnabled = true;
  }

  public selectClamp(clampId: string): void {
    this.selectedClampId = clampId;
    this.selectedObject = `clamp-${clampId}`;
  }

  public deselectClamp(): void {
    this.selectedClampId = null;
    if (this.selectedObject?.startsWith('clamp-')) {
      this.selectedObject = null;
    }
  }

