import { Button, Grid } from '@mui/material';
import { ConfigurationState } from '../../../../data/ConfigurationState';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';
import { SetupChecklistIndicator } from '../../../Common/SetupChecklistIndicator';

export function SoftLimitsSection() {
    const machine = MachineData.Instance;

    const handleCaptureLowerLimits = () => {
        const currentPos = ConfigurationState.Instance.currentMachinePoint;
        machine.xLowerSoftLimitFromMachineZero = currentPos.x;
        machine.yLowerSoftLimitFromMachineZero = currentPos.y;
        machine.zLowerSoftLimitFromMachineZero = currentPos.z;
    };

    const handleCaptureUpperLimits = () => {
        const currentPos = ConfigurationState.Instance.currentMachinePoint;
        machine.xUpperSoftLimitFromMachineZero = currentPos.x;
        machine.yUpperSoftLimitFromMachineZero = currentPos.y;
        machine.zUpperSoftLimitFromMachineZero = currentPos.z;
    };

    return (
        <Grid container spacing={3}>
            <Grid item xs={12}>
                <SetupChecklistIndicator name="Soft Limits" />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="soft-limits-x-lower"
                    listenTo={machine}
                    properties={['xLowerSoftLimitFromMachineZero']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="X Lower Soft Limit"
                            value={machine.xLowerSoftLimitFromMachineZero}
                            onChange={(value) => machine.xLowerSoftLimitFromMachineZero = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="soft-limits-x-upper"
                    listenTo={machine}
                    properties={['xUpperSoftLimitFromMachineZero']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="X Upper Soft Limit"
                            value={machine.xUpperSoftLimitFromMachineZero}
                            onChange={(value) => machine.xUpperSoftLimitFromMachineZero = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="soft-limits-y-lower"
                    listenTo={machine}
                    properties={['yLowerSoftLimitFromMachineZero']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Y Lower Soft Limit"
                            value={machine.yLowerSoftLimitFromMachineZero}
                            onChange={(value) => machine.yLowerSoftLimitFromMachineZero = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="soft-limits-y-upper"
                    listenTo={machine}
                    properties={['yUpperSoftLimitFromMachineZero']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Y Upper Soft Limit"
                            value={machine.yUpperSoftLimitFromMachineZero}
                            onChange={(value) => machine.yUpperSoftLimitFromMachineZero = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="soft-limits-z-lower"
                    listenTo={machine}
                    properties={['zLowerSoftLimitFromMachineZero']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Z Lower Soft Limit"
                            value={machine.zLowerSoftLimitFromMachineZero}
                            onChange={(value) => machine.zLowerSoftLimitFromMachineZero = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="soft-limits-z-upper"
                    listenTo={machine}
                    properties={['zUpperSoftLimitFromMachineZero']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Z Upper Soft Limit"
                            value={machine.zUpperSoftLimitFromMachineZero}
                            onChange={(value) => machine.zUpperSoftLimitFromMachineZero = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            {/* Capture Buttons */}
            <Grid item xs={12} md={6}>
                <Button
                    fullWidth
                    variant="outlined"
                    onClick={handleCaptureLowerLimits}
                    sx={{ mt: 1 }}
                >
                    Capture Lower Limits (Front, Left, Bottom)
                </Button>
            </Grid>

            <Grid item xs={12} md={6}>
                <Button
                    fullWidth
                    variant="outlined"
                    onClick={handleCaptureUpperLimits}
                    sx={{ mt: 1 }}
                >
                    Capture Upper Limits (Back, Right, Top)
                </Button>
            </Grid>
        </Grid>
    );
}
