import {
  Box,
  Button,
  List,
  ListItem,
  ListItemButton,
  ListItemText,
  Typography
} from '@mui/material';
import { useEffect, useState } from 'react';
import { CNCPoint } from '../../data/CNCPoint';
import { CoordinateType } from '../../data/Common/CoordinateType';
import { Fixture, FixtureLibrary } from '../../data/Common/FixtureLibrary';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { Job } from '../../data/Job';
import { MachineData } from '../../data/Machine/MachineData';
import { MachineStateData } from '../../data/MachineStateData';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { ActionBus } from '../../utils/actions/ActionBus';
import { MoveAction, MoveType } from '../../utils/actions/MoveAction';
import { ConfirmDialogManager } from '../../utils/ConfirmDialogManager';
import { CoordinateUtil } from '../../utils/CoordinateUtil';
import { ObserveMultiProperties } from '../../utils/statemanager/ObserveMultiProperties';
import { ViewDataFactory, ViewNames } from '../../utils/ViewDataFactory';
import { FullSizeCNCViewer } from '../MachineViewer/FullSizeCNCViewer';
import { DraggableDialog } from './DraggableDialog';

interface FixtureSelectionDialogProps {
  open: boolean;
  onClose: () => void;
}

export function FixtureSelectionDialog({ open, onClose }: FixtureSelectionDialogProps) {
  const [simulatorViewData] = useState(() => ViewDataFactory.createForContext(ViewNames.FIXTURE_SELECTION));
  const [selectedFixture, setSelectedFixture] = useState<Fixture | null>(null);

  const availableFixtures = FixtureLibrary.Instance.fixtures
    // Remove duplicates by fixture number (or name if number is empty)
    .filter((fixture, index, array) =>
      array.findIndex(f => {
        const key1 = f.fixtureNumber || f.name;
        const key2 = fixture.fixtureNumber || fixture.name;
        return key1 === key2;
      }) === index
    );

  const machineState = MachineStateData.Instance;
  const currentWorkZero = machineState.currentWorkZero;
  const matchingFixture = machineState.getMatchingFixture();

  // Initialize selected fixture to matching fixture when dialog opens
  useEffect(() => {
    if (open && matchingFixture) {
      // Get fresh fixture list
      const availableFixtures = FixtureLibrary.Instance.fixtures
        .filter((fixture, index, array) =>
          array.findIndex(f => {
            const key1 = f.fixtureNumber || f.name;
            const key2 = fixture.fixtureNumber || fixture.name;
            return key1 === key2;
          }) === index
        );

      // Check if matching fixture is in the available fixtures list
      const currentKey = matchingFixture.fixtureNumber || matchingFixture.name;
      const isMatchingFixtureAvailable = availableFixtures.some(
        fixture => (fixture.fixtureNumber || fixture.name) === currentKey
      );
      if (isMatchingFixtureAvailable) {
        setSelectedFixture(matchingFixture);
      }
    }
  }, [open, matchingFixture]);

  const handleGoToXY = (fixture: Fixture) => {
    // Move tool tip to fixture XY position at current Z height
    const currentMachineZ = ConfigurationState.Instance.currentMachinePoint.z;
    const fixtureXY = new CNCPoint(fixture.xOffset, fixture.yOffset, currentMachineZ, CoordinateType.MachineZero);

    // Calculate machine position where tool tip will be at fixture XY
    const targetPosition = CoordinateUtil.machinePositionForToolTipAtFixture(fixtureXY);
    const moveAction = MoveAction.fromCNCPoint(targetPosition, MoveType.Coordinates);
    ActionBus.Instance.addAction(moveAction);
  };

  const handleGoTo = (fixture: Fixture) => {
    // Move tool tip to fixture position
    const fixturePosition = new CNCPoint(fixture.xOffset, fixture.yOffset, fixture.zOffset, CoordinateType.MachineZero);

    // Calculate machine position where tool tip will be at fixture
    const targetPosition = CoordinateUtil.machinePositionForToolTipAtFixture(fixturePosition);


    const moveAction = MoveAction.fromCNCPoint(targetPosition, MoveType.Coordinates);
    ActionBus.Instance.addAction(moveAction);
  };

  const handleUseXYZ = (fixture: Fixture) => {
    // Copy all three axes from fixture to work zero
    machineState.setWorkZeroFromFixture(fixture, true);
    UserMessageQueue.Instance.addMessage(`✓ Work zero set to ${fixture.fixtureNumber || fixture.name} (XYZ)`);
  };

  const handleUseXY = (fixture: Fixture) => {
    // Copy only X and Y from fixture, preserve current Z
    machineState.setWorkZeroFromFixture(fixture, false);
    UserMessageQueue.Instance.addMessage(`✓ Work zero set to ${fixture.fixtureNumber || fixture.name} (XY only)`);
  };

  const handleCapturePosition = async (fixture: Fixture) => {
    // Get current machine position (tool tip location in machine coordinates)
    const currentMachinePoint = ConfigurationState.Instance.currentMachinePoint;

    // Show confirmation dialog
    const confirmed = await ConfirmDialogManager.Instance.showConfirm({
      title: 'Capture Current Position',
      message: `Are you sure you want to update fixture ${fixture.fixtureNumber || fixture.name} to the current position?\n\nNew coordinates will be:\nX: ${currentMachinePoint.x.toFixed(3)}"\nY: ${currentMachinePoint.y.toFixed(3)}"\nZ: ${currentMachinePoint.z.toFixed(3)}"`,
      confirmText: 'Yes, Capture',
      severity: 'warning'
    });

    if (confirmed) {
      // Update fixture with current machine coordinates
      fixture.xOffset = currentMachinePoint.x;
      fixture.yOffset = currentMachinePoint.y;
      fixture.zOffset = currentMachinePoint.z;

      UserMessageQueue.Instance.addMessage(`✓ Captured current position for ${fixture.fixtureNumber || fixture.name}`);
    }
  };

  const handleClose = () => {
    setSelectedFixture(null);
    onClose();
  };

  const formatFixtureName = (fixture: Fixture) => {
    // If name and number are the same, only show the name
    if (fixture.name === fixture.fixtureNumber) {
      return fixture.name;
    }
    // Otherwise show name(number) format
    return `${fixture.name}(${fixture.fixtureNumber})`;
  };

  // Helper function to check if we're at a specific position (within tolerance)
  const isAtPosition = (x: number, y: number, z?: number) => {
    const currentPos = ConfigurationState.Instance.currentMachinePoint;
    const tolerance = 0.001; // 0.001" tolerance

    const atXY = Math.abs(currentPos.x - x) < tolerance && Math.abs(currentPos.y - y) < tolerance;

    if (z !== undefined) {
      return atXY && Math.abs(currentPos.z - z) < tolerance;
    }

    return atXY;
  };

  return (
    <DraggableDialog
      open={open}
      onClose={(event?: any, reason?: any) => {
        handleClose();
      }}
      title="WCS Location/Known Point"
      maxWidth="xl"
      fullWidth
      PaperProps={{
        sx: { height: 'auto', maxHeight: '90vh' }
      }}
      actions={
        <Button
          onClick={() => {
            handleClose();
          }}
          variant="contained"
          sx={{
            backgroundColor: ConfigurationDataColors.Instance.primaryColor,
            '&:hover': {
              backgroundColor: ConfigurationDataColors.Instance.primaryColor,
              opacity: 0.9
            }
          }}
        >
          Close
        </Button>
      }
    >
      <Box sx={{ display: 'flex', height: '600px', gap: 2 }}>
        {/* Left side - Fixture controls and info */}
        <Box sx={{ width: '40%', display: 'flex', flexDirection: 'column', gap: 2 }}>

          {/* Fixture Selection List */}
          <Box sx={{
            flex: 1,
            border: `1px solid ${ConfigurationDataColors.Instance.borderColor}`,
            borderRadius: 1,
            overflow: 'hidden',
            display: 'flex',
            flexDirection: 'column',
            minHeight: 0
          }}>
            <Typography variant="subtitle2" sx={{
              p: 1,
              backgroundColor: ConfigurationDataColors.Instance.lightTextColor,
              borderBottom: `1px solid ${ConfigurationDataColors.Instance.borderColor}`
            }}>
              Choose Fixture
            </Typography>
            <List sx={{
              flex: 1,
              overflow: 'auto',
              p: 0
            }}>
              {availableFixtures.map((fixture) => {
                const fixtureKey = fixture.fixtureNumber || fixture.name;
                const isSelected = selectedFixture ? (selectedFixture.fixtureNumber || selectedFixture.name) === fixtureKey : false;

                return (
                  <ObserveMultiProperties
                    key={`fixture-item-${fixtureKey}`}
                    listenTo={[
                      { object: machineState, properties: ['currentWorkZero'] },
                      { object: fixture, properties: ['xOffset', 'yOffset', 'zOffset'] }
                    ]}
                    control={() => {
                      // Check if this fixture matches the current work zero (XY only, Z is ignored)
                      const tolerance = 0.0001;
                      const matchesWorkZero = !fixture.isComputed &&
                        Math.abs(fixture.xOffset - currentWorkZero.x) < tolerance &&
                        Math.abs(fixture.yOffset - currentWorkZero.y) < tolerance;

                      // Highlight if it's the current work zero OR if user has selected it
                      const shouldHighlight = matchesWorkZero || isSelected;

                      return (
                        <ListItem disablePadding>
                          <ListItemButton
                            selected={shouldHighlight}
                            onClick={() => {
                              setSelectedFixture(fixture);
                            }}
                            sx={{
                              '&.Mui-selected': {
                                backgroundColor: `${ConfigurationDataColors.Instance.primaryColor}33`, // 20% opacity
                                borderLeft: `4px solid ${ConfigurationDataColors.Instance.primaryColor}`,
                                '&:hover': {
                                  backgroundColor: `${ConfigurationDataColors.Instance.primaryColor}4D`, // 30% opacity
                                }
                              }
                            }}
                          >
                            <ListItemText
                              primary={formatFixtureName(fixture)}
                              primaryTypographyProps={{
                                sx: {
                                  fontWeight: matchesWorkZero ? 'bold' : 'normal',
                                  fontSize: '0.95rem'
                                }
                              }}
                              secondary={matchesWorkZero ? '(current)' : undefined}
                            />
                            <Typography
                              variant="caption"
                              sx={{
                                fontFamily: 'monospace',
                                color: ConfigurationDataColors.Instance.darkTextColor,
                                whiteSpace: 'nowrap',
                                ml: 2
                              }}
                            >
                              {!fixture.isComputed && `X${fixture.xOffset.toFixed(3)} Y${fixture.yOffset.toFixed(3)} Z${fixture.zOffset.toFixed(3)}`}
                            </Typography>
                          </ListItemButton>
                        </ListItem>
                      );
                    }}
                  />
                );
              })}
            </List>
          </Box>

          {/* Action Buttons */}
          {selectedFixture && (
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
              {/* Navigation and Use buttons */}
              <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end', alignItems: 'center' }}>
                {/* Show message if already at fixture position */}
                {isAtPosition(selectedFixture.xOffset, selectedFixture.yOffset, selectedFixture.zOffset) ? (
                  <Typography variant="body2" color="text.secondary" sx={{ fontStyle: 'italic' }}>
                    ✓ Already at fixture position
                  </Typography>
                ) : (
                  <>
                    {/* Go To XY button */}
                    <Button
                      variant="outlined"
                      onClick={() => handleGoToXY(selectedFixture)}
                      sx={{ textTransform: 'none' }}
                    >
                      Go To XY
                    </Button>

                    {/* Go To button */}
                    <Button
                      variant="outlined"
                      onClick={() => handleGoTo(selectedFixture)}
                      sx={{ textTransform: 'none' }}
                    >
                      Go To
                    </Button>

                    {/* Show Use buttons if fixture has a number (not a known point) */}
                    {selectedFixture.fixtureNumber && (
                      <>
                        <Button
                          variant="outlined"
                          onClick={() => handleUseXY(selectedFixture)}
                          sx={{ textTransform: 'none', fontWeight: 'bold' }}
                        >
                          Use XY
                        </Button>
                        <Button
                          variant="contained"
                          onClick={() => handleUseXYZ(selectedFixture)}
                          sx={{ fontWeight: 'bold' }}
                        >
                          Use XYZ
                        </Button>
                      </>
                    )}
                  </>
                )}
              </Box>

              {/* Capture Position link - only show for non-system fixtures */}
              {!selectedFixture.systemControlled && (
                <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 0.5 }}>
                  <Typography
                    variant="body2"
                    onClick={() => handleCapturePosition(selectedFixture)}
                    sx={{
                      color: ConfigurationDataColors.Instance.primaryColor,
                      textDecoration: 'underline',
                      cursor: 'pointer',
                      '&:hover': {
                        opacity: 0.7
                      }
                    }}
                  >
                    Capture Current Position
                  </Typography>
                </Box>
              )}
            </Box>
          )}
        </Box>

        {/* Right side - 3D viewer only */}
        <Box sx={{ flex: 1, minHeight: 0 }}>
          <FullSizeCNCViewer
            simulatorViewData={simulatorViewData}
            machineState={MachineStateData.Instance}
            machineData={MachineData.Instance}
            job={ConfigurationState.Instance.currentJob || Job.createTestJob()}
          />
        </Box>
      </Box>
    </DraggableDialog>
  );
}