import Box from '@mui/material/Box';
import CssBaseline from '@mui/material/CssBaseline';
import { ThemeProvider, createTheme } from '@mui/material/styles';
import Typography from '@mui/material/Typography';
import React from 'react';
import './App.css';
import { GCodePreviewDialog } from './components/Common/GCodePreviewDialog';
import { ModalLayer } from './components/Common/ModalLayer';
import { NotificationArea } from './components/Common/NotificationArea';
import { ResetRequiredWatcher } from './components/Common/ResetRequiredWatcher';
import { ConnectionOverlay } from './components/ConnectionOverlay';
import { ConnectionSplashScreen } from './components/ConnectionSplashScreen';
import { HomePromptDialog } from './components/HomePromptDialog';
import { HavenCNCLayout } from './components/Layout/HavenCNCLayout';
import { LoadingSplashScreen } from './components/LoadingSplashScreen';
import { LongRunningOperationDialog } from './components/LongRunningOperationDialog';
import { WizardContainer } from './components/Wizard/WizardContainer';
import { AppStateData } from './data/AppStateData';
import { ConfigurationData } from './data/ConfigurationData';
import { ConfigurationDataColors } from './data/ConfigurationDataColors';
import { ConfigurationState } from './data/ConfigurationState';
import { DataManager } from './data/DataManager';
import { SignalRMessagesData } from './data/SignalRMessagesData';
import { UserMessageQueue } from './data/UserMessageQueue';
import { Machine } from './machine/Machine';
import { CoordinateUtil } from './utils/CoordinateUtil';
import { JobCallbackManager } from './utils/JobCallbackManager';
import { LogCategory, Logger } from './utils/Logger';
import { MachineInterfaceManager } from './utils/MachineInterfaceManager';
import { SignalRIOUpdater } from './utils/SignalRIOUpdater';
import { SignalRManager } from './utils/SignalRManager';
import { SignalRPositionUpdater } from './utils/SignalRPositionUpdater';
import { ObserveState } from './utils/statemanager/ObserveState';

/**
 * Create a reactive Material-UI theme based on current ConfigurationData
 * This function will be called whenever observed configuration properties change
 */
function createReactiveTheme() {
  const config = ConfigurationData.Instance;
  const colors = ConfigurationDataColors.Instance;

  return createTheme({
    palette: {
      mode: 'light',
      primary: {
        main: colors.primaryColor,
      },
      secondary: {
        main: colors.secondaryColor,
      },
    },
    typography: {
      fontSize: 18, // Simple larger base font size
      htmlFontSize: 18,
      // Standard typography variants with slightly larger sizes
      h1: {
        fontSize: '2.5rem',
      },
      h2: {
        fontSize: '2.0rem',
      },
      h3: {
        fontSize: '1.75rem',
      },
      h4: {
        fontSize: '1.5rem',
      },
      h5: {
        fontSize: '1.25rem',
      },
      h6: {
        fontSize: '1.1rem',
      },
      body1: {
        fontSize: '1.0rem',
      },
      body2: {
        fontSize: '0.95rem', // Slightly larger than default
      },
      caption: {
        fontSize: '0.85rem', // Slightly larger than default
      },
      button: {
        fontSize: '0.95rem', // Slightly larger than default
      },
    },
    components: {
      MuiSlider: {
        styleOverrides: {
          root: {
            color: colors.primaryColor,
          },
          track: {
            backgroundColor: colors.primaryColor,
          },
          rail: {
            backgroundColor: colors.borderColor,
          },
          thumb: {
            backgroundColor: colors.primaryColor,
            '&:hover': {
              boxShadow: `0 0 0 8px ${colors.primaryColor}33`,
            },
          },
          mark: {
            backgroundColor: colors.mutedTextColor,
          },
          markLabel: {
            color: colors.darkTextColor,
          },
        },
      },
    },
  });
}

function App() {
  // // //// console.log('App component rendering...');

  // Connection state management
  const [isServerConnected, setIsServerConnected] = React.useState(false);

  // Fullscreen state management
  const [isFullscreen, setIsFullscreen] = React.useState(false);

  // Set minimum window size and start in fullscreen
  React.useEffect(() => {
    // Set minimum window size for desktop apps (Electron)
    if (window.require) {
      try {
        const { ipcRenderer } = window.require('electron');
        // Set minimum size to 1900x1000
        ipcRenderer.send('set-min-size', { width: 1900, height: 1000 });
      } catch (error) {
        Logger.Instance.logError(LogCategory.System, 'Could not set minimum window size - not running in Electron:', error);
      }
    }

    // Start in fullscreen mode
    const enterFullscreen = async () => {
      try {
        if (document.documentElement.requestFullscreen) {
          await document.documentElement.requestFullscreen();
          setIsFullscreen(true);
        }
      } catch (error) {
        Logger.Instance.logError(LogCategory.System, 'Could not enter fullscreen on startup:', error);
      }
    };

    // Small delay to ensure DOM is ready
    setTimeout(enterFullscreen, 100);

    // Listen for fullscreen changes
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };

    // Listen for F11 key to toggle fullscreen
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'F11') {
        event.preventDefault();
        toggleFullscreen();
      }
    };

    document.addEventListener('fullscreenchange', handleFullscreenChange);
    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('fullscreenchange', handleFullscreenChange);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, []);

  // Fullscreen toggle function
  const toggleFullscreen = async () => {
    try {
      if (!document.fullscreenElement) {
        await document.documentElement.requestFullscreen();
        UserMessageQueue.Instance.addMessage('✓ Entered fullscreen mode (Press F11 or click button to exit)');
      } else {
        await document.exitFullscreen();
        UserMessageQueue.Instance.addMessage('✓ Exited fullscreen mode');
      }
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Error toggling fullscreen:', error);
      UserMessageQueue.Instance.addMessage('⚠ Could not toggle fullscreen mode');
    }
  };

  // Initialize data on startup
  React.useEffect(() => {
    const initializeApp = async () => {
      try {

        // Initialize machine interface manager based on URL parameters
        MachineInterfaceManager.Instance.initialize();

        const serverUrl = MachineInterfaceManager.Instance.getServerUrl();

        // Initialize SignalR connection if server URL is configured
        try {
          const signalRInitialized = await SignalRManager.Instance.autoInitialize();

          if (signalRInitialized) {

            // Initialize JobCallbackManager to listen for job events
            JobCallbackManager.Instance.initialize();

            // Start listening for DRO position updates from SignalR
            SignalRPositionUpdater.Instance.startListening();

            // IMPORTANT: Start SignalRMessagesData FIRST so it captures messages
            // Then SignalRIOUpdater can enhance them before display
            SignalRMessagesData.Instance.startListening();

            // Start listening for I/O status updates from SignalR
            // This runs after messages are captured but can still update state
            SignalRIOUpdater.Instance.startListening();
          } else {

            // CRITICAL: Even in simulator mode, we need SignalRPositionUpdater for connection monitoring
            // Creating the instance starts the connection state watcher
            void SignalRPositionUpdater.Instance;
          }

          // Expose SignalRManager globally for console debugging
          (window as any).SignalRManager = SignalRManager.Instance;
          (window as any).JobCallbackManager = JobCallbackManager.Instance;
        } catch (signalRError) {
          console.error('[App] ❌ Failed to initialize SignalR:', signalRError);
          Logger.Instance.logError(LogCategory.Network, 'Failed to initialize SignalR:', signalRError);
        }

        // Expose DataManager globally for console debugging
        (window as any).DataManager = DataManager.Instance;

        // Initialize soft limits cache from API
        try {
        } catch (limitsError) {
          console.error('[App] ⚠ Failed to initialize soft limits cache:', limitsError);
          Logger.Instance.logError(LogCategory.System, 'Failed to initialize soft limits cache:', limitsError);
        }

        // Initialize data - load existing or create initial save
        // This will report progress through AppStateData
        await DataManager.Instance.initializeOnStartup();

        // Apply default jog settings from ConfigurationData to machine controller
        try {
          const machine = Machine.getInstance();
          const config = ConfigurationData.Instance;

          // Set jog increment speed (X1, X10, X100)
          await machine.movement.SetJogIncrementSpeed(config.defaultJogIncrementSpeed);

          // Set jog fast/slow mode (false = slow, true = fast)
          await machine.movement.SetFastJog(config.defaultJogFastMode);

          // Set jog continuous/incremental mode (true = continuous, false = incremental)
          await machine.movement.SetContinuousJog(config.defaultJogContinuousMode);

          Logger.Instance.log(LogCategory.System, `Applied default jog settings: speed=${config.defaultJogIncrementSpeed}, fast=${config.defaultJogFastMode}, continuous=${config.defaultJogContinuousMode}`);
        } catch (jogSettingsError) {
          Logger.Instance.logError(LogCategory.System, 'Failed to apply default jog settings:', jogSettingsError);
        }

        // Initialize ActionData early so it's ready for UI components
        const { ActionData } = await import('./data/ActionData');
        // Trigger singleton creation and loading by accessing the Instance
        void ActionData.Instance;

        // Fetch initial machine position AFTER data is loaded (so offsets are correct)
        // This ensures we have position data immediately instead of waiting for heartbeat
        if (serverUrl) {
          try {
            Logger.Instance.log(LogCategory.System, 'Fetching initial machine position from API (after offsets loaded)');

            const machine = Machine.getInstance();
            const position = await machine.movement.GetCurrentPosition();

            Logger.Instance.log(
              LogCategory.System,
              `Initial position fetched: X:${position.x.toFixed(4)} Y:${position.y.toFixed(4)} Z:${position.z.toFixed(4)} (${position.coordinateType})`
            );

            const machineZeroPosition = CoordinateUtil.toMachineZero(position);

            Logger.Instance.log(
              LogCategory.System,
              `Initial position converted to MachineZero: X:${machineZeroPosition.x.toFixed(4)} Y:${machineZeroPosition.y.toFixed(4)} Z:${machineZeroPosition.z.toFixed(4)}`
            );

            ConfigurationState.Instance.currentMachinePoint = machineZeroPosition;
            // Note: StateManager.propertyChanged is already called in the setter

            Logger.Instance.log(LogCategory.System, 'Initial position successfully set in MachineStateData (with correct offsets)');
          } catch (positionError) {
            console.error('[App] ⚠ Failed to fetch initial position:', positionError);
            Logger.Instance.logError(LogCategory.System, 'Failed to fetch initial position:', positionError);
          }
        }

        // Test message system after initialization
        setTimeout(() => {
          try {
            UserMessageQueue.Instance.addMessage('App initialized successfully!');
          } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Error adding test message:', error);
          }
        }, 1000);
      } catch (error) {
        Logger.Instance.logError(LogCategory.System, 'Error during app initialization:', error);
        // Don't block the UI - AppStateData will handle error state
        try {
          UserMessageQueue.Instance.addMessage('Warning: App initialization had issues - some features may not work correctly');
        } catch (msgError) {
        }
      }
    };

    // Start initialization (don't await - let splash screen show)
    initializeApp();
  }, []);

  // Render based on app state and configuration changes
  return (
    <ObserveState
      key="app-state-observer"
      listenTo={AppStateData.Instance}
      properties={['isInitialized', 'isLoading']}
      control={() => {
        const appState = AppStateData.Instance;

        // Create theme reactively - this will observe configuration changes
        return (
          <ObserveState
            key="app-config-theme-observer"
            listenTo={ConfigurationDataColors.Instance}
            properties={['primaryColor', 'secondaryColor', 'borderColor', 'mutedTextColor', 'darkTextColor']}
            control={() => {
              const theme = createReactiveTheme();

              // Step 1: Show connection splash screen until server connection is established
              if (!isServerConnected) {
                return (
                  <ThemeProvider theme={theme}>
                    <CssBaseline />
                    <ConnectionSplashScreen onConnected={() => setIsServerConnected(true)} />
                  </ThemeProvider>
                );
              }

              // Step 2: Show loading splash screen while loading app data
              if (!appState.isInitialized) {
                return (
                  <ThemeProvider theme={theme}>
                    <CssBaseline />
                    <LoadingSplashScreen />
                  </ThemeProvider>
                );
              }
              // Step 3: Show main app when initialized
              try {
                return (
                  <ThemeProvider theme={theme}>
                    <CssBaseline />
                    <Box sx={{ display: 'flex', height: '100vh' }}>
                      <HavenCNCLayout
                        isFullscreen={isFullscreen}
                        onToggleFullscreen={toggleFullscreen}
                      />
                    </Box>
                    <WizardContainer />
                    <ModalLayer />
                    <GCodePreviewDialog />
                    <NotificationArea />
                    <ResetRequiredWatcher />
                    <ConnectionOverlay />
                    <HomePromptDialog />
                    <LongRunningOperationDialog />
                  </ThemeProvider>
                );
              } catch (error) {
                Logger.Instance.logError(LogCategory.System, 'Error in main App component:', error);
                return (
                  <ThemeProvider theme={theme}>
                    <CssBaseline />
                    <Box sx={{ display: 'flex', height: '100vh', padding: '20px' }}>
                      <Typography variant="h4" color="error">
                        Error: {error instanceof Error ? error.message : 'Unknown error'}
                      </Typography>
                    </Box>
                  </ThemeProvider>
                );
              }
            }}
          />
        );
      }}
    />
  );
}

export default App;
