import { StateManager } from '../utils/statemanager/StateManager';

/**
 * Available views in the application
 */
export enum ViewType {
    Home = 'home',
    MDI = 'mdi',
    Learning = 'learning',
    Milling = 'milling',
    Turning = 'turning',
    Laser = 'laser',
    Settings = 'settings',
    Flow = 'flow',
    Viewer = 'viewer',
    PLC = 'plc'
}

/**
 * Drawer types available in the layout
 */
export type DrawerType = 'control' | 'actions' | 'logs' | 'io' | 'signalr' | 'recent' | null;

/**
 * Centralized state management for the main application layout.
 * Tracks current view, drawer state, and dialog visibility.
 */
export class LayoutState {
    private static _instance: LayoutState;

    private _selectedView: ViewType = ViewType.Home;
    private _activeDrawer: DrawerType = null;
    private _drawerOpen: boolean = false;
    private _isPLCEditorOpen: boolean = false;

    private constructor() { }

    public static get Instance(): LayoutState {
        if (!LayoutState._instance) {
            LayoutState._instance = new LayoutState();
        }
        return LayoutState._instance;
    }

    // Selected view management
    public get selectedView(): ViewType {
        return this._selectedView;
    }

    public set selectedView(value: ViewType) {
        if (value !== this._selectedView) {
            this._selectedView = value;
            StateManager.propertyChanged(this, 'selectedView');
        }
    }

    // Active drawer management
    public get activeDrawer(): DrawerType {
        return this._activeDrawer;
    }

    public set activeDrawer(value: DrawerType) {
        if (value !== this._activeDrawer) {
            this._activeDrawer = value;
            StateManager.propertyChanged(this, 'activeDrawer');
        }
    }

    // Drawer open/closed state
    public get drawerOpen(): boolean {
        return this._drawerOpen;
    }

    public set drawerOpen(value: boolean) {
        if (value !== this._drawerOpen) {
            this._drawerOpen = value;
            StateManager.propertyChanged(this, 'drawerOpen');
        }
    }

    // PLC Editor dialog state
    public get isPLCEditorOpen(): boolean {
        return this._isPLCEditorOpen;
    }

    public set isPLCEditorOpen(value: boolean) {
        if (value !== this._isPLCEditorOpen) {
            this._isPLCEditorOpen = value;
            StateManager.propertyChanged(this, 'isPLCEditorOpen');
        }
    }

    // Navigation helper methods
    public navigateToView(view: ViewType): void {
        // Special case: if view is PLC, open the PLC editor modal
        if (view === ViewType.PLC) {
            this.isPLCEditorOpen = true;
            return;
        }

        // Special case: if navigating to Milling, reset the workflow
        if (view === ViewType.Milling) {
            const { MillingWorkflowState } = require('./MillingWorkflowState');
            MillingWorkflowState.Instance.reset();
        }

        this.selectedView = view;

        // Update drawer state based on view
        const defaultDrawer = this.getDefaultDrawerForView(view);
        this.activeDrawer = defaultDrawer;
        this.drawerOpen = false; // All drawers start closed
    }

    public navigateToHome(): void {
        this.navigateToView(ViewType.Home);
    }

    public toggleDrawer(drawerType: DrawerType): void {
        if (this.activeDrawer === drawerType && this.drawerOpen) {
            // Close the drawer if it's already open
            this.drawerOpen = false;
        } else {
            // Open the requested drawer
            this.activeDrawer = drawerType;
            this.drawerOpen = true;
        }
    }

    public closeDrawer(): void {
        this.drawerOpen = false;
    }

    public openPLCEditor(): void {
        this.isPLCEditorOpen = true;
    }

    public closePLCEditor(): void {
        this.isPLCEditorOpen = false;
    }

    // Determine default drawer type for a view
    private getDefaultDrawerForView(view: ViewType): DrawerType {
        switch (view) {
            case ViewType.Home:
            case ViewType.Viewer:
                return 'control'; // Control panel should be default for home/viewer
            case ViewType.Settings:
            case ViewType.Milling:
            case ViewType.Turning:
            case ViewType.MDI:
            case ViewType.Learning:
            case ViewType.Laser:
            case ViewType.Flow:
            case ViewType.PLC:
                return null; // All other views start with drawers closed
        }
    }
}
