import {
    ChevronRight as ChevronRightIcon,
    Close as CloseIcon,
    Storage as DriveIcon,
    ExpandMore as ExpandMoreIcon,
    Folder as FolderIcon
} from '@mui/icons-material';
import {
    Box,
    Button,
    CircularProgress,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    List,
    ListItemButton,
    ListItemIcon,
    ListItemText,
    TextField,
    Typography
} from '@mui/material';
import React, { useEffect, useState } from 'react';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { Machine } from '../../machine/Machine';
import { DirectoryInfoResponse, DriveInfoResponse } from '../../services/src/models';
import { BackendAvailabilityChecker } from '../../utils/BackendAvailabilityChecker';
import { LogCategory, Logger } from '../../utils/Logger';

export interface DirectoryBrowserDialogProps {
    open: boolean;
    onClose: () => void;
    onSelect: (path: string) => void;
    title?: string;
    confirmText?: string;
}

interface TreeNode {
    path: string;
    name: string;
    isExpanded: boolean;
    isLoading: boolean;
    children: TreeNode[];
    hasSubdirectories: boolean;
}

/**
 * Directory browser dialog with tree navigation using backend API
 * Falls back to manual entry if backend not available
 */
export function DirectoryBrowserDialog({
    open,
    onClose,
    onSelect,
    title = 'Select Directory',
    confirmText = 'Select'
}: DirectoryBrowserDialogProps) {
    const colors = ConfigurationDataColors.Instance;
    const [isBackendAvailable, setIsBackendAvailable] = useState(false);
    const [loading, setLoading] = useState(true);
    const [drives, setDrives] = useState<TreeNode[]>([]);
    const [selectedPath, setSelectedPath] = useState<string>('');
    const [manualPath, setManualPath] = useState<string>('');
    const [error, setError] = useState<string | null>(null);

    // Check backend availability and load drives
    useEffect(() => {
        if (!open) return;

        const checkBackendAndLoadDrives = async () => {
            setLoading(true);
            setError(null);

            try {
                // Check if backend is available using the standard utility
                const backendAvailable = await BackendAvailabilityChecker.isBackendAvailable();

                if (!backendAvailable) {
                    setIsBackendAvailable(false);
                    setLoading(false);
                    return;
                }

                // Backend is available - try to fetch drives
                const machine = Machine.getInstance();
                const driveList = await machine.setup.GetDrives();

                // Convert drives to tree nodes
                const driveNodes: TreeNode[] = driveList.map((drive: DriveInfoResponse) => ({
                    path: drive.name || '',
                    name: `${drive.name || ''} ${drive.label ? `(${drive.label})` : ''}`,
                    isExpanded: false,
                    isLoading: false,
                    children: [],
                    hasSubdirectories: true // Drives always have subdirectories
                }));

                setDrives(driveNodes);
                setIsBackendAvailable(true);
            } catch (error) {
                Logger.Instance.logError(LogCategory.System, 'Failed to load drives:', error);
                setIsBackendAvailable(false);
            } finally {
                setLoading(false);
            }
        };

        checkBackendAndLoadDrives();
    }, [open]);

    // Load subdirectories for a path
    const loadSubdirectories = async (node: TreeNode): Promise<TreeNode[]> => {
        try {
            const machine = Machine.getInstance();
            const directories = await machine.setup.GetDirectories(node.path);

            return directories.map((dir: DirectoryInfoResponse) => ({
                path: dir.fullPath || '',
                name: dir.name || '',
                isExpanded: false,
                isLoading: false,
                children: [],
                hasSubdirectories: dir.hasSubdirectories || false
            }));
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, `Failed to load directories for ${node.path}:`, error);
            throw error;
        }
    };

    // Handle node expansion
    const handleNodeToggle = async (node: TreeNode, index: number[]) => {
        if (!node.hasSubdirectories) return;

        // Toggle expansion state
        node.isExpanded = !node.isExpanded;

        if (node.isExpanded && node.children.length === 0) {
            // Load children
            node.isLoading = true;
            setDrives([...drives]); // Trigger re-render

            try {
                const children = await loadSubdirectories(node);
                node.children = children;
                node.isLoading = false;
                setDrives([...drives]); // Trigger re-render
            } catch (error) {
                node.isLoading = false;
                node.isExpanded = false;
                setDrives([...drives]); // Trigger re-render
                setError('Failed to load subdirectories');
            }
        } else {
            setDrives([...drives]); // Trigger re-render
        }
    };

    // Handle directory selection
    const handleSelectDirectory = (path: string) => {
        setSelectedPath(path);
    };

    // Handle confirm
    const handleConfirm = () => {
        const pathToUse = isBackendAvailable ? selectedPath : manualPath;
        if (pathToUse) {
            onSelect(pathToUse);
            onClose();
        }
    };

    // Recursive tree rendering
    const renderTreeNode = (node: TreeNode, index: number[], level: number = 0) => {
        const hasChildren = node.hasSubdirectories;
        const paddingLeft = level * 2;

        return (
            <React.Fragment key={node.path}>
                <ListItemButton
                    onClick={() => handleSelectDirectory(node.path)}
                    selected={selectedPath === node.path}
                    sx={{ pl: paddingLeft }}
                >
                    {hasChildren && (
                        <IconButton
                            size="small"
                            onClick={(e) => {
                                e.stopPropagation();
                                handleNodeToggle(node, index);
                            }}
                            sx={{ mr: 1 }}
                        >
                            {node.isLoading ? (
                                <CircularProgress size={20} />
                            ) : node.isExpanded ? (
                                <ExpandMoreIcon />
                            ) : (
                                <ChevronRightIcon />
                            )}
                        </IconButton>
                    )}
                    {!hasChildren && <Box sx={{ width: 40 }} />}
                    <ListItemIcon sx={{ minWidth: 40 }}>
                        {level === 0 ? <DriveIcon /> : <FolderIcon />}
                    </ListItemIcon>
                    <ListItemText
                        primary={node.name}
                        primaryTypographyProps={{
                            variant: 'body2',
                            sx: { fontFamily: 'monospace' }
                        }}
                    />
                </ListItemButton>

                {node.isExpanded && node.children.map((child, childIndex) =>
                    renderTreeNode(child, [...index, childIndex], level + 1)
                )}
            </React.Fragment>
        );
    };

    return (
        <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
            <DialogTitle
                sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    backgroundColor: colors.primaryColor,
                    color: colors.lightTextColor,
                    py: 2,
                    px: 3
                }}
            >
                {title}
                <IconButton
                    onClick={onClose}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>

            <DialogContent dividers>
                <Box sx={{ mt: 3 }}>
                    {loading ? (
                        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: 200 }}>
                            <CircularProgress />
                        </Box>
                    ) : !isBackendAvailable ? (
                        <Box sx={{ textAlign: 'center', p: 3 }}>
                            <Typography variant="body1" color="text.secondary" gutterBottom>
                                Backend not connected. Please type the directory path manually.
                            </Typography>
                            <TextField
                                fullWidth
                                label="Directory Path"
                                placeholder="C:\Projects\CNC"
                                value={manualPath}
                                onChange={(e) => setManualPath(e.target.value)}
                                sx={{ mt: 2 }}
                                helperText="Enter the full path to the directory you want to monitor"
                            />
                        </Box>
                    ) : drives.length === 0 ? (
                        <Box sx={{ textAlign: 'center', p: 3 }}>
                            <Typography variant="body1" color="text.secondary">
                                No drives found
                            </Typography>
                        </Box>
                    ) : (
                        <>
                            <Typography variant="body2" color="text.secondary" gutterBottom>
                                Select a directory to monitor for G-code files:
                            </Typography>
                            {error && (
                                <Typography variant="body2" color="error" sx={{ mb: 2 }}>
                                    {error}
                                </Typography>
                            )}
                            <List sx={{ maxHeight: 400, overflow: 'auto', border: `1px solid ${colors.borderColor}`, borderRadius: 1 }}>
                                {drives.map((drive, index) => renderTreeNode(drive, [index], 0))}
                            </List>
                            {selectedPath && (
                                <Box sx={{ mt: 2, p: 2, backgroundColor: colors.lightBackgroundColor, borderRadius: 1 }}>
                                    <Typography variant="caption" color="text.secondary">
                                        Selected Path:
                                    </Typography>
                                    <Typography variant="body2" sx={{ fontFamily: 'monospace', wordBreak: 'break-all' }}>
                                        {selectedPath}
                                    </Typography>
                                </Box>
                            )}
                        </>
                    )}
                </Box>
            </DialogContent>

            <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${colors.borderColor}` }}>
                <Button onClick={onClose} variant="outlined">
                    Cancel
                </Button>
                <Button
                    onClick={handleConfirm}
                    variant="contained"
                    disabled={isBackendAvailable ? !selectedPath : !manualPath.trim()}
                    sx={{
                        backgroundColor: colors.primaryColor,
                        '&:hover': {
                            backgroundColor: colors.primaryColor,
                            opacity: 0.9
                        }
                    }}
                >
                    {confirmText}
                </Button>
            </DialogActions>
        </Dialog>
    );
}
