import { Box, Button, FormControl, Menu, MenuItem, Select, ToggleButton, ToggleButtonGroup, Typography } from '@mui/material';
import React from 'react';
import { NumberInput } from '../../../components/Common/NumberInput';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ObserveMultiState } from '../../../utils/statemanager/ObserveMultiState';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { DataUtilities } from '../../../utils/storage/DataUtilities';
import { ComparisonOperator } from './ComparisonOperator';
import { Condition } from './Condition';
import { DataElement } from './DataElement';
import { DataType, Declaration } from './Declaration';
import { IPLCElement, OutputState, OutputType, PLCRenderMode, PLCValidationIssue } from './IPLCElement';
import { MemoryBitState } from './MemoryBitState';
import { PLCProgramType, PLCSerializationHelper, PLCUtilities } from './PLCUtilities';

/**
 * DataCondition class - A condition based on a data element
 * Handles all data types with appropriate comparison logic (similar to AssignmentPredicate pattern)
 */
export class DataCondition extends Condition {
    private _dataElement: DataElement;
    private _comparisonOperator: ComparisonOperator = ComparisonOperator.Equal;
    private _memoryBitState: MemoryBitState = MemoryBitState.Set;
    private _useConstant: boolean = true;
    private _comparisonValue: string = '';
    private _comparisonElement: DataElement | undefined;
    private _tolerance: number = 0.001; // For float comparisons

    constructor(dataElement?: DataElement) {
        super();
        this._dataElement = dataElement || new DataElement();
        this._dataElement.allowNew = false;  // Conditions only check existing values
        this._dataElement.needsWrite = false;  // Conditions read values, don't write
        this._dataElement.setParentElement(this);

        // Set up cache invalidation listener
        PLCUtilities.setupCacheInvalidationListener(this);
    }

    /**
     * Get the type of condition
     */
    public get conditionType(): string {
        return 'DataCondition';
    }

    /**
     * Check if this condition is disabled
     * A DataCondition is disabled if:
     * 1. Its enabled property is false, OR
     * 2. (For SystemDefault conditions in System context) It references an input/output
     *    that is not available in the System PLC
     */
    public isDisabled(mode: PLCRenderMode, targetProgramType: PLCProgramType): boolean {
        // 1. Check enabled property
        if (!this.enabled) {
            return true;
        }

        // 2. Check if this is a SystemDefault element with unavailable declarations
        // CRITICAL: Only disable when RENDERING in System.plc (targetProgramType === System)
        // When rendering in SystemDefault, undefined I/O should NOT be disabled (that's where they're defined!)
        const elementProgramType = this.plcSource?.getProgramType();

        if (elementProgramType !== PLCProgramType.SystemDefault) {
            return false; // Not from SystemDefault, no need to check
        }

        // Only check if we're rendering in System PLC
        if (targetProgramType !== PLCProgramType.System) {
            return false; // Rendering in SystemDefault - don't disable undefined I/O
        }

        // This is a SystemDefault element being rendered in System PLC
        // Check if declarations are available in System
        const dataElements = this.getDataElements();

        for (const element of dataElements) {
            const shouldDisable = PLCUtilities.shouldBeDisabledDueToDeclarations(
                element,
                targetProgramType,  // Where we're rendering (System)
                elementProgramType  // Where element is from (SystemDefault)
            );
            if (shouldDisable) {
                return true; // Missing declaration in System, disable condition
            }
        }

        return false;
    }

    /**
     * The data element this condition references
     */
    public get dataElement(): DataElement {
        return this._dataElement;
    }

    public set dataElement(value: DataElement) {
        this._dataElement = value;
        if (this._dataElement) {
            this._dataElement.allowNew = false;  // Conditions only check existing values
            this._dataElement.needsWrite = false;  // Conditions read values, don't write
            this._dataElement.setParentElement(this);
        }
        StateManager.propertyChanged(this, 'dataElement');
    }

    public get comparisonOperator(): ComparisonOperator {
        return this._comparisonOperator;
    }

    public set comparisonOperator(value: ComparisonOperator) {
        this._comparisonOperator = value;
        StateManager.propertyChanged(this, 'comparisonOperator');
    }

    public get memoryBitState(): MemoryBitState {
        return this._memoryBitState;
    }

    public set memoryBitState(value: MemoryBitState) {
        this._memoryBitState = value;
        StateManager.propertyChanged(this, 'memoryBitState');
    }

    public get useConstant(): boolean {
        return this._useConstant;
    }

    public set useConstant(value: boolean) {
        this._useConstant = value;
        StateManager.propertyChanged(this, 'useConstant');
    }

    public get comparisonValue(): string {
        return this._comparisonValue;
    }

    public set comparisonValue(value: string) {
        this._comparisonValue = value;
        StateManager.propertyChanged(this, 'comparisonValue');
    }

    public get comparisonElement(): DataElement | undefined {
        return this._comparisonElement;
    }

    public set comparisonElement(value: DataElement | undefined) {
        this._comparisonElement = value;
        if (this._comparisonElement) {
            this._comparisonElement.allowNew = false;  // Conditions only check existing values
            this._comparisonElement.needsWrite = false;  // Conditions read values, don't write
            this._comparisonElement.setParentElement(this);
        }
        StateManager.propertyChanged(this, 'comparisonElement');
    }

    public get tolerance(): number {
        return this._tolerance;
    }

    public set tolerance(value: number) {
        this._tolerance = value;
        StateManager.propertyChanged(this, 'tolerance');
    }

    /**
     * Get all data elements used by this condition
     */
    public getDataElements(): DataElement[] {
        const elements: DataElement[] = [];
        if (this._dataElement) {
            elements.push(this._dataElement);
        }
        if (this._comparisonElement) {
            elements.push(this._comparisonElement);
        }
        return elements;
    }

    /**
     * Render the data condition to JSX - adapts based on data type
     * @param mode Rendering mode (Edit, ReadOnly, or Disabled)
     * @param targetProgramType The program type context for rendering
     */
    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode {
        return <DataConditionRenderer condition={this} renderMode={mode} targetProgramType={targetProgramType} />;
    }

    /**
     * Get declarations that are used/referenced by this condition
     * CRITICAL: Must return ALL declarations from both dataElement and comparisonElement
     */
    public getUsedDeclarations(): Declaration[] {
        const declarations: Declaration[] = [];

        // Always include main data element
        declarations.push(...this._dataElement.getUsedDeclarations());

        // Include comparison element if comparing to another element
        if (!this._useConstant && this._comparisonElement) {
            declarations.push(...this._comparisonElement.getUsedDeclarations());
        }

        // Remove duplicates by name
        const uniqueMap = new Map<string, Declaration>();
        for (const decl of declarations) {
            uniqueMap.set(decl.name, decl);
        }
        return Array.from(uniqueMap.values());
    }

    /**
     * Get declarations that are added/defined by this condition
     */
    public getAddedDeclarations(): Declaration[] {
        const declarations: Declaration[] = [];

        declarations.push(...this._dataElement.getAddedDeclarations());

        if (!this._useConstant && this._comparisonElement) {
            declarations.push(...this._comparisonElement.getAddedDeclarations());
        }

        // Remove duplicates by name
        const uniqueMap = new Map<string, Declaration>();
        for (const decl of declarations) {
            uniqueMap.set(decl.name, decl);
        }
        return Array.from(uniqueMap.values());
    }

    /**
     * Get the PLC logic code for this data condition
     * Returns a boolean expression string like "TailStockPD" or "Word1 > 100"
     */
    public getPLCLogic(availableDeclarations: string[]): string[] {
        if (!this.enabled) {
            return []; // Disabled conditions don't contribute to expression
        }

        // PLC logic generation is ALWAYS for System.plc context
        const targetProgramType = PLCProgramType.System;
        const disabled = this.isDisabled(PLCRenderMode.Edit, targetProgramType);

        if (disabled) {
            return []; // Conditions with unavailable I/O don't contribute to expression
        }

        const dataName = this._dataElement.effectiveName;
        if (!dataName) {
            return []; // Can't generate expression without data element
        }

        // Get the program and declaration to determine type
        const program = this._dataElement.getPLCProgram();
        const declaration = this._dataElement.declaration ||
            (this._dataElement.declarationName && program ?
                PLCUtilities.getDeclarationByName(program, this._dataElement.declarationName) :
                undefined);

        const dataType = declaration?.dataType;

        // Boolean/bit types - check for SET or RESET
        if (dataType === DataType.MemoryBit || dataType === DataType.Input ||
            dataType === DataType.Output || dataType === DataType.Stage) {
            // For RESET state, negate the expression
            if (this._memoryBitState === MemoryBitState.Reset) {
                return [`!${dataName}`];
            }
            // For SET state, just the name
            return [dataName];
        }

        // Numeric types - use comparison operator
        if (dataType === DataType.Word || dataType === DataType.DoubleWord ||
            dataType === DataType.FloatingPointWord || dataType === DataType.DoubleFloatingPointWord) {

            const operatorSymbol = this.getComparisonOperatorSymbol();

            if (this._useConstant) {
                // Compare to constant value
                return [`${dataName} ${operatorSymbol} ${this._comparisonValue || '0'}`];
            } else if (this._comparisonElement) {
                // Compare to another element
                const compName = this._comparisonElement.effectiveName;
                if (compName) {
                    return [`${dataName} ${operatorSymbol} ${compName}`];
                }
            }

            // Fallback if comparison not configured
            return [`${dataName} ${operatorSymbol} 0`];
        }

        // Unknown type - just return the name
        return [dataName];
    }

    /**
     * Get the comparison operator symbol for PLC output
     */
    private getComparisonOperatorSymbol(): string {
        switch (this._comparisonOperator) {
            case ComparisonOperator.Equal: return '==';
            case ComparisonOperator.NotEqual: return '!=';
            case ComparisonOperator.GreaterThan: return '>';
            case ComparisonOperator.LessThan: return '<';
            case ComparisonOperator.GreaterThanOrEqual: return '>=';
            case ComparisonOperator.LessThanOrEqual: return '<=';
            default: return '==';
        }
    }

    /**
     * Get validation issues for this data condition
     */
    public getValidationIssues(): PLCValidationIssue[] {
        const issues: PLCValidationIssue[] = [];

        // Validate that we have a data element
        if (!this._dataElement) {
            issues.push(new PLCValidationIssue(this, 'Data condition must have a data element'));
        } else {
            // Collect validation issues from the data element with context
            const dataElementIssues = this._dataElement.getValidationIssues();
            dataElementIssues.forEach(issue => {
                issues.push(new PLCValidationIssue(issue.element, `[Condition data element] ${issue.message}`));
            });
        }

        // Only validate comparison element if we're using element mode (not constant/value mode)
        if (!this._useConstant && this._comparisonElement) {
            const comparisonIssues = this._comparisonElement.getValidationIssues();
            comparisonIssues.forEach(issue => {
                issues.push(new PLCValidationIssue(issue.element, `[Comparison element] ${issue.message}`));
            });
        }

        return issues;
    }

    /**
     * Determine whether this data condition should be output
     * @param outputType The type of output (Render or PLCCode)
     * @param availableDeclarations Optional array of available declaration names
     * @returns OutputState indicating how this data condition should be handled
     */
    public shouldOutput(outputType: OutputType, availableDeclarations?: string[]): OutputState {
        // TODO: Define proper output logic later
        return OutputState.Output;
    }

    /**
     * Override setParentElement to cascade to child elements
     */
    public setParentElement(parent: IPLCElement | undefined): void {
        super.setParentElement(parent);
        // Cascade to data element and comparison element
        if (this._dataElement) {
            this._dataElement.setParentElement(this);
        }
        if (this._comparisonElement) {
            this._comparisonElement.setParentElement(this);
        }
    }

    /**
     * Get a short, single-line description of this condition for display in tree views
     * Examples: "havenreset is set", "spindle_speed > 100", "axis_x == target_pos"
     * @returns A human-readable summary of the condition
     */
    public getShortDescription(): string {
        const elementName = this._dataElement?.declarationName || '(unknown)';
        const dataType = this._dataElement?.declaration?.dataType;

        // For memory bits, show "is set" or "is reset"
        if (dataType === DataType.MemoryBit) {
            const stateText = this._memoryBitState === MemoryBitState.Set ? 'is set' : 'is reset';
            return `${elementName} ${stateText}`;
        }

        // For numeric types, show operator and value/element
        const operatorSymbol = this._comparisonOperator === ComparisonOperator.Equal ? '==' :
            this._comparisonOperator === ComparisonOperator.NotEqual ? '!=' :
                this._comparisonOperator === ComparisonOperator.GreaterThan ? '>' :
                    this._comparisonOperator === ComparisonOperator.LessThan ? '<' :
                        this._comparisonOperator === ComparisonOperator.GreaterThanOrEqual ? '>=' :
                            this._comparisonOperator === ComparisonOperator.LessThanOrEqual ? '<=' : '==';

        if (this._useConstant) {
            const value = this._comparisonValue || '0';
            return `${elementName} ${operatorSymbol} ${value}`;
        } else {
            const comparisonName = this._comparisonElement?.declarationName || '(unknown)';
            return `${elementName} ${operatorSymbol} ${comparisonName}`;
        }
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): any {
        const data: any = PLCSerializationHelper.getStorageData(this, ['_dataElement', '_comparisonElement']);
        data.conditionType = this.conditionType;
        if (this._dataElement) {
            data.dataElement = this._dataElement.toJSON();
        }
        if (this._comparisonElement) {
            data.comparisonElement = this._comparisonElement.toJSON();
        }
        return data;
    }

    /**
     * Load from JSON
     */
    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data, ['_dataElement', '_comparisonElement', 'dataElement', 'comparisonElement', 'conditionType']);

        // Load data element - support both old and new property names
        const dataElementData = data._dataElement || data.dataElement;
        if (dataElementData) {
            this._dataElement = new DataElement();
            this._dataElement.fromJSON(dataElementData);
            this._dataElement.allowNew = false;  // Conditions only check existing values
            this._dataElement.needsWrite = false;  // Conditions read values, don't write
            this._dataElement.setParentElement(this);
        }

        // Load comparison element - support both old and new property names
        const comparisonElementData = data._comparisonElement || data.comparisonElement;
        if (comparisonElementData) {
            this._comparisonElement = new DataElement();
            this._comparisonElement.fromJSON(comparisonElementData);
            this._comparisonElement.allowNew = false;  // Comparison elements only check existing values
            this._comparisonElement.needsWrite = false;  // Comparison elements read values, don't write
            this._comparisonElement.setParentElement(this);
        }
    }
}

/**
 * Functional component wrapper for DataCondition rendering to allow hooks
 */
function DataConditionRenderer({ condition, renderMode, targetProgramType }: { condition: DataCondition; renderMode?: PLCRenderMode; targetProgramType: PLCProgramType }) {
    const [stateMenuAnchor, setStateMenuAnchor] = React.useState<null | HTMLElement>(null);
    const isReadOnly = renderMode === PLCRenderMode.ReadOnly;
    const effectiveRenderMode = renderMode || PLCRenderMode.Edit;
    const colors = ConfigurationDataColors.Instance;

    return (
        <ObserveMultiState
            key="data-condition-renderer"
            listenTo={[condition, condition.dataElement]}

            control={() => {
                // Get the program and declaration to determine type
                const program = condition.dataElement.getPLCProgram();
                const declaration = condition.dataElement.declaration ||
                    (condition.dataElement.declarationName && program ?
                        PLCUtilities.getDeclarationByName(program, condition.dataElement.declarationName) :
                        undefined);

                const dataType = declaration?.dataType;
                const isBooleanType = dataType ? PLCUtilities.isBooleanType(dataType) : false;
                const isNumericType = dataType ? PLCUtilities.isNumericType(dataType) : false;

                // CRITICAL: Use the passed-in targetProgramType (rendering context)
                // NOT the element's plcSource (that's where it's defined, not where we're rendering)

                // Check if this condition is disabled due to unavailable declarations
                // OR if renderMode is explicitly Disabled (parent section disabled)
                const isConditionDisabled = effectiveRenderMode === PLCRenderMode.Disabled || condition.isDisabled(effectiveRenderMode, targetProgramType);
                const disabledStyle = isConditionDisabled ? {
                    opacity: 0.5,
                    textDecoration: 'line-through',
                    color: colors.mutedTextColor
                } : {};

                // Get friendly display text for SET/RESET based on data type (isCondition = true)
                const setDisplayText = PLCUtilities.getDataElementDisplayText(declaration, program, true, true) || 'SET';
                const resetDisplayText = PLCUtilities.getDataElementDisplayText(declaration, program, false, true) || 'RESET';

                return (
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap', ...disabledStyle }}>
                        {/* Always show the data element */}
                        {condition.dataElement.render(renderMode || PLCRenderMode.Edit, targetProgramType)}

                        {/* For boolean/bit types: Show clickable state */}
                        {isBooleanType && (
                            <>
                                <Typography sx={{ fontFamily: 'monospace', fontSize: '14px', mx: 0.25 }}>is</Typography>
                                <Button
                                    onClick={isReadOnly ? undefined : (e) => setStateMenuAnchor(e.currentTarget)}
                                    disabled={isReadOnly}
                                    size="small"
                                    sx={{
                                        fontFamily: 'monospace',
                                        fontSize: '12px',
                                        minWidth: 'auto',
                                        px: 1.5,
                                        py: 0.5,
                                        textTransform: 'none',
                                        backgroundColor: condition.memoryBitState === MemoryBitState.Set ? colors.successColor : colors.errorColor,
                                        color: colors.lightTextColor,
                                        '&:hover': {
                                            backgroundColor: condition.memoryBitState === MemoryBitState.Set ? colors.successColor : colors.errorColor,
                                            opacity: 0.9
                                        }
                                    }}
                                >
                                    {condition.memoryBitState === MemoryBitState.Set ? setDisplayText : resetDisplayText}
                                </Button>
                                <Menu
                                    anchorEl={stateMenuAnchor}
                                    open={Boolean(stateMenuAnchor)}
                                    onClose={() => setStateMenuAnchor(null)}
                                >
                                    <MenuItem
                                        onClick={() => {
                                            condition.memoryBitState = MemoryBitState.Set;
                                            setStateMenuAnchor(null);
                                        }}
                                    >
                                        {setDisplayText}
                                    </MenuItem>
                                    <MenuItem
                                        onClick={() => {
                                            condition.memoryBitState = MemoryBitState.Reset;
                                            setStateMenuAnchor(null);
                                        }}
                                    >
                                        {resetDisplayText}
                                    </MenuItem>
                                </Menu>
                            </>
                        )}

                        {/* For numeric types: Show operator + value/element */}
                        {isNumericType && (
                            <>
                                <FormControl
                                    size="small"
                                    variant="standard"
                                    sx={{
                                        minWidth: 'auto',
                                        '& .MuiInput-root': {
                                            fontFamily: 'monospace',
                                            fontSize: '14px',
                                            backgroundColor: colors.lightBackgroundColor,
                                            border: `1px solid ${colors.secondaryBorderColor}`,
                                            borderRadius: '4px',
                                            px: 1,
                                            py: 0.5,
                                            '&:before': {
                                                borderBottom: 'none'
                                            },
                                            '&:after': {
                                                borderBottom: 'none'
                                            },
                                            '&:hover:not(.Mui-disabled):before': {
                                                borderBottom: 'none'
                                            }
                                        },
                                        '& .MuiSelect-select': {
                                            paddingTop: 0,
                                            paddingBottom: 0,
                                            paddingRight: '24px !important',
                                            color: colors.darkTextColor
                                        },
                                        '& .MuiSelect-icon': {
                                            color: colors.primaryColor
                                        }
                                    }}
                                >
                                    <Select
                                        value={condition.comparisonOperator}
                                        onChange={(e) => condition.comparisonOperator = e.target.value as ComparisonOperator}
                                        disabled={isReadOnly}
                                    >
                                        <MenuItem value={ComparisonOperator.Equal}>==</MenuItem>
                                        <MenuItem value={ComparisonOperator.NotEqual}>!=</MenuItem>
                                        <MenuItem value={ComparisonOperator.GreaterThan}>&gt;</MenuItem>
                                        <MenuItem value={ComparisonOperator.LessThan}>&lt;</MenuItem>
                                        <MenuItem value={ComparisonOperator.GreaterThanOrEqual}>&gt;=</MenuItem>
                                        <MenuItem value={ComparisonOperator.LessThanOrEqual}>&lt;=</MenuItem>
                                    </Select>
                                </FormControl>

                                <ToggleButtonGroup
                                    value={condition.useConstant ? 'constant' : 'element'}
                                    exclusive
                                    onChange={(_, value) => {
                                        if (value) {
                                            condition.useConstant = value === 'constant';
                                            // Initialize comparison element if switching to element mode
                                            if (!condition.useConstant && !condition.comparisonElement) {
                                                const newElement = new DataElement();
                                                newElement.allowNew = false;
                                                newElement.needsWrite = false;
                                                newElement.setParentElement(condition);
                                                condition.comparisonElement = newElement;
                                            }
                                        }
                                    }}
                                    size="small"
                                    disabled={isReadOnly}
                                    sx={{
                                        '& .MuiToggleButton-root': {
                                            fontFamily: 'monospace',
                                            fontSize: '12px',
                                            minWidth: 'auto',
                                            px: 1.5,
                                            py: 0.5,
                                            textTransform: 'uppercase',
                                            border: `1px solid ${colors.mutedTextColor}`,
                                            '&.Mui-selected': {
                                                backgroundColor: colors.successColor,
                                                color: colors.lightTextColor,
                                                border: 'none',
                                                '&:hover': {
                                                    backgroundColor: colors.successColor,
                                                    opacity: 0.9
                                                }
                                            }
                                        }
                                    }}
                                >
                                    <ToggleButton value="constant">VALUE</ToggleButton>
                                    <ToggleButton value="element">ELEMENT</ToggleButton>
                                </ToggleButtonGroup>

                                {condition.useConstant ? (
                                    <NumberInput
                                        value={parseFloat(condition.comparisonValue) || 0}
                                        onChange={(value) => {
                                            condition.comparisonValue = value.toString();
                                            StateManager.propertyChanged(condition, 'comparisonValue');
                                        }}
                                        disabled={isReadOnly}
                                        showHelperText={false}
                                        size="small"
                                        sx={{
                                            width: 140,
                                            '& .MuiOutlinedInput-root': {
                                                height: '28px'
                                            }
                                        }}
                                    />
                                ) : (
                                    <>
                                        {condition.comparisonElement ? (
                                            condition.comparisonElement.render(renderMode || PLCRenderMode.Edit, targetProgramType)
                                        ) : (
                                            <span style={{ color: colors.mutedTextColor, fontStyle: 'italic' }}>Pick element</span>
                                        )}
                                    </>
                                )}
                            </>
                        )}

                        {condition.comment && <span className="comment" style={{ color: colors.mutedTextColor, fontStyle: 'italic' }}> - {condition.comment}</span>}
                    </Box>
                );
            }}
        />
    );
}
