import { FormControl, FormControlLabel, Grid, InputLabel, MenuItem, Select, Switch } from '@mui/material';
import { useEffect } from 'react';
import { MachineFeatureChecklistItem } from '../../../../data/Checklist/MachineFeatureChecklistItem';
import { SetupChecklistLibrary } from '../../../../data/Checklist/SetupChecklistLibrary';
import { MachineData } from '../../../../data/Machine/MachineData';
import { RotaryAxis } from '../../../../data/Machine/RotaryAxis';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { SetupChecklistIndicator } from '../../../Common/SetupChecklistIndicator';

export function MachineFeaturesSection() {
    const machine = MachineData.Instance;

    // Initialize checklist item if not already present
    useEffect(() => {
        const library = SetupChecklistLibrary.Instance;
        const existingItem = library.getItemByName('Machine Features');
        if (!existingItem) {
            library.addItem(new MachineFeatureChecklistItem());
        }
    }, []);

    return (
        <Grid container spacing={2}>
            <Grid item xs={12}>
                <SetupChecklistIndicator name="Machine Features" />
            </Grid>
            <Grid item xs={12} md={6}>
                <ObserveState
                    key="machine-features-vertical-table"
                    listenTo={machine}
                    properties={['hasVerticalTable']}
                    control={() => (
                        <FormControlLabel
                            control={
                                <Switch
                                    checked={machine.hasVerticalTable}
                                    onChange={(e) => machine.hasVerticalTable = e.target.checked}
                                />
                            }
                            label="Vertical Table"
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="machine-features-laser"
                    listenTo={machine}
                    properties={['hasLaser']}
                    control={() => (
                        <FormControlLabel
                            control={
                                <Switch
                                    checked={machine.hasLaser}
                                    onChange={(e) => machine.hasLaser = e.target.checked}
                                />
                            }
                            label="Laser"
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="machine-features-laser-pointer"
                    listenTo={machine}
                    properties={['hasLaserPointer']}
                    control={() => (
                        <FormControlLabel
                            control={
                                <Switch
                                    checked={machine.hasLaserPointer}
                                    onChange={(e) => machine.hasLaserPointer = e.target.checked}
                                />
                            }
                            label="Laser Pointer"
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="machine-features-drill-head"
                    listenTo={machine}
                    properties={['hasDrillHead']}
                    control={() => (
                        <FormControlLabel
                            control={
                                <Switch
                                    checked={machine.hasDrillHead}
                                    onChange={(e) => machine.hasDrillHead = e.target.checked}
                                />
                            }
                            label="Drill Head"
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="machine-features-atc"
                    listenTo={machine}
                    properties={['hasATC']}
                    control={() => (
                        <FormControlLabel
                            control={
                                <Switch
                                    checked={machine.hasATC}
                                    onChange={(e) => machine.hasATC = e.target.checked}
                                />
                            }
                            label="ATC (Automatic Tool Changer)"
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="machine-features-fixed-touch-plate"
                    listenTo={machine}
                    properties={['hasFixedTouchPlate']}
                    control={() => (
                        <FormControlLabel
                            control={
                                <Switch
                                    checked={machine.hasFixedTouchPlate}
                                    onChange={(e) => machine.hasFixedTouchPlate = e.target.checked}
                                />
                            }
                            label="Fixed Touch Plate"
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="machine-features-rotary-axis"
                    listenTo={machine}
                    properties={['rotaryAxis']}
                    control={() => (
                        <FormControl fullWidth>
                            <InputLabel>Rotary Axis</InputLabel>
                            <Select
                                value={machine.rotaryAxis}
                                onChange={(e) => machine.rotaryAxis = e.target.value as RotaryAxis}
                                label="Rotary Axis"
                            >
                                <MenuItem value={RotaryAxis.None}>None</MenuItem>
                                <MenuItem value={RotaryAxis.Fixed}>Fixed (Permanently Mounted)</MenuItem>
                                <MenuItem value={RotaryAxis.Movable}>Movable (Can be Placed)</MenuItem>
                            </Select>
                        </FormControl>
                    )}
                />
            </Grid>
        </Grid>
    );
}
