import {
  Description as FileIcon,
  AccessTime as TimeIcon,
  CloudUpload as UploadIcon
} from '@mui/icons-material';
import {
  Box,
  Button,
  Chip,
  Paper,
  TextField,
  Typography
} from '@mui/material';
import React, { useCallback, useEffect, useState } from 'react';
import { Material } from '../../../data/Common/Material';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../data/ConfigurationState';
import { Job } from '../../../data/Job';
import { MillingWorkflowState } from '../../../data/MillingWorkflowState';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import { GCodeFileMetadata } from '../../../machine/ICNCJobStorage';
import { Machine } from '../../../machine/Machine';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../utils/statemanager/StateManager';

export interface GCodeStageProps {
  onMovingToNext?: () => void;
  getNextStepName?: () => string;
  onPreviewReady?: () => void;
  onPrepareForNext?: () => boolean; // Returns true if ready to proceed
}

export function GCodeStage({ onMovingToNext, getNextStepName, onPreviewReady, onPrepareForNext }: GCodeStageProps = {}) {
  const [, setHoveredJobIndex] = useState<number | null>(null);
  const [, setHoveredFileIndex] = useState<number | null>(null);

  // Use centralized workflow state
  const workflowState = MillingWorkflowState.Instance;

  // State for recent jobs and files (loaded asynchronously)
  const [recentJobs, setRecentJobs] = useState<Job[]>([]);
  const [availableFiles, setAvailableFiles] = useState<GCodeFileMetadata[]>([]);

  // Instance references
  const machine = Machine.getInstance();
  const jobStorage = machine.jobStorage;

  // Load available files and recent jobs on mount
  useEffect(() => {
    const loadData = async () => {
      try {
        const config = ConfigurationData.Instance;
        // Load G-code files from monitored directories
        const filesResult = await jobStorage.listGCodeFiles(
          config.directoriesToMonitor.length > 0 ? config.directoriesToMonitor : ['/ncfiles/recent', '/ncfiles/templates', '/ncfiles/examples'],
          config.fileTypesToMonitor,
          { page: 0, pageSize: 100, sortBy: 'lastModified', sortDirection: 'desc' }
        );
        setAvailableFiles(filesResult.items);

        // Load recent jobs
        const jobsResult = await jobStorage.listJobs(
          { page: 0, pageSize: 20, sortBy: 'lastModified', sortDirection: 'desc' }
        );

        // Fetch full Job objects for the metadata
        const jobs = await Promise.all(
          jobsResult.items.map(async (meta) => {
            const job = await jobStorage.fetchJob(meta.id);
            return job;
          })
        );

        setRecentJobs(jobs.filter((j): j is Job => j !== null));
      } catch (error) {
        console.error('Error loading jobs/files:', error);
      }
    };

    loadData();
  }, [jobStorage]);

  // Utility function to format file age
  const formatFileAge = (lastModified?: Date): string => {
    if (!lastModified) return 'Unknown';

    const now = new Date();
    const diffMs = now.getTime() - lastModified.getTime();
    const diffMinutes = Math.floor(diffMs / (1000 * 60));
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

    if (diffMinutes < 1) return 'Just now';
    if (diffMinutes < 60) return `${diffMinutes} min ago`;
    if (diffHours < 24) return `${diffHours} hour${diffHours > 1 ? 's' : ''} ago`;
    if (diffDays === 1) return 'Yesterday';
    if (diffDays < 7) return `${diffDays} days ago`;
    return lastModified.toLocaleDateString();
  };

  // Utility function to format file size
  const formatFileSize = (size?: number): string => {
    if (!size) return 'Unknown size';

    const units = ['B', 'KB', 'MB', 'GB'];
    let unitIndex = 0;
    let fileSize = size;

    while (fileSize >= 1024 && unitIndex < units.length - 1) {
      fileSize /= 1024;
      unitIndex++;
    }

    return `${fileSize.toFixed(unitIndex === 0 ? 0 : 1)} ${units[unitIndex]}`;
  };

  // Create a temporary job for preview
  const createPreviewJob = useCallback((gcode: string, filename: string) => {
    let job: Job;

    // Always create a new empty job for G-code preview
    job = new Job();

    // Determine which job to use as base for material/clamps: current job if it has material, otherwise last job
    const baseJob = (ConfigurationState.Instance.currentJob?.material) ? ConfigurationState.Instance.currentJob : ConfigurationState.Instance.lastJob;

    // Copy material from base job if available
    if (baseJob?.material && baseJob.material.xLength > 0) {
      job.material = baseJob.material.clone();
    } else {
      // Create new material with zero size when no base material
      job.material = new Material();
      job.material.xLength = 0;
      job.material.yLength = 0;
      job.material.height = 0;
    }

    // Copy clamps from base job if available
    if (baseJob?.clamps && baseJob.clamps.length > 0) {
      job.clamps = baseJob.clamps.map((clamp: any) => clamp.clone());
    } else {
      // Empty clamps array when no base clamps
      job.clamps = [];
    }

    // Always set the new G-code and name
    job.gcode = gcode;
    job.name = filename;

    return job;
  }, []);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      loadFileContent(file, file.name, 'Uploaded File');
    }
  };

  const loadFileContent = (file: File, fileName: string, jobName: string) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const content = e.target?.result as string;
      previewGCode(content, fileName, jobName);
    };
    reader.readAsText(file);
  };

  const previewJobFromStorage = (job: Job) => {
    previewGCode(job.gcode, `${job.name}.gcode`, job.name);
  };

  const previewGCode = (content: string, fileName: string, jobName: string) => {
    // Create and set proposed job for preview
    const previewJob = createPreviewJob(content, fileName);
    previewJob.name = jobName;
    ConfigurationState.Instance.proposedJob = previewJob;

    // Notify the state manager that the proposed job has changed
    StateManager.propertyChanged(ConfigurationState.Instance, 'proposedJob');

    // Call the callback to trigger navigation to preview stage
    if (onPreviewReady) {
      // Use setTimeout to ensure state has propagated
      setTimeout(() => onPreviewReady(), 0);
    }
  };

  return (
    <ObserveState
      key="gcode-stage-tab-selection"
      listenTo={workflowState}
      properties={['selectedTab', 'editorGCode']}
      control={() => (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
          {/* Selection View - Show file/recent/wizards/editor tabs */}
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, flex: 1 }}>
            {/* Top Navigation Buttons */}
            <Box sx={{ display: 'flex', gap: 2 }}>
              <Button
                variant={workflowState.selectedTab === 'files' ? 'contained' : 'outlined'}
                onClick={() => workflowState.selectedTab = 'files'}
                sx={{
                  flex: 1,
                  py: 2,
                  fontSize: '1.1rem',
                  fontWeight: 'bold'
                }}
              >
                Files
              </Button>
              <Button
                variant={workflowState.selectedTab === 'recent' ? 'contained' : 'outlined'}
                onClick={() => workflowState.selectedTab = 'recent'}
                sx={{
                  flex: 1,
                  py: 2,
                  fontSize: '1.1rem',
                  fontWeight: 'bold'
                }}
              >
                Recent
              </Button>
              <Button
                variant={workflowState.selectedTab === 'wizards' ? 'contained' : 'outlined'}
                onClick={() => workflowState.selectedTab = 'wizards'}
                sx={{
                  flex: 1,
                  py: 2,
                  fontSize: '1.1rem',
                  fontWeight: 'bold'
                }}
              >
                Wizards
              </Button>
              <Button
                variant={workflowState.selectedTab === 'editor' ? 'contained' : 'outlined'}
                onClick={() => workflowState.selectedTab = 'editor'}
                sx={{
                  flex: 1,
                  py: 2,
                  fontSize: '1.1rem',
                  fontWeight: 'bold'
                }}
              >
                Editor
              </Button>
            </Box>

            {/* Content Area - Three column grid layout */}
            <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 2, flex: 1, overflow: 'auto', alignContent: 'start' }}>
              {workflowState.selectedTab === 'files' && (
                <>
                  <Paper sx={{ p: 2, gridColumn: '1 / -1', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <Typography variant="h5">
                      G-Code Files
                    </Typography>
                    <Button
                      variant="contained"
                      component="label"
                      startIcon={<UploadIcon />}
                    >
                      Upload File
                      <input
                        type="file"
                        accept=".gcode,.nc,.cnc,.tap"
                        onChange={handleFileUpload}
                        hidden
                      />
                    </Button>
                  </Paper>

                  {(() => {
                    // Get the most recent run date from last job's run statistics
                    const lastRunDate = ConfigurationState.Instance.lastJob?.runStatistics && ConfigurationState.Instance.lastJob.runStatistics.length > 0
                      ? ConfigurationState.Instance.lastJob.runStatistics[ConfigurationState.Instance.lastJob.runStatistics.length - 1].endTime
                      : undefined;

                    if (availableFiles.length === 0) {
                      return (
                        <Paper sx={{ p: 4, textAlign: 'center', gridColumn: '1 / -1' }}>
                          <Typography variant="body2" color="text.secondary">
                            No G-Code files found
                          </Typography>
                        </Paper>
                      );
                    }

                    return availableFiles.map((fileMeta, fileIndex) => {
                      const isNew = lastRunDate && fileMeta.lastModified && fileMeta.lastModified > lastRunDate;

                      return (
                        <Paper
                          key={fileIndex}
                          sx={{
                            p: 3,
                            cursor: 'pointer',
                            transition: 'all 0.2s',
                            border: isNew ? '2px solid' : '1px solid',
                            borderColor: isNew ? 'success.main' : 'divider',
                            backgroundColor: isNew ? 'success.light' : 'background.paper',
                            '&:hover': {
                              borderColor: 'primary.main',
                              boxShadow: 3,
                              transform: 'translateY(-2px)'
                            }
                          }}
                          onClick={async () => {
                            try {
                              const fileData = await jobStorage.fetchGCodeFile(fileMeta.directory, fileMeta.name);
                              if (fileData) {
                                previewGCode(fileData.content, fileData.name, fileData.name);
                              } else {
                                UserMessageQueue.Instance.addMessage(`❌ Could not load file: ${fileMeta.name}`);
                              }
                            } catch (error) {
                              UserMessageQueue.Instance.addMessage(`❌ Error loading file: ${fileMeta.name}`);
                            }
                          }}
                          onMouseEnter={() => setHoveredFileIndex(fileIndex)}
                          onMouseLeave={() => setHoveredFileIndex(null)}
                        >
                          <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1, mb: 2 }}>
                            <FileIcon color="action" sx={{ fontSize: 32 }} />
                            <Box sx={{ flex: 1 }}>
                              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                                <Typography variant="h6" sx={{ wordBreak: 'break-word' }}>
                                  {fileMeta.name}
                                </Typography>
                                {isNew && (
                                  <Chip
                                    label="NEW"
                                    color="success"
                                    size="small"
                                    sx={{ fontWeight: 'bold' }}
                                  />
                                )}
                              </Box>
                              <Typography variant="caption" color="text.secondary" sx={{ display: 'block' }}>
                                📁 {fileMeta.directory}
                              </Typography>
                            </Box>
                          </Box>
                          <Typography variant="body2" color="text.secondary">
                            {formatFileAge(fileMeta.lastModified)} • {formatFileSize(fileMeta.size)}
                          </Typography>
                        </Paper>
                      );
                    });
                  })()}
                </>
              )}

              {workflowState.selectedTab === 'recent' && (
                <>
                  {/* Current and Last Job Cards */}
                  <ObserveState
                    key="recent-jobs-special"
                    listenTo={ConfigurationState.Instance}
                    properties={['currentJob', 'lastJob']}
                    control={() => (
                      <>
                        {/* Current Job Card */}
                        {ConfigurationState.Instance.currentJob && (
                          <Paper
                            sx={{
                              p: 3,
                              cursor: 'pointer',
                              transition: 'all 0.2s',
                              '&:hover': {
                                borderColor: 'primary.main',
                                boxShadow: 3,
                                transform: 'translateY(-2px)'
                              }
                            }}
                            onClick={() => previewJobFromStorage(ConfigurationState.Instance.currentJob!)}
                          >
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 2 }}>
                              <FileIcon color="primary" sx={{ fontSize: 32 }} />
                              <Box sx={{ flex: 1 }}>
                                <Typography variant="h6">
                                  ⚡ {ConfigurationState.Instance.currentJob.name}
                                </Typography>
                                <Chip label="Current" color="primary" size="small" />
                              </Box>
                            </Box>
                            <Typography variant="body2" color="text.secondary" gutterBottom>
                              {ConfigurationState.Instance.currentJob.material.name} - {ConfigurationState.Instance.currentJob.material.xLength}" × {ConfigurationState.Instance.currentJob.material.yLength}" × {ConfigurationState.Instance.currentJob.material.height}"
                            </Typography>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mt: 2 }}>
                              <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                <TimeIcon fontSize="small" color="action" />
                                <Typography variant="caption">
                                  {ConfigurationState.Instance.currentJob.averageRuntimeFormatted} avg
                                </Typography>
                              </Box>
                              <Typography variant="caption">
                                • {ConfigurationState.Instance.currentJob.executionCount} runs
                              </Typography>
                              <Chip
                                label={ConfigurationState.Instance.currentJob.material.type}
                                size="small"
                                variant="outlined"
                              />
                            </Box>
                          </Paper>
                        )}

                        {/* Last Job Card */}
                        {ConfigurationState.Instance.lastJob && ConfigurationState.Instance.lastJob !== ConfigurationState.Instance.currentJob && (
                          <Paper
                            sx={{
                              p: 3,
                              cursor: 'pointer',
                              transition: 'all 0.2s',
                              '&:hover': {
                                borderColor: 'secondary.main',
                                boxShadow: 3,
                                transform: 'translateY(-2px)'
                              }
                            }}
                            onClick={() => previewJobFromStorage(ConfigurationState.Instance.lastJob!)}
                          >
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 2 }}>
                              <FileIcon color="secondary" sx={{ fontSize: 32 }} />
                              <Box sx={{ flex: 1 }}>
                                <Typography variant="h6">
                                  🕐 {ConfigurationState.Instance.lastJob.name}
                                </Typography>
                                <Chip label="Last" color="secondary" size="small" />
                              </Box>
                            </Box>
                            <Typography variant="body2" color="text.secondary" gutterBottom>
                              {ConfigurationState.Instance.lastJob.material.name} - {ConfigurationState.Instance.lastJob.material.xLength}" × {ConfigurationState.Instance.lastJob.material.yLength}" × {ConfigurationState.Instance.lastJob.material.height}"
                            </Typography>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mt: 2 }}>
                              <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                <TimeIcon fontSize="small" color="action" />
                                <Typography variant="caption">
                                  {ConfigurationState.Instance.lastJob.averageRuntimeFormatted} avg
                                </Typography>
                              </Box>
                              <Typography variant="caption">
                                • {ConfigurationState.Instance.lastJob.executionCount} runs
                              </Typography>
                              <Chip
                                label={ConfigurationState.Instance.lastJob.material.type}
                                size="small"
                                variant="outlined"
                              />
                            </Box>
                          </Paper>
                        )}
                      </>
                    )}
                  />

                  {/* Regular Recent Jobs as Cards */}
                  {recentJobs.slice(0, 10).map((job, index) => (
                    <Paper
                      key={index}
                      sx={{
                        p: 3,
                        cursor: 'pointer',
                        transition: 'all 0.2s',
                        '&:hover': {
                          borderColor: 'primary.main',
                          boxShadow: 3,
                          transform: 'translateY(-2px)'
                        }
                      }}
                      onClick={() => previewJobFromStorage(job)}
                      onMouseEnter={() => setHoveredJobIndex(index)}
                      onMouseLeave={() => setHoveredJobIndex(null)}
                    >
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 2 }}>
                        <FileIcon color="action" sx={{ fontSize: 32 }} />
                        <Typography variant="h6">
                          {job.name}
                        </Typography>
                      </Box>
                      <Typography variant="body2" color="text.secondary" gutterBottom>
                        {job.material.name} - {job.material.xLength}" × {job.material.yLength}" × {job.material.height}"
                      </Typography>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mt: 2 }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                          <TimeIcon fontSize="small" color="action" />
                          <Typography variant="caption">
                            {job.averageRuntimeFormatted} avg
                          </Typography>
                        </Box>
                        <Typography variant="caption">
                          • {job.executionCount} runs
                        </Typography>
                        <Chip
                          label={job.material.type}
                          size="small"
                          variant="outlined"
                        />
                      </Box>
                    </Paper>
                  ))}

                  {recentJobs.length === 0 && (
                    <Paper sx={{ p: 4, textAlign: 'center', gridColumn: '1 / -1' }}>
                      <Typography variant="body2" color="text.secondary">
                        No recent jobs found
                      </Typography>
                    </Paper>
                  )}
                </>
              )}

              {workflowState.selectedTab === 'wizards' && (
                <>
                  <Paper
                    sx={{
                      p: 3,
                      cursor: 'pointer',
                      transition: 'all 0.2s',
                      '&:hover': {
                        boxShadow: 3,
                        transform: 'translateY(-2px)'
                      }
                    }}
                  >
                    <Typography variant="h6" gutterBottom>
                      Surface Spoilboard
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Generate G-Code to surface your spoilboard
                    </Typography>
                  </Paper>

                  <Paper
                    sx={{
                      p: 3,
                      cursor: 'pointer',
                      transition: 'all 0.2s',
                      '&:hover': {
                        boxShadow: 3,
                        transform: 'translateY(-2px)'
                      }
                    }}
                  >
                    <Typography variant="h6" gutterBottom>
                      Dovetail Jig
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Create dovetail joint patterns
                    </Typography>
                  </Paper>

                  <Paper
                    sx={{
                      p: 3,
                      cursor: 'pointer',
                      transition: 'all 0.2s',
                      '&:hover': {
                        boxShadow: 3,
                        transform: 'translateY(-2px)'
                      }
                    }}
                  >
                    <Typography variant="h6" gutterBottom>
                      Pocket Rectangle
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Generate rectangular pocket toolpaths
                    </Typography>
                  </Paper>

                  <Paper
                    sx={{
                      p: 3,
                      cursor: 'pointer',
                      transition: 'all 0.2s',
                      '&:hover': {
                        boxShadow: 3,
                        transform: 'translateY(-2px)'
                      }
                    }}
                  >
                    <Typography variant="h6" gutterBottom>
                      Drill Pattern
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Create custom drilling patterns
                    </Typography>
                  </Paper>

                  <Paper
                    sx={{
                      p: 3,
                      cursor: 'pointer',
                      transition: 'all 0.2s',
                      '&:hover': {
                        boxShadow: 3,
                        transform: 'translateY(-2px)'
                      }
                    }}
                  >
                    <Typography variant="h6" gutterBottom>
                      Text Engraving
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Generate G-Code for text engraving
                    </Typography>
                  </Paper>

                  <Paper
                    sx={{
                      p: 3,
                      cursor: 'pointer',
                      transition: 'all 0.2s',
                      '&:hover': {
                        boxShadow: 3,
                        transform: 'translateY(-2px)'
                      }
                    }}
                  >
                    <Typography variant="h6" gutterBottom>
                      Custom Pattern
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Build your own G-Code pattern
                    </Typography>
                  </Paper>
                </>
              )}

              {workflowState.selectedTab === 'editor' && (
                <Box sx={{ gridColumn: '1 / -1', display: 'flex', flexDirection: 'column', gap: 2, height: '100%' }}>
                  <TextField
                    label="Job Name"
                    fullWidth
                    value={workflowState.editorGCode ? `custom_job_${new Date().toISOString().slice(0, 10)}` : ''}
                    variant="outlined"
                    placeholder="Enter a name for this job"
                    helperText="A unique name will be generated when you save"
                  />
                  <TextField
                    label="G-code"
                    multiline
                    fullWidth
                    value={workflowState.editorGCode}
                    onChange={(e) => workflowState.editorGCode = e.target.value}
                    minRows={25}
                    variant="outlined"
                    placeholder="Enter your G-code here..."
                    InputProps={{
                      sx: {
                        fontFamily: 'monospace',
                        fontSize: '0.875rem',
                        backgroundColor: ConfigurationDataColors.Instance.darkBackgroundColor,
                        color: ConfigurationDataColors.Instance.lightTextColor,
                        '& .MuiOutlinedInput-notchedOutline': {
                          borderColor: ConfigurationDataColors.Instance.borderColor
                        },
                        '&:hover .MuiOutlinedInput-notchedOutline': {
                          borderColor: ConfigurationDataColors.Instance.secondaryBorderColor
                        },
                        '&.Mui-focused .MuiOutlinedInput-notchedOutline': {
                          borderColor: 'primary.main'
                        }
                      }
                    }}
                  />
                  <Box sx={{ display: 'flex', gap: 2, justifyContent: 'flex-end' }}>
                    <Button
                      variant="outlined"
                      onClick={() => workflowState.editorGCode = ''}
                    >
                      Clear
                    </Button>
                    <Button
                      variant="contained"
                      onClick={() => {
                        const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, -5);
                        const jobName = `custom_job_${timestamp}`;
                        previewGCode(workflowState.editorGCode, `${jobName}.gcode`, jobName);
                      }}
                      disabled={!workflowState.editorGCode.trim()}
                    >
                      Preview
                    </Button>
                  </Box>
                </Box>
              )}
            </Box>
          </Box>
        </Box>
      )}
    />
  );
};
