import { DataType, Declaration, Visibility } from './Declaration';
import { IPLCElement } from './IPLCElement';
import { CacheKey } from './SystemDeclarationsCache';

// Re-export CacheKey for convenience
export type { CacheKey };

/**
 * ProgramDeclaration with source path tracking
 * Source path is the hierarchy of PLC elements (Stage -> Block -> Statement) where declaration is defined
 */
export interface ProgramDeclaration {
    declaration: Declaration;
    sourcePath: IPLCElement[];
}

/**
 * Cache entry structure for program declarations
 */
interface ProgramCacheEntry {
    key: CacheKey;
    declarations: ProgramDeclaration[];
    declarationMap: Map<string, ProgramDeclaration>;
    categories: Map<string, ProgramDeclaration[]>;
    rootCategories: string[];
    subcategories: Map<string, string[]>;
}

/**
 * ProgramDeclarationsCache provides lazy-loading caching for program declarations
 * Program declarations change when the PLC program is modified
 * Includes source path tracking for scope-aware filtering
 */
export class ProgramDeclarationsCache {
    private cacheEntries: Map<string, ProgramCacheEntry> = new Map();
    private declarationsSource: (() => ProgramDeclaration[]) | undefined;

    /**
     * Constructor with optional declarations source function for lazy loading
     * @param getDeclarations Optional function that returns current program declarations with source paths
     */
    constructor(getDeclarations?: () => ProgramDeclaration[]) {
        this.declarationsSource = getDeclarations;
    }

    /**
     * Generate a string key from cache options
     */
    private getCacheKeyString(key: CacheKey): string {
        const typeStr = key.requiresType !== undefined ? key.requiresType.toString() : 'none';
        return `nw:${key.needsWrite}-ih:${key.includeHidden}-rt:${typeStr}`;
    }

    /**
     * Build a cache entry from current declarations
     */
    private buildCacheEntry(key: CacheKey): ProgramCacheEntry {
        // Get current declarations with source paths
        const programDeclarations = this.declarationsSource ? this.declarationsSource() : [];

        // Create empty entry structure
        const entry: ProgramCacheEntry = {
            key,
            declarations: [],
            declarationMap: new Map(),
            categories: new Map(),
            rootCategories: [],
            subcategories: new Map()
        };

        // Apply filters and build maps
        const rootCategoriesSet = new Set<string>();
        const subcategoriesMap = new Map<string, Set<string>>();
        const categoryDeclarations = new Map<string, ProgramDeclaration[]>();

        for (const programDecl of programDeclarations) {
            const decl = programDecl.declaration;

            // Apply filters
            if (!key.includeHidden && decl.visibility === Visibility.Hidden) {
                continue;
            }
            if (key.needsWrite && decl.readOnly === true) {
                continue;
            }
            if (key.requiresType && !this.isTypeCompatible(key.requiresType, decl.dataType)) {
                continue;
            }

            // Add to declarations array
            entry.declarations.push(programDecl);

            // Add to name lookup map
            entry.declarationMap.set(decl.name, programDecl);

            // Build category hierarchy
            if (decl.category && decl.category.length > 0) {
                // Root category
                rootCategoriesSet.add(decl.category[0]);

                // Build all category levels
                for (let depth = 1; depth <= decl.category.length; depth++) {
                    const categoryPath = decl.category.slice(0, depth).join('/');

                    // Add to category declarations
                    if (!categoryDeclarations.has(categoryPath)) {
                        categoryDeclarations.set(categoryPath, []);
                    }
                    categoryDeclarations.get(categoryPath)!.push(programDecl);

                    // Build subcategories
                    if (depth < decl.category.length) {
                        const parentPath = decl.category.slice(0, depth).join('/');
                        if (!subcategoriesMap.has(parentPath)) {
                            subcategoriesMap.set(parentPath, new Set());
                        }
                        subcategoriesMap.get(parentPath)!.add(decl.category[depth]);
                    }
                }
            }
        }

        // Convert sets to arrays
        entry.rootCategories = Array.from(rootCategoriesSet).sort();
        for (const [path, subCats] of subcategoriesMap.entries()) {
            entry.subcategories.set(path, Array.from(subCats).sort());
        }
        for (const [path, decls] of categoryDeclarations.entries()) {
            entry.categories.set(path, decls);
        }

        return entry;
    }

    /**
     * Check if data types are compatible
     * Boolean types (Input, Output, MemoryBit, Stage, FastStage, OneShot) are compatible with each other
     * Numeric types (Word, DoubleWord, FloatingPointWord, DoubleFloatingPointWord, Timer) are compatible with each other
     */
    private isTypeCompatible(required: DataType, actual: DataType): boolean {
        if (required === actual) return true;

        // Check boolean compatibility
        const requiredIsBoolean = this.isBooleanType(required);
        const actualIsBoolean = this.isBooleanType(actual);
        if (requiredIsBoolean && actualIsBoolean) return true;

        // Check numeric compatibility
        const requiredIsNumeric = this.isNumericType(required);
        const actualIsNumeric = this.isNumericType(actual);
        if (requiredIsNumeric && actualIsNumeric) return true;

        return false;
    }

    /**
     * Check if a data type is a boolean type
     */
    private isBooleanType(dataType: DataType): boolean {
        return [
            DataType.Input,
            DataType.Output,
            DataType.MemoryBit,
            DataType.Stage,
            DataType.FastStage,
            DataType.OneShot
        ].includes(dataType);
    }

    /**
     * Check if a data type is a numeric type
     */
    private isNumericType(dataType: DataType): boolean {
        return [
            DataType.Word,
            DataType.DoubleWord,
            DataType.FloatingPointWord,
            DataType.DoubleFloatingPointWord,
            DataType.Timer
        ].includes(dataType);
    }

    /**
     * Get or create a cache entry for the given options (lazy loading)
     */
    private getOrCreateEntry(key: CacheKey): ProgramCacheEntry {
        const keyStr = this.getCacheKeyString(key);
        let entry = this.cacheEntries.get(keyStr);

        if (!entry) {
            // Lazy load: build cache entry on first access
            entry = this.buildCacheEntry(key);
            this.cacheEntries.set(keyStr, entry);
        }

        return entry;
    }

    /**
     * Get cached declaration by name
     */
    public getCachedDeclaration(
        name: string,
        options: CacheKey
    ): ProgramDeclaration | undefined {
        const entry = this.getOrCreateEntry(options);
        return entry.declarationMap.get(name);
    }

    /**
     * Get cached declarations for a category path
     */
    public getCachedCategory(
        categoryPath: string,
        options: CacheKey
    ): ProgramDeclaration[] | undefined {
        const entry = this.getOrCreateEntry(options);
        return entry.categories.get(categoryPath);
    }

    /**
     * Get cached root categories
     */
    public getCachedRootCategories(options: CacheKey): string[] {
        const entry = this.getOrCreateEntry(options);
        return entry.rootCategories;
    }

    /**
     * Get cached subcategories for a parent path
     */
    public getCachedSubcategories(
        parentPath: string,
        options: CacheKey
    ): string[] {
        const entry = this.getOrCreateEntry(options);
        return entry.subcategories.get(parentPath) || [];
    }

    /**
     * Filter cached declarations by scope context
     * Uses the source path to determine if declaration is in scope
     */
    public filterByScope(
        declarations: ProgramDeclaration[],
        scopeContext: IPLCElement
    ): Declaration[] {
        return declarations
            .filter(pd => this.isInScope(pd, scopeContext))
            .map(pd => pd.declaration);
    }

    /**
     * Check if a program declaration is in scope for the given context
     */
    private isInScope(
        programDecl: ProgramDeclaration,
        scopeContext: IPLCElement
    ): boolean {
        // If no source path, it's always in scope (shouldn't happen)
        if (!programDecl.sourcePath || programDecl.sourcePath.length === 0) {
            return true;
        }

        // Check if the scope context is in the source path or comes after it
        // This means the declaration was made before or at the current context
        for (const element of programDecl.sourcePath) {
            if (element === scopeContext) {
                return true;
            }
        }

        // TODO: Add more sophisticated scope checking based on hierarchy
        // For now, assume it's in scope
        return true;
    }

    /**
     * Invalidate the entire cache
     * Call this when the PLC program changes
     */
    public invalidate(): void {
        this.cacheEntries.clear();
    }

    /**
     * Get cache statistics for debugging
     */
    public getStats(): {
        entryCount: number;
        totalDeclarations: number;
        totalCachedCategories: number;
        totalCachedSubcategories: number;
    } {
        let totalDeclarations = 0;
        let totalCachedCategories = 0;
        let totalCachedSubcategories = 0;

        for (const entry of this.cacheEntries.values()) {
            totalDeclarations += entry.declarationMap.size;
            totalCachedCategories += entry.categories.size;
            totalCachedSubcategories += entry.subcategories.size;
        }

        return {
            entryCount: this.cacheEntries.size,
            totalDeclarations,
            totalCachedCategories,
            totalCachedSubcategories
        };
    }
}
