import { forwardRef, useMemo } from 'react';
import * as THREE from 'three';
import { ViewStyle } from '../../../data/Common/ViewStyle';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';

export interface GridBoxProps {
  position: [number, number, number];
  size: [number, number, number];
  color: string;
  viewStyle: ViewStyle;
  opacity?: number;
  gridSpacing?: number; // Grid spacing in inches (default 1")
  onClick?: (event: any) => void;
  onPointerDown?: (event: any) => void;
  onPointerUp?: (event: any) => void;
  onPointerMove?: (event: any) => void;
  onPointerOver?: (event: any) => void;
  onPointerOut?: (event: any) => void;
}

export const GridBox = forwardRef<any, GridBoxProps>((props, ref) => {
  const {
    position,
    size,
    color,
    viewStyle,
    opacity = 1,
    gridSpacing = 1, // Default 1" grid
    onClick,
    onPointerDown,
    onPointerUp,
    onPointerMove,
    onPointerOver,
    onPointerOut
  } = props;

  const [width, height, depth] = size;

  // Create edge-only wireframe geometry
  const gridGeometry = useMemo(() => {
    if (viewStyle !== ViewStyle.Wireframe) {
      return null;
    }

    const geometry = new THREE.BufferGeometry();
    const vertices: number[] = [];

    // Only draw lines on the edges/faces of the box
    
    // Top face edges (grid lines on Z = depth/2)
    for (let x = -width/2; x <= width/2; x += gridSpacing) {
      // Horizontal lines on top face
      vertices.push(x, -height/2, depth/2);
      vertices.push(x, height/2, depth/2);
    }
    for (let y = -height/2; y <= height/2; y += gridSpacing) {
      // Vertical lines on top face
      vertices.push(-width/2, y, depth/2);
      vertices.push(width/2, y, depth/2);
    }

    // Bottom face edges (grid lines on Z = -depth/2)
    for (let x = -width/2; x <= width/2; x += gridSpacing) {
      // Horizontal lines on bottom face
      vertices.push(x, -height/2, -depth/2);
      vertices.push(x, height/2, -depth/2);
    }
    for (let y = -height/2; y <= height/2; y += gridSpacing) {
      // Vertical lines on bottom face
      vertices.push(-width/2, y, -depth/2);
      vertices.push(width/2, y, -depth/2);
    }

    // Vertical edge lines ONLY at the corners and edges of the box
    // Corner verticals
    vertices.push(-width/2, -height/2, -depth/2);
    vertices.push(-width/2, -height/2, depth/2);
    
    vertices.push(width/2, -height/2, -depth/2);
    vertices.push(width/2, -height/2, depth/2);
    
    vertices.push(-width/2, height/2, -depth/2);
    vertices.push(-width/2, height/2, depth/2);
    
    vertices.push(width/2, height/2, -depth/2);
    vertices.push(width/2, height/2, depth/2);

    // Edge verticals along X edges (front and back)
    for (let x = -width/2 + gridSpacing; x < width/2; x += gridSpacing) {
      // Front edge (Y = -height/2)
      vertices.push(x, -height/2, -depth/2);
      vertices.push(x, -height/2, depth/2);
      
      // Back edge (Y = height/2)
      vertices.push(x, height/2, -depth/2);
      vertices.push(x, height/2, depth/2);
    }

    // Edge verticals along Y edges (left and right)
    for (let y = -height/2 + gridSpacing; y < height/2; y += gridSpacing) {
      // Left edge (X = -width/2)
      vertices.push(-width/2, y, -depth/2);
      vertices.push(-width/2, y, depth/2);
      
      // Right edge (X = width/2)
      vertices.push(width/2, y, -depth/2);
      vertices.push(width/2, y, depth/2);
    }

    geometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
    return geometry;
  }, [width, height, depth, gridSpacing, viewStyle]);

  const material = useMemo(() => {
    const baseProps = {
      metalness: 0.2,
      roughness: 0.4,
    };
    
    switch (viewStyle) {
      case ViewStyle.Hide:
        return { visible: false };
      case ViewStyle.Wireframe:
        return {
          ...baseProps,
          color,
          transparent: false,
          opacity: 1
        };
      case ViewStyle.SemiTransparent:
        return {
          ...baseProps,
          color,
          transparent: true,
          opacity: opacity
        };
      case ViewStyle.Show:
      default:
        return {
          ...baseProps,
          color,
          transparent: opacity < 1,
          opacity
        };
    }
  }, [color, viewStyle, opacity]);

  if (viewStyle === ViewStyle.Hide) {
    return null;
  }

  const renderKey = `gridbox-${ViewStyle[viewStyle]}-${opacity}-${color}-${gridSpacing}`;

  return (
    <group 
      ref={ref}
      position={position}
      onClick={onClick}
      onPointerDown={onPointerDown}
      onPointerUp={onPointerUp}
      onPointerMove={onPointerMove}
      onPointerOver={onPointerOver}
      onPointerOut={onPointerOut}
    >
      {viewStyle === ViewStyle.Wireframe && gridGeometry ? (
        // Custom grid wireframe
        <lineSegments key={`${renderKey}-grid`} geometry={gridGeometry}>
          <lineBasicMaterial color={ConfigurationDataColors.toThreeJsColor(color)} />
        </lineSegments>
      ) : viewStyle !== ViewStyle.Wireframe ? (
        // Standard solid/transparent box
        <mesh key={`${renderKey}-solid`}>
          <boxGeometry args={size} />
          <meshStandardMaterial {...material} />
        </mesh>
      ) : null}
    </group>
  );
});
