import { Height as MeasureZIcon } from '@mui/icons-material';
import { Box, Typography } from '@mui/material';
import React from 'react';
import { TouchOffWizard } from '../../components/wizards/touchoff/TouchOffWizard';
import { ConfigurationState } from '../../data/ConfigurationState';
import { IUserAction } from './IUserAction';

/**
 * User action to measure Z height (touch off)
 */
export class MeasureZUserAction implements IUserAction {
    public readonly id = 'material_setup_measure_z';
    public readonly category = 'Machine Actions';

    public isAvailable(): boolean {
        const config = ConfigurationState.Instance;
        return config.isHomed && !config.isJobRunning;
    }

    public renderButton(asLink: boolean): React.ReactNode {
        if (asLink) {
            return (
                <React.Fragment>
                    <MeasureZIcon sx={{ fontSize: 18, color: 'primary.main' }} />
                    <Typography variant="body2" sx={{ color: 'inherit', fontWeight: 500 }}>
                        Measure Z
                    </Typography>
                </React.Fragment>
            );
        } else {
            return (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <MeasureZIcon />
                    <Typography>Measure Z</Typography>
                </Box>
            );
        }
    }

    public async run(): Promise<void> {
        // Show wizard with target selection page
        TouchOffWizard.show();
    }
}
