import type { IMachineCallback } from './IMachineCallback';
import type { SystemStatus } from './Machine';

/**
 * Skin event action constants
 * These map to the API's SkinEventAction enum values
 */
export enum SkinEventAction {
    Press = 0,        // Press and hold the button/event
    Release = 1,      // Release the button/event
    Click = 2,        // Single click (press + 100ms delay + release)
    DoubleClick = 3   // Double click (two clicks with 100ms between each)
}

/**
 * Touch off target for material measurement and tool measurement
 */
export enum TouchOffTarget {
    // Coordinate system references (work zero setting)
    MachineBed = 0,                     // Touch off to machine bed (table surface)
    SpoilBoard = 1,                     // Touch off to spoil board (reference only)
    SpoilBoardAndWorkZero = 2,          // Touch off to spoil board and set work zero
    MaterialTop = 3,                    // Touch off to material top surface (reference only)
    MaterialTopAndWorkZero = 4,         // Touch off to material top and set work zero
    WorkZero = 5,                       // Touch off to work zero with fixture offsets
    
    // Tool measurement targets (movable touch plate or manual)
    ToolMeasure = 6,                    // Measure tool length (wizard shows method selection)
    ToolMeasureSpoilboard = 7,          // Measure tool length against spoilboard surface
    ToolMeasureMachineBed = 8,          // Measure tool length against machine bed
    ToolMeasureCurrentPosition = 9      // Measure tool length at current XY position
}

/**
 * Touch plate type for tool measurement
 */
export enum TouchPlateType {
    Fixed = 0,        // Fixed touch plate at known machine position
    Movable = 1       // Movable touch plate placed on work surface
}

/**
 * Measurement target for tool height offset
 */
export enum MeasurementTarget {
    FixedPosition = 0,  // Measure against fixed touch plate position
    Spoilboard = 1,     // Measure against spoilboard surface
    MachineBed = 2      // Measure against machine bed (Z=0 in machine coordinates)
}

/**
 * Interface for CNC system operations (power, homing, errors, etc.)
 */






export interface ICNCSystem {
    exit(): Promise<void>;
    GetSystemStatus(): Promise<SystemStatus>;
    IsConnectedToServer(): Promise<boolean>;
    shutdown(): Promise<void>;
    restartCentroid(): Promise<void>;
    EmergencyStop(): Promise<void>;
    IsHomed(): Promise<boolean>;
    UnhomeMachine(): Promise<void>;
    HomeMachine(callback?: IMachineCallback): Promise<void>;
    GetCurrentErrorState(): Promise<string[] | null>;
    HasCurrentErrors(): Promise<boolean>;

    // Skin event operations
    TriggerSkinEvent(eventNumber: number, action?: SkinEventAction): Promise<void>;

    // Machine control operations
    Stop(): Promise<void>;
    CancelCycle(): Promise<void>;
    SetMachineHomed(isHomed: boolean): Promise<void>;
    MachineHomed(): Promise<void>;
    MachineUnhomed(): Promise<void>;
    EnableSoftLimits(): Promise<void>;
    DisableSoftLimits(): Promise<void>;
    Reset(): Promise<void>;
    EStop(): Promise<void>;

    // Low-level tool operations
    dropTool(callback?: IMachineCallback): Promise<void>;
    loadTool(toolNumber: number, callback?: IMachineCallback): Promise<void>;
    measureCurrentTool(callback?: IMachineCallback): Promise<void>;
    autoMeasureTool(touchPlateType: TouchPlateType, target?: MeasurementTarget, callback?: IMachineCallback): Promise<void>;
    changeTool(toolNumber: number, callback?: IMachineCallback): Promise<void>;
    getCurrentToolNumber(): Promise<number>;
    checkTool(): Promise<void>;
    measureTools(callback?: IMachineCallback): Promise<void>;
    touchOffMaterial(target?: TouchOffTarget, callback?: IMachineCallback): Promise<void>;
    probeAndSetMaterialReference(target: TouchOffTarget, callback?: IMachineCallback): Promise<void>;
}
