import { Tool } from "../../../data/Common/Tool";
import { IMachineCallback } from "../../../machine/IMachineCallback";
import { Wizard } from "../../Wizard/Wizard";
import { WizardManager } from "../../Wizard/WizardManager";
import { SelectMethodStep } from "./steps/SelectMethodStep";

export enum ToolMeasurementMethod {
    AutoFixedTouchPlate = 'auto-fixed',
    ManualFixedPoint = 'manual-fixed',
    ManualSpoilboard = 'manual-spoilboard',
    ManualMachineBed = 'manual-machine-bed'
}

export interface ToolMeasurementWizardState {
    tool: Tool;
}

export class ToolMeasurementWizard extends Wizard<ToolMeasurementWizardState> {
    constructor(tool: Tool, callback?: IMachineCallback) {
        const initialState: ToolMeasurementWizardState = {
            tool
        };

        super(
            null as any, // Temporary - will be set below
            initialState,
            true, // canClose
            false, // clickAwayClose - don't allow accidental closure during operation
            '80%', // width
            '85%'  // height
        );

        // Set callback on wizard instance (WizardManager expects this)
        this.callback = callback;

        // Create the first step with proper wizard reference
        const firstStep = new SelectMethodStep(this, tool, null);
        this.firstStep = firstStep;
        this.currentStep = firstStep;
    }

    /**
     * Show the tool measurement wizard for a specific tool
     */
    static show(tool: Tool, callback?: IMachineCallback): void {
        const wizard = new ToolMeasurementWizard(tool, callback);
        WizardManager.Instance.start(wizard);
    }
}
