import { Air as VacuumIcon } from '@mui/icons-material';
import { Box, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { IOStateData } from '../../data/IOStateData';
import { PLCOutputName } from '../../data/PLCIONames';
import { Machine } from '../../machine/Machine';
import { IUserAction } from './IUserAction';

export class DustCollectorUserAction implements IUserAction {
    public readonly id = 'machine_controls_dust_collector';
    public readonly category = 'Features';

    public renderButton(asLink: boolean): React.ReactNode {
        const output = IOStateData.Instance.getOutputByName(PLCOutputName.DustCollectionOn);
        const isActive = output?.isActive ?? false;
        const config = ConfigurationDataColors.Instance;
        const activeColor = isActive ? config.successColor : 'inherit';

        if (asLink) {
            return (
                <React.Fragment>
                    <VacuumIcon sx={{ fontSize: 18, color: activeColor }} />
                    <Typography variant="body2" sx={{ color: activeColor, fontWeight: isActive ? 600 : 500 }}>
                        Dust Collector
                    </Typography>
                </React.Fragment>
            );
        } else {
            return (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <VacuumIcon sx={{ color: activeColor }} />
                    <Typography sx={{ color: activeColor, fontWeight: isActive ? 600 : 500 }}>Dust Collector</Typography>
                </Box>
            );
        }
    }

    public isAvailable(): boolean {
        const config = ConfigurationState.Instance;
        const output = IOStateData.Instance.getOutputByName(PLCOutputName.DustCollectionOn);
        return output !== undefined && config.isHomed && !config.isJobRunning;
    }

    public async run(): Promise<void> {
        const output = IOStateData.Instance.getOutputByName(PLCOutputName.DustCollectionOn);
        if (!output) {
            return;
        }

        const machine = Machine.getInstance();
        const newState = !output.isActive;
        await machine.io.SetOutputState(output.number, newState);
    }
}
