import { AccountTree as FlowIcon, Terminal as TerminalIcon } from '@mui/icons-material';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationState } from '../../data/ConfigurationState';
import { Storage, StorageType } from '../../machine/ICNCProgramStorage';
import { Machine } from '../../machine/Machine';
import { IUserAction } from './IUserAction';

/**
 * Registry for managing user actions that appear in the ActionsPanel
 * Provides registration, categorization, and retrieval of actions
 * Dynamically includes MDI/Flow program storages marked as actions
 */
export class UserActionRegistry {
  private static _instance: UserActionRegistry | null = null;
  private _actions: Map<string, IUserAction> = new Map();
  private _categories: Set<string> = new Set();
  private _programStorageActionsCache: IUserAction[] | null = null;
  private _lastCacheTime: number = 0;
  private readonly CACHE_DURATION = 5000; // 5 seconds

  private constructor() {
    // Private constructor for singleton pattern
  }

  /**
   * Get the singleton instance of the registry
   */
  public static get Instance(): UserActionRegistry {
    if (!UserActionRegistry._instance) {
      UserActionRegistry._instance = new UserActionRegistry();
    }
    return UserActionRegistry._instance;
  }

  /**
   * Register a new user action
   * @param action The action to register
   * @returns The action ID
   */
  public registerAction(action: IUserAction): string {
    this._actions.set(action.id, action);
    this._categories.add(action.category);
    return action.id;
  }

  /**
   * Convert a program storage to an action
   */
  private storageToAction(storage: Storage): IUserAction {
    const icon = storage.storageType === StorageType.MDI ? TerminalIcon : FlowIcon;
    const actionId = `program_storage_${storage.storageType}_${storage.name}`;

    return {
      id: actionId,
      category: storage.categoryName || (storage.storageType === StorageType.MDI ? 'MDI Commands' : 'Flows'),
      run: async () => {
        const machine = Machine.getInstance();
        const storageData = await machine.storage.getStorageData(storage.name);
        if (!storageData) {
          throw new Error(`Storage not found: ${storage.name}`);
        }

        // Execute the stored program/command
        if (storage.storageType === StorageType.MDI) {
          // For MDI, the data is the G-code command
          const config = ConfigurationData.Instance;

          if (config.previewGCode) {
            // Preview is ON - show preview dialog, don't run yet
            const configState = ConfigurationState.Instance;
            configState.showGCodePreview(
              storage.name,
              [storageData.data],
              undefined, // No callback needed - preview dialog handles execution
              false // Don't start immediately, wait for user confirmation
            );
          } else {
            // Preview is OFF - run immediately without preview
            await machine.program.RunGCode([storageData.data], true);
          }
        } else {
          // For Flow, we would need to execute the flow steps
          // This would require a flow execution system
          throw new Error('Flow execution not yet implemented');
        }
      },
      renderButton: (asLink: boolean) => {
        const IconComponent = icon;
        if (asLink) {
          return (
            <>
              <IconComponent sx={{ fontSize: 18, color: 'primary.main' }} />
              <span style={{ color: 'inherit', fontWeight: 500 }}>{storage.name}</span>
            </>
          );
        }
        return <span>{storage.name}</span>;
      }
    };
  }

  /**
   * Get program storage actions (cached for performance)
   * @returns Promise of array of program storage actions
   */
  private async getProgramStorageActions(): Promise<IUserAction[]> {
    const now = Date.now();

    // Return cached result if still valid
    if (this._programStorageActionsCache && (now - this._lastCacheTime) < this.CACHE_DURATION) {
      return this._programStorageActionsCache;
    }

    // Fetch fresh data
    const machine = Machine.getInstance();
    const actionStorages = await machine.storage.getActionStorages();
    const actions = actionStorages.map((storage: Storage) => this.storageToAction(storage));

    // Update cache
    this._programStorageActionsCache = actions;
    this._lastCacheTime = now;

    return actions;
  }

  /**
   * Invalidate the program storage cache (call when MDI/Flows are saved/deleted)
   */
  public invalidateProgramStorageCache(): void {
    this._programStorageActionsCache = null;
    this._lastCacheTime = 0;
  }

  /**
   * Get an action by its ID (includes program storage actions)
   * @param actionId The unique identifier of the action
   * @returns Promise of the action or undefined if not found
   */
  public async getAction(actionId: string): Promise<IUserAction | undefined> {
    // Check registered actions first
    const registeredAction = this._actions.get(actionId);
    if (registeredAction) {
      return registeredAction;
    }

    // Check if it's a program storage action
    if (actionId.startsWith('program_storage_')) {
      const programActions = await this.getProgramStorageActions();
      return programActions.find(action => action.id === actionId);
    }

    return undefined;
  }

  /**
   * Synchronous version of getAction for backwards compatibility
   * Only checks registered actions, not program storage
   */
  public getActionSync(actionId: string): IUserAction | undefined {
    return this._actions.get(actionId);
  }

  /**
   * Get all actions in a specific category
   * @param category The category name
   * @returns Array of actions in the category
   */
  public getActionsByCategory(category: string): IUserAction[] {
    const actions: IUserAction[] = [];
    for (const action of this._actions.values()) {
      if (action.category === category) {
        actions.push(action);
      }
    }
    return actions;
  }

  /**
   * Get all available categories
   * @returns Array of category names
   */
  public getCategories(): string[] {
    return Array.from(this._categories).sort();
  }

  /**
   * Get all registered actions (includes program storage actions)
   * @returns Promise of array of all actions
   */
  public async getAllActions(): Promise<IUserAction[]> {
    const registeredActions = Array.from(this._actions.values());
    const programActions = await this.getProgramStorageActions();
    return [...registeredActions, ...programActions];
  }

  /**
   * Synchronous version of getAllActions for backwards compatibility
   * Only returns registered actions, not program storage
   */
  public getAllActionsSync(): IUserAction[] {
    return Array.from(this._actions.values());
  }

  /**
   * Get actions grouped by category for display (includes program storage actions)
   * @returns Promise of Map of category names to action arrays
   */
  public async getActionsByCategories(): Promise<Map<string, IUserAction[]>> {
    const allActions = await this.getAllActions();
    const grouped = new Map<string, IUserAction[]>();

    // Group all actions by category
    for (const action of allActions) {
      const existing = grouped.get(action.category) || [];
      existing.push(action);
      grouped.set(action.category, existing);
    }

    return grouped;
  }

  /**
   * Execute an action by its ID
   * @param actionId The action ID to execute
   * @returns Promise that resolves when action completes
   */
  public async executeAction(actionId: string): Promise<void> {
    const action = await this.getAction(actionId);
    if (!action) {
      throw new Error(`Action not found: ${actionId}`);
    }

    if (action.isAvailable && !action.isAvailable()) {
      console.warn(`Action ${actionId} is not currently available`);
      return;
    }

    await action.run();
  }

  /**
   * Remove an action from the registry
   * @param actionId The action ID to remove
   * @returns True if action was removed, false if not found
   */
  public unregisterAction(actionId: string): boolean {
    const action = this._actions.get(actionId);
    if (!action) {
      return false;
    }

    this._actions.delete(actionId);

    // Check if category still has actions
    const categoryStillHasActions = this.getAllActionsSync().some(a => a.category === action.category);
    if (!categoryStillHasActions) {
      this._categories.delete(action.category);
    }

    return true;
  }

  /**
   * Clear all actions (useful for testing or reset)
   */
  public clearAll(): void {
    this._actions.clear();
    this._categories.clear();
    this.invalidateProgramStorageCache();
  }

  /**
   * Register user-defined actions from UserActionData
   * Called after default actions are registered to add user-created actions
   */
  public registerUserDefinedActions(): void {
    const { UserActionData } = require('../../data/UserActionData');
    const userActionData = UserActionData.Instance;

    // TODO: Convert stored action definitions to IUserAction implementations
    // For now, this is a placeholder for the system architecture
    // Future: Implement action definition format and converter
  }
}
