import { ConfigurationState } from '../../data/ConfigurationState';
import { NotificationList } from '../../utils/NotificationList';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { ResetRequiredNotification } from './ResetRequiredNotification';

const RESET_NOTIFICATION_ID = 'reset-required';

/**
 * Watcher component that monitors MachineStateData.requiresReset
 * and shows/hides the reset notification accordingly
 */
export function ResetRequiredWatcher() {
    return (
        <ObserveState
            key="reset-required-watcher"
            listenTo={ConfigurationState.Instance}
            properties={['requiresReset']}
            control={() => {
                const requiresReset = ConfigurationState.Instance.requiresReset;

                // Manage notification list directly - ObserveState will re-run this when requiresReset changes
                if (requiresReset) {
                    // Add notification with high ordinal so it appears above other notifications
                    NotificationList.Instance.add(
                        RESET_NOTIFICATION_ID,
                        <ResetRequiredNotification />,
                        1000 // High ordinal for priority display
                    );
                } else {
                    // Remove notification when reset is no longer required
                    NotificationList.Instance.remove(RESET_NOTIFICATION_ID);
                }

                // This component doesn't render anything directly
                return null;
            }}
        />
    );
}
