/**
 * Registry for assigning unique IDs to PLC elements (statements, predicates, etc.) during render/code generation
 * Uses WeakMap so IDs are automatically cleaned up when objects are garbage collected
 * IDs are assigned on-demand and cached for consistency across render/getPLCLogic/getAddedDeclarations calls
 */
export class StatementIdRegistry {
    private static idMap = new WeakMap<object, number>();
    private static nextId = 1;

    /**
     * Get the unique ID for a PLC element (statement, predicate, etc.)
     * If the element doesn't have an ID yet, assigns the next available one
     * @param element The element to get/assign an ID for
     * @returns The unique ID for this element
     */
    public static getId(element: object): number {
        if (!this.idMap.has(element)) {
            this.idMap.set(element, this.nextId++);
        }
        return this.idMap.get(element)!;
    }

    /**
     * Reset the registry - clears all cached IDs and resets counter to 1
     * Call this at the start of code generation to ensure consistent numbering
     */
    public static reset(): void {
        this.idMap = new WeakMap<object, number>();
        this.nextId = 1;
    }

    /**
     * Get the current ID counter value (for testing/debugging)
     */
    public static getNextIdValue(): number {
        return this.nextId;
    }
}
