import { ICNCPLC } from '../machine/ICNCPLC';
import { PLCApi } from '../services/src/apis/PLCApi';
import { MonitoredIODefinition } from '../services/src/models/MonitoredIODefinition';
import { PLCComparisonResult } from '../services/src/models/PLCComparisonResult';
import { PLCCompilationResult } from '../services/src/models/PLCCompilationResult';
import { PLCInstallationResult } from '../services/src/models/PLCInstallationResult';
import { LogCategory, Logger } from '../utils/Logger';
import { MachineInterfaceManager } from '../utils/MachineInterfaceManager';

/**
 * Centroid PLC implementation that communicates with the HavenCNC Server API
 */
export class CentroidCNCPLC implements ICNCPLC {
    private readonly api: PLCApi;
    private readonly basePath: string;

    constructor() {
        const config = MachineInterfaceManager.Instance.getServiceConfiguration();

        this.basePath = config?.basePath || '';
        this.api = new PLCApi(config || undefined);
    }

    async CompilePLC(sourceLines: string[]): Promise<PLCCompilationResult> {
        try {

            const response = await this.api.apiPLCCompilePLCPost({
                compilePLCRequest: { plcLines: sourceLines }
            });

            console.log('CentroidCNCPLC.CompilePLC: Raw API response:', response);
            console.log('CentroidCNCPLC.CompilePLC: Response type:', typeof response);
            console.log('CentroidCNCPLC.CompilePLC: Response keys:', Object.keys(response || {}));

            return response;
        } catch (error) {
            console.error('CentroidCNCPLC.CompilePLC: API call failed:', error);
            Logger.Instance.logError(LogCategory.System, 'Failed to compile PLC:', error);
            throw error;
        }
    }

    async CompileAndInstallPLC(sourceLines: string[], messages?: string[], estopInputNumber?: number, invertEstopInput?: boolean, inputsToMonitor?: MonitoredIODefinition[], outputsToMonitor?: MonitoredIODefinition[]): Promise<PLCInstallationResult> {
        try {
            const response = await this.api.apiPLCCompileAndInstallPLCPost({
                compileAndInstallPLCRequest: {
                    plcLines: sourceLines,
                    messageLines: messages,
                    estopInputNumber,
                    invertEstopInput,
                    inputsToMonitor,
                    outputsToMonitor
                }
            });

            return response;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to compile and install PLC:', error);
            throw error;
        }
    }

    async GetPLCData(name: string): Promise<string[]> {
        try {
            const response = await this.api.apiPLCGetPLCDataNameGet({ name });

            return response;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, `Failed to get PLC data for ${name}:`, error);
            throw error;
        }
    }

    async SetPLCData(name: string, lines: string[]): Promise<void> {
        try {
            await this.api.apiPLCSetPLCDataPost({
                setPLCDataRequest: { name, lines }
            });
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, `Failed to set PLC data for ${name}:`, error);
            throw error;
        }
    }

    async GetInstalledPLC(): Promise<string[]> {
        try {
            const response = await this.api.apiPLCGetInstalledPLCGet();

            return response;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to get installed PLC:', error);
            throw error;
        }
    }

    async GetInstalledMessages(): Promise<string[]> {
        try {
            const response = await this.api.apiPLCGetInstalledMessagesGet();

            return response;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to get installed messages:', error);
            throw error;
        }
    }

    async ComparePLC(sourceLines: string[]): Promise<PLCComparisonResult> {
        try {
            const response = await this.api.apiPLCComparePLCPost({
                compilePLCRequest: { plcLines: sourceLines }
            });

            return response;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to compare PLC:', error);
            throw error;
        }
    }
}
