import { ArrowForward, Close as CloseIcon } from '@mui/icons-material';
import {
    Box,
    Button,
    Card,
    CardContent,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    Typography,
} from '@mui/material';
import { SystemIcons } from '../../SystemIcons';
import { Tool } from '../../data/Common/Tool';
import { ToolLibrary } from '../../data/Common/ToolLibrary';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';

interface ManualToolChangeDialogProps {
    open: boolean;
    toolNumber: number;
    toolName: string;
    mode?: 'load' | 'drop' | 'change';
    fromToolNumber?: number; // For change mode
    onConfirm: () => void;
    onCancel: () => void;
}

/**
 * Dialog to prompt user to manually load/drop/change a tool
 * Used when a manual tool change is required
 */
export function ManualToolChangeDialog({
    open,
    toolNumber,
    toolName,
    mode = 'load',
    fromToolNumber,
    onConfirm,
    onCancel,
}: ManualToolChangeDialogProps) {
    const colors = ConfigurationDataColors.Instance;
    const toolLibrary = ToolLibrary.Instance;

    const isLoadMode = mode === 'load';
    const isDropMode = mode === 'drop';
    const isChangeMode = mode === 'change' || fromToolNumber !== undefined;

    const title = isChangeMode ? 'Manual Tool Change'
        : isLoadMode ? 'Manual Tool Load'
            : 'Manual Tool Drop';

    const instruction = isChangeMode
        ? 'Please manually remove the current tool and install the new tool in the spindle, then click Continue to proceed.'
        : isLoadMode
            ? 'Please manually install the tool in the spindle, then click Continue to proceed.'
            : 'Please manually remove the tool from the spindle, then click Continue to proceed.';

    // Get tool details from library
    const toTool = toolLibrary.getToolByNumber(toolNumber);
    const fromTool = fromToolNumber ? toolLibrary.getToolByNumber(fromToolNumber) : null;

    const renderToolCard = (tool: Tool | null, toolNum: number | null, toolNameFallback: string, label: string) => (
        <Card sx={{
            flex: 1,
            backgroundColor: colors.lightBackgroundColor,
            border: `2px solid ${colors.primaryColor}`,
            height: '280px',
            display: 'flex',
            flexDirection: 'column',
        }}>
            <CardContent sx={{ textAlign: 'center', py: 4, flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
                <Box sx={{ mb: 2, color: colors.primaryColor }}>
                    {SystemIcons.tool}
                </Box>
                {label && (
                    <Typography variant="overline" color="text.secondary" sx={{ display: 'block', mb: 1 }}>
                        {label}
                    </Typography>
                )}
                {toolNum !== null ? (
                    <>
                        <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 1, color: colors.primaryColor }}>
                            T{toolNum.toString().padStart(2, '0')}
                        </Typography>
                        <Typography variant="h6" sx={{ mb: 2 }}>
                            {tool?.displayName || toolNameFallback}
                        </Typography>
                        {tool && (
                            <>
                                <Typography variant="body2" color="text.secondary">
                                    {tool.cutterType}
                                </Typography>
                                <Typography variant="body2" color="text.secondary">
                                    {tool.cuttingDiameter.toFixed(3)}" Ø
                                </Typography>
                            </>
                        )}
                    </>
                ) : (
                    <>
                        <Typography variant="h5" sx={{ color: colors.mutedTextColor, fontStyle: 'italic' }}>
                            No Tool Loaded
                        </Typography>
                    </>
                )}
            </CardContent>
        </Card>
    );

    return (
        <Dialog
            open={open}
            onClose={onCancel}
            maxWidth="lg"
            fullWidth
        >
            <DialogTitle sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                backgroundColor: colors.primaryColor,
                color: colors.lightTextColor,
                py: 2,
                px: 3
            }}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    {SystemIcons.tool}
                    {title}
                </Box>
                <IconButton
                    onClick={onCancel}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>

            <DialogContent>
                <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', gap: 3 }}>
                    <Typography>
                        The machine has moved to the manual tool change position.
                    </Typography>

                    {isChangeMode && fromTool ? (
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 3, my: 2 }}>
                            {renderToolCard(fromTool, fromToolNumber!, fromTool.displayName, 'Remove')}

                            <Box sx={{
                                display: 'flex',
                                flexDirection: 'column',
                                alignItems: 'center',
                                minWidth: '80px'
                            }}>
                                <ArrowForward sx={{
                                    fontSize: 60,
                                    color: colors.primaryColor
                                }} />
                            </Box>

                            {renderToolCard(toTool || null, toolNumber, toolName, 'Install')}
                        </Box>
                    ) : isLoadMode ? (
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 3, my: 2 }}>
                            {renderToolCard(null, null, '', '')}

                            <Box sx={{
                                display: 'flex',
                                flexDirection: 'column',
                                alignItems: 'center',
                                minWidth: '80px'
                            }}>
                                <ArrowForward sx={{
                                    fontSize: 60,
                                    color: colors.primaryColor
                                }} />
                            </Box>

                            {renderToolCard(toTool || null, toolNumber, toolName, 'Install')}
                        </Box>
                    ) : (
                        <Box sx={{ display: 'flex', justifyContent: 'center', my: 2 }}>
                            {renderToolCard(toTool || null, toolNumber, toolName, 'Remove')}
                        </Box>
                    )}

                    <Box sx={{
                        p: 2,
                        backgroundColor: colors.primaryColor + '20',
                        borderRadius: 1,
                        borderLeft: `4px solid ${colors.primaryColor}`,
                    }}>
                        <Typography variant="body2">
                            {instruction}
                        </Typography>
                    </Box>
                </Box>
            </DialogContent>

            <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${colors.borderColor}` }}>
                <Button
                    onClick={onCancel}
                    variant="outlined"
                >
                    Cancel
                </Button>
                <Button
                    onClick={onConfirm}
                    variant="contained"
                    sx={{
                        backgroundColor: colors.primaryColor,
                        '&:hover': {
                            backgroundColor: colors.primaryColor,
                            filter: 'brightness(1.1)',
                        },
                    }}
                >
                    Continue
                </Button>
            </DialogActions>
        </Dialog>
    );
}
