import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../../data/ConfigurationState';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { JogControls } from '../../../Common/JogControls';
import { WizardStep } from '../../../Wizard/WizardStep';
import { AxisCalibrationWizard } from '../AxisCalibrationWizard';
import { MeasureActualStep } from './MeasureActualStep';

/**
 * Step to command the machine to move a specific distance
 */
export class MoveCommandStep extends WizardStep {
    getTitle(): string {
        const wizard = this.wizard as AxisCalibrationWizard;
        return `Move ${wizard.state.selectedAxis} Axis`;
    }

    nextStep(): WizardStep | null {
        return new MeasureActualStep(this.wizard as AxisCalibrationWizard, this);
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return (
            <ObserveState
                key="move-command-step"
                listenTo={this.wizard}
                properties={['state']}
                control={() => <MoveCommandStepComponent step={this} />}
            />
        );
    }
}

interface MoveCommandStepComponentProps {
    step: MoveCommandStep;
}

function MoveCommandStepComponent({ step }: MoveCommandStepComponentProps) {
    const wizard = step.wizard as AxisCalibrationWizard;
    const colors = ConfigurationDataColors.Instance;

    const axisName = wizard.state.selectedAxis;

    const handleContinue = () => {
        // Capture ending position from current machine coordinates
        const currentPoint = ConfigurationState.Instance.currentMachinePoint;

        let endingPos: number;
        if (axisName === 'X') {
            endingPos = currentPoint.x;
        } else if (axisName === 'Y') {
            endingPos = currentPoint.y;
        } else if (axisName === 'Z') {
            endingPos = currentPoint.z;
        } else {
            endingPos = 0;
        }

        // Calculate commanded distance (what the machine thinks it moved)
        const startingPos = wizard.state.startingPosition;
        const commandedDistance = Math.abs(endingPos - startingPos);

        // Store commanded distance in wizard state
        wizard.state = {
            ...wizard.state,
            commandedDistance
        };

        wizard.advanceToNextStep();
    };

    const handleBack = () => {
        wizard.goToPreviousStep();
    };

    return (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column', gap: 2, p: 3 }}>
            {/* Header */}
            <Box>
                <Typography variant="h5" gutterBottom sx={{ color: colors.primaryColor, fontWeight: 'bold' }}>
                    Step 2: Move the Axis
                </Typography>
            </Box>

            {/* Main content area - side by side layout */}
            <Box sx={{ flex: 1, display: 'flex', gap: 3, minHeight: 0 }}>
                {/* Instructions - left side */}
                <Box sx={{
                    width: '280px',
                    flexShrink: 0,
                    p: 2,
                    backgroundColor: colors.lightBackgroundColor,
                    borderRadius: 1,
                    borderLeft: `4px solid ${colors.infoColor}`,
                    display: 'flex',
                    flexDirection: 'column'
                }}>
                    <Typography variant="subtitle2" sx={{ color: colors.primaryColor, fontWeight: 'bold', mb: 1 }}>
                        Instructions:
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                        1. Zero your measuring device at the starting position
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                        2. Use the jog controls to move the {axisName} axis
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                        3. Watch your measuring device to see actual movement
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor }}>
                        4. Click "Move Complete" when finished moving
                    </Typography>
                </Box>

                {/* Jog Controls - right side, centered */}
                <Box sx={{
                    flex: 1,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    minWidth: 0 // Allow flex to work properly
                }}>
                    <JogControls />
                </Box>
            </Box>

            {/* Bottom buttons */}
            <Box sx={{
                pt: 2,
                borderTop: `1px solid ${colors.borderColor}`,
                display: 'flex',
                justifyContent: 'space-between'
            }}>
                <Button
                    variant="outlined"
                    onClick={handleBack}
                >
                    Back
                </Button>
                <Button
                    variant="contained"
                    onClick={handleContinue}
                    sx={{ backgroundColor: colors.primaryColor }}
                >
                    Move Complete
                </Button>
            </Box>
        </Box>
    );
}
