/**
 * Stage for user messages and prompts (M00, M01, M200, M201, M224, M225)
 */

import { Machine } from '../../machine/Machine';
import { StageDialogManager } from '../../utils/StageDialogManager';
import { JobStage, StageStatus, StageType } from '../JobStage';
import { UserMessageQueue } from '../UserMessageQueue';

export enum UserMessageType {
    Stop = 'M00',              // M00 - Stop for Operator
    OptionalStop = 'M01',      // M01 - Optional Stop for Operator
    PromptAction = 'M200',     // M200 - Stop for Operator, Prompt for Action
    PromptActionNoPLC = 'M201', // M201 - Stop for Operator, Prompt for Action (no PLC)
    PromptInput = 'M224',      // M224 - Prompt for Operator Input
    DisplayMessage = 'M225'    // M225 - Display Message for Period of Time
}

export class UserMessageStage extends JobStage {
    public messageType: UserMessageType;
    public message: string;
    public lineNumber: number;
    public gcodeLine: string;
    public enableJogging: boolean = false;
    public timeoutSeconds?: number; // For M225

    constructor(
        stageNumber: number,
        messageType: UserMessageType,
        message: string,
        lineNumber: number,
        gcodeLine: string,
        enableJogging: boolean = false,
        timeoutSeconds?: number
    ) {
        super(stageNumber, StageType.UserMessage, lineNumber - 1, lineNumber - 1);
        this.messageType = messageType;
        this.message = message;
        this.lineNumber = lineNumber;
        this.gcodeLine = gcodeLine;
        this.enableJogging = enableJogging;
        this.timeoutSeconds = timeoutSeconds;
    }

    protected async executeStage(callback?: import('../JobStage').StageCallback): Promise<void> {
        // M225 with timeout continues automatically after timeout
        if (this.messageType === UserMessageType.DisplayMessage && this.timeoutSeconds !== undefined && this.timeoutSeconds > 0) {
            // Execute the message command through machine interface
            await Machine.getInstance().program.RunGCodeCommand(this.gcodeLine);

            this.status = StageStatus.Completed;
            this.endTime = new Date();

            if (callback) {
                await callback.onComplete();
            }
            return;
        }

        // All other message types require user interaction with Continue/Cancel
        let userConfirmed = false;

        switch (this.messageType) {
            case UserMessageType.Stop:
                userConfirmed = await StageDialogManager.Instance.showM00Dialog(this.message);
                break;
            case UserMessageType.OptionalStop:
                userConfirmed = await StageDialogManager.Instance.showM01Dialog(this.message);
                break;
            case UserMessageType.PromptAction:
            case UserMessageType.PromptActionNoPLC:
                userConfirmed = await StageDialogManager.Instance.showPromptActionDialog(this.message, this.enableJogging);
                break;
            case UserMessageType.PromptInput:
                userConfirmed = await StageDialogManager.Instance.showPromptInputDialog(this.message);
                break;
            default:
                userConfirmed = true;
                break;
        }

        if (userConfirmed) {
            // User clicked Continue
            // For M00/M01 (stops), don't send the command - just continue to next stage
            // For other message types (M200, M201, M224), send the command
            if (this.messageType !== UserMessageType.Stop &&
                this.messageType !== UserMessageType.OptionalStop) {
                await Machine.getInstance().program.RunGCodeCommand(this.gcodeLine);
            }

            this.status = StageStatus.Completed;
            this.endTime = new Date();

            if (callback) {
                await callback.onComplete();
            }
        } else {
            // User clicked Cancel - stop the job
            this.status = StageStatus.Error;
            this.endTime = new Date();
            this.errorMessage = 'User canceled';

            // Show user message that job was canceled
            UserMessageQueue.Instance.addMessage('❌ Job canceled by user');

            if (callback) {
                await callback.onError('User canceled');
            }
        }
    }

    public getStageName(): string {
        return 'User Message';
    }

    public getDisplayName(): string {
        switch (this.messageType) {
            case UserMessageType.Stop:
                return 'Operator Stop';
            case UserMessageType.OptionalStop:
                return 'Optional Stop';
            case UserMessageType.PromptAction:
            case UserMessageType.PromptActionNoPLC:
                return 'Operator Prompt';
            case UserMessageType.PromptInput:
                return 'Input Required';
            case UserMessageType.DisplayMessage:
                return 'Message';
            default:
                return 'User Interaction';
        }
    }

    public getDescription(): string {
        let desc = `${this.messageType} (Line ${this.lineNumber})`;

        if (this.message) {
            desc += `\n${this.message}`;
        }

        if (this.enableJogging) {
            desc += '\nJogging enabled';
        }

        if (this.timeoutSeconds !== undefined && this.timeoutSeconds > 0) {
            desc += `\nAuto-continue after ${this.timeoutSeconds} seconds`;
        } else if (this.messageType !== UserMessageType.DisplayMessage) {
            desc += '\nPress CYCLE START to continue';
        }

        return desc;
    }

    public getStageDisplayData(): string[] {
        const data = [
            `${this.messageType} (Line ${this.lineNumber})`
        ];

        if (this.message) {
            data.push(this.message);
        }

        if (this.enableJogging) {
            data.push('Jogging enabled');
        }

        if (this.timeoutSeconds !== undefined && this.timeoutSeconds > 0) {
            data.push(`Auto-continue after ${this.timeoutSeconds} seconds`);
        } else if (this.messageType !== UserMessageType.DisplayMessage) {
            data.push('Press CYCLE START to continue');
        }

        return data;
    }
}
