import { ArrowDownward, ArrowUpward, Close as CloseIcon } from '@mui/icons-material';
import {
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    FormControlLabel,
    IconButton,
    Switch,
    TextField,
    ToggleButton,
    ToggleButtonGroup,
    Typography
} from '@mui/material';
import { useEffect, useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { formatStageName } from '../data/Declaration';
import { PLCProgram } from '../data/PLCProgram';
import { PLCStage, StageType } from '../data/PLCStage';
import { PLCUtilities } from '../data/PLCUtilities';

interface StageDialogProps {
    open: boolean;
    stage?: PLCStage; // If provided, we're editing; otherwise creating new
    program: PLCProgram; // The specific program being edited
    onClose: () => void;
    onSave: (name: string, description: string, type: StageType, enabled: boolean, fast: boolean) => void;
    onMoveUp?: () => void; // Optional callback to move stage up
    onMoveDown?: () => void; // Optional callback to move stage down
}

/**
 * Dialog for creating or editing a PLC stage
 * Validates that stage name is unique within the specific program
 */
export function StageDialog({ open, stage, program, onClose, onSave, onMoveUp, onMoveDown }: StageDialogProps) {
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [stageType, setStageType] = useState<StageType>(StageType.Main);
    const [enabled, setEnabled] = useState(true);
    const [fast, setFast] = useState(false);
    const [nameError, setNameError] = useState('');
    const colors = ConfigurationDataColors.Instance;

    // Determine if move buttons should be enabled based on position in group
    const canMoveUp = stage && onMoveUp ? (() => {
        const stagesOfType = program.stages.filter(s => s.type === stage.type);
        const currentIndex = stagesOfType.findIndex(s => s === stage);
        return currentIndex > 0;
    })() : false;

    const canMoveDown = stage && onMoveDown ? (() => {
        const stagesOfType = program.stages.filter(s => s.type === stage.type);
        const currentIndex = stagesOfType.findIndex(s => s === stage);
        return currentIndex < stagesOfType.length - 1;
    })() : false;

    // Initialize form when dialog opens or stage changes
    useEffect(() => {
        if (open) {
            if (stage) {
                // Editing existing stage
                setName(stage.name);
                setDescription(stage.description || '');
                setStageType(stage.type);
                setEnabled(stage.enabled);
                setFast(stage.fast);
            } else {
                // Creating new stage - start with empty name (user must specify)
                setName('');
                setDescription('');
                setStageType(StageType.Main);
                setEnabled(true);
                setFast(false);
            }
            setNameError('');
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [open, stage]);

    const handleNameChange = (newName: string) => {
        setName(newName);

        // Validate format first
        const formatError = PLCUtilities.validateStageName(newName);
        if (formatError) {
            setNameError(formatError);
            return;
        }

        // Then validate uniqueness
        if (!PLCUtilities.isStageNameUnique(newName, stage, program)) {
            setNameError('Stage name must be unique');
        } else {
            setNameError('');
        }
    };

    const handleSave = () => {
        const trimmedName = name.trim();

        // Final validation - format
        const formatError = PLCUtilities.validateStageName(trimmedName);
        if (formatError) {
            setNameError(formatError);
            return;
        }

        // Final validation - uniqueness
        if (!PLCUtilities.isStageNameUnique(trimmedName, stage, program)) {
            setNameError('Stage name must be unique');
            return;
        }

        // Format name with uppercase and _S suffix
        const formattedName = formatStageName(trimmedName);

        onSave(formattedName, description.trim(), stageType, enabled, fast);
        onClose();
    };

    const handleCancel = () => {
        onClose();
    };

    const isValid = name.trim() && !nameError;

    return (
        <Dialog open={open} onClose={handleCancel} maxWidth="sm" fullWidth>
            <DialogTitle sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                backgroundColor: colors.primaryColor,
                color: colors.lightTextColor,
                py: 2,
                px: 3
            }}>
                {stage ? 'Edit Stage' : 'Create New Stage'}
                <IconButton
                    onClick={handleCancel}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: `${colors.lightTextColor}1A`
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>
            <DialogContent>
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, mt: 3 }}>
                    {/* Stage Name */}
                    <TextField
                        label="Stage Name"
                        value={name}
                        onChange={(e) => handleNameChange(e.target.value)}
                        error={Boolean(nameError)}
                        helperText={nameError || 'Only alphabetic characters (no spaces, numbers, or special characters). _S suffix will be added automatically.'}
                        fullWidth
                        autoFocus
                        required
                    />

                    {/* Description */}
                    <TextField
                        label="Description"
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                        placeholder="Optional description or comment"
                        multiline
                        rows={3}
                        fullWidth
                    />

                    {/* Stage Type */}
                    <Box>
                        <Typography variant="subtitle2" sx={{ mb: 1, color: 'text.secondary' }}>
                            Stage Type
                        </Typography>
                        <ToggleButtonGroup
                            value={stageType}
                            exclusive
                            onChange={(e, newType) => {
                                if (newType !== null) {
                                    setStageType(newType);
                                }
                            }}
                            fullWidth
                            sx={{
                                '& .MuiToggleButton-root': {
                                    textTransform: 'none',
                                    '&.Mui-selected': {
                                        backgroundColor: colors.primaryColor,
                                        color: colors.lightTextColor,
                                        '&:hover': {
                                            backgroundColor: colors.primaryColor,
                                            opacity: 0.9
                                        }
                                    }
                                }
                            }}
                        >
                            <ToggleButton value={StageType.Initial}>
                                Initial
                            </ToggleButton>
                            <ToggleButton value={StageType.Main}>
                                Main
                            </ToggleButton>
                            <ToggleButton value={StageType.Final}>
                                Final
                            </ToggleButton>
                        </ToggleButtonGroup>
                        <Typography variant="caption" sx={{ mt: 0.5, display: 'block', color: 'text.secondary' }}>
                            {stageType === StageType.Initial && 'Runs once at startup for initialization'}
                            {stageType === StageType.Main && 'Runs continuously as main program logic'}
                            {stageType === StageType.Final && 'Runs once at shutdown for cleanup'}
                        </Typography>
                    </Box>

                    {/* Fast/Normal Stage */}
                    <Box>
                        <Typography variant="subtitle2" sx={{ mb: 1, color: 'text.secondary' }}>
                            Stage Speed
                        </Typography>
                        <ToggleButtonGroup
                            value={fast ? 'fast' : 'normal'}
                            exclusive
                            onChange={(e, newValue) => {
                                if (newValue !== null) {
                                    setFast(newValue === 'fast');
                                }
                            }}
                            fullWidth
                            sx={{
                                '& .MuiToggleButton-root': {
                                    textTransform: 'none',
                                    '&.Mui-selected': {
                                        backgroundColor: colors.primaryColor,
                                        color: colors.lightTextColor,
                                        '&:hover': {
                                            backgroundColor: colors.primaryColor,
                                            opacity: 0.9
                                        }
                                    }
                                }
                            }}
                        >
                            <ToggleButton value="normal">
                                Normal
                            </ToggleButton>
                            <ToggleButton value="fast">
                                Fast
                            </ToggleButton>
                        </ToggleButtonGroup>
                        <Typography variant="caption" sx={{ mt: 0.5, display: 'block', color: 'text.secondary' }}>
                            {fast ? 'Fast stages run at higher priority with minimal overhead' : 'Normal stages run at standard scan rate (default)'}
                        </Typography>
                    </Box>

                    {/* Stage Enabled/Disabled */}
                    <Box>
                        <FormControlLabel
                            control={
                                <Switch
                                    checked={enabled}
                                    onChange={(e) => setEnabled(e.target.checked)}
                                    sx={{
                                        '& .MuiSwitch-switchBase.Mui-checked': {
                                            color: colors.primaryColor,
                                        },
                                        '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': {
                                            backgroundColor: colors.primaryColor,
                                        },
                                    }}
                                />
                            }
                            label={
                                <Box>
                                    <Typography variant="body2">
                                        Stage Enabled
                                    </Typography>
                                    <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                                        {enabled ? 'Stage will execute during program run' : 'Stage will be skipped during program run'}
                                    </Typography>
                                </Box>
                            }
                        />
                    </Box>
                </Box>
            </DialogContent>
            <DialogActions sx={{ px: 3, pb: 2, justifyContent: 'space-between' }}>
                <Box sx={{ display: 'flex', gap: 1 }}>
                    {stage && onMoveUp && (
                        <Button
                            onClick={onMoveUp}
                            disabled={!canMoveUp}
                            variant="outlined"
                            startIcon={<ArrowUpward />}
                            sx={{ textTransform: 'none' }}
                        >
                            Move Up
                        </Button>
                    )}
                    {stage && onMoveDown && (
                        <Button
                            onClick={onMoveDown}
                            disabled={!canMoveDown}
                            variant="outlined"
                            startIcon={<ArrowDownward />}
                            sx={{ textTransform: 'none' }}
                        >
                            Move Down
                        </Button>
                    )}
                </Box>
                <Box sx={{ display: 'flex', gap: 1 }}>
                    <Button onClick={handleCancel} sx={{ textTransform: 'none' }}>
                        Cancel
                    </Button>
                    <Button
                        onClick={handleSave}
                        variant="contained"
                        disabled={!isValid}
                        sx={{
                            textTransform: 'none',
                            backgroundColor: colors.primaryColor,
                            '&:hover': {
                                backgroundColor: colors.primaryColor,
                                opacity: 0.9
                            }
                        }}
                    >
                        {stage ? 'Save' : 'Create'}
                    </Button>
                </Box>
            </DialogActions>
        </Dialog>
    );
}
