import { Close, Error as ErrorIcon, PlayArrow as PlayIcon, Stop as StopIcon, CheckCircle as SuccessIcon } from '@mui/icons-material';
import {
    Alert,
    Box,
    Button,
    Checkbox,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    FormControlLabel,
    Snackbar,
    Typography
} from '@mui/material';
import { useEffect, useRef, useState } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { GCodeExecutionCallback } from '../../machine/ICNCProgram';
import { Machine } from '../../machine/Machine';
import { ConfirmDialogManager } from '../../utils/ConfirmDialogManager';
import { JobRetryManager } from '../../utils/JobRetryManager';
import { LogCategory, Logger } from '../../utils/Logger';
import { RetryState } from '../../utils/RetryState';
import { ObserveState } from '../../utils/statemanager/ObserveState';

/**
 * G-code preview dialog component
 * Driven by ConfigurationState.gcodePreviewRequest (title, code, callback)
 * Shows generated G-code with Run, Save, and Cancel buttons
 * Displays execution progress with color-coded lines:
 * - Executed lines: blue
 * - Current line: red
 * - Pending lines: default color
 * Invokes optional callback on completion to support chained operations
 */
export function GCodePreviewDialog() {
    const [isRunning, setIsRunning] = useState(false);
    const [currentLineNumber, setCurrentLineNumber] = useState(-1);
    const [errorMessage, setErrorMessage] = useState<string | null>(null);
    const [successMessage, setSuccessMessage] = useState<string | null>(null);
    const [copySuccess, setCopySuccess] = useState(false);
    const [completedSuccessfully, setCompletedSuccessfully] = useState(false);
    const [wasStopped, setWasStopped] = useState(false);
    const [retryState] = useState(() => new RetryState()); // Local retry state
    const hasAutoStartedRef = useRef(false);
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const currentLineRef = useRef<HTMLDivElement>(null);
    const isStoppingRef = useRef(false);

    // Reset state when dialog opens
    useEffect(() => {
        const request = ConfigurationState.Instance.gcodePreviewRequest;
        if (request && !hasAutoStartedRef.current && !isRunning) {
            // Reset all state when a new request comes in (but not if job is running)
            setCurrentLineNumber(-1);
            setErrorMessage(null);
            setSuccessMessage(null);
            setCompletedSuccessfully(false);
            setWasStopped(false);
            isStoppingRef.current = false;
        }

        if (!request) {
            // Reset when dialog closes
            hasAutoStartedRef.current = false;
            setWasStopped(false);
            isStoppingRef.current = false;
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [ConfigurationState.Instance.gcodePreviewRequest]);

    // Auto-scroll to current line when it changes
    useEffect(() => {
        if (currentLineNumber >= 0 && currentLineRef.current) {
            currentLineRef.current.scrollIntoView({
                behavior: 'smooth',
                block: 'center'
            });
        }
    }, [currentLineNumber]);



    const handleRun = async () => {
        const configState = ConfigurationState.Instance;
        const request = configState.gcodePreviewRequest;

        if (!request || isRunning || wasStopped) return;

        try {
            setIsRunning(true);
            setCurrentLineNumber(-1);
            setErrorMessage(null);
            setSuccessMessage(null);
            setCompletedSuccessfully(false);
            setWasStopped(false);
            isStoppingRef.current = false;

            // Wrap the provided callback to add UI tracking
            const wrappedCallback: GCodeExecutionCallback = {
                onExecuteLine: (jobId: string, lineNumber: number, currentLine: string, totalLines: number, isLastStep: boolean) => {
                    // lineNumber from SignalR is 1-based, but array indices are 0-based
                    setCurrentLineNumber(lineNumber - 1);

                    // Call original callback if provided
                    if (request.callback?.onExecuteLine) {
                        request.callback.onExecuteLine(jobId, lineNumber, currentLine, totalLines, isLastStep);
                    }
                },
                onError: (jobId: string, errorMsg: string) => {
                    Logger.Instance.logError(LogCategory.System, `G-code execution error: ${errorMsg}`);
                    setErrorMessage(errorMsg);
                    setIsRunning(false);

                    // Call original callback if provided
                    if (request.callback?.onError) {
                        request.callback.onError(jobId, errorMsg);
                    }
                },
                onComplete: async (jobId: string, success: boolean, errorMsg?: string, linesExecuted?: number, duration?: string) => {
                    if (success) {
                        console.log('[DEBUG] GCodePreviewDialog: Execution completed successfully, calling callback');
                        Logger.Instance.log(LogCategory.System, `GCodePreviewDialog: Execution completed successfully, calling callback`);
                        setSuccessMessage(`Execution completed successfully! ${linesExecuted} lines executed in ${duration}`);
                        setCurrentLineNumber(-1);
                        setCompletedSuccessfully(true);
                        setIsRunning(false);

                        // Call original callback if provided
                        if (request.callback?.onComplete) {
                            console.log('[DEBUG] GCodePreviewDialog: Invoking onComplete callback');
                            Logger.Instance.log(LogCategory.System, `GCodePreviewDialog: Invoking onComplete callback`);
                            await request.callback.onComplete(jobId, success, errorMsg, linesExecuted, duration);
                            console.log('[DEBUG] GCodePreviewDialog: onComplete callback finished');
                            Logger.Instance.log(LogCategory.System, `GCodePreviewDialog: onComplete callback finished`);
                        } else {
                            console.log('[DEBUG] GCodePreviewDialog: No callback to invoke');
                            Logger.Instance.log(LogCategory.System, `GCodePreviewDialog: No callback to invoke`);
                        }
                    } else {
                        console.error('[DEBUG] GCodePreviewDialog: Execution failed:', errorMsg);
                        Logger.Instance.logError(LogCategory.System, `G-code execution failed: ${errorMsg}`);
                        setErrorMessage(errorMsg || 'Execution failed');
                        setIsRunning(false);

                        // Call original callback if provided
                        if (request.callback?.onComplete) {
                            console.log('[DEBUG] GCodePreviewDialog: Invoking onComplete callback for error case');
                            Logger.Instance.log(LogCategory.System, `GCodePreviewDialog: Invoking onComplete callback for error case`);
                            await request.callback.onComplete(jobId, success, errorMsg, linesExecuted, duration);
                        }
                    }
                }
            };

            // Execute G-code - the Promise is only for detecting START errors, NOT completion
            // Job completion is ONLY detected via the wrappedCallback.onComplete() above
            // DO NOT set isRunning(false) here - only the callback should do that
            JobRetryManager.Instance.executeWithRetry(request.code, request.title, wrappedCallback, retryState)
                .catch(error => {
                    // Only fires if job failed to START (not if it fails during execution)
                    Logger.Instance.logError(LogCategory.System, 'Failed to start G-code:', error);
                    setErrorMessage(error instanceof Error ? error.message : 'Unknown error occurred');
                    setIsRunning(false);
                });
        } catch (error) {
            // Catch any synchronous errors in setup
            Logger.Instance.logError(LogCategory.System, 'Failed to initialize G-code execution:', error);
            setErrorMessage(error instanceof Error ? error.message : 'Unknown error occurred');
            setIsRunning(false);
        }
    };

    const handleStop = async () => {
        if (!isRunning || isStoppingRef.current) return;

        try {
            isStoppingRef.current = true;
            await Machine.getInstance().program.Stop();

            setIsRunning(false);
            setWasStopped(true);
            setErrorMessage('Execution stopped by user');
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to stop G-code execution:', error);
            setErrorMessage(error instanceof Error ? error.message : 'Failed to stop execution');
            setIsRunning(false);
            setWasStopped(true);
        } finally {
            isStoppingRef.current = false;
        }
    };

    // Auto-start execution if startImmediately is true
    useEffect(() => {
        const request = ConfigurationState.Instance.gcodePreviewRequest;
        if (request && request.startImmediately && !hasAutoStartedRef.current && !isRunning) {
            hasAutoStartedRef.current = true;
            // Use setTimeout to ensure the dialog is fully rendered before starting
            setTimeout(() => {
                handleRun();
            }, 100);
        }

        // Reset flag when dialog closes
        if (!request) {
            hasAutoStartedRef.current = false;
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [ConfigurationState.Instance.gcodePreviewRequest, isRunning, handleRun]);

    const handleNext = async () => {
        console.log('[DEBUG] GCodePreviewDialog: handleNext called');
        Logger.Instance.log(LogCategory.System, `GCodePreviewDialog: handleNext called`);
        const request = ConfigurationState.Instance.gcodePreviewRequest;
        if (!request?.callback?.onComplete) {
            console.log('[DEBUG] GCodePreviewDialog: handleNext - no callback, returning');
            Logger.Instance.log(LogCategory.System, `GCodePreviewDialog: handleNext - no callback, returning`);
            return;
        }

        // Reset state before calling callback
        setCompletedSuccessfully(false);
        setSuccessMessage(null);
        setErrorMessage(null);
        setCurrentLineNumber(-1);
        hasAutoStartedRef.current = false;

        // Clear the preview dialog
        console.log('[DEBUG] GCodePreviewDialog: handleNext - clearing preview and calling callback');
        Logger.Instance.log(LogCategory.System, `GCodePreviewDialog: handleNext - clearing preview and calling callback`);
        ConfigurationState.Instance.clearGCodePreview();

        // Call the original callback which should trigger the next preview
        await request.callback.onComplete('', true);
        console.log('[DEBUG] GCodePreviewDialog: handleNext - callback completed');
        Logger.Instance.log(LogCategory.System, `GCodePreviewDialog: handleNext - callback completed`);
    };

    const handleClose = () => {
        console.log('[DEBUG] GCodePreviewDialog: handleClose called, isRunning=', isRunning);
        Logger.Instance.log(LogCategory.System, `GCodePreviewDialog: handleClose called, isRunning=${isRunning}`);
        if (isRunning) {
            console.log('[DEBUG] GCodePreviewDialog: handleClose - prevented because still running');
            Logger.Instance.log(LogCategory.System, `GCodePreviewDialog: handleClose - prevented because still running`);
            return; // Prevent closing while running
        }

        console.log('[DEBUG] GCodePreviewDialog: handleClose - clearing preview and resetting state');
        Logger.Instance.log(LogCategory.System, `GCodePreviewDialog: handleClose - clearing preview and resetting state`);
        ConfigurationState.Instance.clearGCodePreview();
        setCurrentLineNumber(-1);
        setErrorMessage(null);
        setSuccessMessage(null);
        setCompletedSuccessfully(false);
        setWasStopped(false);
        hasAutoStartedRef.current = false;
        isStoppingRef.current = false;
    };



    return (
        <ObserveState
            key="gcode-preview-dialog"
            listenTo={ConfigurationState.Instance}
            properties={['gcodePreviewRequest']}
            control={() => {
                const configState = ConfigurationState.Instance;
                const colors = ConfigurationDataColors.Instance;
                const request = configState.gcodePreviewRequest;

                // Generate colored G-code display
                const renderGCodeWithColors = () => {
                    if (!request) return null;

                    return request.code.map((line, index) => {
                        let color = colors.lightTextColor;
                        let fontWeight: 'normal' | 'bold' = 'normal';

                        // currentLineNumber is now 0-based (converted from 1-based SignalR)
                        // index is 0-based array index
                        const isCurrentLine = index === currentLineNumber;
                        if (isCurrentLine) {
                            // Current line: red and bold
                            color = ConfigurationDataColors.Instance.errorColor;
                            fontWeight = 'bold';
                        } else if (index < currentLineNumber) {
                            // Executed lines: blue
                            color = ConfigurationDataColors.Instance.infoColor;
                        }

                        return (
                            <Box
                                key={index}
                                ref={isCurrentLine ? currentLineRef : null}
                                component="div"
                                sx={{
                                    color: color,
                                    fontWeight: fontWeight,
                                    fontFamily: 'monospace',
                                    fontSize: '0.9rem',
                                    lineHeight: 1.5,
                                    whiteSpace: 'pre'
                                }}
                            >
                                {`${(index + 1).toString().padStart(4, ' ')}: ${line}`}
                            </Box>
                        );
                    });
                };

                return (
                    <Dialog
                        open={request !== null}
                        maxWidth="md"
                        fullWidth
                        disableEscapeKeyDown
                        sx={{
                            zIndex: 3000
                        }}
                        PaperProps={{
                            sx: {
                                borderRadius: 2,
                                boxShadow: 3
                            }
                        }}
                    >
                        <DialogTitle sx={{
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'space-between',
                            backgroundColor: colors.primaryColor,
                            color: colors.lightTextColor,
                            py: 2,
                            px: 3
                        }}>
                            {request?.title || 'G-Code Preview'}
                        </DialogTitle>
                        <DialogContent sx={{ position: 'relative' }}>
                            {/* Retry Status Display - uses local retry state */}
                            <ObserveState
                                key="job-retry-status"
                                listenTo={retryState}
                                properties={['isRetrying', 'retryCount']}
                                control={() => {
                                    if (!retryState.isRetrying) return null;

                                    return (
                                        <Alert severity="info" sx={{ mt: 3, mb: 2 }}>
                                            <Typography variant="body2" sx={{ fontWeight: 'bold' }}>
                                                Waiting for Job Slot...
                                            </Typography>
                                            <Typography variant="body2">
                                                Another job is running. Retry attempt {retryState.retryCount} of {JobRetryManager.Instance.maxRetries}
                                                <br />
                                                Will retry every {JobRetryManager.Instance.retryIntervalMs}ms
                                            </Typography>
                                        </Alert>
                                    );
                                }}
                            />
                            {successMessage && (
                                <Alert
                                    severity="success"
                                    icon={<SuccessIcon />}
                                    sx={{ mt: 3, mb: 2 }}
                                >
                                    <Typography variant="body2" sx={{ fontWeight: 'bold' }}>
                                        Success!
                                    </Typography>
                                    <Typography variant="body2">
                                        {successMessage}
                                    </Typography>
                                </Alert>
                            )}
                            {errorMessage && (
                                <Alert
                                    severity="error"
                                    icon={<ErrorIcon />}
                                    sx={{ mb: 2 }}
                                    onClose={() => setErrorMessage(null)}
                                >
                                    <Typography variant="body2" sx={{ fontWeight: 'bold' }}>
                                        Execution Error
                                    </Typography>
                                    <Typography variant="body2">
                                        {errorMessage}
                                    </Typography>
                                </Alert>
                            )}
                            <Box sx={{ mb: 2 }}>
                                <Typography variant="body2" sx={{ mb: 1 }}>
                                    {isRunning
                                        ? `Executing line ${currentLineNumber + 1} of ${request?.code.length || 0}...`
                                        : 'Review the G-code that will be executed:'}
                                </Typography>
                            </Box>
                            <Box
                                ref={scrollContainerRef}
                                sx={{
                                    border: `1px solid ${colors.borderColor}`,
                                    borderRadius: 1,
                                    padding: 2,
                                    backgroundColor: colors.veryDarkColor,
                                    minHeight: '400px',
                                    maxHeight: '500px',
                                    overflowY: 'auto',
                                    '&::-webkit-scrollbar': {
                                        width: '8px'
                                    },
                                    '&::-webkit-scrollbar-track': {
                                        backgroundColor: colors.darkBackgroundColor
                                    },
                                    '&::-webkit-scrollbar-thumb': {
                                        backgroundColor: colors.borderColor,
                                        borderRadius: '4px'
                                    }
                                }}
                            >
                                {renderGCodeWithColors()}
                            </Box>
                            <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                                {request?.code.length || 0} lines
                                {isRunning && currentLineNumber >= 0 && ` • Executing line ${currentLineNumber + 1}`}
                            </Typography>

                            {/* Floating Run Button - Centered (only when not running and not completed) */}
                            {!isRunning && !completedSuccessfully && !wasStopped && (
                                <Button
                                    onClick={handleRun}
                                    sx={{
                                        position: 'absolute',
                                        top: '50%',
                                        left: '50%',
                                        transform: 'translate(-50%, -50%)',
                                        zIndex: 10,
                                        width: 120,
                                        height: 120,
                                        borderRadius: '50%',
                                        backgroundColor: `${colors.lightTextColor}4D`,
                                        color: colors.lightTextColor,
                                        fontSize: '3rem',
                                        minWidth: 0,
                                        padding: 0,
                                        boxShadow: `0 8px 24px ${colors.darkTextColor}66`,
                                        backdropFilter: 'blur(8px)',
                                        border: `3px solid ${colors.lightTextColor}66`,
                                        transition: 'all 0.3s ease',
                                        '&:hover': {
                                            backgroundColor: `${colors.lightTextColor}80`,
                                            transform: 'translate(-50%, -50%) scale(1.05)',
                                            boxShadow: `0 12px 32px ${colors.darkTextColor}80`,
                                        }
                                    }}
                                >
                                    <PlayIcon sx={{ fontSize: '4rem' }} />
                                </Button>
                            )}
                        </DialogContent>
                        <DialogActions sx={{
                            p: 2,
                            gap: 2,
                            justifyContent: 'flex-end',
                            borderTop: `1px solid ${colors.borderColor}`
                        }}>
                            {/* Left side: Preview settings checkbox (only when showPreviewSettings is true) */}
                            {request?.showPreviewSettings && (
                                <Box sx={{ flexGrow: 1, mr: 'auto' }}>
                                    <FormControlLabel
                                        control={
                                            <Checkbox
                                                checked={!ConfigurationData.Instance.previewGCode}
                                                onChange={(e) => {
                                                    ConfigurationData.Instance.previewGCode = !e.target.checked;
                                                }}
                                                sx={{
                                                    color: colors.borderColor,
                                                    '&.Mui-checked': {
                                                        color: colors.primaryColor
                                                    }
                                                }}
                                            />
                                        }
                                        label={
                                            <Box>
                                                <Typography variant="body2" sx={{ fontWeight: 'bold' }}>
                                                    Don't show this preview again
                                                </Typography>
                                                <Typography variant="caption" color="text.secondary">
                                                    Re-enable in Settings → System → "Show G-code Preview"
                                                </Typography>
                                            </Box>
                                        }
                                    />
                                </Box>
                            )}

                            {/* Right side: Action buttons */}
                            <Box sx={{ display: 'flex', gap: 2, ...(isRunning && { mx: 'auto' }) }}>
                                {/* Initial State: Only show Cancel/Close button on right - Run button is overlaid */}
                                {!isRunning && !completedSuccessfully && !wasStopped && (
                                    <Button
                                        onClick={handleClose}
                                        variant="outlined"
                                        sx={{
                                            borderColor: colors.borderColor,
                                            color: colors.darkTextColor,
                                            '&:hover': {
                                                borderColor: colors.primaryColor,
                                                backgroundColor: 'rgba(0, 0, 0, 0.04)'
                                            }
                                        }}
                                    >
                                        {request?.callback ? 'Cancel' : 'Close'}
                                    </Button>
                                )}

                                {/* Running State: Stop and E-Stop buttons */}
                                {isRunning && (
                                    <>
                                        <Button
                                            onClick={handleStop}
                                            variant="contained"
                                            startIcon={<StopIcon sx={{ fontSize: 32 }} />}
                                            sx={{
                                                backgroundColor: 'error.main',
                                                color: colors.lightTextColor,
                                                minWidth: 140,
                                                height: 80,
                                                fontSize: '1.1rem',
                                                fontWeight: 'bold',
                                                '&:hover': {
                                                    backgroundColor: 'error.dark'
                                                }
                                            }}
                                        >
                                            Stop
                                        </Button>
                                        <Button
                                            onClick={async () => {
                                                const confirmed = await ConfirmDialogManager.Instance.showConfirm({
                                                    title: 'Emergency Stop',
                                                    message: 'Are you sure you want to emergency stop? This will halt all machine operations immediately.',
                                                    confirmText: 'Emergency Stop',
                                                    severity: 'error'
                                                });

                                                if (confirmed) {
                                                    try {
                                                        await Machine.getInstance().system.EmergencyStop();
                                                        handleStop(); // Also trigger normal stop to clean up dialog state
                                                    } catch (error) {
                                                        Logger.Instance.logError(LogCategory.System, 'Emergency stop failed:', error);
                                                    }
                                                }
                                            }}
                                            variant="contained"
                                            startIcon={<StopIcon sx={{ fontSize: 32, fontWeight: 'bold' }} />}
                                            sx={{
                                                backgroundColor: colors.errorColor,
                                                color: colors.lightTextColor,
                                                minWidth: 140,
                                                height: 80,
                                                fontSize: '1.1rem',
                                                fontWeight: 'bold',
                                                border: `2px solid ${colors.errorColor}`,
                                                '&:hover': {
                                                    backgroundColor: colors.errorColor,
                                                    opacity: 0.85,
                                                    border: `2px solid ${colors.errorColor}`
                                                }
                                            }}
                                        >
                                            E-Stop
                                        </Button>
                                    </>
                                )}

                                {/* Stopped State: Close button */}
                                {wasStopped && (
                                    <Button
                                        onClick={handleClose}
                                        variant="contained"
                                        startIcon={<Close />}
                                        sx={{
                                            backgroundColor: colors.borderColor,
                                            color: colors.lightTextColor,
                                            minWidth: 140,
                                            height: 80,
                                            fontSize: '1.1rem',
                                            fontWeight: 'bold',
                                            '&:hover': {
                                                backgroundColor: colors.secondaryBorderColor
                                            }
                                        }}
                                    >
                                        Close
                                    </Button>
                                )}

                                {/* Completed State with Callback: Next button */}
                                {completedSuccessfully && request?.callback && (
                                    <Button
                                        onClick={handleNext}
                                        variant="contained"
                                        sx={{
                                            backgroundColor: 'success.main',
                                            color: colors.lightTextColor,
                                            minWidth: 140,
                                            height: 80,
                                            fontSize: '1.1rem',
                                            fontWeight: 'bold',
                                            '&:hover': {
                                                backgroundColor: 'success.dark'
                                            }
                                        }}
                                    >
                                        Next
                                    </Button>
                                )}

                                {/* Completed State without Callback: Run Again and Close buttons */}
                                {completedSuccessfully && !request?.callback && (
                                    <>
                                        <Button
                                            onClick={() => {
                                                // Reset state and re-run
                                                setCompletedSuccessfully(false);
                                                setSuccessMessage(null);
                                                setErrorMessage(null);
                                                setCurrentLineNumber(-1);
                                                setWasStopped(false);
                                                hasAutoStartedRef.current = false;
                                                handleRun();
                                            }}
                                            variant="outlined"
                                            startIcon={<PlayIcon sx={{ fontSize: 32 }} />}
                                            sx={{
                                                borderColor: colors.primaryColor,
                                                color: colors.primaryColor,
                                                minWidth: 140,
                                                height: 80,
                                                fontSize: '1.1rem',
                                                fontWeight: 'bold',
                                                '&:hover': {
                                                    borderColor: colors.primaryColor,
                                                    backgroundColor: 'rgba(0, 0, 0, 0.04)'
                                                }
                                            }}
                                        >
                                            Run Again
                                        </Button>
                                        <Button
                                            onClick={handleClose}
                                            variant="contained"
                                            startIcon={<Close />}
                                            sx={{
                                                backgroundColor: colors.primaryColor,
                                                color: colors.lightTextColor,
                                                minWidth: 140,
                                                height: 80,
                                                fontSize: '1.1rem',
                                                fontWeight: 'bold',
                                                '&:hover': {
                                                    backgroundColor: colors.primaryColor,
                                                    opacity: 0.9
                                                }
                                            }}
                                        >
                                            Close
                                        </Button>
                                    </>
                                )}
                            </Box>
                        </DialogActions>
                        <Snackbar
                            open={copySuccess}
                            autoHideDuration={2000}
                            onClose={() => setCopySuccess(false)}
                            message="G-code copied to clipboard!"
                            anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
                        />
                    </Dialog>
                );
            }}
        />
    );
}
