    public static get MachineStateData(): MachineStateData | null {
        return SingletonRegistry._machineStateData;
    }

    public static set MachineStateData(instance: MachineStateData | null) {
        if (SingletonRegistry._machineStateData !== null && instance !== null) {
            const errorMsg = `SINGLETON VIOLATION: Attempted to create a second instance of MachineStateData! ` +
                `This is likely caused by hot reload or circular dependencies.`;
            console.error(errorMsg);
            console.trace('Stack trace for singleton violation:');
            throw new Error(errorMsg);
        }
        SingletonRegistry._machineStateData = instance;
    }

