import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { Tool } from '../../../../data/Common/Tool';
import { ToolLibrary } from '../../../../data/Common/ToolLibrary';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { ToolEditorForm } from '../../../Common/ToolEditorForm';
import { WizardStep } from '../../../Wizard/WizardStep';
import { ChangeToolWizard } from '../ChangeToolWizard';
import { MeasureNewToolStep } from './MeasureNewToolStep';

export class SelectNewToolStep extends WizardStep {
    public getTitle(): string {
        return 'Define New Tool';
    }

    public nextStep(): WizardStep | null {
        const wizardState = (this.wizard as ChangeToolWizard).state;
        if (wizardState.newTool) {
            return new MeasureNewToolStep(this.wizard as ChangeToolWizard, wizardState.newTool, this);
        }
        return null;
    }

    public backStep(): WizardStep | null {
        return this.priorStep;
    }

    private handleToolChange(tool: Tool): void {
        const wizardState = (this.wizard as ChangeToolWizard).state;
        wizardState.newTool = tool;
        StateManager.propertyChanged(this.wizard, 'state');
    }

    private handleContinue(): void {
        // No need to save - we're editing the tool object directly
        // The tool is already in the library (it's the oldTool)

        const nextStep = this.nextStep();
        if (nextStep) {
            this.wizard.currentStep = nextStep;
            StateManager.propertyChanged(this.wizard, 'currentStep');
        }
    }

    private getNextAvailableToolNumber(): number {
        const toolLibrary = ToolLibrary.Instance;
        const usedNumbers = toolLibrary.tools
            .map(t => t.toolNumber)
            .filter((n): n is number => n !== null)
            .sort((a, b) => a - b);

        // Find first gap in sequence starting from 1
        for (let i = 1; i <= usedNumbers.length + 1; i++) {
            if (!usedNumbers.includes(i)) {
                return i;
            }
        }

        return 1; // Fallback
    }

    public render(): React.ReactNode {
        const config = ConfigurationData.Instance;
        const colors = ConfigurationDataColors.Instance;
        const toolLibrary = ToolLibrary.Instance;
        const wizardState = (this.wizard as ChangeToolWizard).state;

        // Use the old tool's number (we're replacing it with same tool number)
        const initialToolNumber = wizardState.newTool?.toolNumber ?? wizardState.oldTool?.toolNumber ?? 1;

        return (
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>
                {/* Instructions */}
                <Box sx={{
                    p: 2,
                    backgroundColor: colors.primaryColor + '15',
                    borderRadius: 1,
                    borderLeft: `4px solid ${colors.primaryColor}`
                }}>
                    <Typography variant="h6" sx={{ mb: 1, fontWeight: 'bold' }}>
                        Define New Tool
                    </Typography>
                    <Typography variant="body1">
                        Enter the specifications for the new tool that you just installed. The tool number has been pre-filled with the current tool number.
                    </Typography>
                </Box>

                {/* Tool Editor Form */}
                <Box sx={{ flex: 1, overflow: 'auto' }}>
                    <ToolEditorForm
                        tool={wizardState.newTool}
                        library={toolLibrary}
                        onToolChange={(tool) => this.handleToolChange(tool)}
                        initialToolNumber={initialToolNumber}
                        showToolViewer={false}
                    />
                </Box>

                {/* Continue Button - Observe tool for validation changes */}
                <ObserveState
                    key="continue-button-observer"
                    listenTo={wizardState.newTool || this}
                    control={() => (
                        <Box sx={{ display: 'flex', justifyContent: 'flex-end', pt: 2, borderTop: `1px solid ${colors.borderColor}` }}>
                            <Button
                                variant="contained"
                                color="primary"
                                size="large"
                                onClick={() => this.handleContinue()}
                                disabled={!wizardState.newTool || !wizardState.newTool.isValid()}
                                sx={{
                                    py: 1.5,
                                    minWidth: 150
                                }}
                            >
                                Continue
                            </Button>
                        </Box>
                    )}
                />
            </Box>
        );
    }
}
