import { IMachineInterface } from '../machine/Machine';
import { CentroidCNCFeatures } from './CentroidCNCFeatures';
import { CentroidCNCIO } from './CentroidCNCIO';
import { CentroidCNCJobStorage } from './CentroidCNCJobStorage';
import { CentroidCNCMovement } from './CentroidCNCMovement';
import { CentroidCNCPLC } from './CentroidCNCPLC';
import { CentroidCNCProgram } from './CentroidCNCProgram';
import { CentroidCNCProgramStorage } from './CentroidCNCProgramStorage';
import { CentroidCNCSetup } from './CentroidCNCSetup';
import { CentroidCNCSpindle } from './CentroidCNCSpindle';
import { CentroidCNCSystem } from './CentroidCNCSystem';

/**
 * Centroid machine interface that communicates with the HavenCNC Server API
 * All method implementations use the generated service APIs to communicate with Centroid
 */
export class CentroidMachineInterface implements IMachineInterface {
  public readonly system: CentroidCNCSystem;
  public readonly movement: CentroidCNCMovement;
  public readonly spindle: CentroidCNCSpindle;
  public readonly program: CentroidCNCProgram;
  public readonly features: CentroidCNCFeatures;
  public readonly io: CentroidCNCIO;
  public readonly plc: CentroidCNCPLC;
  public readonly setup: CentroidCNCSetup;
  public readonly storage: CentroidCNCProgramStorage;
  public readonly jobStorage: CentroidCNCJobStorage;

  constructor() {
    this.system = new CentroidCNCSystem();
    this.movement = new CentroidCNCMovement();
    this.spindle = new CentroidCNCSpindle();
    this.program = new CentroidCNCProgram();
    this.features = new CentroidCNCFeatures();
    this.io = new CentroidCNCIO();
    this.plc = new CentroidCNCPLC();
    this.setup = new CentroidCNCSetup();
    this.storage = new CentroidCNCProgramStorage();
    this.jobStorage = new CentroidCNCJobStorage();
  }

  /**
   * Centroid requires SignalR monitoring - it's a real machine connection
   */
  public requiresSignalRMonitoring(): boolean {
    return true;
  }
}