import { Clear as ClearIcon } from '@mui/icons-material';
import {
    Box,
    Button,
    Chip,
    Divider,
    List,
    Paper,
    Typography,
} from '@mui/material';
import { createTheme } from '@mui/material/styles';
import React from 'react';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { SignalRMessagesData } from '../../data/SignalRMessagesData';
import { SignalRStateData } from '../../data/SignalRStateData';
import { ObserveState } from '../../utils/statemanager/ObserveState';

interface SignalRMessagesDrawerProps {
    onViewChange?: (view: string) => void;
}

/**
 * SignalR Messages Drawer Component
 * Displays messages collected by SignalRMessagesData singleton.
 * Messages persist even when drawer is closed/reopened.
 */
export function SignalRMessagesDrawer(props: SignalRMessagesDrawerProps) {
    const theme = createTheme();

    const getSeverityColor = (severity?: string): string => {
        const colors = ConfigurationDataColors.Instance;
        switch (severity) {
            case 'Error':
                return colors.errorColor;
            case 'Warning':
                return colors.warningColor;
            case 'Info':
            default:
                return colors.primaryColor;
        }
    };

    const formatTimestamp = (date: Date): string => {
        return date.toLocaleTimeString('en-US', {
            hour12: false,
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit',
            fractionalSecondDigits: 3
        });
    };

    const handleClear = (): void => {
        SignalRMessagesData.Instance.clearMessages();
    };

    return (
        <ObserveState
            key="signalr-messages-drawer"
            listenTo={SignalRMessagesData.Instance}
            properties={['messages']}
            control={() => {
                const colors = ConfigurationDataColors.Instance;
                const messages = SignalRMessagesData.Instance.messages;

                return (
                    <Box
                        sx={{
                            height: '100%',
                            display: 'flex',
                            flexDirection: 'column',
                            backgroundColor: theme.palette.background.default,
                            overflow: 'hidden',
                        }}
                    >
                        {/* Header */}
                        <Box
                            sx={{
                                padding: 2,
                                backgroundColor: colors.lightBackgroundColor,
                                borderBottom: `1px solid ${colors.borderColor}`,
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'space-between',
                            }}
                        >
                            <Typography variant="h6" sx={{ color: colors.darkTextColor }}>
                                SignalR Messages
                            </Typography>
                            <Button
                                variant="outlined"
                                size="small"
                                startIcon={<ClearIcon />}
                                onClick={handleClear}
                                sx={{
                                    borderColor: colors.borderColor,
                                    color: colors.darkTextColor,
                                    '&:hover': {
                                        borderColor: colors.primaryColor,
                                        backgroundColor: `${colors.darkTextColor}0D`,
                                    },
                                }}
                            >
                                Clear
                            </Button>
                        </Box>

                        {/* Message Count */}
                        <Box
                            sx={{
                                padding: 1.5,
                                backgroundColor: theme.palette.background.paper,
                                borderBottom: `1px solid ${colors.borderColor}`,
                            }}
                        >
                            <Typography variant="body2" sx={{ color: colors.darkTextColor }}>
                                {messages.length} message{messages.length !== 1 ? 's' : ''} received
                            </Typography>
                        </Box>

                        {/* Messages List */}
                        <Box
                            sx={{
                                flexGrow: 1,
                                overflow: 'auto',
                                padding: 2,
                            }}
                        >
                            {messages.length === 0 ? (
                                <Box
                                    sx={{
                                        display: 'flex',
                                        alignItems: 'center',
                                        justifyContent: 'center',
                                        height: '100%',
                                    }}
                                >
                                    <Typography variant="body2" sx={{ color: colors.darkTextColor, opacity: 0.6 }}>
                                        No messages received yet
                                    </Typography>
                                </Box>
                            ) : (
                                <List sx={{ padding: 0 }}>
                                    {messages.map((msg, index) => (
                                        <React.Fragment key={msg.id}>
                                            <Paper
                                                elevation={1}
                                                sx={{
                                                    marginBottom: 2,
                                                    padding: 1.5,
                                                    backgroundColor: theme.palette.background.paper,
                                                    borderLeft: `4px solid ${getSeverityColor(msg.severity)}`,
                                                }}
                                            >
                                                <Box sx={{ display: 'flex', alignItems: 'center', marginBottom: 0.5 }}>
                                                    <Chip
                                                        label={msg.type}
                                                        size="small"
                                                        sx={{
                                                            backgroundColor: getSeverityColor(msg.severity),
                                                            color: colors.lightTextColor,
                                                            fontWeight: 'bold',
                                                            marginRight: 1,
                                                            fontSize: '0.7rem',
                                                        }}
                                                    />
                                                    <Typography variant="caption" sx={{ color: colors.darkTextColor, opacity: 0.7 }}>
                                                        {formatTimestamp(msg.timestamp)}
                                                    </Typography>
                                                </Box>
                                                <Typography variant="body2" sx={{ color: colors.darkTextColor }}>
                                                    {msg.message}
                                                </Typography>
                                            </Paper>
                                            {index < messages.length - 1 && <Divider />}
                                        </React.Fragment>
                                    ))}
                                </List>
                            )}
                        </Box>

                        {/* Connection Status Footer */}
                        <ObserveState
                            key="signalr-connection-status"
                            listenTo={SignalRStateData.Instance}
                            properties={['connectionState', 'connectionStatusText', 'connectionStatusColor']}
                            control={() => (
                                <Box
                                    sx={{
                                        padding: 1.5,
                                        backgroundColor: theme.palette.background.paper,
                                        borderTop: `1px solid ${colors.borderColor}`,
                                        display: 'flex',
                                        alignItems: 'center',
                                        justifyContent: 'space-between',
                                    }}
                                >
                                    <Typography variant="caption" sx={{ color: colors.darkTextColor }}>
                                        Connection Status:
                                    </Typography>
                                    <Chip
                                        label={SignalRStateData.Instance.connectionStatusText}
                                        size="small"
                                        sx={{
                                            backgroundColor: SignalRStateData.Instance.connectionStatusColor,
                                            color: colors.lightTextColor,
                                            fontWeight: 'bold',
                                            fontSize: '0.7rem',
                                        }}
                                    />
                                </Box>
                            )}
                        />
                    </Box>
                );
            }}
        />
    );
}
