import { CheckCircle as SuccessIcon } from '@mui/icons-material';
import { Alert, Box, Button, Checkbox, FormControlLabel, Typography } from '@mui/material';
import React, { useState } from 'react';
import { Tool } from '../../../../data/Common/Tool';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { WizardStep } from '../../../Wizard/WizardStep';
import { ToolMeasurementMethod, ToolMeasurementWizard } from '../ToolMeasurementWizard';
import { TriggerMeasureStep } from './TriggerMeasureStep';

/**
 * Step to confirm touchplate is working and positioned correctly
 */
export class ConfirmTouchplateStep extends WizardStep {
    private tool: Tool;
    private method: ToolMeasurementMethod;

    constructor(wizard: ToolMeasurementWizard, tool: Tool, previousStep: WizardStep | null, method: ToolMeasurementMethod) {
        super(wizard, previousStep);
        this.tool = tool;
        this.method = method;
    }

    getTitle(): string {
        return 'Confirm Touchplate';
    }

    nextStep(): WizardStep | null {
        return new TriggerMeasureStep(this.wizard as ToolMeasurementWizard, this.tool, this, this.method);
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return <ConfirmTouchplateStepComponent step={this} />;
    }
}

interface ConfirmTouchplateStepComponentProps {
    step: ConfirmTouchplateStep;
}

function ConfirmTouchplateStepComponent({ step }: ConfirmTouchplateStepComponentProps) {
    const wizard = step.wizard as ToolMeasurementWizard;
    const colors = ConfigurationDataColors.Instance;
    const [isTriggered, setIsTriggered] = useState(false);
    const [isPositioned, setIsPositioned] = useState(false);

    const handleTestTrigger = () => {
        // TODO: Add code to wait for actual touchplate trigger
        // For now, just simulate the trigger
        setIsTriggered(true);
    };

    const handleContinue = () => {
        wizard.advanceToNextStep();
    };

    return (
        <Box sx={{ p: 3, display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>
            <Typography variant="body1" color="text.secondary">
                Before measuring, let's verify the touchplate is working correctly.
            </Typography>

            <Alert severity="info" sx={{ mb: 2 }}>
                <Typography variant="body2">
                    <strong>Step 1:</strong> Manually trigger the touchplate to verify it's working
                </Typography>
            </Alert>

            <Box sx={{ display: 'flex', justifyContent: 'center', my: 2 }}>
                <Button
                    variant="outlined"
                    onClick={handleTestTrigger}
                    disabled={isTriggered}
                    size="large"
                    sx={{ minWidth: 200 }}
                >
                    {isTriggered ? 'Touchplate Triggered!' : 'Test Touchplate Trigger'}
                </Button>
            </Box>

            {isTriggered && (
                <Alert severity="success" icon={<SuccessIcon />}>
                    <Typography variant="body2">
                        Touchplate is working correctly!
                    </Typography>
                </Alert>
            )}

            <Alert severity="warning" sx={{ mt: 2 }}>
                <Typography variant="body2">
                    <strong>Step 2:</strong> Confirm the touchplate is properly positioned under the tool
                </Typography>
            </Alert>

            <Box sx={{ display: 'flex', justifyContent: 'center', my: 2 }}>
                <FormControlLabel
                    control={
                        <Checkbox
                            checked={isPositioned}
                            onChange={(e) => setIsPositioned(e.target.checked)}
                            disabled={!isTriggered}
                        />
                    }
                    label="Touchplate is properly positioned"
                />
            </Box>

            <Box sx={{ flex: 1 }} />

            <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 2 }}>
                <Button
                    variant="outlined"
                    onClick={() => wizard.goToPreviousStep()}
                >
                    Back
                </Button>
                <Button
                    variant="contained"
                    onClick={handleContinue}
                    disabled={!isTriggered || !isPositioned}
                    sx={{ backgroundColor: colors.primaryColor }}
                >
                    Measure
                </Button>
            </Box>
        </Box>
    );
}
