import React, { ReactNode } from "react";
import { LogCategory, Logger } from "../Logger";
import { Profiler } from "../Profiler";
import { StateManager } from "./StateManager";

/**
 <ObserveMultiState
 key="unique-identifier"
 listenTo={[anobject, anobject]}
 control={() => {
        return (

        );
    }}
 />

 CRITICAL: Always provide a unique 'key' prop to prevent React reconciliation issues.
 **/
export class ObserveMultiState extends React.Component<{
    key?: string; // RECOMMENDED: Unique identifier to prevent React reconciliation issues
    profilerName?: string; // Optional: Custom name for profiler tracking (defaults to key)
    listenTo: (object | null | undefined)[];
    control: () => React.JSX.Element | ReactNode;
    shouldRender?: (changedProperties: string[]) => boolean; // Optional: Return false to skip re-render
    onWillUnmount?: () => void;
}, { updateCounter: number }> {
    constructor(props: any) {
        super(props);
        this.state = { updateCounter: 0 };
    }

    render() {
        const profilerName = this.props.profilerName || this.props.key || 'ObserveMultiState';
        Profiler.Instance.captureStart(`${profilerName}-render`);
        const result = this.props.control();
        Profiler.Instance.captureEnd(`${profilerName}-render`);
        return result;
    }

    componentDidUpdate(prevProps: {
        key?: string;
        listenTo: (object | null | undefined)[];
        control: () => React.JSX.Element | ReactNode;
        onWillUnmount?: () => void;
    }) {
        // Safety check: ensure both listenTo props are arrays
        if (!Array.isArray(this.props.listenTo) || !Array.isArray(prevProps.listenTo)) {
            return;
        }

        for (let obj of this.props.listenTo) {
            if (obj && !prevProps.listenTo.includes(obj)) {
                if (Array.isArray(obj)) {
                    const error = 'ObserveMultiState.listenTo[] elements cannot be arrays. Each element must be an object instance. Arrays do not have individual property watchers.';
                    Logger.Instance.logError(LogCategory.StateManager, error);
                    throw new Error(error);
                }
                StateManager.addObserver(obj, this);
            }
        }

        for (let obj of prevProps.listenTo) {
            if (obj && !this.props.listenTo.includes(obj)) {
                StateManager.removeObserver(obj, this);
            }
        }
    }

    componentDidMount() {
        if (this.props.listenTo && Array.isArray(this.props.listenTo)) {
            for (let l of this.props.listenTo) {
                if (l) {
                    if (Array.isArray(l)) {
                        const error = 'ObserveMultiState.listenTo[] elements cannot be arrays. Each element must be an object instance. Arrays do not have individual property watchers.';
                        Logger.Instance.logError(LogCategory.StateManager, error);
                        throw new Error(error);
                    }
                    StateManager.addObserver(l, this);
                }
            }
        }
    }

    componentWillUnmount() {
        if (this.props.listenTo && Array.isArray(this.props.listenTo)) {
            for (let l of this.props.listenTo) {
                if (l) StateManager.removeObserver(l, this);
            }
        }

        if (this.props.onWillUnmount) {
            this.props.onWillUnmount();
        }
    }

    updateFromStateManager(changedProperties?: string[]) {
        // Call optional shouldRender to allow component to skip unnecessary re-renders
        if (this.props.shouldRender && !this.props.shouldRender(changedProperties || [])) {
            return; // Skip re-render
        }

        this.setState(prevState => ({ updateCounter: prevState.updateCounter + 1 }));
        this.forceUpdate();
    }
}
