import {
  Analytics as AnalysisIcon,
  CheckCircle as CheckIcon,
  PlayArrow as DryRunIcon,
  Edit as EditIcon,
  Visibility as PreviewIcon,
  Visibility as ViewIcon,
  GpsFixed as WorkZeroIcon
} from '@mui/icons-material';
import {
  Box,
  Button,
  Card,
  CardContent,
  CardHeader,
  Checkbox,
  Divider,
  FormControlLabel,
  Grid,
  ToggleButton,
  ToggleButtonGroup,
  Typography
} from '@mui/material';
import React, { useEffect, useState } from 'react';
import { CNCPoint } from '../../../data/CNCPoint';
import { CoordinateType } from '../../../data/Common/CoordinateType';
import { FixtureLibrary } from '../../../data/Common/FixtureLibrary';
import { SimulatorViewData } from '../../../data/Common/SimulatorViewData';
import { ViewStyle } from '../../../data/Common/ViewStyle';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../data/ConfigurationState';
import { DryRunToolMode, DryRunToolpathMode } from '../../../data/DryRunSettings';
import { Job } from '../../../data/Job';
import { MachineStateData } from '../../../data/MachineStateData';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ModalManager } from '../../../utils/ModalManager';
import { ViewDataFactory, ViewNames } from '../../../utils/ViewDataFactory';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { DraggableDialog } from '../../Common/DraggableDialog';
import { GCodeEditorDialog } from '../../Common/GCodeEditorDialog';
import { JogControls } from '../../Common/JogControls';
import { NumberInput } from '../../Common/NumberInput';
import { SetWorkZeroDialog } from '../../Common/SetWorkZeroDialog';
import { CNCViewType, CameraTarget } from '../../MachineViewer/CNCViewer';
import { SimulatorDialog } from '../../SimulatorDialog';
import { TouchOffWizard } from '../../wizards/touchoff/TouchOffWizard';
import { JobInfoHeader } from './JobInfoHeader';

export interface SetupJobStageProps {
  onMovingToNext?: () => void;
  getNextStepName?: () => string;
}

export const SetupJobStage: React.FC<SetupJobStageProps> = ({ onMovingToNext, getNextStepName } = {}) => {
  const machineState = MachineStateData.Instance;
  const colors = ConfigurationDataColors.Instance;
  const [workZeroDialogOpen, setWorkZeroDialogOpen] = useState(false);
  const [jogControlsDialogOpen, setJogControlsDialogOpen] = useState(false);
  const [dryRunDialogOpen, setDryRunDialogOpen] = useState(false);
  const [dryRunPreviewOpen, setDryRunPreviewOpen] = useState(false);
  const [showGCodeEditor, setShowGCodeEditor] = useState(false);
  const [dismissedNonG54Warning, setDismissedNonG54Warning] = useState(false);

  // Create simulator view for dry run preview
  const [dryRunSimulatorView] = useState(() => {
    const viewData = new SimulatorViewData();
    viewData.currentViewType = CNCViewType.Top;
    viewData.cameraTargetMode = CameraTarget.GCodeCenter;
    viewData.showSettingsButton = true;
    viewData.showViewTypeButtons = true;

    const topView = viewData.topView;
    // Show only material, dry run toolpaths, tool, and work home
    topView.material = ViewStyle.Show;
    topView.dryRunToolpaths = true;
    topView.tool = ViewStyle.Show;
    topView.workHome = true;

    // Hide everything else
    topView.toolpaths = false;
    topView.gantry = ViewStyle.Hide;
    topView.base = ViewStyle.Hide;
    topView.bed = ViewStyle.Hide;
    topView.spindle = ViewStyle.Hide;
    topView.spoilBoard = ViewStyle.Hide;
    topView.clamps = ViewStyle.Hide;
    topView.softLimits = false;
    topView.machineZero = false;
    topView.machineHome = false;
    topView.rotary = ViewStyle.Hide;
    topView.verticalTable = ViewStyle.Hide;
    topView.atc = ViewStyle.Hide;

    return viewData;
  });

  // Validate work zero on mount - check if fixture position has changed
  useEffect(() => {
    if (ConfigurationState.Instance.currentJob) {
      ConfigurationState.Instance.currentJob.validateWorkZeroOnLoad(machineState.currentWorkZero);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []); // Run once on mount

  // Monitor position changes and auto-unconfirm if position moves
  useEffect(() => {
    if (ConfigurationState.Instance.currentJob) {
      ConfigurationState.Instance.currentJob.checkAndUpdateWorkZeroConfirmation(ConfigurationState.Instance.currentMachinePoint);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ConfigurationState.Instance.currentMachinePoint]);

  // Handle work zero confirmation toggle
  const handleWorkZeroConfirmToggle = () => {
    if (!ConfigurationState.Instance.currentJob) return;

    if (!ConfigurationState.Instance.currentJob.workZeroConfirmed) {
      // Confirming: use Job method to capture and store position
      ConfigurationState.Instance.currentJob.confirmWorkZero(ConfigurationState.Instance.currentMachinePoint);
    } else {
      // Unconfirming: use Job method
      ConfigurationState.Instance.currentJob.unconfirmWorkZero();
    }
  };

  // Handle Touch Off Z wizard
  const handleTouchOffZ = () => {
    TouchOffWizard.showForWorkZero();
  };

  // Handle Set Z to Spoilboard
  const handleSetZToSpoilboard = () => {
    // Get the top of the spoilboard from CoordinateUtil
    const spoilboardBox = CoordinateUtil.getSpoilboardBox(machineState);
    const spoilboardTopZ = spoilboardBox.origin.z + spoilboardBox.height;

    // Set Z work zero to the top of the spoilboard
    const currentWorkZero = machineState.currentWorkZero;

    // Update work zero with new Z value, keeping X and Y the same
    machineState.currentWorkZero = new CNCPoint(
      currentWorkZero.x,
      currentWorkZero.y,
      spoilboardTopZ,
      CoordinateType.MachineZero
    );
  };

  return (
    <>
      <ObserveState
        key="setup-job-stage-fixture-detection"
        listenTo={ConfigurationState.Instance.currentJob || new Job()}
        properties={['gcode']}
        control={() => (
          <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column', position: 'relative' }}>
            {/* Multiple Fixtures Warning Overlay */}
            {ConfigurationState.Instance.currentJob?.hasMultipleFixtures() && (
              <Box
                sx={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  right: 0,
                  bottom: 0,
                  backgroundColor: colors.modalBackdrop,
                  zIndex: 1000,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  p: 3
                }}
              >
                <Card sx={{ maxWidth: 500 }}>
                  <CardHeader
                    title="Multiple Fixtures Not Supported"
                    titleTypographyProps={{ variant: 'h6', color: colors.darkTextColor }}
                    sx={{ backgroundColor: colors.warningColor, color: colors.darkTextColor }}
                  />
                  <CardContent sx={{ backgroundColor: colors.lightTextColor }}>
                    <Typography variant="body1" paragraph sx={{ color: colors.darkTextColor }}>
                      This G-code uses multiple fixtures: {ConfigurationState.Instance.currentJob.getUniqueFixtures().join(', ')}
                    </Typography>
                    <Typography variant="body2" sx={{ color: `${colors.darkTextColor}B3` }}>
                      Currently, only single-fixture jobs are supported. Please edit your G-code to use a single fixture (G54 recommended) or split this into multiple jobs.
                    </Typography>
                  </CardContent>
                </Card>
              </Box>
            )}

            {/* Non-G54 Fixture Warning Overlay */}
            {!dismissedNonG54Warning && !ConfigurationState.Instance.currentJob?.hasMultipleFixtures() && ConfigurationState.Instance.currentJob?.hasNonG54Fixtures() && (
              <Box
                sx={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  right: 0,
                  bottom: 0,
                  backgroundColor: colors.modalBackdrop,
                  zIndex: 1000,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  p: 3
                }}
              >
                <Card sx={{ maxWidth: 500 }}>
                  <CardHeader
                    title="Custom WCS Detected"
                    titleTypographyProps={{ variant: 'h6', color: colors.darkTextColor }}
                    sx={{ backgroundColor: colors.warningColor, color: colors.darkTextColor }}
                  />
                  <CardContent sx={{ backgroundColor: colors.lightTextColor }}>
                    <Typography variant="body1" paragraph sx={{ color: colors.darkTextColor }}>
                      This G-code uses {ConfigurationState.Instance.currentJob.getUniqueFixtures()[0]} instead of the standard G54 WCS.
                    </Typography>
                    <Typography variant="body2" sx={{ color: `${colors.darkTextColor}B3` }} paragraph>
                      Would you like to:
                    </Typography>
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 2 }}>
                      <Button
                        variant="contained"
                        fullWidth
                        onClick={() => {
                          const fixture = FixtureLibrary.getFixtureByNumber(ConfigurationState.Instance.currentJob!.getUniqueFixtures()[0]);
                          if (fixture) {
                            machineState.setWorkZeroFromFixture(fixture, true);
                            UserMessageQueue.Instance.addMessage(`✓ Work zero set to ${fixture.fixtureNumber} (XYZ)`);
                          }
                          setDismissedNonG54Warning(true);
                        }}
                      >
                        Use This WCS's XYZ
                      </Button>
                      <Button
                        variant="outlined"
                        fullWidth
                        onClick={() => {
                          const fixture = FixtureLibrary.getFixtureByNumber(ConfigurationState.Instance.currentJob!.getUniqueFixtures()[0]);
                          if (fixture) {
                            machineState.setWorkZeroFromFixture(fixture, false);
                            UserMessageQueue.Instance.addMessage(`✓ Work zero set to ${fixture.fixtureNumber} (XY only)`);
                          }
                          setDismissedNonG54Warning(true);
                        }}
                      >
                        Use This WCS's XY Only
                      </Button>
                      <Button
                        variant="text"
                        fullWidth
                        onClick={() => setDismissedNonG54Warning(true)}
                      >
                        Continue Without Using This WCS
                      </Button>
                    </Box>
                  </CardContent>
                </Card>
              </Box>
            )}

            {/* Job Info Header - Fixed height header bar */}
            <Box sx={{
              p: 2,
              borderBottom: `1px solid ${colors.borderColor}`,
              backgroundColor: 'background.paper',
              flexShrink: 0
            }}>
              <JobInfoHeader
                jobName={ConfigurationState.Instance.currentJob?.name || 'Unnamed Job'}
                job={ConfigurationState.Instance.currentJob || null}
              />
            </Box>

            {/* Two Column Layout - Scrollable content */}
            <Box sx={{ flex: 1, minHeight: 0, overflow: 'auto', p: 3 }}>
              <Grid container spacing={3}>
                {/* Left Column - Analysis */}
                <Grid item xs={12} md={6} sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                  {/* Analysis Card - 2/3 height */}
                  <Card sx={{ flex: 2, display: 'flex', flexDirection: 'column' }}>
                    <CardHeader
                      avatar={<AnalysisIcon sx={{ color: colors.primaryColor }} />}
                      title="Analysis"
                      titleTypographyProps={{ variant: 'h6' }}
                      action={
                        <Button
                          variant="outlined"
                          color="primary"
                          size="small"
                          startIcon={<EditIcon />}
                          onClick={() => setShowGCodeEditor(true)}
                        >
                          Edit G-code
                        </Button>
                      }
                    />
                    <Divider />
                    <CardContent sx={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'auto' }}>
                      <Typography variant="body2" color="text.secondary" paragraph>
                        Analyze your job for potential issues, tool paths, and estimated run time.
                      </Typography>

                      {/* Analysis details will go here */}
                      <Box sx={{ flex: 1, p: 2, backgroundColor: 'background.default', borderRadius: 1, minHeight: '100px' }}>
                        <Typography variant="body2" color="text.secondary" align="center">
                          Analysis results will appear here
                        </Typography>
                      </Box>
                    </CardContent>
                  </Card>
                </Grid>

                {/* Right Column - Dry Run and Work Zero */}
                <Grid item xs={12} md={6} sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                  {/* Dry Run Card - Sized to content */}
                  <Card>
                    <CardHeader
                      avatar={<DryRunIcon sx={{ color: colors.primaryColor }} />}
                      title="Dry Run"
                      titleTypographyProps={{ variant: 'h6' }}
                    />
                    <Divider />
                    <CardContent>
                      <Typography variant="body2" color="text.secondary" paragraph>
                        Run the job without cutting to verify tool paths and detect collisions.
                      </Typography>
                      <Box sx={{ display: 'flex', gap: 1 }}>
                        <Button
                          variant="outlined"
                          color="success"
                          fullWidth
                          startIcon={<ViewIcon />}
                          onClick={() => {
                            const modalId = 'simulator-dialog';
                            const viewData = ViewDataFactory.createForContext(ViewNames.SIMULATOR_DIALOG);
                            ModalManager.Instance.showModal({
                              id: modalId,
                              render: () => (
                                <SimulatorDialog
                                  open={true}
                                  onClose={() => ModalManager.Instance.closeModal(modalId)}
                                  simulatorViewData={viewData}
                                  maxWidth="xl"
                                />
                              )
                            });
                          }}
                        >
                          View Simulator
                        </Button>
                        <Button
                          variant="contained"
                          color="success"
                          fullWidth
                          onClick={() => setDryRunDialogOpen(true)}
                        >
                          Dry Run
                        </Button>
                      </Box>
                    </CardContent>
                  </Card>

                  {/* Confirm Work Zero Card - Takes remaining space */}
                  <ObserveState
                    key="work-zero-confirm-card"
                    listenTo={ConfigurationState.Instance.currentJob || new Job()}
                    properties={['workZeroConfirmed']}
                    control={() => (
                      <Card sx={{ flex: 1 }}>
                        <CardHeader
                          avatar={ConfigurationState.Instance.currentJob?.workZeroConfirmed ? (
                            <CheckIcon sx={{ color: 'success.dark' }} />
                          ) : (
                            <WorkZeroIcon sx={{ color: 'warning.dark' }} />
                          )}
                          title={ConfigurationState.Instance.currentJob?.workZeroConfirmed
                            ? 'Work Zero Confirmed'
                            : 'Work Zero Not Confirmed'}
                          titleTypographyProps={{ variant: 'body1', fontWeight: 500 }}
                          sx={{
                            backgroundColor: ConfigurationState.Instance.currentJob?.workZeroConfirmed
                              ? 'success.light'
                              : 'warning.light'
                          }}
                        />
                        <Divider />
                        <CardContent>
                          <Typography variant="body2" color="text.secondary" paragraph>
                            Set and confirm your work zero position before starting the job.
                          </Typography>

                          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                            <Button
                              variant="outlined"
                              color="primary"
                              fullWidth
                              onClick={() => setWorkZeroDialogOpen(true)}
                            >
                              Go to Work Zero
                            </Button>
                            <Button
                              variant="outlined"
                              color="primary"
                              fullWidth
                              onClick={handleTouchOffZ}
                            >
                              Touch Off Z
                            </Button>
                            <Button
                              variant="outlined"
                              color="primary"
                              fullWidth
                              onClick={handleSetZToSpoilboard}
                            >
                              Set Z to Spoilboard
                            </Button>
                            <Button
                              variant="outlined"
                              color="primary"
                              fullWidth
                              onClick={() => setJogControlsDialogOpen(true)}
                            >
                              Change Work Zero
                            </Button>
                            <Button
                              variant={ConfigurationState.Instance.currentJob?.workZeroConfirmed ? 'outlined' : 'contained'}
                              color="success"
                              fullWidth
                              onClick={handleWorkZeroConfirmToggle}
                            >
                              {ConfigurationState.Instance.currentJob?.workZeroConfirmed ? 'Confirmed' : 'Confirm'}
                            </Button>
                          </Box>
                        </CardContent>
                      </Card>
                    )}
                  />
                </Grid>
              </Grid>
            </Box>

            {/* Go to Work Zero Dialog */}
            <DraggableDialog
              open={workZeroDialogOpen}
              onClose={() => setWorkZeroDialogOpen(false)}
              title="Go to Work Zero"
              maxWidth="md"
              fullWidth
            >
              <SetWorkZeroDialog onClose={() => setWorkZeroDialogOpen(false)} />
            </DraggableDialog>

            {/* Jog Controls Dialog for Change Work Zero */}
            <DraggableDialog
              open={jogControlsDialogOpen}
              onClose={() => setJogControlsDialogOpen(false)}
              title="Change Work Zero"
              maxWidth="md"
              fullWidth
            >
              <Box sx={{ p: 3 }}>
                <JogControls />
              </Box>
            </DraggableDialog>

            {/* Dry Run Dialog - Non-modal */}
            <DraggableDialog
              open={dryRunDialogOpen}
              onClose={() => setDryRunDialogOpen(false)}
              title="Dry Run Instructions"
              maxWidth="md"
              fullWidth
              hideBackdrop
              disableEnforceFocus
              PaperProps={{
                sx: {
                  position: 'fixed',
                  top: 100,
                  right: 20,
                  m: 0,
                  maxHeight: 'calc(100vh - 120px)'
                }
              }}
              actions={
                <>
                  <Button
                    startIcon={<PreviewIcon />}
                    onClick={() => setDryRunPreviewOpen(true)}
                  >
                    Preview
                  </Button>
                  <Box sx={{ flex: 1 }} />
                  <Button onClick={() => setDryRunDialogOpen(false)}>
                    Close
                  </Button>
                  <Button
                    variant="contained"
                    sx={{
                      backgroundColor: colors.primaryColor,
                      '&:hover': { backgroundColor: colors.primaryColor }
                    }}
                    onClick={() => {
                      // TODO: Start dry run with current settings
                      setDryRunDialogOpen(false);
                    }}
                  >
                    Start Dry Run
                  </Button>
                </>
              }
            >
              <ObserveState
                key="dry-run-settings-dialog"
                listenTo={ConfigurationState.Instance.currentJob}
                properties={['dryRunToolpathMode', 'dryRunToolMode', 'dryRunZ', 'dryRunChangeSpeed', 'dryRunSpeed']}
                control={() => {
                  const currentJob = ConfigurationState.Instance.currentJob;
                  if (!currentJob) return null;

                  return (
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                      {/* Toolpath Mode */}
                      <Box>
                        <Typography variant="subtitle2" gutterBottom sx={{ fontWeight: 600 }}>
                          Toolpath Mode
                        </Typography>
                        <ToggleButtonGroup
                          value={currentJob.dryRunToolpathMode}
                          exclusive
                          onChange={(_, value) => {
                            if (value !== null) {
                              currentJob.dryRunToolpathMode = value;
                            }
                          }}
                          fullWidth
                          size="small"
                        >
                          <ToggleButton value={DryRunToolpathMode.NoChanges}>
                            No Changes
                          </ToggleButton>
                          <ToggleButton value={DryRunToolpathMode.RemoveDuplicate}>
                            Remove Duplicate
                          </ToggleButton>
                          <ToggleButton value={DryRunToolpathMode.TraceOutline}>
                            Trace Outline
                          </ToggleButton>
                        </ToggleButtonGroup>
                      </Box>

                      {/* Tool Mode */}
                      <Box>
                        <Typography variant="subtitle2" gutterBottom sx={{ fontWeight: 600 }}>
                          Tool Mode
                        </Typography>
                        <ToggleButtonGroup
                          value={currentJob.dryRunToolMode}
                          exclusive
                          onChange={(_, value) => {
                            if (value !== null) {
                              currentJob.dryRunToolMode = value;
                            }
                          }}
                          fullWidth
                          size="small"
                        >
                          <ToggleButton value={DryRunToolMode.CurrentTool}>
                            Current Tool
                          </ToggleButton>
                          <ToggleButton value={DryRunToolMode.DoToolChanges}>
                            Do Tool Changes
                          </ToggleButton>
                          <ToggleButton value={DryRunToolMode.LaserPointer}>
                            Laser Pointer
                          </ToggleButton>
                        </ToggleButtonGroup>
                      </Box>

                      {/* Run At Z */}
                      <Box>
                        <NumberInput
                          label="Run at Z"
                          value={currentJob.dryRunZ}
                          onChange={(value) => {
                            currentJob.dryRunZ = value;
                          }}
                          fullWidth
                          size="small"
                          precision={3}
                          allowFractions={true}
                          showHelperText={false}
                        />
                      </Box>

                      {/* Speed Override */}
                      <Box>
                        <FormControlLabel
                          control={
                            <Checkbox
                              checked={currentJob.dryRunChangeSpeed}
                              onChange={(e) => {
                                currentJob.dryRunChangeSpeed = e.target.checked;
                              }}
                            />
                          }
                          label="Change Speed"
                        />
                        {currentJob.dryRunChangeSpeed && (
                          <NumberInput
                            label="Feed Rate (in/min)"
                            value={currentJob.dryRunSpeed}
                            onChange={(value) => {
                              currentJob.dryRunSpeed = Math.max(1, value);
                            }}
                            fullWidth
                            size="small"
                            sx={{ mt: 1 }}
                            min={1}
                            precision={1}
                            allowNegative={false}
                            allowFractions={false}
                            helperText="Feed rate in inches per minute"
                          />
                        )}
                      </Box>
                    </Box>
                  );
                }}
              />
            </DraggableDialog>

            {/* Dry Run Preview Dialog */}
            <SimulatorDialog
              open={dryRunPreviewOpen}
              onClose={() => setDryRunPreviewOpen(false)}
              simulatorViewData={dryRunSimulatorView}
              maxWidth="lg"
              showDryRunGCode={true}
            />
          </Box>
        )}
      />

      {/* G-code Editor Dialog */}
      <GCodeEditorDialog
        open={showGCodeEditor}
        gcode={ConfigurationState.Instance.currentJob?.gcode || ''}
        onSave={(gcode) => {
          if (ConfigurationState.Instance.currentJob) {
            ConfigurationState.Instance.currentJob.gcode = gcode;
            StateManager.propertyChanged(machineState, 'currentJob');
          }
          setShowGCodeEditor(false);
        }}
        onCancel={() => setShowGCodeEditor(false)}
      />
    </>
  );
};
