import React from 'react';
import { IStorable } from '../../../common/IStorable';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { DataUtilities } from '../../../utils/storage/DataUtilities';
import { DataElement } from '../data/DataElement';
import { Declaration } from '../data/Declaration';
import { IPLCElement, OutputState, OutputType, PLCRenderMode, PLCValidationIssue } from '../data/IPLCElement';
import { IPLCSource, PLCProgramType, PLCSerializationHelper, PLCUtilities } from '../data/PLCUtilities';

/**
 * Abstract base class for all PLC predicates (operations)
 * Predicates represent the actual operations/instructions in ladder logic
 * Each concrete predicate type will extend this class with specific behavior
 */
export abstract class BasePLCPredicate implements IStorable, IPLCElement {
    private _comment: string;       // Optional comment for this predicate
    private _enabled: boolean;      // Whether this predicate is enabled/active
    private _plcSource: IPLCSource | undefined;
    private _parentElement: IPLCElement | undefined;  // Parent statement that contains this predicate

    constructor() {
        this._plcSource = undefined;
        this._comment = '';
        this._enabled = true;

        // Set up cache invalidation listener
        PLCUtilities.setupCacheInvalidationListener(this);
    }

    /**
     * Render the predicate to JSX - must be implemented by derived classes
     * @param mode Rendering mode (Edit, ReadOnly, or Disabled)
     * @param targetProgramType The program type context for rendering
     */
    public abstract render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode;

    /**
     * Get declarations that are used/referenced by this predicate - must be implemented by derived classes
     */
    public abstract getUsedDeclarations(): Declaration[];

    /**
     * Get declarations that are added/defined by this predicate - must be implemented by derived classes
     */
    public abstract getAddedDeclarations(): Declaration[];

    /**
     * Get the PLC logic code for this predicate - must be implemented by derived classes
     */
    public abstract getPLCLogic(): string[];

    /**
     * Get pre-PLC logic code that runs before any IF statements (e.g., reset toggle bits)
     * Default implementation returns empty array - override in predicates that need pre-logic
     * @returns Array of PLC logic lines to be output before the main logic
     */
    public getPrePLCLogic(): string[] {
        return [];
    }

    /**
     * Get secondary PLC logic code for this predicate (e.g., toggle logic after primary action)
     * Default implementation returns empty array - override in predicates that need secondary logic
     * @returns Array of PLC logic lines to be output after the primary predicate logic
     */
    public getSecondaryPLCLogic(): string[] {
        return [];
    }

    /**
     * Get the inline comment for this predicate (used when rendering in IF statements)
     * @returns The comment string, or empty string if no comment
     */
    public getComment(): string {
        return this._comment || '';
    }

    /**
     * Get validation issues for this predicate - must be implemented by derived classes
     */
    public abstract getValidationIssues(): PLCValidationIssue[];

    /**
     * Get all data elements used by this predicate - must be implemented by derived classes
     */
    public abstract getDataElements(): DataElement[];

    /**
     * Get a short, single-line description of this predicate for display in tree views
     * Example: "Set DustCollector output" or "Send message 'Ready'"
     * @returns A human-readable summary of the predicate's action
     */
    public abstract getShortDescription(): string;

    /**
     * Check if this predicate is disabled
     * A predicate is disabled if:
     * 1. Its enabled property is false, OR
     * 2. (For SystemDefault predicates in System context) It references an input/output
     *    that is not available in the System PLC
     * 
     * IMPORTANT: When rendering SystemDefault PLC itself, predicates should NOT be disabled
     * due to undefined inputs/outputs - that's where they're being defined!
     */
    public isDisabled(mode: PLCRenderMode, targetProgramType: PLCProgramType): boolean {
        // 1. Check enabled property
        if (!this._enabled) {
            return true;
        }

        // 2. Check if predicate uses unavailable declarations (SystemDefault -> System merge)
        // Only applies when a SystemDefault predicate is being used in System context
        if (!this.plcSource || this.plcSource.getProgramType() !== PLCProgramType.SystemDefault) {
            return false; // Not from SystemDefault, no availability check needed
        }

        // This is from SystemDefault - check if it's being used in System context
        // If targetProgramType is not System, no check needed
        // CRITICAL: When rendering SystemDefault itself, don't disable due to undefined I/O
        if (targetProgramType !== PLCProgramType.System) {
            return false; // Rendering for SystemDefault itself, or other non-System context
        }

        const parentProgramType = targetProgramType;
        const currentProgramType = this.plcSource.getProgramType();

        // SystemDefault predicate being used in System - check if inputs/outputs are defined in System
        const dataElements = this.getDataElements();

        for (const element of dataElements) {
            const shouldDisable = PLCUtilities.shouldBeDisabledDueToDeclarations(element, parentProgramType, currentProgramType);
            if (shouldDisable) {
                return true; // Missing declaration, disable predicate
            }
        }

        return false;
    }

    /**
     * Determine whether this predicate should be output
     * @param outputType The type of output (Render or PLCCode)
     * @param availableDeclarations Optional array of available declaration names
     * @returns OutputState indicating how this predicate should be handled
     */
    public shouldOutput(outputType: OutputType, availableDeclarations?: string[]): OutputState {
        // TODO: Define proper output logic later
        return OutputState.Output;
    }

    public get comment(): string {
        return this._comment;
    }

    public set comment(value: string) {
        this._comment = value;
        StateManager.propertyChanged(this, 'comment');
    }

    public get enabled(): boolean {
        return this._enabled;
    }

    public set enabled(value: boolean) {
        this._enabled = value;
        StateManager.propertyChanged(this, 'enabled');
    }

    public get plcSource(): IPLCSource | undefined {
        const resolved = PLCUtilities.resolvePLCSource(this, false);
        return resolved !== null ? resolved : undefined;
    }

    /**
     * Get the type of this PLC element
     */
    public getElementType(): 'predicate' {
        return 'predicate';
    }

    /**
     * Reset cached state before rendering or code generation
     * Default implementation does nothing - override in subclasses that need it
     */
    public preRenderReset(): void {
        // Default: no-op
    }

    /**
     * Get unique identifier for this predicate
     */
    public getElementId(): string {
        return `predicate-${this.constructor.name}`;
    }

    /**
     * Get the parent element (statement) that contains this predicate
     */
    public getParentElement(): IPLCElement | undefined {
        return this._parentElement;
    }

    /**
     * Set the parent element (statement) that contains this predicate
     */
    public setParentElement(parent: IPLCElement | undefined): void {
        this._parentElement = parent;
        // Clear cached plcSource - will be resolved on next access
        this._plcSource = undefined;
        // Subclasses should override and cascade to their child DataElements
    }

    /**
     * Serialize to JSON - can be overridden by derived classes
     */
    public toJSON(): object {
        return PLCSerializationHelper.getStorageData(this);
    }

    /**
     * Load from JSON - can be overridden by derived classes
     */
    public fromJSON(data: any): void {
        if (!data) return;
        DataUtilities.loadStorageData(this, data);
    }
}
