import { Handyman as HandymanIcon } from '@mui/icons-material';
import { Box, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationState } from '../../data/ConfigurationState';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { Machine } from '../../machine/Machine';
import { LogCategory, Logger } from '../Logger';
import { IUserAction } from './IUserAction';

export class MeasureToolUserAction implements IUserAction {
    public readonly id = 'tool_management_measure_tool';
    public readonly category = 'Tool Management';

    public isAvailable(): boolean {
        const config = ConfigurationState.Instance;
        return config.isHomed && !config.isJobRunning;
    }

    public renderButton(asLink: boolean): React.ReactNode {
        if (asLink) {
            return (
                <React.Fragment>
                    <HandymanIcon sx={{ fontSize: 18, color: 'primary.main' }} />
                    <Typography variant="body2" sx={{ color: 'inherit', fontWeight: 500 }}>
                        Measure Tool
                    </Typography>
                </React.Fragment>
            );
        } else {
            return (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <HandymanIcon />
                    <Typography>Measure Tool</Typography>
                </Box>
            );
        }
    }

    public async run(): Promise<void> {
        try {
            const machine = Machine.getInstance();
            await machine.system.measureCurrentTool();
            UserMessageQueue.Instance.addMessage('✓ Tool measurement complete');
        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : String(error);
            Logger.Instance.logError(LogCategory.UserInterface, 'Failed to measure tool:', error);
            UserMessageQueue.Instance.addMessage(`❌ Failed to measure tool: ${errorMessage}`);
        }
    }
}
