import { CheckCircle, RadioButtonUnchecked } from '@mui/icons-material';
import { Box, Button, Card, CardContent, Chip, Divider, LinearProgress, Typography } from '@mui/material';
import { SetupChecklistLibrary } from '../../../data/Checklist/SetupChecklistLibrary';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ConfirmDialogManager } from '../../../utils/ConfirmDialogManager';
import { ObserveState } from '../../../utils/statemanager/ObserveState';

/**
 * Setup Checklist Section Component
 * Displays setup checklist items showing completion status
 * Allows users to manually confirm items that have passed automated checks
 */
export function SetupChecklistSection() {
    const colors = ConfigurationDataColors.Instance;
    const library = SetupChecklistLibrary.Instance;

    const handleResetAll = async () => {
        const confirmed = await ConfirmDialogManager.Instance.showConfirm({
            title: 'Reset All Confirmations',
            message: 'Are you sure you want to reset all manual confirmations? This will mark all manually confirmed items as incomplete.',
            confirmText: 'Reset All',
            severity: 'warning'
        });

        if (confirmed) {
            library.allItems.forEach(item => {
                if (item.needsManualConfirmation()) {
                    item.manuallyConfirmed = false;
                }
            });
        }
    };

    return (
        <ObserveState
            key="setup-checklist-section"
            listenTo={library}
            properties={['items']}
            control={() => {
                const completionPercentage = library.getCompletionPercentage();
                const completedCount = library.completedItems.length;
                const totalCount = library.items.length;
                const incompleteItems = library.incompleteItems;
                const completedItems = library.completedItems;

                return (
                    <Box>
                        <Box sx={{ mb: 3 }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
                                <Typography variant="h6">
                                    Setup Checklist
                                </Typography>
                                <Chip
                                    label={`${completedCount} / ${totalCount}`}
                                    color={completionPercentage === 100 ? 'success' : 'default'}
                                    size="small"
                                />
                            </Box>

                            <Box sx={{ mb: 2 }}>
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                                    <Typography variant="body2" color="text.secondary">
                                        {completionPercentage}% Complete
                                    </Typography>
                                </Box>
                                <LinearProgress
                                    variant="determinate"
                                    value={completionPercentage}
                                    sx={{
                                        height: 8,
                                        borderRadius: 1,
                                        backgroundColor: colors.borderColor,
                                        '& .MuiLinearProgress-bar': {
                                            backgroundColor: colors.primaryColor,
                                        },
                                    }}
                                />
                            </Box>

                            {/* Reset Link */}
                            <Typography
                                variant="caption"
                                sx={{
                                    display: 'block',
                                    textAlign: 'right',
                                    mt: 1,
                                    color: 'primary.main',
                                    cursor: 'pointer',
                                    textDecoration: 'underline',
                                    '&:hover': {
                                        color: 'primary.dark'
                                    }
                                }}
                                onClick={handleResetAll}
                            >
                                reset setup list
                            </Typography>
                        </Box>

                        <Divider sx={{ mb: 2 }} />

                        {totalCount === 0 ? (
                            <Box sx={{ textAlign: 'center', py: 4 }}>
                                <Typography variant="body2" color="text.secondary">
                                    No checklist items configured
                                </Typography>
                            </Box>
                        ) : (
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                                {/* Todo Items */}
                                {incompleteItems.length > 0 && (
                                    <>
                                        <Typography variant="subtitle2" sx={{ fontWeight: 600, color: colors.errorColor, textTransform: 'uppercase' }}>
                                            Todo
                                        </Typography>
                                        {incompleteItems.map((item, index) => {
                                            const needsManual = item.needsManualConfirmation();
                                            const checkPassed = item.completionCheck();
                                            const canAutoComplete = checkPassed && needsManual && !item.manuallyConfirmed;

                                            return (
                                                <Card
                                                    key={`incomplete-${index}`}
                                                    sx={{
                                                        backgroundColor: `${colors.errorColor}0D`,
                                                        borderLeft: `6px solid ${colors.errorColor}`,
                                                        border: `1px solid ${colors.errorColor}4D`,
                                                    }}
                                                >
                                                    <CardContent sx={{ py: 1.5, px: 2, '&:last-child': { pb: 1.5 } }}>
                                                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                                                            <RadioButtonUnchecked
                                                                sx={{
                                                                    color: colors.errorColor,
                                                                    fontSize: '1.25rem',
                                                                }}
                                                            />

                                                            <Box sx={{ flex: 1 }}>
                                                                <Typography
                                                                    variant="body2"
                                                                    sx={{
                                                                        fontWeight: 500,
                                                                        color: 'text.primary',
                                                                    }}
                                                                    title={item.description || ''}
                                                                >
                                                                    {item.name}
                                                                </Typography>

                                                                {canAutoComplete && (
                                                                    <Button
                                                                        variant="outlined"
                                                                        size="small"
                                                                        onClick={() => library.confirmItem(item)}
                                                                        sx={{ mt: 1, fontSize: '0.75rem' }}
                                                                    >
                                                                        Complete
                                                                    </Button>
                                                                )}
                                                            </Box>
                                                        </Box>
                                                    </CardContent>
                                                </Card>
                                            );
                                        })}
                                    </>
                                )}

                                {/* Completed Items */}
                                {completedItems.length > 0 && (
                                    <>
                                        {incompleteItems.length > 0 && <Divider sx={{ my: 2 }} />}
                                        <Typography variant="subtitle2" sx={{ fontWeight: 600, color: colors.successColor, textTransform: 'uppercase' }}>
                                            Completed
                                        </Typography>
                                        {completedItems.map((item, index) => (
                                            <Card
                                                key={`completed-${index}`}
                                                sx={{
                                                    backgroundColor: `${colors.successColor}0D`,
                                                    borderLeft: `6px solid ${colors.successColor}`,
                                                    border: `1px solid ${colors.successColor}4D`,
                                                }}
                                            >
                                                <CardContent sx={{ py: 1.5, px: 2, '&:last-child': { pb: 1.5 } }}>
                                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                                                        <CheckCircle
                                                            sx={{
                                                                color: colors.successColor,
                                                                fontSize: '1.25rem',
                                                            }}
                                                        />

                                                        <Box sx={{ flex: 1 }}>
                                                            <Typography
                                                                variant="body2"
                                                                sx={{
                                                                    fontWeight: 500,
                                                                    textDecoration: 'line-through',
                                                                    color: 'text.secondary',
                                                                }}
                                                                title={item.description || ''}
                                                            >
                                                                {item.name}
                                                            </Typography>

                                                            {item.needsManualConfirmation() && (
                                                                <Button
                                                                    size="small"
                                                                    variant="outlined"
                                                                    onClick={() => library.resetItem(item)}
                                                                    sx={{
                                                                        mt: 1,
                                                                        fontSize: '0.75rem',
                                                                        textTransform: 'none',
                                                                    }}
                                                                >
                                                                    Reset
                                                                </Button>
                                                            )}
                                                        </Box>
                                                    </Box>
                                                </CardContent>
                                            </Card>
                                        ))}
                                    </>
                                )}
                            </Box>
                        )}
                    </Box>
                );
            }}
        />
    );
}