import { Box } from '@mui/material';
import { CoordinatesDisplay } from '../Common/CoordinatesDisplay';

interface ControlPanelProps {
  onViewChange?: (view: string) => void;
}

function ControlPanelComponent({ onViewChange }: ControlPanelProps) {
  return (
    <Box sx={{ height: '100%' }}>
      <CoordinatesDisplay />
    </Box>
  );
}

export const ControlPanel = ({ onViewChange }: { onViewChange?: (view: string) => void }) => (
  <ControlPanelComponent onViewChange={onViewChange} />
);
