import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import { Box, Button, CircularProgress, Typography } from '@mui/material';
import React from 'react';
import { Tool } from '../../../../data/Common/Tool';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { MachineStateData } from '../../../../data/MachineStateData';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { WizardStep } from '../../../Wizard/WizardStep';
import { ChangeToolWizard } from '../ChangeToolWizard';

export class MeasureNewToolStep extends WizardStep {
    private newTool: Tool | null;
    private isMeasuring: boolean = false;
    private hasMeasured: boolean = false;
    private measurementError: string | null = null;

    constructor(wizard: ChangeToolWizard, newTool: Tool | null, previousStep: WizardStep | null) {
        super(wizard, previousStep);
        this.newTool = newTool;
    }

    public getTitle(): string {
        return 'Measure New Tool';
    }

    public nextStep(): WizardStep | null {
        return null; // This is the final step
    }

    public backStep(): WizardStep | null {
        return this.priorStep;
    }

    private async handleMeasure(): Promise<void> {
        if (!this.newTool) {
            this.measurementError = 'No tool selected to measure';
            StateManager.propertyChanged(this, 'measurementError');
            return;
        }

        this.isMeasuring = true;
        this.measurementError = null;
        StateManager.propertyChanged(this, 'isMeasuring');
        StateManager.propertyChanged(this, 'measurementError');

        try {

            // Update the current tool number before measuring
            if (this.newTool.toolNumber !== undefined && this.newTool.toolNumber !== null) {
                const machineState = MachineStateData.Instance;
                machineState.currentToolNumber = this.newTool.toolNumber;
            }

            // Close this wizard first
            this.wizard.closeWizard();

            // Call measureCurrentTool which will launch the wizard if needed based on measurement mode
            const { MachineInterfaceManager } = await import('../../../../utils/MachineInterfaceManager');
            const machine = MachineInterfaceManager.Instance.getMachineInterface();

            if (machine?.system) {
                await machine.system.measureCurrentTool();
                this.hasMeasured = true;
                StateManager.propertyChanged(this, 'hasMeasured');
            } else {
                throw new Error('Machine interface not available');
            }
        } catch (error) {
            Logger.Instance.logError(LogCategory.Tools, 'Error measuring tool:', error);
            this.measurementError = error instanceof Error ? error.message : 'Failed to measure tool';
            this.hasMeasured = false;
            StateManager.propertyChanged(this, 'measurementError');
            StateManager.propertyChanged(this, 'hasMeasured');
        } finally {
            this.isMeasuring = false;
            StateManager.propertyChanged(this, 'isMeasuring');
        }
    }

    private handleComplete(): void {
        // Tool number already updated, just close the wizard
    }

    public render(): React.ReactNode {
        return (
            <ObserveState
                key="measure-new-tool-step"
                listenTo={this}
                properties={['isMeasuring', 'hasMeasured', 'measurementError']}
                control={() => {
                    const config = ConfigurationData.Instance;
                    const colors = ConfigurationDataColors.Instance;

                    return (
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>
                            {/* Instructions */}
                            <Box sx={{
                                p: 2,
                                backgroundColor: colors.primaryColor + '15',
                                borderRadius: 1,
                                borderLeft: `4px solid ${colors.primaryColor}`
                            }}>
                                <Typography variant="h6" sx={{ mb: 1, fontWeight: 'bold' }}>
                                    Measure New Tool
                                </Typography>
                                <Typography variant="body1">
                                    Once the tool change is complete, click the button below to measure the new tool length.
                                </Typography>
                            </Box>

                            {/* Tool Info */}
                            {this.newTool && (
                                <Box sx={{
                                    p: 2,
                                    border: `1px solid ${colors.borderColor}`,
                                    borderRadius: 1
                                }}>
                                    <Typography variant="subtitle2" sx={{ color: 'text.secondary', mb: 1 }}>
                                        Tool to Measure
                                    </Typography>
                                    <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 1 }}>
                                        T{(this.newTool.toolNumber ?? 0).toString().padStart(2, '0')} - {this.newTool.displayName}
                                    </Typography>
                                    <Box sx={{ display: 'flex', gap: 2, mt: 1 }}>
                                        <Box>
                                            <Typography variant="caption" sx={{ color: 'text.secondary' }}>Cutting Diameter</Typography>
                                            <Typography variant="body2">{this.newTool.cuttingDiameter?.toFixed(3) || '0.000'}"</Typography>
                                        </Box>
                                        <Box>
                                            <Typography variant="caption" sx={{ color: 'text.secondary' }}>Cutting Length</Typography>
                                            <Typography variant="body2">{this.newTool.cuttingLength?.toFixed(3) || '0.000'}"</Typography>
                                        </Box>
                                        <Box>
                                            <Typography variant="caption" sx={{ color: 'text.secondary' }}>Type</Typography>
                                            <Typography variant="body2">{this.newTool.cutterType}</Typography>
                                        </Box>
                                    </Box>
                                </Box>
                            )}

                            {/* Measurement Status */}
                            {this.hasMeasured && (
                                <Box sx={{
                                    p: 2,
                                    backgroundColor: colors.successColor + '15',
                                    borderRadius: 1,
                                    borderLeft: `4px solid ${colors.successColor}`,
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: 2
                                }}>
                                    <CheckCircleIcon sx={{ color: colors.successColor, fontSize: 32 }} />
                                    <Box>
                                        <Typography variant="h6" sx={{ fontWeight: 'bold' }}>
                                            Tool Measured Successfully
                                        </Typography>
                                        <Typography variant="body2">
                                            The tool length has been updated. Click "Complete Tool Change" to finish.
                                        </Typography>
                                    </Box>
                                </Box>
                            )}

                            {/* Error Message */}
                            {this.measurementError && (
                                <Box sx={{
                                    p: 2,
                                    backgroundColor: colors.errorColor + '15',
                                    borderRadius: 1,
                                    borderLeft: `4px solid ${colors.errorColor}`
                                }}>
                                    <Typography variant="body1" sx={{ color: colors.errorColor }}>
                                        {this.measurementError}
                                    </Typography>
                                </Box>
                            )}

                            {/* Action Buttons */}
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 'auto' }}>
                                <Button
                                    variant="contained"
                                    size="large"
                                    onClick={() => this.handleMeasure()}
                                    disabled={this.isMeasuring || this.hasMeasured}
                                    startIcon={this.isMeasuring ? <CircularProgress size={20} color="inherit" /> : undefined}
                                    sx={{ py: 1.5 }}
                                >
                                    {this.isMeasuring
                                        ? 'Measuring...'
                                        : this.hasMeasured
                                            ? 'Measurement Complete'
                                            : 'Measure Tool'
                                    }
                                </Button>

                                {this.hasMeasured && (
                                    <Button
                                        variant="contained"
                                        color="success"
                                        size="large"
                                        onClick={() => this.handleComplete()}
                                        sx={{ py: 1.5 }}
                                    >
                                        Complete Tool Change
                                    </Button>
                                )}
                            </Box>
                        </Box>
                    );
                }}
            />
        );
    }
}
