import { Grid } from '@mui/material';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';
import { OffsetEditor } from '../../../Common/OffsetEditor';

export function LaserSection() {
    const machine = MachineData.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
                <ObserveState
                    key="laser-offset"
                    listenTo={machine}
                    properties={['laserOffset']}
                    control={() => (
                        <OffsetEditor
                            offset={machine.laserOffset}
                            label="Offset from Spindle"
                            showLabel={true}
                            precision={3}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="laser-width"
                    listenTo={machine}
                    properties={['laserWidth']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Laser Width"
                            value={machine.laserWidth}
                            onChange={(value) => machine.laserWidth = value}
                            margin="normal"
                            precision={3}
                            helperText="Width of laser housing"
                        />
                    )}
                />

                <ObserveState
                    key="laser-length"
                    listenTo={machine}
                    properties={['laserLength']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Laser Length"
                            value={machine.laserLength}
                            onChange={(value) => machine.laserLength = value}
                            margin="normal"
                            precision={3}
                            helperText="Length of laser housing"
                        />
                    )}
                />

                <ObserveState
                    key="laser-height"
                    listenTo={machine}
                    properties={['laserHeight']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Laser Height"
                            value={machine.laserHeight}
                            onChange={(value) => machine.laserHeight = value}
                            margin="normal"
                            precision={3}
                            helperText="Height of laser housing"
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="laser-offset"
                    listenTo={machine}
                    properties={['laserOffset']}
                    control={() => (
                        <OffsetEditor
                            offset={machine.laserOffset}
                            label="Laser Mount Offset"
                            showLabel={true}
                            precision={2}
                            xLabel="X Offset"
                            yLabel="Y Offset"
                            zLabel="Z Offset"
                        />
                    )}
                />
            </Grid>
        </Grid>
    );
}
