import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../../data/ConfigurationState';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { JogControls } from '../../../Common/JogControls';
import { WizardStep } from '../../../Wizard/WizardStep';
import { AxisCalibrationWizard } from '../AxisCalibrationWizard';
import { MoveCommandStep } from './MoveCommandStep';

/**
 * Step to move spindle to starting position for calibration
 */
export class StartingPositionStep extends WizardStep {

    getTitle(): string {
        const wizard = this.wizard as AxisCalibrationWizard;
        return `Position ${wizard.state.selectedAxis} Axis`;
    }

    nextStep(): WizardStep | null {
        return new MoveCommandStep(this.wizard as AxisCalibrationWizard, this);
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return (
            <ObserveState
                key="starting-position-step"
                listenTo={this.wizard}
                properties={['state']}
                control={() => <StartingPositionStepComponent step={this} />}
            />
        );
    }
}

interface StartingPositionStepComponentProps {
    step: StartingPositionStep;
}

function StartingPositionStepComponent({ step }: StartingPositionStepComponentProps) {
    const wizard = step.wizard as AxisCalibrationWizard;
    const colors = ConfigurationDataColors.Instance;

    const axisName = wizard.state.selectedAxis;

    const handleContinue = () => {
        // Capture starting position from current machine coordinates
        const currentPoint = ConfigurationState.Instance.currentMachinePoint;

        let startingPos: number;
        if (axisName === 'X') {
            startingPos = currentPoint.x;
        } else if (axisName === 'Y') {
            startingPos = currentPoint.y;
        } else if (axisName === 'Z') {
            startingPos = currentPoint.z;
        } else {
            startingPos = 0;
        }

        // Store starting position in wizard state
        wizard.state = {
            ...wizard.state,
            startingPosition: startingPos
        };

        wizard.advanceToNextStep();
    };

    const handleBack = () => {
        wizard.goToPreviousStep();
    };

    return (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column', gap: 2, p: 3 }}>
            {/* Header */}
            <Box>
                <Typography variant="h5" gutterBottom sx={{ color: colors.primaryColor, fontWeight: 'bold' }}>
                    Step 1: Pick Starting Position
                </Typography>
            </Box>

            {/* Main content area - side by side layout */}
            <Box sx={{ flex: 1, display: 'flex', gap: 3, minHeight: 0 }}>
                {/* Instructions - left side */}
                <Box sx={{
                    width: '280px',
                    flexShrink: 0,
                    p: 2,
                    backgroundColor: colors.lightBackgroundColor,
                    borderRadius: 1,
                    borderLeft: `4px solid ${colors.infoColor}`,
                    display: 'flex',
                    flexDirection: 'column'
                }}>
                    <Typography variant="subtitle2" sx={{ color: colors.primaryColor, fontWeight: 'bold', mb: 1 }}>
                        Instructions:
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                        1. Position a dial indicator or measuring device on the {axisName} axis
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                        2. Find a reference surface to measure from
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                        3. Zero your measuring device or note the starting position
                    </Typography>
                    <Typography variant="body2" sx={{ color: colors.darkTextColor }}>
                        4. Click Continue when ready to move the axis
                    </Typography>
                </Box>

                {/* Jog Controls - right side, centered */}
                <Box sx={{
                    flex: 1,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    minWidth: 0 // Allow flex to work properly
                }}>
                    <JogControls />
                </Box>
            </Box>

            {/* Bottom buttons */}
            <Box sx={{
                pt: 2,
                borderTop: `1px solid ${colors.borderColor}`,
                display: 'flex',
                justifyContent: 'space-between'
            }}>
                <Button
                    variant="outlined"
                    onClick={handleBack}
                >
                    Back
                </Button>
                <Button
                    variant="contained"
                    onClick={handleContinue}
                    sx={{ backgroundColor: colors.primaryColor }}
                >
                    Capture Starting Position
                </Button>
            </Box>
        </Box>
    );
}
