import { Add as AddIcon, Delete as DeleteIcon, Edit as EditIcon } from '@mui/icons-material';
import { Box, Button, Chip, IconButton, Paper, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Typography } from '@mui/material';
import { useState } from 'react';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { SymbolNameWithUsageTooltip } from '../components/SymbolNameWithUsageTooltip';
import { PLCProgram } from '../data/PLCProgram';
import { PLCProgramType } from '../data/PLCUtilities';
import { M94M95Trigger } from '../data/triggers/M94M95Trigger';
import { M94M95TriggerDialog } from './M94M95TriggerDialog';

interface M94M95TriggersTabProps {
    programType: PLCProgramType;
}

/**
 * M94/M95 Triggers Tab - Configuration for M-code triggered outputs
 * M94: Turn on output
 * M95: Turn off output
 */
export function M94M95TriggersTab({ programType }: M94M95TriggersTabProps): React.ReactElement {
    const [dialogOpen, setDialogOpen] = useState(false);
    const [editingTrigger, setEditingTrigger] = useState<M94M95Trigger | null>(null);
    const config = ConfigurationData.Instance;
    const colors = ConfigurationDataColors.Instance;

    // Get the correct program based on the passed programType
    const program = PLCProgram.Instance(programType);

    const handleAdd = () => {
        setEditingTrigger(null);
        setDialogOpen(true);
    };

    const handleEdit = (trigger: M94M95Trigger) => {
        setEditingTrigger(trigger);
        setDialogOpen(true);
    };

    const handleDelete = (trigger: M94M95Trigger) => {
        program.removeM94M95Trigger(trigger);
    };

    const handleDialogClose = () => {
        setDialogOpen(false);
        setEditingTrigger(null);
    };

    const handleDialogSave = (trigger: M94M95Trigger) => {
        if (editingTrigger) {
            program.updateM94M95Trigger(editingTrigger, trigger);
        } else {
            program.addM94M95Trigger(trigger);
        }
        handleDialogClose();
    };

    return (
        <ObserveState
            key="m94m95-triggers-tab"
            listenTo={program}
            properties={['m94m95Triggers']}
            control={() => (
                <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column', gap: 2 }}>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <Typography variant="h5">
                            M94/M95 Output Triggers
                        </Typography>
                        <Button
                            variant="contained"
                            startIcon={<AddIcon />}
                            onClick={handleAdd}
                            sx={{
                                backgroundColor: colors.primaryColor,
                                '&:hover': {
                                    backgroundColor: colors.primaryColor,
                                    opacity: 0.9,
                                },
                            }}
                        >
                            Add Trigger
                        </Button>
                    </Box>

                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                        <Typography variant="body2" color="textSecondary">
                            Configure M94/M95 G-code commands to control outputs during program execution.
                        </Typography>
                        <Box sx={{ display: 'flex', gap: 3 }}>
                            <Typography variant="body2" color="textSecondary">
                                <strong>M94/##</strong> - Turn on output(s) mapped to trigger ##
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                                <strong>M95/##</strong> - Turn off output(s) mapped to trigger ##
                            </Typography>
                        </Box>
                    </Box>

                    <TableContainer component={Paper} sx={{ flex: 1 }}>
                        <Table stickyHeader>
                            <TableHead>
                                <TableRow>
                                    <TableCell sx={{ fontWeight: 600 }}>Name</TableCell>
                                    <TableCell sx={{ fontWeight: 600 }}>Trigger #</TableCell>
                                    <TableCell sx={{ fontWeight: 600 }}>ON Command</TableCell>
                                    <TableCell sx={{ fontWeight: 600 }}>OFF Command</TableCell>
                                    <TableCell sx={{ fontWeight: 600 }}>Outputs</TableCell>
                                    <TableCell sx={{ fontWeight: 600 }}>Description</TableCell>
                                    <TableCell sx={{ fontWeight: 600 }} align="right">Actions</TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {program.m94m95Triggers.length === 0 ? (
                                    <TableRow>
                                        <TableCell colSpan={7} align="center" sx={{ py: 4 }}>
                                            <Typography variant="body2" color="textSecondary">
                                                No M94/M95 triggers configured. Click "Add Trigger" to create one.
                                            </Typography>
                                        </TableCell>
                                    </TableRow>
                                ) : (
                                    program.m94m95Triggers.map((trigger, index) => (
                                        <TableRow key={index} hover>
                                            <TableCell>
                                                <SymbolNameWithUsageTooltip
                                                    centroidName={trigger.name || 'UNNAMED'}
                                                    programType={programType}
                                                >
                                                    <Typography variant="body2">
                                                        {trigger.name || '(Unnamed)'}
                                                    </Typography>
                                                </SymbolNameWithUsageTooltip>
                                            </TableCell>
                                            <TableCell>
                                                <Chip
                                                    label={trigger.number}
                                                    size="small"
                                                    sx={{
                                                        fontFamily: 'monospace',
                                                        backgroundColor: colors.lightBackgroundColor,
                                                        border: `1px solid ${colors.borderColor}`,
                                                    }}
                                                />
                                            </TableCell>
                                            <TableCell>
                                                <Chip
                                                    label={trigger.getM94Command()}
                                                    size="small"
                                                    sx={{
                                                        fontFamily: 'monospace',
                                                        backgroundColor: colors.lightBackgroundColor,
                                                        border: `1px solid ${colors.borderColor}`,
                                                    }}
                                                />
                                            </TableCell>
                                            <TableCell>
                                                <Chip
                                                    label={trigger.getM95Command()}
                                                    size="small"
                                                    sx={{
                                                        fontFamily: 'monospace',
                                                        backgroundColor: colors.lightBackgroundColor,
                                                        border: `1px solid ${colors.borderColor}`,
                                                    }}
                                                />
                                            </TableCell>
                                            <TableCell>
                                                {trigger.outputs.length === 0 ? (
                                                    <Typography variant="body2" color="textSecondary" fontStyle="italic">
                                                        No outputs
                                                    </Typography>
                                                ) : (
                                                    <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap' }}>
                                                        {trigger.outputs.map((output, idx) => (
                                                            <Chip
                                                                key={idx}
                                                                label={output}
                                                                size="small"
                                                                variant="outlined"
                                                            />
                                                        ))}
                                                    </Box>
                                                )}
                                            </TableCell>
                                            <TableCell>{trigger.description || '-'}</TableCell>
                                            <TableCell align="right">
                                                <IconButton
                                                    size="small"
                                                    onClick={() => handleEdit(trigger)}
                                                    sx={{ mr: 1 }}
                                                >
                                                    <EditIcon fontSize="small" />
                                                </IconButton>
                                                <IconButton
                                                    size="small"
                                                    onClick={() => handleDelete(trigger)}
                                                    color="error"
                                                >
                                                    <DeleteIcon fontSize="small" />
                                                </IconButton>
                                            </TableCell>
                                        </TableRow>
                                    ))
                                )}
                            </TableBody>
                        </Table>
                    </TableContainer>

                    <M94M95TriggerDialog
                        open={dialogOpen}
                        trigger={editingTrigger}
                        program={program}
                        onClose={handleDialogClose}
                        onSave={handleDialogSave}
                    />
                </Box>
            )}
        />
    );
}
