import { Close as CloseIcon, Warning as WarningIcon } from '@mui/icons-material';
import {
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    List,
    ListItem,
    ListItemText,
    Typography
} from '@mui/material';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { PLCValidationIssue } from '../data/IPLCElement';

interface ValidationConfirmDialogProps {
    open: boolean;
    onClose: () => void;
    onConfirm: () => void;
    issues: PLCValidationIssue[];
    action: 'compile' | 'install';
}

/**
 * Dialog for confirming compilation/installation when validation issues exist
 * Shows a list of validation issues with their location (stage/block)
 */
export function ValidationConfirmDialog({
    open,
    onClose,
    onConfirm,
    issues,
    action
}: ValidationConfirmDialogProps) {
    const colors = ConfigurationDataColors.Instance;

    /**
     * Get human-readable location for a validation issue
     */
    const getIssueLocation = (issue: PLCValidationIssue): string => {
        const element = issue.element;
        const elementType = element.getElementType();

        if (elementType === 'program') {
            // Get program name from the element
            const programType = (element as any).getProgramType?.() || 'Unknown';
            return programType === 0 ? 'System Default PLC' : 'System PLC';
        }

        if (elementType === 'stage') {
            const stageName = (element as any).name || 'Unknown Stage';
            return `Stage: ${stageName}`;
        }

        if (elementType === 'block') {
            const blockName = (element as any).name || 'Unknown Block';
            const parent = element.getParentElement();
            const stageName = parent && 'name' in parent ? (parent as any).name : 'Unknown Stage';
            return `Stage: ${stageName} → Block: ${blockName}`;
        }

        if (elementType === 'statement') {
            const statement = element as any;
            const statementType = statement.constructor?.name || 'Statement';

            // Walk up to find block and stage
            let currentParent = element.getParentElement();
            let blockName = 'Unknown Block';
            let stageName = 'Unknown Stage';

            if (currentParent && currentParent.getElementType() === 'block') {
                blockName = (currentParent as any).name || 'Unknown Block';
                const stageParent = currentParent.getParentElement();
                if (stageParent && 'name' in stageParent) {
                    stageName = (stageParent as any).name || 'Unknown Stage';
                }
            }

            return `Stage: ${stageName} → Block: ${blockName} → ${statementType}`;
        }

        return 'Unknown Location';
    };

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth="md"
            fullWidth
        >
            <DialogTitle
                sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    backgroundColor: colors.primaryColor,
                    color: colors.lightTextColor,
                    py: 2,
                    px: 3
                }}
            >
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                    <WarningIcon fontSize="large" />
                    <Typography variant="h6">
                        Validation Issues Found
                    </Typography>
                </Box>
                <IconButton
                    onClick={onClose}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>
            <DialogContent>
                <Typography variant="body1" gutterBottom sx={{ mt: 3 }}>
                    The PLC programs have {issues.length} validation issue{issues.length !== 1 ? 's' : ''}.
                    Do you want to {action} anyway?
                </Typography>
                <Box sx={{ mt: 2 }}>
                    <List dense>
                        {issues.map((issue, index) => (
                            <ListItem
                                key={index}
                                sx={{
                                    borderLeft: `3px solid ${colors.borderColor}`,
                                    backgroundColor: `${colors.warningColor}0D`,
                                    mb: 1,
                                    borderRadius: 1
                                }}
                            >
                                <ListItemText
                                    primary={issue.message}
                                    secondary={getIssueLocation(issue)}
                                    primaryTypographyProps={{
                                        fontWeight: 500
                                    }}
                                    secondaryTypographyProps={{
                                        color: 'text.secondary',
                                        fontSize: '0.875rem'
                                    }}
                                />
                            </ListItem>
                        ))}
                    </List>
                </Box>
            </DialogContent>
            <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${colors.borderColor}` }}>
                <Button
                    onClick={onClose}
                    variant="outlined"
                >
                    Cancel
                </Button>
                <Button
                    onClick={() => {
                        onConfirm();
                        onClose();
                    }}
                    variant="contained"
                    sx={{
                        backgroundColor: colors.primaryColor,
                        '&:hover': {
                            backgroundColor: colors.primaryColor,
                            opacity: 0.9
                        }
                    }}
                >
                    {action === 'compile' ? 'Compile Anyway' : 'Install Anyway'}
                </Button>
            </DialogActions>
        </Dialog>
    );
}
