import { Tool } from "../../../data/Common/Tool";
import { Wizard } from "../../Wizard/Wizard";
import { WizardManager } from "../../Wizard/WizardManager";
import { MoveToChangeLocationStep } from "./steps/MoveToChangeLocationStep";

export interface ChangeToolWizardState {
    oldTool: Tool | null;
    newTool: Tool | null;
    isSameSpecification: boolean | null; // null = not yet answered
}

export class ChangeToolWizard extends Wizard<ChangeToolWizardState> {
    constructor(currentTool: Tool | null) {
        const initialState: ChangeToolWizardState = {
            oldTool: currentTool,
            newTool: null,
            isSameSpecification: null
        };

        super(
            null as any, // Temporary - will be set below
            initialState,
            true, // canClose
            false, // clickAwayClose - don't allow accidental closure during operation
            '80%', // width
            '85%'  // height
        );

        // Create the first step with proper wizard reference
        const firstStep = new MoveToChangeLocationStep(this, currentTool, null);
        this.firstStep = firstStep;
        this.currentStep = firstStep;
    }

    /**
     * Show the change tool wizard
     */
    static show(currentTool: Tool | null): void {
        const wizard = new ChangeToolWizard(currentTool);
        WizardManager.Instance.start(wizard);
    }
}
