import { IStorable } from '../../common/IStorable';
import { CameraTarget, CNCViewType } from '../../components/MachineViewer/CNCViewer';
import { StateManager } from '../../utils/statemanager/StateManager';
import { SimulatorView } from './SimulatorView';
import { ViewStyle } from './ViewStyle';

/**
 * Manages simulator views for each perspective type (Perspective, Side, Top, Front)
 * Each view type has its own SimulatorView with independent settings
 */
export class SimulatorViewData implements IStorable {
    private _currentViewType: CNCViewType = CNCViewType.Perspective;
    private _cameraTargetMode: CameraTarget = CameraTarget.MachineCenter;
    private _perspectiveView: SimulatorView;
    private _sideView: SimulatorView;
    private _topView: SimulatorView;
    private _frontView: SimulatorView;

    // Viewer behavior properties
    private _showViewTypeButtons: boolean = false;
    private _showSettingsButton: boolean = false;
    private _enableOrbit: boolean = true;
    private _enableClampDragging: boolean = false;
    private _enableSpindleDrag: boolean = false;
    private _isHardcodedSettings: boolean = true;
    private _shareVisibilitySettings: boolean = true;

    // View change counter - incremented when view type changes to trigger re-renders
    // This is NOT persisted - just used for reactivity
    private _viewChangeCounter: number = 0;

    constructor() {
        // Initialize each view with appropriate defaults
        this._perspectiveView = new SimulatorView();

        this._sideView = new SimulatorView();

        this._topView = new SimulatorView();
        // Top view optimized for workpiece viewing
        this._topView.gantry = ViewStyle.SemiTransparent;
        this._topView.base = ViewStyle.Hide;

        this._frontView = new SimulatorView();

        // Register listeners on sub-objects to propagate state changes
        this.registerSubObjectListeners();
    }

    public get currentViewType(): CNCViewType {
        return this._currentViewType;
    }

    public set currentViewType(value: CNCViewType) {
        this._currentViewType = value;
        this._viewChangeCounter++; // Increment counter to trigger re-renders
        StateManager.propertyChanged(this, 'currentViewType');
        StateManager.propertyChanged(this, 'viewChangeCounter');
    }

    public get viewChangeCounter(): number {
        return this._viewChangeCounter;
    }

    public get cameraTargetMode(): CameraTarget {
        return this._cameraTargetMode;
    }

    public set cameraTargetMode(value: CameraTarget) {
        this._cameraTargetMode = value;
        StateManager.propertyChanged(this, 'cameraTargetMode');
    }

    /**
     * Get the SimulatorView for a specific view type
     */
    public getViewForType(viewType: CNCViewType): SimulatorView {
        switch (viewType) {
            case CNCViewType.Perspective:
                return this._perspectiveView;
            case CNCViewType.Side:
                return this._sideView;
            case CNCViewType.Top:
                return this._topView;
            case CNCViewType.Front:
                return this._frontView;
            default:
                return this._perspectiveView;
        }
    }

    /**
     * Get the current active SimulatorView based on currentViewType
     */
    public getCurrentView(): SimulatorView {
        return this.getViewForType(this._currentViewType);
    }

    public get perspectiveView(): SimulatorView {
        return this._perspectiveView;
    }

    public get sideView(): SimulatorView {
        return this._sideView;
    }

    public get topView(): SimulatorView {
        return this._topView;
    }

    public get frontView(): SimulatorView {
        return this._frontView;
    }

    // Viewer behavior properties

    public get showViewTypeButtons(): boolean {
        return this._showViewTypeButtons;
    }

    public set showViewTypeButtons(value: boolean) {
        this._showViewTypeButtons = value;
        StateManager.propertyChanged(this, 'showViewTypeButtons');
    }

    public get showSettingsButton(): boolean {
        return this._showSettingsButton;
    }

    public set showSettingsButton(value: boolean) {
        this._showSettingsButton = value;
        StateManager.propertyChanged(this, 'showSettingsButton');
    }

    public get enableOrbit(): boolean {
        return this._enableOrbit;
    }

    public set enableOrbit(value: boolean) {
        this._enableOrbit = value;
        StateManager.propertyChanged(this, 'enableOrbit');
    }

    public get enableClampDragging(): boolean {
        return this._enableClampDragging;
    }

    public set enableClampDragging(value: boolean) {
        this._enableClampDragging = value;
        StateManager.propertyChanged(this, 'enableClampDragging');
    }

    public get enableSpindleDrag(): boolean {
        return this._enableSpindleDrag;
    }

    public set enableSpindleDrag(value: boolean) {
        this._enableSpindleDrag = value;
        StateManager.propertyChanged(this, 'enableSpindleDrag');
    }

    public get isHardcodedSettings(): boolean {
        return this._isHardcodedSettings;
    }

    public set isHardcodedSettings(value: boolean) {
        this._isHardcodedSettings = value;
        StateManager.propertyChanged(this, 'isHardcodedSettings');
    }

    public get shareVisibilitySettings(): boolean {
        return this._shareVisibilitySettings;
    }

    public set shareVisibilitySettings(value: boolean) {
        this._shareVisibilitySettings = value;
        StateManager.propertyChanged(this, 'shareVisibilitySettings');
    }

    /**
     * Copy visibility settings from one view to another
     * Used when shareVisibilitySettings is enabled to synchronize settings across perspectives
     * @param sourceView The view to copy settings from
     * @param targetView The view to copy settings to
     */
    public copyVisibilitySettings(sourceView: SimulatorView, targetView: SimulatorView): void {
        targetView.workHome = sourceView.workHome;
        targetView.toolpaths = sourceView.toolpaths;
        targetView.dryRunToolpaths = sourceView.dryRunToolpaths;
        targetView.softLimits = sourceView.softLimits;
        targetView.machineZero = sourceView.machineZero;
        targetView.machineHome = sourceView.machineHome;
        targetView.material = sourceView.material;
        targetView.gantry = sourceView.gantry;
        targetView.base = sourceView.base;
        targetView.bed = sourceView.bed;
        targetView.railing = sourceView.railing;
        targetView.spindle = sourceView.spindle;
        targetView.workPiece = sourceView.workPiece;
        targetView.spoilBoard = sourceView.spoilBoard;
        targetView.clamps = sourceView.clamps;
        targetView.tool = sourceView.tool;
        targetView.rotary = sourceView.rotary;
        targetView.verticalTable = sourceView.verticalTable;
        targetView.laser = sourceView.laser;
        targetView.laserPointer = sourceView.laserPointer;
        targetView.drillHead = sourceView.drillHead;
        targetView.atc = sourceView.atc;
    }

    /**
     * Register listeners on sub-objects to trigger SimulatorViewData change notifications
     * This ensures that when SimulatorView properties change, the parent SimulatorViewData is notified
     */
    private registerSubObjectListeners(): void {
        // Register listener for each view to propagate changes
        StateManager.addObserver(this._perspectiveView, () => {
            StateManager.propertyChanged(this, 'perspectiveView');
        }, [], 'SimulatorViewData-PerspectiveView');

        StateManager.addObserver(this._sideView, () => {
            StateManager.propertyChanged(this, 'sideView');
        }, [], 'SimulatorViewData-SideView');

        StateManager.addObserver(this._topView, () => {
            StateManager.propertyChanged(this, 'topView');
        }, [], 'SimulatorViewData-TopView');

        StateManager.addObserver(this._frontView, () => {
            StateManager.propertyChanged(this, 'frontView');
        }, [], 'SimulatorViewData-FrontView');
    }

    /**
     * Unregister listeners on sub-objects before they are replaced during fromJSON
     */
    private unregisterSubObjectListeners(): void {
        StateManager.removeObserverByName(this._perspectiveView, 'SimulatorViewData-PerspectiveView');
        StateManager.removeObserverByName(this._sideView, 'SimulatorViewData-SideView');
        StateManager.removeObserverByName(this._topView, 'SimulatorViewData-TopView');
        StateManager.removeObserverByName(this._frontView, 'SimulatorViewData-FrontView');
    }

    public toJSON(): object {
        // Only save camera and visibility settings
        // Behavior properties (showViewTypeButtons, enableOrbit, etc.) are NOT saved
        // They are always determined by the factory
        return {
            currentViewType: this._currentViewType,
            cameraTargetMode: this._cameraTargetMode,
            perspectiveView: this._perspectiveView.toJSON(),
            sideView: this._sideView.toJSON(),
            topView: this._topView.toJSON(),
            frontView: this._frontView.toJSON()
        };
    }

    public fromJSON(data: any): void {
        // Unregister old listeners before loading data
        this.unregisterSubObjectListeners();

        if (data.currentViewType !== undefined) {
            this._currentViewType = data.currentViewType;
        }
        if (data.cameraTargetMode !== undefined) {
            this._cameraTargetMode = data.cameraTargetMode;
        }
        if (data.perspectiveView) {
            this._perspectiveView.fromJSON(data.perspectiveView);
        }
        if (data.sideView) {
            this._sideView.fromJSON(data.sideView);
        }
        if (data.topView) {
            this._topView.fromJSON(data.topView);
        }
        if (data.frontView) {
            this._frontView.fromJSON(data.frontView);
        }

        // Re-register listeners after loading
        this.registerSubObjectListeners();
    }
}
