import { PanTool as ManualIcon, TouchApp as TouchplateIcon } from '@mui/icons-material';
import { Box, Card, CardActionArea, CardContent, Grid, Typography } from '@mui/material';
import React from 'react';
import { Tool } from '../../../../data/Common/Tool';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { WizardStep } from '../../../Wizard/WizardStep';
import { ToolMeasurementMethod, ToolMeasurementWizard } from '../ToolMeasurementWizard';
import { ConfirmTouchplateStep } from './ConfirmTouchplateStep';
import { ManualJogStep } from './ManualJogStep';

/**
 * Step to select between touchplate and manual measurement
 */
export class SelectTouchplateOrManualStep extends WizardStep {
    private tool: Tool;
    private method: ToolMeasurementMethod;

    constructor(wizard: ToolMeasurementWizard, tool: Tool, previousStep: WizardStep | null, method: ToolMeasurementMethod) {
        super(wizard, previousStep);
        this.tool = tool;
        this.method = method;
    }

    getTitle(): string {
        return 'Select Measurement Method';
    }

    nextStep(): WizardStep | null {
        // Will be set dynamically based on selection
        return null;
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return <SelectTouchplateOrManualStepComponent step={this} />;
    }
}

interface SelectTouchplateOrManualStepComponentProps {
    step: SelectTouchplateOrManualStep;
}

function SelectTouchplateOrManualStepComponent({ step }: SelectTouchplateOrManualStepComponentProps) {
    const wizard = step.wizard as ToolMeasurementWizard;
    const colors = ConfigurationDataColors.Instance;

    const handleTouchplateSelect = () => {
        const nextStep = new ConfirmTouchplateStep(wizard, step['tool'], step, step['method']);
        wizard.currentStep = nextStep;
        StateManager.propertyChanged(wizard, 'currentStep');
    };

    const handleManualSelect = () => {
        const nextStep = new ManualJogStep(wizard, step['tool'], step, step['method']);
        wizard.currentStep = nextStep;
        StateManager.propertyChanged(wizard, 'currentStep');
    };

    return (
        <Box sx={{ p: 3 }}>
            <Typography variant="body1" sx={{ mb: 3, color: 'text.secondary' }}>
                Choose how you want to measure the tool:
            </Typography>

            <Grid container spacing={3}>
                <Grid item xs={12} sm={6}>
                    <Card
                        sx={{
                            height: '100%',
                            border: `2px solid ${colors.borderColor}`,
                            transition: 'all 0.2s ease-in-out',
                            '&:hover': {
                                boxShadow: 3,
                                borderColor: colors.primaryColor
                            }
                        }}
                    >
                        <CardActionArea
                            onClick={handleTouchplateSelect}
                            sx={{ height: '100%', p: 3 }}
                        >
                            <CardContent sx={{ textAlign: 'center' }}>
                                <TouchplateIcon sx={{ fontSize: 80, color: colors.primaryColor, mb: 2 }} />
                                <Typography variant="h5" gutterBottom>
                                    Use Touchplate
                                </Typography>
                                <Typography variant="body2" color="text.secondary">
                                    Automatically measure using the moveable touchplate
                                </Typography>
                            </CardContent>
                        </CardActionArea>
                    </Card>
                </Grid>

                <Grid item xs={12} sm={6}>
                    <Card
                        sx={{
                            height: '100%',
                            border: `2px solid ${colors.borderColor}`,
                            transition: 'all 0.2s ease-in-out',
                            '&:hover': {
                                boxShadow: 3,
                                borderColor: colors.secondaryColor
                            }
                        }}
                    >
                        <CardActionArea
                            onClick={handleManualSelect}
                            sx={{ height: '100%', p: 3 }}
                        >
                            <CardContent sx={{ textAlign: 'center' }}>
                                <ManualIcon sx={{ fontSize: 80, color: colors.secondaryColor, mb: 2 }} />
                                <Typography variant="h5" gutterBottom>
                                    Manual Measurement
                                </Typography>
                                <Typography variant="body2" color="text.secondary">
                                    Manually jog and measure the tool
                                </Typography>
                            </CardContent>
                        </CardActionArea>
                    </Card>
                </Grid>
            </Grid>
        </Box>
    );
}
