import { StateManager } from '../../utils/statemanager/StateManager';
import { MachineData } from '../Machine/MachineData';
import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Spindle Configuration Checklist Item
 * Automatic validation that spindle is configured (encoder enabled)
 */
export class SpindleConfigurationChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Spindle Configuration',
            'Verify spindle is configured with encoder or manual settings'
        );

        // Listen for changes to spindle configuration
        const machine = MachineData.Instance;
        StateManager.addObserver(machine, () => {
            StateManager.propertyChanged(this, 'manuallyConfirmed');
        }, ['spindleConfig']);

        // Also listen to the spindle config object itself
        StateManager.addObserver(machine.spindleConfig, () => {
            StateManager.propertyChanged(this, 'manuallyConfirmed');
        }, ['encoderEnabled']);
    }

    /**
     * This is an auto-validation item
     */
    public needsManualConfirmation(): boolean {
        return false;
    }

    /**
     * Validation check: Spindle encoder must be enabled (YES)
     */
    public completionCheck(): boolean {
        const machine = MachineData.Instance;

        // Check if encoder is enabled (YES)
        return machine.spindleConfig.encoderEnabled === true;
    }

    public clone(): SpindleConfigurationChecklistItem {
        const cloned = new SpindleConfigurationChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
