
import {
    Box,
    Paper,
    TextField,
    ToggleButton,
    ToggleButtonGroup,
    Typography,
} from '@mui/material';
import React, { useState } from 'react';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager';

/**
 * Laser Setup Tab - Laser PWM configuration settings
 */
export function LaserSetupTab(): React.ReactElement {
    const [machineData] = useState(() => MachineData.Instance);
    const colors = ConfigurationDataColors.Instance;
    const laserConfig = machineData.laserPWMConfig;

    return (
        <ObserveState
            key="laser-setup-tab"
            listenTo={laserConfig}
            properties={[
                'pwmEnabled',
                'frequency',
                'sCommandRange1000',
                'floor',
                'onlyApplyFloorDuringVelocityMoves',
                'inverseOutput',
                'laserCoolingFanDelayTimer'
            ]}
            control={() => (
                <Box sx={{ p: 3 }}>
                    <Typography variant="h5" gutterBottom>
                        Laser PWM Setup
                    </Typography>

                    <Paper elevation={2} sx={{ p: 3, mt: 2 }}>
                        {/* PWM Enable Toggle */}
                        <Box sx={{ display: 'flex', alignItems: 'center', mb: 3 }}>
                            <Typography sx={{ width: '250px', fontWeight: 500 }}>
                                PWM Enable
                            </Typography>
                            <Box sx={{ width: '330px' }}>
                                <ToggleButtonGroup
                                    value={laserConfig.pwmEnabled ? 'yes' : 'no'}
                                    exclusive
                                    onChange={(_, value) => {
                                        if (value !== null) {
                                            laserConfig.pwmEnabled = value === 'yes';
                                        }
                                    }}
                                    size="small"
                                >
                                    <ToggleButton
                                        value="yes"
                                        sx={{
                                            '&.Mui-selected': {
                                                backgroundColor: ConfigurationDataColors.Instance.successColor,
                                                color: colors.lightTextColor,
                                                '&:hover': { backgroundColor: ConfigurationDataColors.Instance.successColor }
                                            }
                                        }}
                                    >
                                        Yes
                                    </ToggleButton>
                                    <ToggleButton
                                        value="no"
                                        sx={{
                                            '&.Mui-selected': {
                                                backgroundColor: ConfigurationDataColors.Instance.errorColor,
                                                color: colors.lightTextColor,
                                                '&:hover': { backgroundColor: ConfigurationDataColors.Instance.errorColor }
                                            }
                                        }}
                                    >
                                        No
                                    </ToggleButton>
                                </ToggleButtonGroup>
                            </Box>
                        </Box>

                        {/* Conditional rendering - only show if PWM is enabled */}
                        {laserConfig.pwmEnabled && (
                            <>
                                {/* Base Frequency */}
                                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                                    <Typography sx={{ width: '250px', fontWeight: 500 }}>
                                        Base Frequency
                                    </Typography>
                                    <Box sx={{ width: '330px', display: 'flex', alignItems: 'center', gap: 1 }}>
                                        <TextField
                                            type="number"
                                            value={laserConfig.frequency ?? ''}
                                            onChange={(e) => {
                                                const val = parseFloat(e.target.value);
                                                laserConfig.frequency = isNaN(val) ? null : val;
                                            }}
                                            size="small"
                                            sx={{ flex: 1 }}
                                        />
                                        <Typography variant="body2" sx={{ minWidth: '30px' }}>
                                            Hz
                                        </Typography>
                                    </Box>
                                </Box>

                                {/* PWM S command range toggle */}
                                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                                    <Typography sx={{ width: '250px', fontWeight: 500 }}>
                                        PWM S command range
                                    </Typography>
                                    <Box sx={{ width: '330px' }}>
                                        <ToggleButtonGroup
                                            value={laserConfig.sCommandRange1000 ? '0-1000' : '0-100'}
                                            exclusive
                                            onChange={(_, value) => {
                                                if (value !== null) {
                                                    laserConfig.sCommandRange1000 = value === '0-1000';
                                                }
                                            }}
                                            size="small"
                                        >
                                            <ToggleButton
                                                value="0-1000"
                                                sx={{
                                                    '&.Mui-selected': {
                                                        backgroundColor: colors.primaryColor,
                                                        color: colors.lightTextColor
                                                    }
                                                }}
                                            >
                                                0-1000
                                            </ToggleButton>
                                            <ToggleButton
                                                value="0-100"
                                                sx={{
                                                    '&.Mui-selected': {
                                                        backgroundColor: colors.primaryColor,
                                                        color: colors.lightTextColor
                                                    }
                                                }}
                                            >
                                                0-100
                                            </ToggleButton>
                                        </ToggleButtonGroup>
                                    </Box>
                                </Box>

                                {/* Power Level Floor */}
                                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                                    <Typography sx={{ width: '250px', fontWeight: 500 }}>
                                        Power Level Floor
                                    </Typography>
                                    <Box sx={{ width: '330px', display: 'flex', alignItems: 'center', gap: 1 }}>
                                        <TextField
                                            type="number"
                                            value={laserConfig.floor ?? ''}
                                            onChange={(e) => {
                                                const val = parseFloat(e.target.value);
                                                laserConfig.floor = isNaN(val) ? null : val;
                                            }}
                                            size="small"
                                            sx={{ flex: 1 }}
                                        />
                                        <Typography variant="body2" sx={{ minWidth: '30px' }}>
                                            %
                                        </Typography>
                                    </Box>
                                </Box>

                                {/* Only Apply Floor During PWM Velocity Modulation Moves */}
                                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                                    <Typography sx={{ width: '250px', fontWeight: 500 }}>
                                        Only Apply Floor During PWM Velocity Modulation Moves
                                    </Typography>
                                    <Box sx={{ width: '330px' }}>
                                        <ToggleButtonGroup
                                            value={laserConfig.onlyApplyFloorDuringVelocityMoves ? 'yes' : 'no'}
                                            exclusive
                                            onChange={(_, value) => {
                                                if (value !== null) {
                                                    laserConfig.onlyApplyFloorDuringVelocityMoves = value === 'yes';
                                                }
                                            }}
                                            size="small"
                                        >
                                            <ToggleButton
                                                value="yes"
                                                sx={{
                                                    '&.Mui-selected': {
                                                        backgroundColor: ConfigurationDataColors.Instance.successColor,
                                                        color: colors.lightTextColor,
                                                        '&:hover': { backgroundColor: ConfigurationDataColors.Instance.successColor }
                                                    }
                                                }}
                                            >
                                                Yes
                                            </ToggleButton>
                                            <ToggleButton
                                                value="no"
                                                sx={{
                                                    '&.Mui-selected': {
                                                        backgroundColor: ConfigurationDataColors.Instance.errorColor,
                                                        color: colors.lightTextColor,
                                                        '&:hover': { backgroundColor: ConfigurationDataColors.Instance.errorColor }
                                                    }
                                                }}
                                            >
                                                No
                                            </ToggleButton>
                                        </ToggleButtonGroup>
                                    </Box>
                                </Box>

                                {/* Inverse Output */}
                                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                                    <Typography sx={{ width: '250px', fontWeight: 500 }}>
                                        Inverse Output
                                    </Typography>
                                    <Box sx={{ width: '330px' }}>
                                        <ToggleButtonGroup
                                            value={laserConfig.inverseOutput ? 'yes' : 'no'}
                                            exclusive
                                            onChange={(_, value) => {
                                                if (value !== null) {
                                                    laserConfig.inverseOutput = value === 'yes';
                                                }
                                            }}
                                            size="small"
                                        >
                                            <ToggleButton
                                                value="yes"
                                                sx={{
                                                    '&.Mui-selected': {
                                                        backgroundColor: ConfigurationDataColors.Instance.successColor,
                                                        color: colors.lightTextColor,
                                                        '&:hover': { backgroundColor: ConfigurationDataColors.Instance.successColor }
                                                    }
                                                }}
                                            >
                                                Yes
                                            </ToggleButton>
                                            <ToggleButton
                                                value="no"
                                                sx={{
                                                    '&.Mui-selected': {
                                                        backgroundColor: ConfigurationDataColors.Instance.errorColor,
                                                        color: colors.lightTextColor,
                                                        '&:hover': { backgroundColor: ConfigurationDataColors.Instance.errorColor }
                                                    }
                                                }}
                                            >
                                                No
                                            </ToggleButton>
                                        </ToggleButtonGroup>
                                    </Box>
                                </Box>

                                {/* Laser Cooling Fan Delay Timer */}
                                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                                    <Typography sx={{ width: '250px', fontWeight: 500 }}>
                                        Laser cooling fan delay timer
                                    </Typography>
                                    <Box sx={{ width: '330px', display: 'flex', alignItems: 'center', gap: 1 }}>
                                        <TextField
                                            type="number"
                                            value={laserConfig.laserCoolingFanDelayTimer ?? ''}
                                            onChange={(e) => {
                                                const val = parseFloat(e.target.value);
                                                laserConfig.laserCoolingFanDelayTimer = isNaN(val) ? null : val;
                                            }}
                                            size="small"
                                            sx={{ flex: 1 }}
                                        />
                                        <Typography variant="body2" sx={{ minWidth: '60px' }}>
                                            seconds
                                        </Typography>
                                    </Box>
                                </Box>
                            </>
                        )}
                    </Paper>
                </Box>
            )}
        />
    );
}
