import { Construction as SurfaceIcon } from '@mui/icons-material';
import { Box, Typography } from '@mui/material';
import React from 'react';
import { SurfaceSpoilboardWizard } from '../../components/wizards/surfacing/SurfaceSpoilboardWizard';
import { ConfigurationState } from '../../data/ConfigurationState';
import { IUserAction } from './IUserAction';

export class SurfaceSpoilboardUserAction implements IUserAction {
    public readonly id = 'machine_surface_spoilboard';
    public readonly category = 'Machine Actions';
    public readonly isDefaultHomeAction = false;

    public isAvailable(): boolean {
        const config = ConfigurationState.Instance;
        return config.isHomed && !config.isJobRunning;
    }

    public renderButton(asLink: boolean): React.ReactNode {
        if (asLink) {
            return (
                <React.Fragment>
                    <SurfaceIcon sx={{ fontSize: 18, color: 'primary.main' }} />
                    <Typography variant="body2" sx={{ color: 'inherit', fontWeight: 500 }}>
                        Surface Spoilboard
                    </Typography>
                </React.Fragment>
            );
        } else {
            return (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <SurfaceIcon />
                    <Typography>Surface Spoilboard</Typography>
                </Box>
            );
        }
    }

    public run(): void {
        SurfaceSpoilboardWizard.show();
    }
}
