import React from 'react';
import { ToolMeasurementWizard } from '../components/wizards/toolmeasurement/ToolMeasurementWizard';
import { CutterType, ToolMeasurementMode } from '../data/Common/Tool';
import { ToolLibrary } from '../data/Common/ToolLibrary';
import { ConfigurationState } from '../data/ConfigurationState';
import { MachineData } from '../data/Machine/MachineData';
import { MachineStateData } from '../data/MachineStateData';
import { UserMessageQueue } from '../data/UserMessageQueue';
import { ICNCSystem, MeasurementTarget, SkinEventAction, TouchOffTarget, TouchPlateType } from '../machine/ICNCSystem';
import type { IMachineCallback } from '../machine/IMachineCallback';
import { SystemStatus } from '../machine/Machine';
import { LogCategory, Logger } from '../utils/Logger';
import { ManualToolChangeHelper } from '../utils/ManualToolChangeHelper';

export class SimulatorCNCSystem implements ICNCSystem {

  /**
   * Helper to simulate a long-running operation with dialog
   */
  private async simulateOperation(title: string, message: string, durationMs: number = 2000, callback?: IMachineCallback): Promise<void> {
    const operation = ConfigurationState.Instance.startLongRunningOperation(title, message, durationMs, callback);

    // Wait for duration
    await new Promise(resolve => setTimeout(resolve, durationMs));

    ConfigurationState.Instance.completeLongRunningOperation();
  }

  async exit(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ System exit initiated');
  }

  async GetSystemStatus(): Promise<SystemStatus> {
    // Return simulated system status
    return {
      currentDateTime: new Date(),
      isCNCConnected: true, // Simulator is always "connected"
      status: 'Simulator mode - all systems operational'
    };
  }

  async shutdown(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ System shutdown initiated');
  }

  async restartCentroid(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Centroid system restarted');
  }

  async EmergencyStop(): Promise<void> {
    UserMessageQueue.Instance.addMessage('🚨 EMERGENCY STOP ACTIVATED');
  }

  async IsHomed(): Promise<boolean> {
    // Return homed state from ConfigurationState (runtime, not persisted)
    return ConfigurationState.Instance.isHomed;
  }

  async UnhomeMachine(): Promise<void> {
    ConfigurationState.Instance.isHomed = false;
    ConfigurationState.Instance.skipHoming = false; // Reset skip flag when unhoming
    UserMessageQueue.Instance.addMessage('✓ Machine unhomed');
  }

  async HomeMachine(callback?: IMachineCallback): Promise<void> {
    try {
      await this.simulateOperation('Homing Machine', 'Homing all axes...', 2000, callback);
      ConfigurationState.Instance.isHomed = true;
      ConfigurationState.Instance.skipHoming = false;
      MachineStateData.Instance.incrementSessionNumber();
      await this.MachineHomed();
      UserMessageQueue.Instance.addMessage('✓ Machine homing complete');
      await callback?.onComplete?.();
    } catch (error) {
      // Only call onError if it's NOT a cancellation (cancellation already called onCancel)
      const isCancellation = error instanceof Error && error.message.startsWith('Operation canceled:');
      if (!isCancellation && callback?.onError) {
        await callback.onError(error instanceof Error ? error : new Error(String(error)));
      }
      if (!isCancellation) {
        throw error;
      }
    }
  }

  async GetCurrentErrorState(): Promise<string[] | null> {
    // Simulator has no errors by default
    return null;
  }

  async HasCurrentErrors(): Promise<boolean> {
    return false;
  }

  async IsConnectedToServer(): Promise<boolean> {
    // Simulator is always connected
    return true;
  }

  // Skin event operations
  async TriggerSkinEvent(eventNumber: number, action: SkinEventAction = SkinEventAction.Click): Promise<void> {
    const actionName = ['Press', 'Release', 'Click', 'DoubleClick'][action];
    UserMessageQueue.Instance.addMessage(`✓ Skin event ${eventNumber} triggered (${actionName})`);
  }

  // Machine control operations
  async Stop(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Stop button triggered (SkinEvent 47)');
  }

  async CancelCycle(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Cycle cancelled (SkinEvent 46)');
  }

  async SetMachineHomed(isHomed: boolean): Promise<void> {
    // Update simulator homed state
    UserMessageQueue.Instance.addMessage(`✓ Machine homed state set to: ${isHomed}`);
  }

  async MachineHomed(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Machine marked as homed (SkinEvent 57 = 1)');
  }

  async MachineUnhomed(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Machine marked as unhomed (SkinEvent 57 = 0)');
  }

  async Reset(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Reset triggered (SkinEvent 56)');
  }

  async EnableSoftLimits(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Soft limits enabled');
  }

  async DisableSoftLimits(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Soft limits disabled');
  }

  async EStop(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ E-stop reset triggered (SkinEvent 56)');
  }

  // Tool management operations
  async dropTool(callback?: IMachineCallback): Promise<void> {
    await this.simulateOperation('Dropping Tool', 'Releasing tool into holder...');
    const machineState = MachineStateData.Instance;
    machineState.currentToolNumber = 0; // No tool loaded
    await machineState.manualSave(); // Save immediately - critical tool state
    UserMessageQueue.Instance.addMessage('✓ Tool dropped into holder');
    if (callback?.onComplete) {
      await callback.onComplete();
    }
  }

  async loadTool(toolNumber: number, callback?: IMachineCallback): Promise<void> {
    try {
      await this.simulateOperation('Loading Tool', `Loading tool ${toolNumber}...`);
      const machineState = MachineStateData.Instance;
      machineState.currentToolNumber = toolNumber;
      await machineState.manualSave(); // Save immediately - critical tool state

      // Check if tool has already been measured in this session
      const toolLibrary = ToolLibrary.Instance;
      const tool = toolLibrary.getToolByNumber(toolNumber);

      if (tool && !tool.needsMeasurement(machineState.sessionNumber)) {
        UserMessageQueue.Instance.addMessage(`✓ Tool ${toolNumber} loaded - already measured in this session`);

        // Tool already measured - invoke callback directly
        if (callback?.onComplete) {
          await callback.onComplete();
        }
      } else {
        UserMessageQueue.Instance.addMessage(`✓ Tool ${toolNumber} loaded, now measuring...`);

        // Chain to measurement with original callback
        await this.measureCurrentTool(callback);
      }
    } catch (error) {
      if (callback?.onError) {
        await callback.onError(error as Error);
      }
      throw error;
    }
  }

  async measureCurrentTool(callback?: IMachineCallback): Promise<void> {
    try {
      const machineState = MachineStateData.Instance;
      const machineData = MachineData.Instance;
      const { ConfigurationState } = require('../data/ConfigurationState');

      // Check if we should use Reset Z wizard instead of tool measurement
      // Only when job is actively running with resetZInsteadOfToolMeasure enabled
      const currentJob = ConfigurationState.Instance.currentJob;
      if (currentJob && currentJob.resetZInsteadOfToolMeasure && ConfigurationState.Instance.isJobRunning) {
        // Launch work zero wizard instead of measuring tool
        const { TouchOffWizard } = await import('../components/wizards/touchoff/TouchOffWizard');

        // Wait for wizard to complete using a Promise
        return new Promise<void>((resolve, reject) => {
          const wizard = TouchOffWizard.showForWorkZero();
          wizard.callback = {
            onComplete: async () => {
              if (callback?.onComplete) {
                await callback.onComplete();
              }
              resolve();
            },
            onCancel: async () => {
              const cancelError = new Error('Work zero measurement cancelled');
              if (callback?.onError) {
                await callback.onError(cancelError);
              }
              reject(cancelError);
            },
            onError: async (error: Error | string) => {
              if (callback?.onError) {
                await callback.onError(error as Error);
              }
              reject(error);
            }
          };
        });
      }

      const currentToolNumber = machineState.currentToolNumber;
      const currentTool = ToolLibrary.Instance.getToolByNumber(currentToolNumber);

      if (!currentTool) {
        const errorMessage = `No tool currently loaded (T${currentToolNumber})`;
        UserMessageQueue.Instance.addMessage(`❌ ${errorMessage}`);
        if (callback?.onError) {
          await callback.onError(new Error(errorMessage));
        }
        throw new Error(errorMessage);
      }

      // Check if we can auto-measure:
      // 1. Must have fixed touch plate configured
      // 2. Tool must allow automatic measurement
      const hasFixedTouchPlate = machineData.hasFixedTouchPlate;
      const isAutoMeasure = currentTool.measurementMode === ToolMeasurementMode.AutoMeasure;
      const isAutoMeasureConfirm = currentTool.measurementMode === ToolMeasurementMode.AutoMeasureConfirm;

      if (hasFixedTouchPlate && isAutoMeasure) {
        // Fully automatic - no confirmation needed
        await this.autoMeasureTool(TouchPlateType.Fixed, MeasurementTarget.FixedPosition, callback);
      } else if (hasFixedTouchPlate && isAutoMeasureConfirm) {
        // Auto-measure with confirmation - show info dialog then auto-measure
        return new Promise<void>((resolve, reject) => {
          const { ConfirmDialogManager } = require('../utils/ConfirmDialogManager');

          ConfirmDialogManager.Instance.showConfirm({
            title: 'Measuring Tool',
            message: `Measuring tool ${currentTool.displayName} using fixed touch plate.`,
            confirmText: 'OK',
            cancelText: undefined,
            severity: 'info'
          }).then(async (confirmed: boolean) => {
            if (confirmed) {
              try {
                await this.autoMeasureTool(TouchPlateType.Fixed, MeasurementTarget.FixedPosition, callback);
                resolve();
              } catch (error) {
                reject(error);
              }
            } else {
              const cancelError = new Error('Measurement canceled by user');
              if (callback?.onError) {
                await callback.onError(cancelError);
              }
              reject(cancelError);
            }
          });
        });
      } else {
        // Show full wizard - either no fixed touch plate OR tool requires manual measurement
        return new Promise<void>((resolve, reject) => {
          const wizardCallback: IMachineCallback = {
            onComplete: async () => {
              try {
                if (callback?.onComplete) {
                  await callback.onComplete();
                }
                resolve();
              } catch (error) {
                reject(error);
              }
            },
            onError: async (error: string | Error) => {
              try {
                if (callback?.onError) {
                  await callback.onError(error);
                }
                reject(error);
              } catch (err) {
                reject(err);
              }
            }
          };
          ToolMeasurementWizard.show(currentTool, wizardCallback);
        });
      }
    } catch (error) {
      if (callback?.onError) {
        await callback.onError(error as Error);
      }
      throw error;
    }
  }

  async autoMeasureTool(touchPlateType: TouchPlateType, target: MeasurementTarget = MeasurementTarget.FixedPosition, callback?: IMachineCallback): Promise<void> {
    try {
      const typeStr = touchPlateType === TouchPlateType.Fixed ? 'fixed' : 'movable';
      const targetStr = target === MeasurementTarget.FixedPosition ? 'fixed position' : target === MeasurementTarget.Spoilboard ? 'spoilboard' : 'machine bed';

      await this.simulateOperation('Auto Measuring Tool', `Measuring tool with ${typeStr} touch plate against ${targetStr}...`);

      const machineState = MachineStateData.Instance;
      const currentToolNumber = machineState.currentToolNumber;
      const currentTool = ToolLibrary.Instance.getToolByNumber(currentToolNumber);

      if (currentTool) {
        // Simulate measurement by updating tool's measured length and session
        // Use lengthBelowHolder as the simulated measured length (with slight variation)
        currentTool.measuredLength = currentTool.lengthBelowHolder * 0.999; // Simulate 0.1% measurement variance
        currentTool.lastMeasuredSessionNumber = machineState.sessionNumber;

        UserMessageQueue.Instance.addMessage(`✓ Tool ${currentToolNumber} measured successfully`);
      }

      if (callback?.onComplete) {
        await callback.onComplete();
      }
    } catch (error) {
      if (callback?.onError) {
        await callback.onError(error as Error);
      }
      throw error;
    }
  }

  async changeTool(toolNumber: number, callback?: IMachineCallback): Promise<void> {
    try {
      const machineState = MachineStateData.Instance;
      const machineData = MachineData.Instance;
      const currentToolNumber = machineState.currentToolNumber || 0;
      const toolLibrary = ToolLibrary.Instance;

      Logger.Instance.log(LogCategory.System, `Simulator changeTool: current=${currentToolNumber}, target=${toolNumber}`);

      // Check if target tool exists
      const targetTool = toolLibrary.getToolByNumber(toolNumber);
      if (!targetTool) {
        throw new Error(`Tool ${toolNumber} not found in tool library`);
      }

      // Check if requested tool is already loaded
      if (currentToolNumber === toolNumber && currentToolNumber !== 0) {
        Logger.Instance.log(LogCategory.System, `Tool ${toolNumber} already loaded, checking measurement`);
        // Check if tool needs measurement
        if (targetTool && !targetTool.needsMeasurement(MachineStateData.Instance.sessionNumber)) {
          Logger.Instance.log(LogCategory.System, `Tool ${toolNumber} already measured, completing immediately`);
          if (callback?.onComplete) {
            await callback.onComplete();
          }
          return;
        } else {
          Logger.Instance.log(LogCategory.System, `Tool ${toolNumber} needs measurement, launching wizard`);
          await this.measureCurrentTool(callback);
          return;
        }
      }

      // Determine if current and target tools are manual
      const currentTool = currentToolNumber ? toolLibrary.getToolByNumber(currentToolNumber) : null;

      let isCurrentManual: boolean;
      let isTargetManual: boolean;

      if (!machineData.hasATC) {
        // No ATC system - all tools are manual
        isCurrentManual = currentToolNumber > 0;
        isTargetManual = true;
        Logger.Instance.log(LogCategory.System, `Simulator: Machine has no ATC - treating all tools as manual`);
      } else {
        // ATC system exists - check tool types and ATC slots
        const currentToolHolder = currentToolNumber ? machineData.atcToolClamps.find(tc => tc.clampNumber === currentToolNumber) : null;
        const targetToolHolder = machineData.atcToolClamps.find(tc => tc.clampNumber === toolNumber);

        isCurrentManual = currentTool ? (currentTool.cutterType === CutterType.Manual || !currentToolHolder) : false;
        isTargetManual = targetTool.cutterType === CutterType.Manual || !targetToolHolder;
      }

      Logger.Instance.log(LogCategory.System, `Simulator: Tool change analysis: hasATC=${machineData.hasATC}, current manual=${isCurrentManual}, target manual=${isTargetManual}`);

      // Special case: Both tools are manual - use combined dialog flow
      if (currentToolNumber && isCurrentManual && isTargetManual) {
        Logger.Instance.log(LogCategory.System, `Simulator: Both tools manual - using combined dialog flow`);
        await this.changeToolBothManual(currentToolNumber, currentTool!.displayName, toolNumber, targetTool.displayName, callback);
        return;
      }

      // Special case: Loading manual tool from empty spindle
      if (!currentToolNumber && isTargetManual) {
        Logger.Instance.log(LogCategory.System, `Simulator: Loading manual tool from empty spindle`);
        await this.loadManualTool(toolNumber, targetTool.displayName, callback);
        return;
      }

      // Mixed or ATC tools - use standard drop/load flow with callback chaining
      Logger.Instance.log(LogCategory.System, `Simulator: Using standard drop/load flow`);

      // Helper function to load and measure tool (called after successful drop)
      const loadAndMeasureTool = async () => {
        try {
          // Load new tool
          if (isTargetManual) {
            // Manual tool - show load dialog (no long running operation)
            Logger.Instance.log(LogCategory.System, `Simulator: Loading manual tool T${toolNumber}`);

            try {
              await ManualToolChangeHelper.showDialog(toolNumber, targetTool.displayName);
            } catch (error) {
              // User cancelled the dialog
              if (callback?.onError) {
                await callback.onError(error as Error);
              }
              return;
            }
          } else {
            // ATC tool - start long running operation with duration for simulator countdown
            ConfigurationState.Instance.startLongRunningOperation(
              'Changing Tool',
              `Loading tool ${toolNumber}...`,
              2000, // 2 second duration for simulator
              {
                onComplete: async () => {
                  // Load complete callback - close dialog and proceed
                  ConfigurationState.Instance.completeLongRunningOperation();

                  machineState.currentToolNumber = toolNumber;
                  await machineState.manualSave();

                  // Check if tool needs measurement
                  if (targetTool && targetTool.needsMeasurement(machineState.sessionNumber)) {
                    // Measure the new tool
                    await this.measureCurrentTool(callback);
                  } else {
                    // Tool doesn't need measurement - notify success
                    UserMessageQueue.Instance.addMessage(`✓ Changed to tool ${toolNumber}`);
                    if (callback?.onComplete) {
                      await callback.onComplete();
                    }
                  }
                },
                onCancel: async () => {
                  // Cancel callback - call CancelCycle, close dialog, propagate error
                  await this.CancelCycle();
                  ConfigurationState.Instance.completeLongRunningOperation();
                  if (callback?.onError) {
                    await callback.onError(new Error('Operation canceled'));
                  }
                }
              }
            );

            // Return immediately - dialog handles the countdown and callback invocation
            return;
          }
        } catch (error) {
          Logger.Instance.logError(LogCategory.System, 'Failed during load/measure:', error);
          if (callback?.onError) {
            await callback.onError(error as Error);
          }
        }
      };

      // Drop current tool if one is loaded
      if (machineState.currentToolNumber !== 0) {
        if (isCurrentManual) {
          // Manual tool - show drop dialog
          Logger.Instance.log(LogCategory.System, `Simulator: Dropping manual tool T${currentToolNumber}`);

          try {
            await ManualToolChangeHelper.showDropDialog(currentToolNumber, currentTool!.displayName);
          } catch (error) {
            // User cancelled the dialog - don't proceed to load
            if (callback?.onError) {
              await callback.onError(error as Error);
            }
            return;
          }

          machineState.currentToolNumber = 0;
          await machineState.manualSave();

          // Drop successful, proceed to load
          await loadAndMeasureTool();
        } else {
          // ATC tool - start long running operation with duration for simulator countdown
          ConfigurationState.Instance.startLongRunningOperation(
            'Changing Tool',
            'Dropping current tool...',
            2000, // 2 second duration for simulator
            {
              onComplete: async () => {
                // Drop complete callback - close dialog and proceed to load
                ConfigurationState.Instance.completeLongRunningOperation();

                // Drop completed successfully
                machineState.currentToolNumber = 0;
                await machineState.manualSave();

                // Drop successful, proceed to load
                await loadAndMeasureTool();
              },
              onCancel: async () => {
                // Cancel callback - call CancelCycle, close dialog, propagate error
                await this.CancelCycle();
                ConfigurationState.Instance.completeLongRunningOperation();
                if (callback?.onError) {
                  await callback.onError(new Error('Operation canceled'));
                }
              }
            }
          );
        }
      } else {
        // No tool to drop, go straight to load
        await loadAndMeasureTool();
      }
    } catch (error) {
      ConfigurationState.Instance.completeLongRunningOperation();
      if (callback?.onError) {
        await callback.onError(error as Error);
      }
      throw error;
    }
  }

  private async changeToolBothManual(
    currentToolNumber: number,
    currentToolName: string,
    targetToolNumber: number,
    targetToolName: string,
    callback?: IMachineCallback
  ): Promise<void> {
    try {
      const machineState = MachineStateData.Instance;
      const toolLibrary = ToolLibrary.Instance;
      const targetTool = toolLibrary.getToolByNumber(targetToolNumber);

      Logger.Instance.log(LogCategory.System, `Simulator: Combined manual tool change from T${currentToolNumber} to T${targetToolNumber}`);

      // Show combined manual tool change dialog (no long running operation for manual tools)
      try {
        await ManualToolChangeHelper.showCombinedDialog(
          currentToolNumber,
          currentToolName,
          targetToolNumber,
          targetToolName
        );
      } catch (error) {
        // User cancelled the dialog
        if (callback?.onError) {
          await callback.onError(error as Error);
        }
        return;
      }

      // Update current tool number
      machineState.currentToolNumber = targetToolNumber;
      await machineState.manualSave();

      // Chain to measurement with original callback
      await this.measureCurrentTool(callback);
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, `Simulator: Failed to change between manual tools:`, error);
      if (callback?.onError) {
        await callback.onError(error as Error);
      }
      throw error;
    }
  }

  private async loadManualTool(
    toolNumber: number,
    toolName: string,
    callback?: IMachineCallback
  ): Promise<void> {
    try {
      const machineState = MachineStateData.Instance;
      const toolLibrary = ToolLibrary.Instance;
      const targetTool = toolLibrary.getToolByNumber(toolNumber);

      Logger.Instance.log(LogCategory.System, `Simulator: Loading manual tool T${toolNumber}`);

      // Simulate moving to manual tool change position
      const operation = ConfigurationState.Instance.startLongRunningOperation(
        'Loading Tool',
        'Moving to manual tool change position...'
      );

      await new Promise(resolve => setTimeout(resolve, 2000));

      // Show manual tool load dialog (keep operation active so user can cancel)
      ConfigurationState.Instance.updateLongRunningOperationMessage(`Install T${toolNumber}...`);

      try {
        await ManualToolChangeHelper.showDialog(toolNumber, toolName);
      } catch (error) {
        // User cancelled the dialog
        ConfigurationState.Instance.completeLongRunningOperation();
        if (callback?.onError) {
          await callback.onError(error as Error);
        }
        return;
      }

      // Update current tool number
      machineState.currentToolNumber = toolNumber;
      await machineState.manualSave();

      // Chain to measurement with original callback
      await this.measureCurrentTool(callback);
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, `Simulator: Failed to load manual tool:`, error);
      if (callback?.onError) {
        await callback.onError(error as Error);
      }
      throw error;
    }
  }

  async getCurrentToolNumber(): Promise<number> {
    const machineState = MachineStateData.Instance;
    return machineState.currentToolNumber;
  }

  async checkTool(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Tool check complete');
  }

  async measureTools(callback?: IMachineCallback): Promise<void> {
    // Show dialog to select which tools to measure
    // The dialog will handle the actual measurement via measureToolsWithList
    const { ModalManager } = await import('../utils/ModalManager');
    const { MeasureToolsDialog } = await import('../components/MeasureToolsDialog');

    const modalId = 'measure-tools-dialog';
    ModalManager.Instance.showModal({
      id: modalId,
      render: () => React.createElement(MeasureToolsDialog, {
        open: true,
        onClose: () => ModalManager.Instance.closeModal(modalId),
        callback: callback
      })
    });
  }

  /**
   * Internal method to measure a list of tools
   * Called by MeasureToolsDialog after user selects tools
   */
  async measureToolsWithList(toolNumbers: number[]): Promise<void> {
    const toolLibrary = ToolLibrary.Instance;
    const machineState = MachineStateData.Instance;

    // Reset measurement session for all tools to ensure they get measured
    for (const toolNumber of toolNumbers) {
      const tool = toolLibrary.getToolByNumber(toolNumber);
      if (tool) {
        tool.lastMeasuredSessionNumber = 0; // Reset to force measurement
      }
    }

    await this.simulateOperation('Measuring Tools', `Measuring ${toolNumbers.length} tools...`);

    // Update last measured session for all tools
    for (const toolNumber of toolNumbers) {
      const tool = toolLibrary.getToolByNumber(toolNumber);
      if (tool) {
        tool.lastMeasuredSessionNumber = machineState.sessionNumber;
      }
    }

    UserMessageQueue.Instance.addMessage(`✓ Measured ${toolNumbers.length} tools`);
  }

  async touchOffMaterial(target?: TouchOffTarget, callback?: IMachineCallback): Promise<void> {
    // Handle tool measurement targets by calling measureCurrentTool
    if (target === TouchOffTarget.ToolMeasure || 
        target === TouchOffTarget.ToolMeasureSpoilboard || 
        target === TouchOffTarget.ToolMeasureMachineBed || 
        target === TouchOffTarget.ToolMeasureCurrentPosition) {
      // All tool measurement flows go through measureCurrentTool which launches the wizard
      // The wizard will handle method selection and measurement
      await this.measureCurrentTool(callback);
      return;
    }

    // Launch touch-off wizard for material coordinate system references
    const { TouchOffWizard } = await import('../components/wizards/touchoff/TouchOffWizard');
    
    if (target === TouchOffTarget.WorkZero) {
      TouchOffWizard.showForWorkZero(callback);
    } else if (target === TouchOffTarget.MaterialTop) {
      TouchOffWizard.showForMaterialTop(callback);
    } else if (target === TouchOffTarget.MaterialTopAndWorkZero) {
      TouchOffWizard.showForMaterialTopAndWorkZero(callback);
    } else if (target === TouchOffTarget.SpoilBoard) {
      TouchOffWizard.showForSpoilboard(callback);
    } else if (target === TouchOffTarget.SpoilBoardAndWorkZero) {
      TouchOffWizard.showForSpoilboardAndWorkZero(callback);
    } else if (target === TouchOffTarget.MachineBed) {
      TouchOffWizard.showForMachineBed(callback);
    } else {
      // No target specified - show wizard with selection page
      TouchOffWizard.show(callback);
    }
  }

  async probeAndSetMaterialReference(target: TouchOffTarget, callback?: IMachineCallback): Promise<void> {
    try {
      // Get movable touch plate configuration
      const touchPlateHeight = MachineData.Instance.movableTouchPlateHeight;

      // Simulate probing delay
      await this.simulateOperation('Probing', 'Probing surface with touch plate...');

      // Get current position and simulate touch-off
      const currentPosition = ConfigurationState.Instance.currentMachinePoint;
      const measuredZ = currentPosition.z;

      // Calculate actual surface position
      const actualSurfaceToolTipZ = measuredZ - touchPlateHeight;

      // Convert from tool tip to spindle position
      const { CoordinateUtil } = await import('../utils/CoordinateUtil');
      const toolOffset = CoordinateUtil.getCurrentOffsets();
      const actualSurfaceSpindleZ = actualSurfaceToolTipZ + toolOffset.z;

      // Set the appropriate reference
      const { CoordinateOperations } = await import('../utils/CoordinateOperations');
      
      if (target === TouchOffTarget.MachineBed) {
        CoordinateOperations.setMachineBedReferenceZ(actualSurfaceSpindleZ);
      } else if (target === TouchOffTarget.SpoilBoard) {
        CoordinateOperations.setSpoilboardReferenceZ(actualSurfaceSpindleZ, false);
      } else if (target === TouchOffTarget.SpoilBoardAndWorkZero) {
        CoordinateOperations.setSpoilboardReferenceZ(actualSurfaceSpindleZ, true);
      } else if (target === TouchOffTarget.MaterialTop) {
        CoordinateOperations.setMaterialTopReferenceZ(actualSurfaceSpindleZ);
      } else if (target === TouchOffTarget.MaterialTopAndWorkZero || target === TouchOffTarget.WorkZero) {
        CoordinateOperations.setMaterialTopReferenceZ(actualSurfaceSpindleZ);
        // MaterialTopAndWorkZero and WorkZero both set material top reference AND work zero
      }

      // Simulate retract
      await this.simulateOperation('Retracting', 'Moving to safe height...');

      if (callback?.onComplete) {
        await callback.onComplete();
      }
    } catch (error) {
      if (callback?.onError) {
        await callback.onError(error as Error);
      }
      throw error;
    }
  }
}
