import { IStorable } from "../../common/IStorable";
import { LogCategory, Logger } from "../../utils/Logger";
import { StateManager } from "../../utils/statemanager/StateManager";
import { ATCSetupChecklistItem } from "./ATCSetupChecklistItem";
import { AxisCalibrationChecklistItem } from "./AxisCalibrationChecklistItem";
import { AxisConfigurationChecklistItem } from "./AxisConfigurationChecklistItem";
import { FeedRateSpeedsChecklistItem } from "./FeedRateSpeedsChecklistItem";
import { FileMonitoringChecklistItem } from "./FileMonitoringChecklistItem";
import { FixedToolMeasurementPositionChecklistItem } from "./FixedToolMeasurementPositionChecklistItem";
import { FixedTouchPlatePositionChecklistItem } from "./FixedTouchPlatePositionChecklistItem";
import { HomingChecklistItem } from "./HomingChecklistItem";
import { InputsChecklistItem } from "./InputsChecklistItem";
import { MachineBedToolMeasurementPositionChecklistItem } from "./MachineBedToolMeasurementPositionChecklistItem";
import { MachineFeatureChecklistItem } from "./MachineFeatureChecklistItem";
import { MachineNameAndBoardChecklistItem } from "./MachineNameAndBoardChecklistItem";
import { MachineZeroChecklistItem } from "./MachineZeroChecklistItem";
import { ManualToolChangeChecklistItem } from "./ManualToolChangeChecklistItem";
import { MeasurementSetupChecklistItem } from "./MeasurementSetupChecklistItem";
import { MovableTouchPlateHeightChecklistItem } from "./MovableTouchPlateHeightChecklistItem";
import { OutputsChecklistItem } from "./OutputsChecklistItem";
import { SetupChecklistItem } from "./SetupChecklistItem";
import { SimulatorChecklistItem } from "./SimulatorChecklistItem";
import { SoftLimitsChecklistItem } from "./SoftLimitsChecklistItem";
import { SpindleConfigurationChecklistItem } from "./SpindleConfigurationChecklistItem";
import { SpoilBoardChecklistItem } from "./SpoilBoardChecklistItem";
import { SpoilboardToolMeasurementPositionChecklistItem } from "./SpoilboardToolMeasurementPositionChecklistItem";
import { TestModeOffChecklistItem } from "./TestModeOffChecklistItem";

/**
 * Library of setup checklist items
 * Singleton pattern for managing all setup checklist items
 */
export class SetupChecklistLibrary implements IStorable {
    private static _instance: SetupChecklistLibrary;
    private _items: SetupChecklistItem[] = [];

    private constructor() {
        // Private constructor for singleton
    }

    /**
     * Get the singleton instance
     */
    public static get Instance(): SetupChecklistLibrary {
        if (!SetupChecklistLibrary._instance) {
            SetupChecklistLibrary._instance = new SetupChecklistLibrary();
            // Ensure default items exist when instance is first created
            SetupChecklistLibrary._instance.ensureDefaultItemsExist();
        }
        return SetupChecklistLibrary._instance;
    }

    /**
     * Get all checklist items (filtered by shouldInclude)
     */
    public get items(): SetupChecklistItem[] {
        return this._items.filter(item => item.shouldInclude());
    }

    /**
     * Get all checklist items (unfiltered, including those that shouldn't be included)
     */
    public get allItems(): SetupChecklistItem[] {
        return [...this._items];
    }

    /**
     * Get all completed checklist items (filtered by shouldInclude)
     */
    public get completedItems(): SetupChecklistItem[] {
        return this._items.filter(item => item.shouldInclude() && item.isCompleted());
    }

    /**
     * Get all incomplete checklist items (filtered by shouldInclude)
     */
    public get incompleteItems(): SetupChecklistItem[] {
        return this._items.filter(item => item.shouldInclude() && !item.isCompleted());
    }

    /**
     * Get items that can be auto-completed (completionCheck returns true but not manually confirmed)
     * (filtered by shouldInclude)
     */
    public get autoCompletableItems(): SetupChecklistItem[] {
        return this._items.filter(item =>
            item.shouldInclude() &&
            !item.isCompleted() &&
            item.completionCheck() &&
            item.needsManualConfirmation() &&
            !item.manuallyConfirmed
        );
    }

    /**
     * Add a checklist item
     */
    public addItem(item: SetupChecklistItem): void {
        this._items.push(item);
        // Listen to item changes and propagate to library listeners
        StateManager.addObserver(item, () => {
            StateManager.propertyChanged(this, 'items');
        }, ['manuallyConfirmed']);
        StateManager.propertyChanged(this, 'items');
    }

    /**
     * Remove a checklist item by index
     */
    public removeItem(index: number): void {
        if (index >= 0 && index < this._items.length) {
            this._items.splice(index, 1);
            StateManager.propertyChanged(this, 'items');
        }
    }

    /**
     * Remove a specific checklist item
     */
    public removeItemByReference(item: SetupChecklistItem): void {
        const index = this._items.indexOf(item);
        if (index !== -1) {
            this.removeItem(index);
        }
    }

    /**
     * Update a checklist item
     */
    public updateItem(oldItem: SetupChecklistItem, newItem: SetupChecklistItem): void {
        const index = this._items.indexOf(oldItem);
        if (index !== -1) {
            this._items[index] = newItem;
            StateManager.propertyChanged(this, 'items');
        }
    }

    /**
     * Get a checklist item by name
     */
    public getItemByName(name: string): SetupChecklistItem | undefined {
        return this._items.find(item => item.name === name);
    }

    /**
     * Get the default items definition (name + creator function)
     */
    private getDefaultItems(): Array<{ name: string; creator: () => SetupChecklistItem }> {
        return [
            { name: 'Machine Name and Board Type', creator: () => new MachineNameAndBoardChecklistItem() },
            { name: 'Inputs Configuration', creator: () => new InputsChecklistItem() },
            { name: 'Outputs Configuration', creator: () => new OutputsChecklistItem() },
            { name: 'Machine Features', creator: () => new MachineFeatureChecklistItem() },
            { name: 'Machine Zero Coordinates', creator: () => new MachineZeroChecklistItem() },
            { name: 'Soft Limits', creator: () => new SoftLimitsChecklistItem() },
            { name: 'Spoil Board', creator: () => new SpoilBoardChecklistItem() },
            { name: 'File Monitoring Configuration', creator: () => new FileMonitoringChecklistItem() },
            { name: 'Feed Rate Speeds', creator: () => new FeedRateSpeedsChecklistItem() },
            { name: 'Homing Configuration', creator: () => new HomingChecklistItem() },
            { name: 'Manual Tool Change Location', creator: () => new ManualToolChangeChecklistItem() },
            { name: 'Simulator Configuration', creator: () => new SimulatorChecklistItem() },
            { name: 'ATC Setup', creator: () => new ATCSetupChecklistItem() },
            { name: 'Axis Configuration', creator: () => new AxisConfigurationChecklistItem() },
            { name: 'Axis Calibration', creator: () => new AxisCalibrationChecklistItem() },
            { name: 'Spindle Configuration', creator: () => new SpindleConfigurationChecklistItem() },
            { name: 'Measurement Setup', creator: () => new MeasurementSetupChecklistItem() },
            { name: 'Movable Touch Plate Height', creator: () => new MovableTouchPlateHeightChecklistItem() },
            { name: 'Fixed Touch Plate Position', creator: () => new FixedTouchPlatePositionChecklistItem() },
            { name: 'Fixed Tool Measurement Position', creator: () => new FixedToolMeasurementPositionChecklistItem() },
            { name: 'Spoilboard Tool Measurement Position', creator: () => new SpoilboardToolMeasurementPositionChecklistItem() },
            { name: 'Machine Bed Tool Measurement Position', creator: () => new MachineBedToolMeasurementPositionChecklistItem() },
            { name: 'Turn Off Test Mode', creator: () => new TestModeOffChecklistItem() }
        ];
    }

    /**
     * Ensure all default checklist items exist in the library
     * This should be called after loading from storage to ensure new items are added
     */
    public ensureDefaultItemsExist(): void {
        const defaultItems = this.getDefaultItems();

        for (const { name, creator } of defaultItems) {
            if (!this.getItemByName(name)) {
                this.addItem(creator());
            }
        }

        // Trigger a state update to ensure UI refreshes
        StateManager.propertyChanged(this, 'items');
    }

    /**
     * Sort items to match the default order
     */
    private sortItemsByDefaultOrder(): void {
        const defaultItems = this.getDefaultItems();
        const defaultOrder = defaultItems.map(item => item.name);

        this._items.sort((a, b) => {
            const indexA = defaultOrder.indexOf(a.name);
            const indexB = defaultOrder.indexOf(b.name);

            // If item not found in default order, put it at the end
            const orderA = indexA === -1 ? defaultOrder.length : indexA;
            const orderB = indexB === -1 ? defaultOrder.length : indexB;

            return orderA - orderB;
        });
    }

    /**
     * Mark an item as manually confirmed
     */
    public confirmItem(item: SetupChecklistItem): void {
        item.manuallyConfirmed = true;
        // Sort items to maintain default order
        this.sortItemsByDefaultOrder();
        StateManager.propertyChanged(this, 'items');
        // State change will be propagated through listener set up in addItem

        // Auto-save checklist after confirmation
        this.saveAsync();
    }

    /**
     * Reset an item's manual confirmation
     */
    public resetItem(item: SetupChecklistItem): void {
        item.manuallyConfirmed = false;
        // State change will be propagated through listener set up in addItem

        // Auto-save checklist after reset
        this.saveAsync();
    }

    /**
     * Auto-complete all items that have completionCheck() returning true
     */
    public autoCompleteAll(): void {
        const autoCompletable = this.autoCompletableItems;
        autoCompletable.forEach(item => {
            item.manuallyConfirmed = true;
        });
        if (autoCompletable.length > 0) {
            // Sort items to maintain default order
            this.sortItemsByDefaultOrder();
            StateManager.propertyChanged(this, 'items');
        }
    }

    /**
     * Clear all checklist items
     */
    public clear(): void {
        this._items = [];
        StateManager.propertyChanged(this, 'items');
    }

    /**
     * Get completion percentage (0-100) based on items that shouldInclude
     */
    public getCompletionPercentage(): number {
        const includedItems = this._items.filter(item => item.shouldInclude());
        if (includedItems.length === 0) return 100;
        const completed = includedItems.filter(item => item.isCompleted()).length;
        return Math.round((completed / includedItems.length) * 100);
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): object {
        return {
            items: this._items.map(item => item.toJSON())
        };
    }

    /**
     * Deserialize from JSON
     */
    public fromJSON(data: any): void {
        // Ensure all default items exist first
        this.ensureDefaultItemsExist();

        // Load manuallyConfirmed state from saved data
        if (data.items && Array.isArray(data.items)) {
            data.items.forEach((savedItem: any) => {
                if (savedItem.name) {
                    // Find matching item in library by name
                    const item = this.getItemByName(savedItem.name);
                    if (item && savedItem.manuallyConfirmed !== undefined) {
                        // Restore the manuallyConfirmed state
                        item.manuallyConfirmed = savedItem.manuallyConfirmed;
                    }
                }
            });
        }

        // Trigger state update
        StateManager.propertyChanged(this, 'items');
    }

    /**
     * Save checklist asynchronously (auto-save helper)
     */
    private async saveAsync(): Promise<void> {
        try {
            Logger.Instance.log(LogCategory.DataManager, 'Auto-saving setup checklist...');
            // Use dynamic import to avoid circular dependency
            const { DataManager } = await import('../DataManager');
            await DataManager.Instance.saveSetupChecklistIndividual();
            Logger.Instance.log(LogCategory.DataManager, 'Setup checklist auto-save completed');
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to auto-save setup checklist:', error);
        }
    }
}
