import { TextField } from '@mui/material';
import { useEffect, useState } from 'react';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';

export interface GCodeEditorProps {
    value: string;
    onChange: (value: string) => void;
    minRows?: number;
    maxRows?: number;
    readOnly?: boolean;
    placeholder?: string;
    fillHeight?: boolean; // If true, editor fills 100% of container height
}

export function GCodeEditor({
    value,
    onChange,
    minRows = 20,
    maxRows = 25,
    readOnly = false,
    placeholder = 'Enter G-code here...',
    fillHeight = false
}: GCodeEditorProps) {
    // Manage internal state for editing
    const [internalValue, setInternalValue] = useState(value);

    // Update internal state when external value changes
    useEffect(() => {
        setInternalValue(value);
    }, [value]);

    const handleChange = (newValue: string) => {
        if (readOnly) return;

        // Update internal state immediately for responsive typing
        setInternalValue(newValue);

        // Notify parent of change
        onChange(newValue);
    };

    return (
        <TextField
            multiline
            fullWidth
            value={internalValue}
            onChange={(e) => handleChange(e.target.value)}
            minRows={fillHeight ? undefined : minRows}
            maxRows={fillHeight ? undefined : maxRows}
            variant="outlined"
            placeholder={placeholder}
            sx={fillHeight ? {
                height: '100%',
                '& .MuiInputBase-root': {
                    height: '100%',
                    alignItems: 'flex-start'
                },
                '& .MuiInputBase-inputMultiline': {
                    height: '100% !important',
                    overflow: 'auto !important'
                }
            } : undefined}
            InputProps={{
                readOnly: readOnly,
                sx: {
                    fontFamily: 'monospace',
                    fontSize: '0.875rem',
                    backgroundColor: ConfigurationDataColors.Instance.darkBackgroundColor,
                    color: ConfigurationDataColors.Instance.lightTextColor,
                    '& .MuiOutlinedInput-notchedOutline': {
                        borderColor: ConfigurationDataColors.Instance.borderColor
                    },
                    '&:hover .MuiOutlinedInput-notchedOutline': {
                        borderColor: ConfigurationDataColors.Instance.secondaryBorderColor
                    },
                    '&.Mui-focused .MuiOutlinedInput-notchedOutline': {
                        borderColor: 'primary.main'
                    }
                }
            }}
        />
    );
}
