import { CNCPoint } from '../data/CNCPoint';
import { JogIncrementSpeed } from '../data/ConfigurationState';
import { IOEvent } from './IOEvent';
import { JogDirection } from './JogDirection';
import { MoveDirection } from './MoveDirection';
import { MoveStrategy } from './MoveStrategy';
import { MoveType } from './MoveType';

/**
 * Coordinate system for movement commands
 */
export enum MovementCoordinateType {
    Machine = 'Machine',     // Machine coordinates (absolute from machine zero)
    WorkZero = 'WorkZero'    // Work coordinates (relative to current fixture with tool offsets)
}

/**
 * Interface for CNC movement operations
 */
export interface ICNCMovement {
    SetMoveType(moveType: MoveType): Promise<void>;
    GetMoveType(): Promise<MoveType>;
    GetCurrentPosition(): Promise<CNCPoint>;
    MoveTo(point: CNCPoint, coordinateType: MovementCoordinateType, xySpeed?: number, zSpeed?: number, strategy?: MoveStrategy): Promise<void>;
    MoveToUntil(point: CNCPoint, coordinateType: MovementCoordinateType, event: IOEvent, xySpeed?: number, zSpeed?: number): Promise<void>;
    MoveDirectionUntil(
        direction: MoveDirection,
        event: IOEvent,
        maxDistance?: number,
        speed?: number
    ): Promise<void>;
    SetCurrentFixturePoint(): Promise<void>;
    // GetFastFeedRate(): Promise<number>;
    // SetFastFeedRate(feedRate: number): Promise<void>;
    // GetNormalFeedRate(): Promise<number>;
    // SetNormalFeedRate(feedRate: number): Promise<void>;
    AdjustFeedRate(factor: number): Promise<void>;
    GetCurrentFeedRateFactor(): Promise<number>;
    ResetFeedRateFactor(): Promise<void>;

    /**
     * Start jog in specified direction using current jog settings from ConfigurationState
     * @param direction Direction to jog (XPlus, XMinus, YPlus, YMinus, ZPlus, ZMinus, APlus, AMinus)
     */
    StartJog(direction: JogDirection): Promise<void>;

    /**
     * Stop continuous jog movement
     */
    StopJog(): Promise<void>;

    /**
     * Keep continuous jog active (renewal pattern - must be called every 100ms)
     * Required for continuous jog to prevent 250ms timeout on backend
     * @param direction Direction to keep jogging (must match StartJog direction)
     */
    KeepJogging(direction: JogDirection): Promise<void>;

    /**
     * Set jog mode to continuous or incremental
     * @param isContinuous True for continuous mode, false for incremental mode
     */
    SetContinuousJog(isContinuous: boolean): Promise<void>;

    /**
     * Set jog speed to fast or slow
     * @param isFast True for fast mode (rabbit), false for slow mode (turtle)
     */
    SetFastJog(isFast: boolean): Promise<void>;

    /**
     * Set jog increment speed multiplier
     * @param speed Speed multiplier (X1, X10, or X100)
     */
    SetJogIncrementSpeed(speed: JogIncrementSpeed): Promise<void>;
}
