import { Box, Typography } from '@mui/material';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { DataUtilities } from '../../../utils/storage/DataUtilities';
import { DataElement } from '../data/DataElement';
import { DataType, Declaration } from '../data/Declaration';
import { PLCOutput } from '../data/io/PLCOutput';
import { IPLCElement, PLCRenderMode } from '../data/IPLCElement';
import { PLCProgram } from '../data/PLCProgram';
import { PLCProgramType } from '../data/PLCUtilities';
import { BasePLCStatement } from './BasePLCStatement';

/**
 * Standard M9495 Handling Statement
 * System-only statement with no UI that outputs standard M94/M95 trigger handling code
 * Only available in SystemDefault PLC programs
 */
export class StandardM9495HandlingStatement extends BasePLCStatement {
    /**
     * Get a short, single-line description for display in tree views
     * @returns A human-readable summary
     */
    public getShortDescription(): string {
        return 'Standard M94/M95 handling';
    }

    /**
     * Validate the statement
     */
    public validate(): string | undefined {
        return undefined; // Always valid
    }

    /**
     * Render the statement (informational display only, no editable properties)
     */
    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): any {
        const colors = ConfigurationDataColors.Instance;

        return (
            <Box
                sx={{
                    padding: 2,
                    backgroundColor: colors.selectionColor, // Light blue background for system-only statements
                    border: `1px solid ${colors.borderColor}`,
                    borderRadius: 1,
                    opacity: this._enabled ? 1 : 0.5
                }}
            >
                <Typography
                    variant="subtitle2"
                    sx={{ color: colors.primaryColor, fontWeight: 'bold' }}
                >
                    Standard M94/M95 Handling
                </Typography>
                <Typography variant="body2" sx={{ marginTop: 0.5 }}>
                    Standard M94/M95 trigger handling code (system only)
                </Typography>
            </Box>
        );
    }

    /**
     * Get declarations used by this statement
     */
    public getUsedDeclarations(): Declaration[] {
        return [];
    }

    /**
     * Get declarations added by this statement
     */
    public getAddedDeclarations(): Declaration[] {
        // Validate that this statement has a valid plcSource
        if (!this.plcSource) {
            throw new Error('StandardM9495HandlingStatement: plcSource is not set. Statement must be added to a program before calling getAddedDeclarations()');
        }

        // CRITICAL: StandardM9495HandlingStatement should ONLY be used in SystemDefault program
        const myProgramType = this.plcSource.getProgramType();
        if (myProgramType !== PLCProgramType.SystemDefault) {
            throw new Error(`StandardM9495HandlingStatement can only be used in SystemDefault program, but found in ${myProgramType} program`);
        }

        if (!this._enabled) {
            return [];
        }

        const declarations: Declaration[] = [];

        // Get all outputs from SystemDefault that are not handled by explicit M94/M95 triggers
        const unhandledOutputs = this.getUnhandledOutputs();

        // Create SV system variable declarations for each unhandled output
        for (const output of unhandledOutputs) {
            const triggerNumber = output.getTriggerNumber();
            if (triggerNumber !== null) {
                // Generate declaration name based on output centroid name
                const declName = `${output.centroidName}_MM`;
                const svName = `SV_M94_M95_${triggerNumber}`;
                const svDecl = new Declaration(declName);
                svDecl.description = `M94/M95 trigger for ${output.name} (auto-generated)`;
                svDecl.dataType = DataType.M94M95Trigger;
                svDecl.isSystem = false;
                svDecl.mappedToLocation = svName;
                svDecl.isSetText = output.activeText || 'Is Active';
                svDecl.isResetText = output.inactiveText || 'Is Inactive';
                declarations.push(svDecl);
            }
        }

        return declarations;
    }

    /**
     * Get PLC logic code
     * Outputs standard M94/M95 trigger handling code
     */
    public getPLCLogic(availableDeclarations: string[]): string[] {
        if (!this._enabled) {
            return [];
        }

        const lines: string[] = [];
        lines.push('; Standard M94/M95 Handling - Auto-generated for outputs without explicit triggers');
        lines.push('');

        // Get all outputs from SystemDefault that are not handled by explicit M94/M95 triggers
        const unhandledOutputs = this.getUnhandledOutputs();

        if (unhandledOutputs.length === 0) {
            lines.push('; All outputs are handled by explicit M94/M95 triggers');
            return lines;
        }

        // Generate SET/RST logic for each unhandled output
        for (const output of unhandledOutputs) {
            const triggerNumber = output.getTriggerNumber();
            if (triggerNumber !== null) {
                const declName = `${output.centroidName}_MM`;
                const outputName = output.centroidName;

                lines.push(`; Auto-generated M94/M95 handling for ${output.name} (trigger ${triggerNumber})`);
                lines.push(`IF (${declName}) THEN SET ${outputName}`);
                lines.push(`IF !(${declName}) THEN RST ${outputName}`);
                lines.push('');
            }
        }

        return lines;
    }

    /**
     * Get outputs that are not handled by explicit M94/M95 triggers
     * Checks both SystemDefault and System programs for trigger definitions
     */
    private getUnhandledOutputs(): PLCOutput[] {
        if (!this.plcSource) {
            return [];
        }

        // Get the SystemDefault program (which is where this statement should be)
        const systemDefaultProgram = PLCProgram.Instance(PLCProgramType.SystemDefault);
        const systemProgram = PLCProgram.Instance(PLCProgramType.System);

        // Get all outputs from System PLC (outputs are only defined on System, not SystemDefault)
        const allOutputs = systemProgram.outputs;

        // Build a set of all output names that are handled by explicit M94/M95 triggers
        // Check BOTH SystemDefault and System programs
        const handledOutputNames = new Set<string>();

        // Add outputs from SystemDefault triggers
        for (const trigger of systemDefaultProgram.m94m95Triggers) {
            for (const outputName of trigger.outputs) {
                handledOutputNames.add(outputName);
            }
        }

        // Add outputs from System triggers (System inherits from SystemDefault)
        for (const trigger of systemProgram.m94m95Triggers) {
            for (const outputName of trigger.outputs) {
                handledOutputNames.add(outputName);
            }
        }

        // Filter to get only outputs that:
        // 1. Are NOT in any explicit trigger
        // 2. Have a valid trigger number (i.e., no custom G-code defined)
        // 3. Do NOT have custom onCommand/offCommand defined on the output itself
        const unhandledOutputs = allOutputs.filter(output => {
            const isHandled = handledOutputNames.has(output.centroidName);
            const hasTriggerNumber = output.getTriggerNumber() !== null;
            const hasCustomCommands = output.onCommand !== '' || output.offCommand !== '';
            return !isHandled && hasTriggerNumber && !hasCustomCommands;
        });

        return unhandledOutputs;
    }

    /**
     * Get validation issues
     */
    public getValidationIssues(): any[] {
        return [];
    }

    /**
     * Get all data elements (none for this statement)
     */
    public getDataElements(): DataElement[] {
        return [];
    }

    /**
     * Clone the statement
     */
    public clone(): StandardM9495HandlingStatement {
        const cloned = new StandardM9495HandlingStatement();
        cloned._comment = this._comment;
        cloned._enabled = this._enabled;
        return cloned;
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): object {
        return {
            type: 'StandardM9495HandlingStatement',
            ...DataUtilities.getStorageData(this, ['_parentElement', '_plcSource'])
        };
    }

    /**
     * Deserialize from JSON
     */
    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data, ['_parentElement', '_plcSource']);
    }

    /**
     * Set parent element and cascade to children
     */
    public setParentElement(parent: IPLCElement | undefined): void {
        super.setParentElement(parent);
        // No children to cascade to
    }
}
