import { Alert, Box, Button, Typography } from '@mui/material';
import React from 'react';
import { Tool } from '../../../../data/Common/Tool';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../../data/ConfigurationState';
import { MachineData } from '../../../../data/Machine/MachineData';
import { MachineStateData } from '../../../../data/MachineStateData';
import { UserMessageQueue } from '../../../../data/UserMessageQueue';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { ZJogControls } from '../../../Common/ZJogControls';
import { WizardStep } from '../../../Wizard/WizardStep';
import { ToolMeasurementMethod, ToolMeasurementWizard } from '../ToolMeasurementWizard';

/**
 * Step for manual measurement with Z jog controls
 */
export class ManualJogStep extends WizardStep {
    private tool: Tool;
    private method: ToolMeasurementMethod;

    constructor(wizard: ToolMeasurementWizard, tool: Tool, previousStep: WizardStep | null, method: ToolMeasurementMethod) {
        super(wizard, previousStep);
        this.tool = tool;
        this.method = method;
    }

    getTitle(): string {
        return 'Manual Tool Measurement';
    }

    private getPositionName(): string {
        switch (this.method) {
            case ToolMeasurementMethod.ManualFixedPoint:
                return 'Fixed Tool Measurement Point';
            case ToolMeasurementMethod.ManualSpoilboard:
                return 'Spoilboard';
            case ToolMeasurementMethod.ManualMachineBed:
                return 'Machine Bed';
            default:
                return 'Measurement Surface';
        }
    }

    nextStep(): WizardStep | null {
        // Final step - wizard will close after measurement
        return null;
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return <ManualJogStepComponent step={this} />;
    }
}

interface ManualJogStepComponentProps {
    step: ManualJogStep;
}

function ManualJogStepComponent({ step }: ManualJogStepComponentProps) {
    const wizard = step.wizard as ToolMeasurementWizard;
    const colors = ConfigurationDataColors.Instance;

    const handleMeasure = async () => {
        try {
            // Get current Z position (Machine Zero coordinates)
            const currentPos = ConfigurationState.Instance.currentMachinePoint;
            const currentZ = currentPos.z;

            // Get the fixed point Z position (bottom of spindle without tool)
            const fixedPointZ = MachineData.Instance.fixedToolMeasurementPointZ;

            // Calculate tool length: difference between current position (with tool) and fixed point (without tool)
            const toolLength = currentZ - fixedPointZ;

            // Store the measured tool length
            step['tool'].measuredLength = toolLength;

            // Mark tool as measured in current session
            const machineState = MachineStateData.Instance;
            step['tool'].lastMeasuredSessionNumber = machineState.sessionNumber;

            Logger.Instance.log(LogCategory.System, `Tool ${step['tool'].toolName} measured: Length = ${toolLength.toFixed(4)} (Current Z: ${currentZ.toFixed(4)}, Fixed Point Z: ${fixedPointZ.toFixed(4)})`);
            UserMessageQueue.Instance.addMessage(`✓ Tool ${step['tool'].toolName} measured: Length = ${toolLength.toFixed(4)}"`);

            await wizard.callback?.onComplete?.();
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to measure tool:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to measure tool');
        }
    };

    return (
        <Box sx={{ p: 3, display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>
            <Alert severity="info">
                <Typography variant="body2">
                    Use the Z-axis jog controls to carefully lower the tool until it just touches the {step['getPositionName']()}. When the tool tip just touches the surface, click "Measure" to record the position.
                </Typography>
            </Alert>

            <Box sx={{
                flex: 1,
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                gap: 2,
                my: 3
            }}>
                <ZJogControls />
            </Box>

            <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 2 }}>
                <Button
                    variant="outlined"
                    onClick={() => wizard.goToPreviousStep()}
                >
                    Back
                </Button>
                <Button
                    variant="contained"
                    onClick={handleMeasure}
                    sx={{ backgroundColor: colors.primaryColor }}
                >
                    Measure
                </Button>
            </Box>
        </Box>
    );
}
