import {
    Close as CloseIcon,
    Delete as DeleteIcon,
    Edit as EditIcon,
    Refresh as RefreshIcon,
    PlayArrow as RunIcon,
    Save as SaveIcon
} from '@mui/icons-material';
import {
    Alert,
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    Divider,
    FormControlLabel,
    Grid,
    IconButton,
    List,
    ListItemButton,
    ListItemSecondaryAction,
    ListItemText,
    Paper,
    Switch,
    TextField,
    Typography
} from '@mui/material';
import React, { useEffect, useState } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { Storage, StorageType } from '../../machine/ICNCProgramStorage';
import { Machine } from '../../machine/Machine';
import { ConfirmDialogManager } from '../../utils/ConfirmDialogManager';
import { LogCategory, Logger } from '../../utils/Logger';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { GCodeEditor } from '../Common/GCodeEditor';

interface SaveDialogProps {
    open: boolean;
    onClose: () => void;
    onSave: (name: string, categoryName: string, exposeAsAction: boolean) => void;
    initialName?: string;
    initialCategoryName?: string;
    initialExposeAsAction?: boolean;
}

const SaveDialog: React.FC<SaveDialogProps> = ({
    open,
    onClose,
    onSave,
    initialName = '',
    initialCategoryName = '',
    initialExposeAsAction = false
}) => {
    const colors = ConfigurationDataColors.Instance;
    const [name, setName] = useState(initialName);
    const [categoryName, setCategoryName] = useState(initialCategoryName);
    const [exposeAsAction, setExposeAsAction] = useState(initialExposeAsAction);

    useEffect(() => {
        setName(initialName);
        setCategoryName(initialCategoryName);
        setExposeAsAction(initialExposeAsAction);
    }, [initialName, initialCategoryName, initialExposeAsAction]);

    const handleSave = () => {
        if (!name.trim()) {
            UserMessageQueue.Instance.addMessage('❌ Please enter a name for the MDI command');
            return;
        }

        if (exposeAsAction && !categoryName.trim()) {
            UserMessageQueue.Instance.addMessage('❌ Please enter a category name when exposing as action');
            return;
        }

        onSave(name.trim(), categoryName.trim(), exposeAsAction);
        onClose();
    };

    return (
        <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
            <DialogTitle sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                backgroundColor: colors.primaryColor,
                color: colors.lightTextColor,
                py: 2,
                px: 3
            }}>
                Save MDI Command
                <IconButton
                    onClick={onClose}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>
            <DialogContent>
                <TextField
                    sx={{ mt: 3 }}
                    fullWidth
                    label="Command Name"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    margin="normal"
                    placeholder="e.g., 'Quick Home', 'Tool Change Position'"
                />

                <FormControlLabel
                    control={
                        <Switch
                            checked={exposeAsAction}
                            onChange={(e) => setExposeAsAction(e.target.checked)}
                            sx={{
                                '& .MuiSwitch-switchBase.Mui-checked': {
                                    color: colors.primaryColor,
                                },
                                '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': {
                                    backgroundColor: colors.primaryColor,
                                },
                            }}
                        />
                    }
                    label="Expose as Action Button"
                    sx={{ mt: 2, mb: 1 }}
                />

                {exposeAsAction && (
                    <TextField
                        fullWidth
                        label="Category Name"
                        value={categoryName}
                        onChange={(e) => setCategoryName(e.target.value)}
                        margin="normal"
                        placeholder="e.g., 'Home All Axes', 'Move to Tool Change'"
                        helperText="This name will appear on action buttons throughout the application"
                    />
                )}
            </DialogContent>
            <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${colors.borderColor}` }}>
                <Button onClick={onClose}>Cancel</Button>
                <Button
                    onClick={handleSave}
                    variant="contained"
                    sx={{
                        backgroundColor: colors.primaryColor,
                        '&:hover': {
                            backgroundColor: colors.primaryColor,
                            filter: 'brightness(0.9)'
                        }
                    }}
                >
                    Save
                </Button>
            </DialogActions>
        </Dialog>
    );
};

export function MDIView() {
    const [gcode, setGcode] = useState('');
    const [savedCommands, setSavedCommands] = useState<Storage[]>([]);
    const [saveDialogOpen, setSaveDialogOpen] = useState(false);
    const [editingCommand, setEditingCommand] = useState<Storage | null>(null);

    const loadSavedCommands = async () => {
        try {
            const machine = Machine.getInstance();
            const names = await machine.storage.getMDIStorageNames();
            const commands: Storage[] = [];

            for (const name of names) {
                const storage = await machine.storage.getStorageData(name);
                if (storage) {
                    commands.push(storage);
                }
            }

            setSavedCommands(commands.sort((a, b) => a.name.localeCompare(b.name)));
        } catch (error) {
            Logger.Instance.logError(LogCategory.UserInterface, 'Failed to load saved MDI commands:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to load saved commands');
        }
    };

    useEffect(() => {
        loadSavedCommands();
    }, []);

    /**
     * Preprocess MDI G-code to add G01 and feed rate to coordinate-only lines
     * Lines like "X10" or "X10 Y5 Z2" become "G01 X10 F500" or "G01 X10 Y5 Z2 F500"
     */
    const preprocessMDICode = (code: string): string => {
        const config = ConfigurationData.Instance;
        const configState = ConfigurationState.Instance;

        // Determine feed rate based on fast/slow jog mode
        const isFast = configState.jogFastMode;
        const feedRate = isFast ? config.fastJogXY : config.slowJogXY;

        const lines = code.split('\n');
        const processedLines = lines.map(line => {
            const trimmed = line.trim();

            // Skip empty lines or comments
            if (!trimmed || trimmed.startsWith('(') || trimmed.startsWith(';')) {
                return line;
            }

            // Check if line contains only coordinate letters (X, Y, Z, A) followed by numbers
            // This regex matches lines that only have coordinate commands, optional spaces, and values
            const coordinateOnlyPattern = /^([XYZA][-+]?\d+\.?\d*\s*)+$/i;

            if (coordinateOnlyPattern.test(trimmed)) {
                // This is a coordinate-only line, add G01 and feed rate
                return `G01 ${trimmed} F${feedRate.toFixed(0)}`;
            }

            return line;
        });

        return processedLines.join('\n');
    };

    const handleRunDirect = async () => {
        if (!gcode.trim()) {
            UserMessageQueue.Instance.addMessage('❌ Please enter G-code to run');
            return;
        }

        try {
            // Preprocess G-code to add G01 and feed rate to coordinate-only lines
            const preprocessedCode = preprocessMDICode(gcode);

            // Split G-code into lines and filter empty lines
            const gcodeLines = preprocessedCode.split('\n').filter(line => line.trim());

            // Execute directly without preview dialog
            const machine = Machine.getInstance();
            await machine.program.RunGCode(gcodeLines, true);
        } catch (error) {
            Logger.Instance.logError(LogCategory.UserInterface, 'Failed to execute MDI command:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to execute MDI command');
        }
    };

    const handleRunWithPreview = async () => {
        if (!gcode.trim()) {
            UserMessageQueue.Instance.addMessage('❌ Please enter G-code to run');
            return;
        }

        try {
            // Preprocess G-code to add G01 and feed rate to coordinate-only lines
            const preprocessedCode = preprocessMDICode(gcode);

            // Split G-code into lines and filter empty lines
            const gcodeLines = preprocessedCode.split('\n').filter(line => line.trim());

            // Use preview dialog with auto-run enabled (no callback for MDI - not a chained operation)
            const config = ConfigurationData.Instance;
            config.showGCodePreview('MDI Execution', gcodeLines, undefined, true); // startImmediately = true for MDI
        } catch (error) {
            Logger.Instance.logError(LogCategory.UserInterface, 'Failed to show MDI preview:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to execute MDI command');
        }
    };

    const handleSave = async (name: string, categoryName: string, exposeAsAction: boolean) => {
        if (!gcode.trim()) {
            UserMessageQueue.Instance.addMessage('❌ Please enter G-code to save');
            return;
        }

        try {
            const machine = Machine.getInstance();
            const storage = new Storage();
            storage.name = name;
            storage.data = gcode.trim();
            storage.storageType = StorageType.MDI;
            storage.exposeAsAction = exposeAsAction;
            storage.categoryName = exposeAsAction ? categoryName : '';
            storage.createdAt = editingCommand ? editingCommand.createdAt : new Date();
            storage.updatedAt = new Date();

            await machine.storage.saveStorageData(storage);

            // Notify listeners that user actions have been updated
            const { DataReloadNotifier, DataReloadEvent } = await import('../../utils/DataReloadNotifier');
            await DataReloadNotifier.Instance.notifyListeners(DataReloadEvent.UserActionsUpdated);

            await loadSavedCommands();
            setEditingCommand(null);
        } catch (error) {
            Logger.Instance.logError(LogCategory.UserInterface, 'Failed to save MDI command:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to save MDI command');
        }
    };

    const handleLoad = (command: Storage) => {
        setGcode(command.data);
        setEditingCommand(command);
    };

    const handleEdit = (command: Storage) => {
        setGcode(command.data);
        setEditingCommand(command);
        setSaveDialogOpen(true);
    };

    const handleDelete = async (command: Storage) => {
        const confirmed = await ConfirmDialogManager.Instance.showDeleteConfirm(`MDI command "${command.name}"`);
        if (!confirmed) return;

        try {
            const machine = Machine.getInstance();
            await machine.storage.deleteStorageData(command.name);

            // Notify listeners that user actions have been updated
            const { DataReloadNotifier, DataReloadEvent } = await import('../../utils/DataReloadNotifier');
            await DataReloadNotifier.Instance.notifyListeners(DataReloadEvent.UserActionsUpdated);

            await loadSavedCommands();

            // Clear editor if we were editing this command
            if (editingCommand?.name === command.name) {
                setGcode('');
                setEditingCommand(null);
            }
        } catch (error) {
            Logger.Instance.logError(LogCategory.UserInterface, 'Failed to delete MDI command:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to delete MDI command');
        }
    };

    const handleNew = () => {
        setGcode('');
        setEditingCommand(null);
    };

    return (
        <ObserveState
            key="mdi-view"
            listenTo={ConfigurationDataColors.Instance}
            properties={['primaryColor', 'backgroundColor', 'textColor', 'borderColor']}
            control={() => {
                const config = ConfigurationData.Instance;
                const colors = ConfigurationDataColors.Instance;

                return (
                    <Box sx={{ p: 3, height: '100%', display: 'flex', flexDirection: 'column' }}>
                        <Typography variant="h4" gutterBottom sx={{ color: colors.primaryColor }}>
                            MDI (Manual Data Input)
                        </Typography>

                        <Grid container spacing={3} sx={{ flex: 1, minHeight: 0 }}>
                            {/* Left Panel - G-code Editor */}
                            <Grid item xs={12} md={8} sx={{ display: 'flex', flexDirection: 'column', minHeight: 0 }}>
                                <Paper sx={{ p: 3, height: '100%', display: 'flex', flexDirection: 'column' }}>
                                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                                        <Typography variant="h6">G-code Command</Typography>
                                        <Button
                                            variant="outlined"
                                            onClick={handleNew}
                                            size="small"
                                        >
                                            New
                                        </Button>
                                    </Box>

                                    {editingCommand && (
                                        <Alert severity="info" sx={{ mb: 2, flexShrink: 0 }}>
                                            Editing: <strong>{editingCommand.name}</strong>
                                            {editingCommand.exposeAsAction && ` (Category: ${editingCommand.categoryName})`}
                                        </Alert>
                                    )}

                                    <Box sx={{ flex: 1, minHeight: 0 }}>
                                        <GCodeEditor
                                            value={gcode}
                                            onChange={setGcode}
                                            placeholder="Enter G-code commands here...&#10;Example:&#10;G0 X0 Y0 Z5&#10;G1 X10 Y10 F100"
                                            fillHeight={true}
                                        />
                                    </Box>

                                    <Box sx={{ display: 'flex', gap: 2, mt: 2, flexShrink: 0, justifyContent: 'space-between' }}>
                                        <Button
                                            variant="outlined"
                                            startIcon={<SaveIcon />}
                                            onClick={() => setSaveDialogOpen(true)}
                                            disabled={!gcode.trim()}
                                        >
                                            Save
                                        </Button>

                                        <Box sx={{ display: 'flex', gap: 2 }}>
                                            <Button
                                                variant="outlined"
                                                startIcon={<RunIcon />}
                                                onClick={handleRunWithPreview}
                                                disabled={!gcode.trim()}
                                                sx={{
                                                    borderColor: colors.primaryColor,
                                                    color: colors.primaryColor,
                                                    '&:hover': {
                                                        borderColor: colors.primaryColor,
                                                        backgroundColor: 'rgba(0, 0, 0, 0.04)'
                                                    }
                                                }}
                                            >
                                                Run w/ Preview
                                            </Button>

                                            <Button
                                                variant="contained"
                                                startIcon={<RunIcon />}
                                                onClick={handleRunDirect}
                                                disabled={!gcode.trim()}
                                                sx={{
                                                    backgroundColor: colors.primaryColor,
                                                    '&:hover': {
                                                        backgroundColor: colors.primaryColor,
                                                        opacity: 0.8
                                                    }
                                                }}
                                            >
                                                Run
                                            </Button>
                                        </Box>
                                    </Box>
                                </Paper>
                            </Grid>

                            {/* Right Panel - Saved Commands */}
                            <Grid item xs={12} md={4} sx={{ display: 'flex', flexDirection: 'column', minHeight: 0 }}>
                                <Paper sx={{ p: 3, height: '100%', display: 'flex', flexDirection: 'column', minHeight: 0 }}>
                                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2, flexShrink: 0 }}>
                                        <Typography variant="h6">Saved Commands</Typography>
                                        <IconButton onClick={loadSavedCommands} size="small">
                                            <RefreshIcon />
                                        </IconButton>
                                    </Box>

                                    <Box sx={{ flex: 1, overflow: 'auto', minHeight: 0 }}>
                                        {savedCommands.length === 0 ? (
                                            <Typography color="text.secondary" sx={{ textAlign: 'center', mt: 4 }}>
                                                No saved MDI commands.
                                                <br />
                                                Create and save commands to see them here.
                                            </Typography>
                                        ) : (
                                            <List dense>
                                                {savedCommands.map((command, index) => (
                                                    <React.Fragment key={command.name}>
                                                        <ListItemButton
                                                            onClick={() => handleLoad(command)}
                                                            sx={{
                                                                borderRadius: 1,
                                                                mb: 1,
                                                                border: editingCommand?.name === command.name
                                                                    ? `2px solid ${colors.primaryColor}`
                                                                    : '1px solid transparent',
                                                                '&:hover': {
                                                                    backgroundColor: `${colors.primaryColor}10`
                                                                }
                                                            }}
                                                        >
                                                            <ListItemText
                                                                primary={command.name}
                                                                secondary={
                                                                    <Box>
                                                                        {command.exposeAsAction && (
                                                                            <Typography variant="caption" color="primary" display="block">
                                                                                Category: {command.categoryName}
                                                                            </Typography>
                                                                        )}
                                                                        <Typography variant="caption" color="text.secondary">
                                                                            {command.data.split('\n')[0].substring(0, 40)}
                                                                            {command.data.length > 40 ? '...' : ''}
                                                                        </Typography>
                                                                    </Box>
                                                                }
                                                            />
                                                            <ListItemSecondaryAction>
                                                                <IconButton
                                                                    edge="end"
                                                                    onClick={(e) => {
                                                                        e.stopPropagation();
                                                                        handleEdit(command);
                                                                    }}
                                                                    size="small"
                                                                    sx={{ mr: 1 }}
                                                                >
                                                                    <EditIcon />
                                                                </IconButton>
                                                                <IconButton
                                                                    edge="end"
                                                                    onClick={(e) => {
                                                                        e.stopPropagation();
                                                                        handleDelete(command);
                                                                    }}
                                                                    size="small"
                                                                    color="error"
                                                                >
                                                                    <DeleteIcon />
                                                                </IconButton>
                                                            </ListItemSecondaryAction>
                                                        </ListItemButton>
                                                        {index < savedCommands.length - 1 && <Divider />}
                                                    </React.Fragment>
                                                ))}
                                            </List>
                                        )}
                                    </Box>
                                </Paper>
                            </Grid>
                        </Grid>

                        <SaveDialog
                            open={saveDialogOpen}
                            onClose={() => {
                                setSaveDialogOpen(false);
                                setEditingCommand(null);
                            }}
                            onSave={handleSave}
                            initialName={editingCommand?.name || ''}
                            initialCategoryName={editingCommand?.categoryName || ''}
                            initialExposeAsAction={editingCommand?.exposeAsAction || false}
                        />
                    </Box>
                );
            }}
        />
    );
}