import { IStorable } from '../../../../common/IStorable';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { PLCUtilities } from '../PLCUtilities';

/**
 * PLC Output definition
 * Static configuration for outputs - actual number and state come from API/SignalR
 */
export class PLCOutput implements IStorable {
  private _centroidName: string;
  private _name: string;
  private _category: string;
  private _activeText: string;
  private _inactiveText: string;
  private _number: number | null;
  private _onCommand: string = '';  // Custom G-code to turn on (e.g., "M3" for spindle)
  private _offCommand: string = '';  // Custom G-code to turn off (e.g., "M5" for spindle)

  constructor(
    centroidName: string = '',
    name: string = '',
    category: string = 'General',
    activeText: string = 'Active',
    inactiveText: string = 'Inactive',
    number: number | null = null
  ) {
    this._centroidName = centroidName;
    this._name = name;
    this._category = category;
    this._activeText = activeText;
    this._inactiveText = inactiveText;
    this._number = number;
  }

  public get centroidName(): string {
    return this._centroidName;
  }

  public set centroidName(value: string) {
    this._centroidName = value;
    StateManager.propertyChanged(this, 'centroidName');
  }

  public get name(): string {
    return this._name;
  }

  public set name(value: string) {
    this._name = value;
    StateManager.propertyChanged(this, 'name');
  }

  public get category(): string {
    return this._category;
  }

  public set category(value: string) {
    this._category = value;
    StateManager.propertyChanged(this, 'category');
  }

  public get activeText(): string {
    return this._activeText;
  }

  public set activeText(value: string) {
    this._activeText = value;
    StateManager.propertyChanged(this, 'activeText');
  }

  public get inactiveText(): string {
    return this._inactiveText;
  }

  public set inactiveText(value: string) {
    this._inactiveText = value;
    StateManager.propertyChanged(this, 'inactiveText');
  }

  public get number(): number | null {
    return this._number;
  }

  public set number(value: number | null) {
    this._number = value;
    StateManager.propertyChanged(this, 'number');
  }

  /**
   * Get the custom G-code command to turn this output ON
   * Empty string means use default M94/[trigger] command
   */
  public get onCommand(): string {
    return this._onCommand;
  }

  public set onCommand(value: string) {
    this._onCommand = value;
    StateManager.propertyChanged(this, 'onCommand');
  }

  /**
   * Get the custom G-code command to turn this output OFF
   * Empty string means use default M95/[trigger] command
   */
  public get offCommand(): string {
    return this._offCommand;
  }

  public set offCommand(value: string) {
    this._offCommand = value;
    StateManager.propertyChanged(this, 'offCommand');
  }

  /**
   * Get the M94/M95 trigger number for this output (51 + output number)
   * Returns null if no number is assigned
   */
  public getTriggerNumber(): number | null {
    if (this._number !== null) {
      return 51 + this._number;
    }
    return null;
  }

  /**
   * Get G-code command to turn output ON
   * Uses custom onCommand if set, otherwise checks M94/M95 triggers, otherwise uses standard M94/[51 + output number]
   */
  public getOnGCode(): string {
    // Use custom command if defined
    if (this._onCommand) {
      return this._onCommand;
    }
    return PLCUtilities.getOutputOnGCode(this._centroidName, this._number);
  }

  /**
   * Get G-code command to turn output OFF
   * Uses custom offCommand if set, otherwise checks M94/M95 triggers, otherwise uses standard M95/[51 + output number]
   */
  public getOffGCode(): string {
    // Use custom command if defined
    if (this._offCommand) {
      return this._offCommand;
    }
    return PLCUtilities.getOutputOffGCode(this._centroidName, this._number);
  }

  /**
   * Create a copy of this output definition
   */
  public clone(): PLCOutput {
    return new PLCOutput(
      this._centroidName,
      this._name,
      this._category,
      this._activeText,
      this._inactiveText,
      this._number
    );
  }

  /**
   * Serialize to JSON
   */
  public toJSON(): object {
    return DataUtilities.getStorageData(this);
  }

  /**
   * Load from JSON
   */
  public fromJSON(data: any): void {
    if (!data) return;
    DataUtilities.loadStorageData(this, data);
  }
}