import { Close as CloseIcon, Pause as PauseIcon, PlayArrow as PlayIcon, Stop as StopIcon } from '@mui/icons-material';
import { Box, Button, Dialog, DialogActions, DialogContent, DialogTitle, IconButton, List, ListItem, ListItemText, Slider, Tab, Tabs, Typography } from '@mui/material';
import { useEffect, useRef, useState } from 'react';
import { ConfigurationDataColors } from '../data/ConfigurationDataColors';
import { ConfigurationState } from '../data/ConfigurationState';
import { Job } from '../data/Job';
import { JobExecutionState, JobExecutionStatus } from '../data/JobExecutionState';
import { JobStage } from '../data/JobStage';
import { MachineData } from '../data/Machine/MachineData';
import { MachineStateData } from '../data/MachineStateData';
import { Machine } from '../machine/Machine';
import { ConfirmDialogManager } from '../utils/ConfirmDialogManager';
import { ObserveState } from '../utils/statemanager/ObserveState';
import { StateManager } from '../utils/statemanager/StateManager';
import { ToolUtils } from '../utils/ToolUtils';
import { ViewDataFactory, ViewNames } from '../utils/ViewDataFactory';
import { FullSizeCNCViewer } from './MachineViewer/FullSizeCNCViewer';

interface JobRunDialogProps {
    open: boolean;
    onClose: () => void;
    job: Job;
    onRunComplete?: () => void;
}

export function JobRunDialog({ open, onClose, job, onRunComplete }: JobRunDialogProps) {
    const colors = ConfigurationDataColors.Instance;
    // Create a new execution state for this run - each run is independent
    const [execState] = useState(() => new JobExecutionState(job));
    const shouldStopRef = useRef<boolean>(false);
    const isRunningRef = useRef<boolean>(false);
    const currentLineRef = useRef<HTMLDivElement>(null);
    const [viewerTab, setViewerTab] = useState(0); // 0 = G-Code, 1 = 3D Viewer
    const [simulatorView] = useState(() => ViewDataFactory.createForContext(ViewNames.JOB_RUN_DIALOG));

    // Reset state when dialog opens/closes
    useEffect(() => {
        if (open) {
            // Reset execution state when opening
            execState.reset();
            shouldStopRef.current = false;
            isRunningRef.current = false;
        }
    }, [open, execState]);

    // Auto-scroll to current line when it changes
    useEffect(() => {
        const currentLine = execState.currentLineNumber;
        if (currentLine >= 0 && currentLineRef.current) {
            currentLineRef.current.scrollIntoView({
                behavior: 'smooth',
                block: 'center'
            });
        }
    }, [execState.currentLineNumber]);

    // Timer for elapsed time - runs continuously when job has started
    useEffect(() => {
        // Only run timer if job has started (has a startTime)
        if (!execState.startTime) return;

        const interval = setInterval(() => {
            // If endTime exists, show final elapsed time, otherwise compute from current time
            const endTime = execState.endTime || Date.now();
            const elapsed = Math.floor((endTime - execState.startTime) / 1000);
            execState.elapsedSeconds = elapsed;
            StateManager.propertyChanged(execState, 'elapsedSeconds');
        }, 1000); // Update every second

        return () => clearInterval(interval);
    }, [execState, execState.startTime, execState.endTime]);

    // Auto-run the job when dialog opens
    useEffect(() => {
        if (!open || !job || isRunningRef.current || execState.isCompleted) return;

        isRunningRef.current = true;
        shouldStopRef.current = false;
        execState.startJob();

        const runJobWithProgress = async () => {
            const stages = job.stages;

            for (let i = 0; i < stages.length; i++) {
                if (shouldStopRef.current) break;

                execState.currentStageIndex = i;
                const stage = stages[i];

                // Wait while paused
                while (execState.isPaused && !shouldStopRef.current) {
                    await new Promise(resolve => setTimeout(resolve, 100));
                }

                if (shouldStopRef.current) break;

                // Execute the stage
                try {
                    await new Promise<void>((resolve, reject) => {
                        const callback = {
                            onComplete: async () => {
                                resolve();
                            },
                            onError: async (errorMessage: string) => {
                                reject(new Error(errorMessage));
                            },
                            onExecuteLine: (jobId: string, lineNumber: number, currentLine: string, totalLines: number, isLastStep: boolean) => {
                                // lineNumber from backend/simulator is 1-based, convert to 0-based for array indexing
                                execState.currentLineNumber = lineNumber - 1;
                            },
                            skipPreview: true  // Bypass preview dialogs - we're already in the run dialog
                        };
                        stage.runStage(callback);
                    });
                } catch (error) {
                    console.error('Stage execution error:', error);
                    execState.errorMessage = error instanceof Error ? error.message : 'Unknown error';
                    execState.stop();
                    isRunningRef.current = false;
                    return;
                }
            }

            // All stages completed or stopped
            if (shouldStopRef.current) {
                execState.stop();
            } else {
                execState.complete();
                if (onRunComplete) {
                    onRunComplete();
                }
            }
            isRunningRef.current = false;
        };

        runJobWithProgress();
    }, [open, job, onRunComplete, execState]);

    const handlePause = () => {
        execState.pause();
    };

    const handleResume = () => {
        execState.resume();
    };

    const handleStop = async () => {
        // Set stop flag to break the job loop
        shouldStopRef.current = true;
        execState.stop();

        // Call backend to cancel the cycle (not just stop)
        try {
            await Machine.getInstance().system.CancelCycle();
        } catch (error) {
            console.error('Failed to cancel cycle on backend:', error);
        }
    };

    const handleEStop = async () => {
        // Emergency stop - immediately halt all motion
        shouldStopRef.current = true;
        execState.stop();

        try {
            await Machine.getInstance().system.EStop();
        } catch (error) {
            console.error('Failed to trigger E-stop:', error);
        }
    };

    const handleRunAgain = async () => {
        // Create a completely new execution state for the fresh run
        // This ensures total independence from the previous run
        execState.reset();
        isRunningRef.current = false;
        shouldStopRef.current = false;

        // Manually start the job execution
        isRunningRef.current = true;
        execState.startJob();

        const runJobWithProgress = async () => {
            const stages = job.stages;

            for (let i = 0; i < stages.length; i++) {
                if (shouldStopRef.current) break;

                execState.currentStageIndex = i;
                const stage = stages[i];

                // Wait while paused
                while (execState.isPaused && !shouldStopRef.current) {
                    await new Promise(resolve => setTimeout(resolve, 100));
                }

                if (shouldStopRef.current) break;

                // Execute the stage
                try {
                    await new Promise<void>((resolve, reject) => {
                        const callback = {
                            onComplete: async () => {
                                resolve();
                            },
                            onError: async (errorMessage: string) => {
                                reject(new Error(errorMessage));
                            },
                            onExecuteLine: (jobId: string, lineNumber: number, currentLine: string, totalLines: number, isLastStep: boolean) => {
                                // lineNumber from backend/simulator is 1-based, convert to 0-based for array indexing
                                execState.currentLineNumber = lineNumber - 1;
                            },
                            skipPreview: true  // Bypass preview dialogs - we're already in the run dialog
                        };
                        stage.runStage(callback);
                    });
                } catch (error) {
                    console.error('Stage execution error:', error);
                    execState.errorMessage = error instanceof Error ? error.message : 'Unknown error';
                    execState.stop();
                    isRunningRef.current = false;
                    return;
                }
            }

            // All stages completed or stopped
            if (shouldStopRef.current) {
                execState.stop();
            } else {
                execState.complete();
                if (onRunComplete) {
                    onRunComplete();
                }
            }
            isRunningRef.current = false;
        };

        runJobWithProgress();
    };

    const formatTime = (seconds: number): string => {
        const hours = Math.floor(seconds / 3600);
        const minutes = Math.floor((seconds % 3600) / 60);
        const secs = seconds % 60;

        if (hours > 0) {
            return `${hours}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
        }
        return `${minutes}:${secs.toString().padStart(2, '0')}`;
    };

    return (
        <ObserveState
            key="job-run-dialog-root"
            listenTo={execState}
            properties={['isStopped', 'isCompleted']}
            control={() => {
                const canClose = execState.isStopped || execState.isCompleted;

                return (
                    <Dialog
                        open={open}
                        onClose={canClose ? onClose : undefined}
                        maxWidth="xl"
                        fullWidth
                        PaperProps={{ sx: { height: '85vh' } }}
                        disableEscapeKeyDown={!canClose}
                    >
                        <DialogTitle sx={{
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'space-between',
                            backgroundColor: colors.primaryColor,
                            color: colors.lightTextColor,
                            py: 2,
                            px: 3
                        }}>
                            Running Job: {job.name}
                            {canClose && (
                                <IconButton
                                    onClick={onClose}
                                    sx={{
                                        color: colors.lightTextColor,
                                        '&:hover': {
                                            backgroundColor: `${colors.lightTextColor}1A`
                                        }
                                    }}
                                >
                                    <CloseIcon />
                                </IconButton>
                            )}
                        </DialogTitle>

                        <DialogContent sx={{ p: 0, display: 'flex', height: '100%' }}>
                            {/* Left Side: Stage List (25%) */}
                            <Box sx={{
                                width: '25%',
                                borderRight: `1px solid ${colors.borderColor}`,
                                overflow: 'auto',
                                backgroundColor: colors.lightBackgroundColor
                            }}>
                                <ObserveState
                                    key="job-run-stages-list"
                                    listenTo={job}
                                    properties={['stages']}
                                    control={() => {
                                        const stages = job.stages;
                                        return (
                                            <ObserveState
                                                key="job-run-stages-state"
                                                listenTo={execState}
                                                properties={['currentStageIndex', 'isRunning', 'isPaused', 'isStopped', 'isCompleted']}
                                                control={() => (
                                                    <List sx={{ p: 0 }}>
                                                        {stages.map((stage: JobStage, index: number) => {
                                                            const isActive = index === execState.currentStageIndex && execState.isRunning;
                                                            const isCompleted = execState.isCompleted ? true : index < execState.currentStageIndex;
                                                            const isPending = index > execState.currentStageIndex && !execState.isCompleted;

                                                            return (
                                                                <ListItem
                                                                    key={index}
                                                                    sx={{
                                                                        py: 2,
                                                                        px: 3,
                                                                        backgroundColor: isActive
                                                                            ? colors.primaryColor
                                                                            : isCompleted
                                                                                ? 'success.light'
                                                                                : 'transparent',
                                                                        color: isActive ? colors.lightTextColor : isCompleted ? 'success.dark' : 'text.primary',
                                                                        borderBottom: `1px solid ${colors.borderColor}`,
                                                                        opacity: isPending ? 0.6 : 1
                                                                    }}
                                                                >
                                                                    <ListItemText
                                                                        primary={
                                                                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                                                                <Typography variant="body2" fontWeight="bold">
                                                                                    Stage {stage.stageNumber}
                                                                                </Typography>
                                                                                {isActive && <Typography variant="caption">(Running)</Typography>}
                                                                                {isCompleted && <Typography variant="caption">✓</Typography>}
                                                                            </Box>
                                                                        }
                                                                        secondary={
                                                                            <Typography variant="caption" sx={{ color: isActive ? `${colors.lightTextColor}CC` : 'text.secondary' }}>
                                                                                {stage.getDescription()}
                                                                            </Typography>
                                                                        }
                                                                    />
                                                                </ListItem>
                                                            );
                                                        })}
                                                    </List>
                                                )}
                                            />
                                        );
                                    }}
                                />
                            </Box>

                            {/* Middle: Tabbed Viewer (50%) */}
                            <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', borderRight: `1px solid ${colors.borderColor}` }}>
                                {/* Tabs Header */}
                                <Box sx={{ backgroundColor: colors.darkBackgroundColor, borderBottom: `2px solid ${colors.primaryColor}` }}>
                                    <Tabs
                                        value={viewerTab}
                                        onChange={(_, newValue) => setViewerTab(newValue)}
                                        sx={{
                                            minHeight: 48,
                                            '& .MuiTab-root': {
                                                color: `${colors.lightTextColor}B3`,
                                                fontWeight: 'bold',
                                                minHeight: 48,
                                                textTransform: 'none',
                                                fontSize: '0.9rem',
                                                '&.Mui-selected': {
                                                    color: colors.lightTextColor
                                                }
                                            },
                                            '& .MuiTabs-indicator': {
                                                backgroundColor: colors.lightTextColor,
                                                height: 3
                                            }
                                        }}
                                    >
                                        <Tab label="G-Code" />
                                        <Tab label="3D Viewer" />
                                    </Tabs>
                                </Box>

                                <ObserveState
                                    key="job-run-viewer-state"
                                    listenTo={execState}
                                    properties={['currentStageIndex', 'currentLineNumber']}
                                    control={() => {
                                        const stages = job.stages;
                                        const currentStage = stages[execState.currentStageIndex];

                                        if (!currentStage) {
                                            return (
                                                <Box sx={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', p: 3 }}>
                                                    <Typography color="text.secondary">No stage selected</Typography>
                                                </Box>
                                            );
                                        }

                                        const allGCodeLines = job.getModifiedGCode(
                                            MachineStateData.Instance.currentFixtureNumber,
                                            MachineStateData.Instance.currentToolNumber,
                                            ToolUtils.getCurrentTool()?.toolMeasured || false
                                        ).split('\n');

                                        const { stageLines } = currentStage.getGCodeLinesWithContext(allGCodeLines, 0);

                                        return (
                                            <>
                                                {/* G-Code Tab */}
                                                {viewerTab === 0 && (
                                                    <Box sx={{
                                                        flex: 1,
                                                        overflow: 'auto',
                                                        backgroundColor: colors.veryDarkColor,
                                                        color: colors.lightTextColor,
                                                        fontFamily: 'monospace',
                                                        fontSize: '13px',
                                                        p: 2
                                                    }}>
                                                        {/* Current stage lines only */}
                                                        {stageLines.map((line, idx) => {
                                                            const isCurrentLine = idx === execState.currentLineNumber;
                                                            const isExecuted = idx < execState.currentLineNumber;

                                                            let color = colors.lightTextColor; // Default pending color
                                                            let fontWeight: 'normal' | 'bold' = 'normal';

                                                            if (isCurrentLine) {
                                                                color = colors.errorColor; // Current line
                                                                fontWeight = 'bold';
                                                            } else if (isExecuted) {
                                                                color = colors.infoColor; // Executed lines
                                                            }

                                                            return (
                                                                <div
                                                                    key={`stage-${idx}`}
                                                                    ref={isCurrentLine ? currentLineRef : null}
                                                                    style={{
                                                                        paddingLeft: '8px',
                                                                        color: color,
                                                                        fontWeight: fontWeight,
                                                                        backgroundColor: isCurrentLine ? `${colors.errorColor}1A` : 'transparent'
                                                                    }}
                                                                >
                                                                    {line}
                                                                </div>
                                                            );
                                                        })}
                                                    </Box>
                                                )}

                                                {/* 3D Viewer Tab */}
                                                {viewerTab === 1 && (
                                                    <Box sx={{ flex: 1, minHeight: 0 }}>
                                                        <ObserveState
                                                            key="job-run-3d-viewer"
                                                            listenTo={MachineStateData.Instance}
                                                            properties={['currentJob', 'currentToolNumber', 'currentSpindleMachinePosition']}
                                                            control={() => (
                                                                <FullSizeCNCViewer
                                                                    simulatorViewData={simulatorView}
                                                                    job={job}
                                                                    machineState={MachineStateData.Instance}
                                                                    machineData={MachineData.Instance}
                                                                />
                                                            )}
                                                        />
                                                    </Box>
                                                )}
                                            </>
                                        );
                                    }}
                                />
                            </Box>

                            {/* Right Side: Controls (25%) */}
                            <Box sx={{ width: '25%', p: 3, display: 'flex', flexDirection: 'column', gap: 3, alignItems: 'center' }}>
                                {/* Timer */}
                                <ObserveState
                                    key="job-run-timer"
                                    listenTo={execState}
                                    properties={['elapsedSeconds']}
                                    control={() => (
                                        <Box sx={{ textAlign: 'center', width: '100%' }}>
                                            <Typography variant="h4" fontWeight="bold" sx={{ color: colors.primaryColor }}>
                                                {formatTime(execState.elapsedSeconds)}
                                            </Typography>
                                            <Typography variant="caption" color="text.secondary">
                                                Elapsed Time
                                            </Typography>
                                        </Box>
                                    )}
                                />

                                {/* Status Message */}
                                <ObserveState
                                    key="job-run-status"
                                    listenTo={execState}
                                    properties={['isRunning', 'isPaused', 'isCompleted', 'isStopped']}
                                    control={() => {
                                        const status = execState.status;
                                        return (
                                            <Box sx={{
                                                p: 2,
                                                width: '100%',
                                                borderRadius: 1,
                                                textAlign: 'center',
                                                border: `1px solid ${colors.borderColor}`
                                            }}>
                                                <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 0.5 }}>
                                                    Status
                                                </Typography>
                                                <Typography variant="h6" fontWeight="bold" sx={{
                                                    color: status === JobExecutionStatus.Running
                                                        ? 'info.main'
                                                        : status === JobExecutionStatus.Completed
                                                            ? 'success.main'
                                                            : status === JobExecutionStatus.Stopped
                                                                ? 'error.main'
                                                                : 'warning.main'
                                                }}>
                                                    {status === JobExecutionStatus.Running && 'Running'}
                                                    {status === JobExecutionStatus.Paused && 'Paused'}
                                                    {status === JobExecutionStatus.Stopped && 'Stopped'}
                                                    {status === JobExecutionStatus.Completed && 'Completed'}
                                                    {status === JobExecutionStatus.Ready && 'Ready'}
                                                </Typography>
                                            </Box>
                                        );
                                    }}
                                />

                                {/* Current Position */}
                                <ObserveState
                                    key="job-run-position"
                                    listenTo={ConfigurationState.Instance}
                                    properties={['currentMachinePoint']}
                                    control={() => {
                                        const pos = ConfigurationState.Instance.currentMachinePoint;
                                        return (
                                            <Box sx={{
                                                width: '100%',
                                                p: 2,
                                                borderRadius: 1,
                                                backgroundColor: colors.lightBackgroundColor,
                                                border: `1px solid ${colors.borderColor}`
                                            }}>
                                                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                                                    <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                                        <Typography variant="body2" fontWeight="bold">X:</Typography>
                                                        <Typography variant="body2" fontFamily="monospace">{pos.x.toFixed(4)}</Typography>
                                                    </Box>
                                                    <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                                        <Typography variant="body2" fontWeight="bold">Y:</Typography>
                                                        <Typography variant="body2" fontFamily="monospace">{pos.y.toFixed(4)}</Typography>
                                                    </Box>
                                                    <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                                        <Typography variant="body2" fontWeight="bold">Z:</Typography>
                                                        <Typography variant="body2" fontFamily="monospace">{pos.z.toFixed(4)}</Typography>
                                                    </Box>
                                                </Box>
                                            </Box>
                                        );
                                    }}
                                />

                                {/* Vertical Sliders Container */}
                                <ObserveState
                                    key="job-run-sliders"
                                    listenTo={execState}
                                    properties={['feedRateOverride', 'spindleSpeedOverride', 'isRunning']}
                                    control={() => (
                                        <Box sx={{ display: 'flex', gap: 4, justifyContent: 'center', flex: 1, width: '100%', py: 2 }}>
                                            {/* Feed Rate Slider */}
                                            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', height: '100%' }}>
                                                <Typography variant="caption" gutterBottom fontWeight="bold" sx={{ mb: 1 }}>
                                                    Feed Rate
                                                </Typography>
                                                <Typography variant="h6" fontWeight="bold" sx={{ color: colors.primaryColor, mb: 2 }}>
                                                    {execState.feedRateOverride}%
                                                </Typography>
                                                <Slider
                                                    orientation="vertical"
                                                    value={execState.feedRateOverride}
                                                    onChange={(_, value) => {
                                                        execState.feedRateOverride = value as number;
                                                    }}
                                                    min={10}
                                                    max={200}
                                                    step={5}
                                                    marks={[
                                                        { value: 50, label: '' },
                                                        { value: 100, label: '' },
                                                        { value: 150, label: '' },
                                                        { value: 200, label: '' }
                                                    ]}
                                                    valueLabelDisplay="auto"
                                                    disabled={!execState.isRunning}
                                                    sx={{
                                                        flex: 1,
                                                        minHeight: 200,
                                                        '& .MuiSlider-thumb': {
                                                            backgroundColor: colors.primaryColor
                                                        },
                                                        '& .MuiSlider-track': {
                                                            backgroundColor: colors.primaryColor
                                                        },
                                                        '& .MuiSlider-rail': {
                                                            backgroundColor: colors.borderColor
                                                        }
                                                    }}
                                                />
                                            </Box>

                                            {/* Spindle Speed Slider */}
                                            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', height: '100%' }}>
                                                <Typography variant="caption" gutterBottom fontWeight="bold" sx={{ mb: 1 }}>
                                                    Spindle Speed
                                                </Typography>
                                                <Typography variant="h6" fontWeight="bold" sx={{ color: colors.primaryColor, mb: 2 }}>
                                                    {execState.spindleSpeedOverride}%
                                                </Typography>
                                                <Slider
                                                    orientation="vertical"
                                                    value={execState.spindleSpeedOverride}
                                                    onChange={(_, value) => {
                                                        execState.spindleSpeedOverride = value as number;
                                                    }}
                                                    min={10}
                                                    max={200}
                                                    step={5}
                                                    marks={[
                                                        { value: 50, label: '' },
                                                        { value: 100, label: '' },
                                                        { value: 150, label: '' },
                                                        { value: 200, label: '' }
                                                    ]}
                                                    valueLabelDisplay="auto"
                                                    disabled={!execState.isRunning}
                                                    sx={{
                                                        flex: 1,
                                                        minHeight: 200,
                                                        '& .MuiSlider-thumb': {
                                                            backgroundColor: colors.primaryColor
                                                        },
                                                        '& .MuiSlider-track': {
                                                            backgroundColor: colors.primaryColor
                                                        },
                                                        '& .MuiSlider-rail': {
                                                            backgroundColor: colors.borderColor
                                                        }
                                                    }}
                                                />
                                            </Box>
                                        </Box>
                                    )}
                                />
                            </Box>
                        </DialogContent>

                        <DialogActions sx={{
                            p: 2,
                            gap: 2,
                            justifyContent: 'center',
                            borderTop: `1px solid ${colors.borderColor}`
                        }}>
                            <ObserveState
                                key="job-run-buttons"
                                listenTo={execState}
                                properties={['isRunning', 'isPaused', 'isStopped', 'isCompleted']}
                                control={() => (
                                    <>
                                        {/* Show Complete/Run Again when job is done */}
                                        {execState.isCompleted && (
                                            <>
                                                <Button
                                                    onClick={onClose}
                                                    variant="contained"
                                                    sx={{
                                                        backgroundColor: 'success.main',
                                                        color: colors.lightTextColor,
                                                        minWidth: 140,
                                                        height: 80,
                                                        fontSize: '1.1rem',
                                                        fontWeight: 'bold',
                                                        '&:hover': {
                                                            backgroundColor: 'success.dark'
                                                        }
                                                    }}
                                                >
                                                    Complete
                                                </Button>
                                                <Button
                                                    onClick={async () => {
                                                        const confirmed = await ConfirmDialogManager.Instance.showConfirm({
                                                            title: 'Run Job Again?',
                                                            message: 'Are you sure you want to run this job again?',
                                                            confirmText: 'Run Again',
                                                            severity: 'info'
                                                        });

                                                        if (confirmed) {
                                                            handleRunAgain();
                                                        }
                                                    }}
                                                    variant="contained"
                                                    startIcon={<PlayIcon sx={{ fontSize: 32 }} />}
                                                    sx={{
                                                        backgroundColor: colors.primaryColor,
                                                        color: colors.lightTextColor,
                                                        minWidth: 140,
                                                        height: 80,
                                                        fontSize: '1.1rem',
                                                        fontWeight: 'bold',
                                                        '&:hover': {
                                                            backgroundColor: colors.primaryColor,
                                                            opacity: 0.9
                                                        }
                                                    }}
                                                >
                                                    Run Again
                                                </Button>
                                            </>
                                        )}

                                        {/* Show Pause/Cancel/EStop when job is running */}
                                        {!execState.isCompleted && (
                                            <>
                                                {/* Pause/Resume Button */}
                                                <Button
                                                    onClick={execState.isPaused ? handleResume : handlePause}
                                                    disabled={!execState.isRunning && !execState.isPaused}
                                                    variant="contained"
                                                    startIcon={execState.isPaused ? <PlayIcon sx={{ fontSize: 32 }} /> : <PauseIcon sx={{ fontSize: 32 }} />}
                                                    sx={{
                                                        backgroundColor: execState.isPaused ? 'success.main' : 'warning.main',
                                                        color: colors.lightTextColor,
                                                        minWidth: 140,
                                                        height: 80,
                                                        fontSize: '1.1rem',
                                                        fontWeight: 'bold',
                                                        '&:hover': {
                                                            backgroundColor: execState.isPaused ? 'success.dark' : 'warning.dark'
                                                        },
                                                        '&:disabled': {
                                                            backgroundColor: colors.secondaryBorderColor,
                                                            color: colors.mutedTextColor
                                                        }
                                                    }}
                                                >
                                                    {execState.isPaused ? 'Resume' : 'Pause'}
                                                </Button>

                                                {/* Cancel Button */}
                                                <Button
                                                    onClick={handleStop}
                                                    disabled={execState.isStopped || execState.isCompleted}
                                                    variant="contained"
                                                    startIcon={<StopIcon sx={{ fontSize: 32 }} />}
                                                    sx={{
                                                        backgroundColor: 'error.main',
                                                        color: colors.lightTextColor,
                                                        minWidth: 140,
                                                        height: 80,
                                                        fontSize: '1.1rem',
                                                        fontWeight: 'bold',
                                                        '&:hover': {
                                                            backgroundColor: 'error.dark'
                                                        },
                                                        '&:disabled': {
                                                            backgroundColor: colors.secondaryBorderColor,
                                                            color: colors.mutedTextColor
                                                        }
                                                    }}
                                                >
                                                    Cancel
                                                </Button>

                                                {/* Emergency Stop Button */}
                                                <Button
                                                    onClick={handleEStop}
                                                    disabled={execState.isStopped || execState.isCompleted}
                                                    variant="contained"
                                                    startIcon={<StopIcon sx={{ fontSize: 32, fontWeight: 'bold' }} />}
                                                    sx={{
                                                        backgroundColor: colors.errorColor,
                                                        color: colors.lightTextColor,
                                                        minWidth: 140,
                                                        height: 80,
                                                        fontSize: '1.1rem',
                                                        fontWeight: 'bold',
                                                        border: `3px solid ${colors.errorColor}`,
                                                        '&:hover': {
                                                            backgroundColor: colors.errorColor
                                                        },
                                                        '&:disabled': {
                                                            backgroundColor: colors.secondaryBorderColor,
                                                            color: colors.mutedTextColor,
                                                            border: `3px solid ${colors.mutedTextColor}`
                                                        }
                                                    }}
                                                >
                                                    E-Stop
                                                </Button>
                                            </>
                                        )}
                                    </>
                                )}
                            />
                        </DialogActions>
                    </Dialog>
                );
            }}
        />
    );
}
