import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Axis Calibration Checklist Item
 * Manual confirmation that axes have been calibrated
 */
export class AxisCalibrationChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Axis Calibration',
            'Confirm all axes have been calibrated and tested for accuracy'
        );
    }

    /**
     * This is a manual confirmation item
     */
    public needsManualConfirmation(): boolean {
        return true;
    }

    /**
     * Always returns true - this is purely manual confirmation
     */
    public completionCheck(): boolean {
        return true;
    }

    public clone(): AxisCalibrationChecklistItem {
        const cloned = new AxisCalibrationChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
