import { IStorable } from '../../../../common/IStorable';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { AddActionType } from './AddActionType';
import { KeybindingItem } from './KeybindingItem';

/**
 * Represents a UI trigger (skin event) for PLC actions
 * These are events that can be triggered from the UI/skin with unique event numbers
 */
export class UITrigger implements IStorable {
    private _eventName: string = '';
    private _eventNumber: number = 0;
    private _description: string = '';
    private _pressedText: string = 'Triggered';
    private _notPressedText: string = 'Not Triggered';
    private _addAction: AddActionType = AddActionType.No;
    private _keybindings: KeybindingItem[] = [];  // List of keybindings for this trigger

    constructor(eventName?: string, eventNumber?: number) {
        // Process the event name through the setter to ensure _UI suffix
        if (eventName) {
            this.eventName = eventName;
        }
        this._eventNumber = eventNumber || 0;
    }

    /**
     * Get the event name
     */
    public get eventName(): string {
        return this._eventName;
    }

    public set eventName(value: string) {
        // Ensure the name ends with _UI suffix and is uppercase
        let processedName = value.toUpperCase().trim();
        if (!processedName.endsWith('_UI')) {
            processedName = processedName + '_UI';
        }
        this._eventName = processedName;
        StateManager.propertyChanged(this, 'eventName');
    }

    /**
     * Get the event number (must be unique across System and SystemDefault, max 255)
     */
    public get eventNumber(): number {
        return this._eventNumber;
    }

    public set eventNumber(value: number) {
        this._eventNumber = value;
        StateManager.propertyChanged(this, 'eventNumber');
    }

    /**
     * Get the description of this UI trigger
     */
    public get description(): string {
        return this._description;
    }

    public set description(value: string) {
        this._description = value;
        StateManager.propertyChanged(this, 'description');
    }

    /**
     * Get the text to display when trigger is triggered/active
     */
    public get pressedText(): string {
        return this._pressedText;
    }

    public set pressedText(value: string) {
        this._pressedText = value;
        StateManager.propertyChanged(this, 'pressedText');
    }

    /**
     * Get the text to display when trigger is not triggered/inactive
     */
    public get notPressedText(): string {
        return this._notPressedText;
    }

    public set notPressedText(value: string) {
        this._notPressedText = value;
        StateManager.propertyChanged(this, 'notPressedText');
    }

    /**
     * Get whether this trigger should be added to the action panel
     */
    public get addAction(): AddActionType {
        return this._addAction;
    }

    public set addAction(value: AddActionType) {
        this._addAction = value;
        StateManager.propertyChanged(this, 'addAction');
    }

    /**
     * Get the list of keybindings
     */
    public get keybindings(): KeybindingItem[] {
        return this._keybindings;
    }

    /**
     * Add a keybinding to this trigger
     */
    public addKeybinding(keybinding: KeybindingItem): void {
        this._keybindings.push(keybinding);
        StateManager.propertyChanged(this, 'keybindings');
    }

    /**
     * Update an existing keybinding
     */
    public updateKeybinding(oldKeybinding: KeybindingItem, newKeybinding: KeybindingItem): void {
        const index = this._keybindings.indexOf(oldKeybinding);
        if (index !== -1) {
            this._keybindings[index] = newKeybinding;
            StateManager.propertyChanged(this, 'keybindings');
        }
    }

    /**
     * Remove a keybinding from this trigger
     */
    public removeKeybinding(keybinding: KeybindingItem): void {
        const index = this._keybindings.indexOf(keybinding);
        if (index !== -1) {
            this._keybindings.splice(index, 1);
            StateManager.propertyChanged(this, 'keybindings');
        }
    }

    /**
     * Get a display string for this trigger
     */
    public getDisplayString(): string {
        return `Event ${this._eventNumber}: ${this._eventName || '(Unnamed)'}`;
    }

    /**
     * Get a human-readable string representation of all keybindings
     * Examples: "Ctrl+A, Shift+F1", "F5"
     */
    public getKeyString(): string {
        if (this._keybindings.length === 0) {
            return '(No keys assigned)';
        }
        return this._keybindings.map(kb => kb.getKeyString()).join(', ');
    }

    /**
     * Check if this trigger matches a keyboard event
     * @param event The keyboard event to check
     * @returns True if the event matches any of this trigger's keybindings
     */
    public matches(event: KeyboardEvent): boolean {
        return this._keybindings.some(kb => kb.matches(event));
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): object {
        const baseData = DataUtilities.getStorageData(this, ['_keybindings']);
        return {
            ...baseData,
            keybindings: this._keybindings.map(kb => kb.toJSON())
        };
    }

    /**
     * Deserialize from JSON
     */
    public fromJSON(data: any): void {
        // Load keybindings array
        if (data.keybindings && Array.isArray(data.keybindings)) {
            this._keybindings = data.keybindings.map((kbData: any) => {
                const kb = new KeybindingItem();
                kb.fromJSON(kbData);
                return kb;
            });
        }

        // Load other properties
        DataUtilities.loadStorageData(this, data, ['_keybindings', 'keybindings']);
    }

    /**
     * Clone this UI trigger
     */
    public clone(): UITrigger {
        const cloned = new UITrigger();
        cloned.fromJSON(this.toJSON());
        return cloned;
    }
}
