import CloseIcon from '@mui/icons-material/Close';
import {
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    Paper,
    Typography
} from '@mui/material';
import { useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { TimerStatement } from '../statements/TimerStatement';

interface TimerStructureDialogProps {
    timerStatement: TimerStatement;
    open: boolean;
    onClose: () => void;
}

/**
 * TimerStructureDialog - Configure which action branches to show/hide
 * Displays pseudo-code visualization with clickable [show]/[hide] links
 */
export function TimerStructureDialog(props: TimerStructureDialogProps) {
    const { timerStatement, open, onClose } = props;
    const colors = ConfigurationDataColors.Instance;

    // Local state for editing (uncommitted changes)
    const [localHideTimerStartActions, setLocalHideTimerStartActions] = useState(timerStatement.hideTimerStartActions);
    const [localCancelEnabled, setLocalCancelEnabled] = useState(timerStatement.cancelEnabled);

    const handleApply = () => {
        timerStatement.hideTimerStartActions = localHideTimerStartActions;
        timerStatement.cancelEnabled = localCancelEnabled;
        StateManager.propertyChanged(timerStatement, 'hideTimerStartActions');
        StateManager.propertyChanged(timerStatement, 'cancelEnabled');
        onClose();
    };

    const handleCancel = () => {
        // Reset local state to current values
        setLocalHideTimerStartActions(timerStatement.hideTimerStartActions);
        setLocalCancelEnabled(timerStatement.cancelEnabled);
        onClose();
    };

    // Get condition expression for display
    const conditionLogic = timerStatement.conditionGroup?.getPLCLogic([]);
    const conditionExpr = conditionLogic && conditionLogic.length > 0 ? conditionLogic[0] : '[condition]';

    // Style definitions matching LogicStructureDialog
    const enabledStyle = {
        color: colors.darkTextColor,
        fontWeight: 'bold',
        fontFamily: 'monospace',
        fontSize: '14px',
        padding: '4px 8px',
        backgroundColor: colors.primaryColor + '20',
        borderRadius: '4px',
        marginBottom: '4px',
        display: 'flex',
        alignItems: 'center',
        gap: 1
    };

    const disabledStyle = {
        color: colors.mutedTextColor,
        fontWeight: 'normal',
        fontFamily: 'monospace',
        fontSize: '14px',
        padding: '4px 8px',
        marginBottom: '4px',
        display: 'flex',
        alignItems: 'center',
        gap: 1
    };

    const strikethrough = {
        textDecoration: 'line-through'
    };

    const linkStyle = {
        color: colors.primaryColor,
        textDecoration: 'none !important',
        cursor: 'pointer',
        fontSize: '11px',
        fontFamily: 'sans-serif',
        fontWeight: 'bold',
        border: `1px solid ${colors.primaryColor}`,
        padding: '2px 6px',
        borderRadius: '3px',
        backgroundColor: colors.lightOverlay,
        '&:hover': {
            backgroundColor: colors.primaryColor,
            color: colors.lightTextColor
        }
    };

    return (
        <Dialog open={open} onClose={handleCancel} maxWidth="md" fullWidth>
            <DialogTitle sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                backgroundColor: colors.primaryColor,
                color: colors.lightTextColor,
                py: 2,
                px: 3
            }}>
                Configure Timer Structure
                <IconButton
                    onClick={handleCancel}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>

            <DialogContent>
                <Box sx={{ mt: 3 }}>
                    <Typography variant="body1" sx={{ mb: 2, color: colors.darkTextColor }}>
                        Click links in the structure below to configure sections. Links appear only when relevant.
                    </Typography>

                    {/* Pseudo-code visualization */}
                    <Paper sx={{
                        p: 2,
                        backgroundColor: colors.lightBackgroundColor,
                        border: `1px solid ${colors.borderColor}`,
                        fontFamily: 'monospace'
                    }}>
                        <Box sx={enabledStyle}>
                            <span>when ({conditionExpr}) for {timerStatement.timerLengthMs}ms</span>
                        </Box>

                        {/* OnTimerStart Branch - can be hidden */}
                        <Box sx={{ ...(!localHideTimerStartActions ? enabledStyle : disabledStyle), ml: 2 }}>
                            <span style={localHideTimerStartActions ? strikethrough : undefined}>
                                OnTimerStart [actions]
                            </span>
                            <Typography
                                component="span"
                                onClick={() => setLocalHideTimerStartActions(!localHideTimerStartActions)}
                                sx={linkStyle}
                            >
                                [{localHideTimerStartActions ? 'show' : 'hide'}]
                            </Typography>
                        </Box>

                        {/* OnTimerComplete Branch - always shown */}
                        <Box sx={{ ...enabledStyle, ml: 2 }}>
                            <span>OnTimerComplete [actions]</span>
                        </Box>

                        {/* Cancel Condition Branch - optional */}
                        <Box sx={{ ...(localCancelEnabled ? enabledStyle : disabledStyle), ml: 2 }}>
                            <span style={!localCancelEnabled ? strikethrough : undefined}>
                                cancel if [condition]
                            </span>
                            <Typography
                                component="span"
                                onClick={() => setLocalCancelEnabled(!localCancelEnabled)}
                                sx={linkStyle}
                            >
                                [{localCancelEnabled ? 'hide' : 'show'}]
                            </Typography>
                        </Box>
                    </Paper>
                </Box>
            </DialogContent>

            <DialogActions sx={{
                p: 2,
                gap: 1,
                justifyContent: 'flex-end',
                borderTop: `1px solid ${colors.borderColor}`
            }}>
                <Button onClick={handleCancel} variant="outlined">
                    Cancel
                </Button>
                <Button onClick={handleApply} variant="contained">
                    Apply
                </Button>
            </DialogActions>
        </Dialog>
    );
}
