import { Close as CloseIcon } from '@mui/icons-material';
import {
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    Typography
} from '@mui/material';
import { useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { NumberInput } from '../../Common/NumberInput';

interface LayoutToolHoldersDialogProps {
    open: boolean;
    onClose: () => void;
    onConfirm: (spacing: number) => void;
    approachAxis: 'X' | 'Y';
}

export function LayoutToolHoldersDialog({
    open,
    onClose,
    onConfirm,
    approachAxis
}: LayoutToolHoldersDialogProps) {
    const colors = ConfigurationDataColors.Instance;
    const [spacing, setSpacing] = useState<number>(1.0);

    const handleConfirm = () => {
        onConfirm(spacing);
        onClose();
    };

    const nonApproachAxis = approachAxis === 'Y' ? 'X' : 'Y';

    return (
        <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
            <DialogTitle sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                backgroundColor: colors.primaryColor,
                color: colors.lightTextColor,
                py: 2,
                px: 3
            }}>
                Layout Tool Holders
                <IconButton
                    onClick={onClose}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>
            <DialogContent>
                <Box sx={{ mt: 3 }}>
                    <Typography variant="body2" sx={{ mb: 3 }}>
                        Specify the spacing increment to apply between tool holders along the {nonApproachAxis} axis.
                        Each tool holder position will be set starting from tool holder 1.
                    </Typography>
                    <NumberInput
                        fullWidth
                        label={`Spacing Increment (${nonApproachAxis} axis)`}
                        value={spacing}
                        onChange={setSpacing}
                        precision={3}
                        helperText={`Distance between each tool holder on ${nonApproachAxis} axis`}
                    />
                    <Typography variant="caption" color="text.secondary" sx={{ mt: 2, display: 'block' }}>
                        Tool holder 1 will remain at its current position. Each subsequent holder
                        will have {spacing.toFixed(3)} added to its {nonApproachAxis} coordinate.
                    </Typography>
                </Box>
            </DialogContent>
            <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${colors.borderColor}` }}>
                <Button onClick={onClose}>
                    Cancel
                </Button>
                <Button
                    variant="contained"
                    onClick={handleConfirm}
                    sx={{
                        backgroundColor: colors.primaryColor,
                        '&:hover': {
                            backgroundColor: colors.primaryColor,
                            opacity: 0.9
                        }
                    }}
                >
                    Apply Layout
                </Button>
            </DialogActions>
        </Dialog>
    );
}
