import Box from '@mui/material/Box';
import { NotificationList } from '../../utils/NotificationList';
import { ObserveState } from '../../utils/statemanager/ObserveState';

/**
 * Simple notification area that renders all notifications from NotificationList
 * No extra properties needed - just renders what's in the list
 */
export function NotificationArea() {
  return (
    <ObserveState
      listenTo={NotificationList.Instance}
      properties={['notifications']}
      control={() => {
        const notifications = NotificationList.Instance.notifications;

        if (notifications.length === 0) {
          return null;
        }

        return (
          <Box
            sx={{
              position: 'fixed',
              bottom: 20,
              right: 20,
              display: 'flex',
              flexDirection: 'column', // Stack downward from bottom
              gap: 1,
              pointerEvents: 'none', // Allow click-through for container
              zIndex: 5000 // Above all except connection overlay
            }}
          >
            {notifications
              .sort((a, b) => b.ordinal - a.ordinal) // Higher ordinals on top (reverse sort)
              .map((notification) => (
                <Box
                  key={notification.id}
                  sx={{
                    pointerEvents: 'auto' // Re-enable pointer events for individual notifications
                  }}
                >
                  {notification.component}
                </Box>
              ))}
          </Box>
        );
      }}
    />
  );
}
